// 5. DỮ LIỆU LUYỆN NÓI MẪU (SPEAKING_DATA)
const SPEAKING_DATA = [
  { id: 1, topic: "Đón tiếp khách hàng", sv: "Hej! Välkommen till vår salong.", vi: "Xin chào! Chào mừng đến với tiệm của chúng tôi.", phonetic: "/hej ˈvɛːlˌkɔmːɛn tɪl voːr saˈlɔŋ/" },
  { id: 2, topic: "Đón tiếp khách hàng", sv: "God morgon! Hur mår du idag?", vi: "Chào buổi sáng! Hôm nay bạn cảm thấy thế nào?", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr moːr dʉː ɪˈdɑːɡ/" },
  { id: 3, topic: "Đón tiếp khách hàng", sv: "Hej och välkommen! Har du bokat tid?", vi: "Xin chào và chào mừng! Bạn đã đặt lịch hẹn chưa?", phonetic: "/hej ɔ ˈvɛːlˌkɔmːɛn hɑːr dʉː ˈbuːkat tiːd/" },
  { id: 4, topic: "Đón tiếp khách hàng", sv: "Varsågod och sitt ner här en stund.", vi: "Mời bạn ngồi xuống đây một lát.", phonetic: "/ˈvɑːrʃɔˌɡuːd ɔ sɪtː neːr hɛːr ɛn stɵnd/" },
  { id: 5, topic: "Đón tiếp khách hàng", sv: "Vad trevligt att se dig igen!", vi: "Thật vui được gặp lại bạn!", phonetic: "/vɑːd ˈtreːvlɪɡt at seː dej ɪˈjɛn/" },
  { id: 6, topic: "Đón tiếp khách hàng", sv: "Välkommen in! Jag heter My Han och ska hjälpa dig idag.", vi: "Chào mừng vào tiệm! Mình tên là My Han và sẽ hỗ trợ bạn hôm nay.", phonetic: "/ˈvɛːlˌkɔmːɛn ɪn jɑːɡ ˈheːtɛr myː hɑn ɔ skɑː ˈjɛlːpa dej ɪˈdɑːɡ/" },
  { id: 7, topic: "Đón tiếp khách hàng", sv: "Hur var din dag hittills?", vi: "Ngày của bạn từ nãy đến giờ thế nào?", phonetic: "/hʉːr vɑːr diːn dɑːɡ ˈhɪtːɪls/" },
  { id: 8, topic: "Đón tiếp khách hàng", sv: "Jag är så glad att du kom hit idag.", vi: "Mình rất vui vì hôm nay bạn đã đến đây.", phonetic: "/jɑːɡ ɛːr soː ɡlɑːd at dʉː kɔm hɪt ɪˈdɑːɡ/" },
  { id: 9, topic: "Đón tiếp khách hàng", sv: "Ta av dig jackan om du vill, så hänger jag upp den.", vi: "Bạn cởi áo khoác nếu muốn nhé, mình sẽ treo lên giúp.", phonetic: "/tɑː ɑːv dej ˈjakːan ɔm dʉː vɪl soː ˈhɛŋːɛr jɑːɡ ɵpː dɛn/" },
  { id: 10, topic: "Đón tiếp khách hàng", sv: "Känn dig som hemma här hos oss.", vi: "Hãy cứ tự nhiên như ở nhà khi ở chỗ tụi mình nhé.", phonetic: "/ɕɛnː dej sɔm ˈhɛmːa hɛːr huːs ɔsː/" },
  { id: 11, topic: "Mời nước khách", sv: "Vill du ha något att dricka, kaffe eller vatten?", vi: "Bạn có muốn uống chút gì không, cà phê hay nước lọc?", phonetic: "/vɪl dʉː hɑː ˈnoːɡɔt at ˈdrɪkːa ˈkafːɛ ˈɛlːɛr ˈvatːɛn/" },
  { id: 12, topic: "Mời nước khách", sv: "Vill du ha ett glas kallt vatten medan du väntar?", vi: "Bạn có muốn một ly nước lạnh trong lúc chờ không?", phonetic: "/vɪl dʉː hɑː ɛt ɡlɑːs kalːt ˈvatːɛn ˈmeːdan dʉː ˈvɛnːtar/" },
  { id: 13, topic: "Mời nước khách", sv: "Jag kan bjuda på te eller kaffe om du önskar.", vi: "Mình có thể mời trà hoặc cà phê nếu bạn muốn.", phonetic: "/jɑːɡ kan ˈbjʉːda pɔː teː ˈɛlːɛr ˈkafːɛ ɔm dʉː ˈœnːskar/" },
  { id: 14, topic: "Mời nước khách", sv: "Föredrar du varmt eller kallt vatten?", vi: "Bạn thích nước ấm hay nước lạnh hơn?", phonetic: "/ˌfœrɛˈdrɑːr dʉː varmt ˈɛlːɛr kalːt ˈvatːɛn/" },
  { id: 15, topic: "Mời nước khách", sv: "Ska jag hälla upp lite te åt dig?", vi: "Mình rót thêm chút trà cho bạn nhé?", phonetic: "/skɑː jɑːɡ ˈhɛlːa ɵpː ˈliːtɛ teː oːt dej/" },
  { id: 16, topic: "Mời nước khách", sv: "Här kommer ditt vatten. Varsågod!", vi: "Nước của bạn đây. Mời bạn dùng!", phonetic: "/hɛːr ˈkɔmːɛr dɪt ˈvatːɛn ˈvɑːrʃɔˌɡuːd/" },
  { id: 17, topic: "Mời nước khách", sv: "Vill du ha socker eller mjölk i kaffet?", vi: "Bạn có muốn thêm đường hay sữa vào cà phê không?", phonetic: "/vɪl dʉː hɑː ˈsɔkːɛr ˈɛlːɛr mjœlk ɪ ˈkafːɛt/" },
  { id: 18, topic: "Mời nước khách", sv: "Jag fixar en kopp varmt te direkt.", vi: "Mình pha một tách trà nóng ngay đây.", phonetic: "/jɑːɡ ˈfɪkːsar ɛn kɔpː varmt teː dɪˈrɛkt/" },
  { id: 19, topic: "Mời nước khách", sv: "Vill du ha en liten kaka till kaffet?", vi: "Bạn có muốn ăn thêm một chiếc bánh nhỏ kèm cà phê không?", phonetic: "/vɪl dʉː hɑː ɛn ˈliːtɛn ˈkɑːka tɪl ˈkafːɛt/" },
  { id: 20, topic: "Mời nước khách", sv: "Säg bara till om du vill ha påfyllning.", vi: "Cứ bảo mình nếu bạn muốn châm thêm nhé.", phonetic: "/sɛːj ˈbɑːra tɪl ɔm dʉː vɪl hɑː ˈpoːˌfʏlːnɪŋ/" },
  { id: 21, topic: "Thao tác nối mi / Spa", sv: "Blunda och slappna av nu.", vi: "Hãy nhắm mắt lại và thư giãn nhé.", phonetic: "/ˈblɵnːda ɔ ˈslapːna ɑːv nʉː/" },
  { id: 22, topic: "Thao tác nối mi / Spa", sv: "Känns det bra och bekvämt på britsen?", vi: "Nằm trên giường liệu trình có thấy thoải mái không?", phonetic: "/ɕɛnːs deː brɑː ɔ bɛˈkvɛːmt pɔː brɪtːsɛn/" },
  { id: 23, topic: "Thao tác nối mi / Spa", sv: "Jag sätter på en mjuk ögonpad under fransarna nu.", vi: "Bây giờ mình dán miếng lót mắt mềm dưới hàng mi nhé.", phonetic: "/jɑːɡ ˈsɛtːɛr pɔː ɛn mjʉːk ˈœːɡɔnˌpad ɵnːdɛr ˈfranːsarːa nʉː/" },
  { id: 24, topic: "Thao tác nối mi / Spa", sv: "Säg till direkt om det svider eller sticker till.", vi: "Báo ngay cho mình nếu thấy cay hoặc châm chích nhé.", phonetic: "/sɛːj tɪl dɪˈrɛkt ɔm deː ˈsviːdɛr ˈɛlːɛr ˈstɪkːɛr tɪl/" },
  { id: 25, topic: "Thao tác nối mi / Spa", sv: "Vi börjar med att rengöra fransarna noga.", vi: "Tụi mình bắt đầu bằng việc làm sạch mi thật kỹ.", phonetic: "/viː ˈbœrːjar meːd at ˈreːnˌjœːra ˈfranːsarːa ˈnoːɡa/" },
  { id: 26, topic: "Thao tác nối mi / Spa", sv: "Nu applicerar jag limmet försiktigt på varje frans.", vi: "Giờ mình gắn keo cẩn thận lên từng sợi mi.", phonetic: "/nʉː ˌapːlɪˈseːrar jɑːɡ ˈlɪmːɛt fœrˈsɪkːtɪt pɔː ˈvarːjɛ frans/" },
  { id: 27, topic: "Thao tác nối mi / Spa", sv: "Känns tejpningen för stram på något ställe?", vi: "Miếng băng dán có bị căng ở chỗ nào không?", phonetic: "/ɕɛnːs ˈtɛjpnɪŋɛn fœr stram pɔː ˈnoːɡɔt ˈstɛlːɛ/" },
  { id: 28, topic: "Thao tác nối mi / Spa", sv: "Jag masserar hårbotten med lugna rörelser nu.", vi: "Bây giờ mình massage da đầu với các động tác nhẹ nhàng nhé.", phonetic: "/jɑːɡ maˈseːrar ˈhoːrˌbɔtːɛn meːd ˈlɵɡːna ˈrœːrɛlsɛr nʉː/" },
  { id: 29, topic: "Thao tác nối mi / Spa", sv: "Är vattnet lagom varmt när jag sköljer håret?", vi: "Nước có vừa độ ấm khi mình xả tóc không?", phonetic: "/ɛːr ˈvatːnɛt ˈlɑːɡɔm varmt nɛːr jɑːɡ ˈɕœlːjɛr ˈhoːrɛt/" },
  { id: 30, topic: "Thao tác nối mi / Spa", sv: "Nu är vi klara med behandlingen. Öppna ögonen sakta.", vi: "Xong liệu trình rồi đây. Bạn mở mắt từ từ nhé.", phonetic: "/nʉː ɛːr viː ˈklɑːra meːd bɛˈhanːdlɪŋɛn ˈœpːna ˈœːɡɔnɛn ˈsakːta/" },
  { id: 31, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vilken stil gillar du mest, naturlig eller volym?", vi: "Bạn thích kiểu nào nhất, tự nhiên hay dày vol?", phonetic: "/ˈvɪlːkɛn stiːl ˈjɪlːar dʉː mɛst nɑtʉːˈliːr ˈɛlːɛr vɔˈlʏːm/" },
  { id: 32, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vill du ha en öppen docköga eller en mjuk kattöga?", vi: "Bạn muốn dáng mắt búp bê tròn to hay dáng mắt mèo dịu dàng?", phonetic: "/vɪl dʉː hɑː ɛn ˈœpːɛn ˈdɔkˌœːɡa ˈɛlːɛr ɛn mjʉːk ˈkatˌœːɡa/" },
  { id: 33, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Jag rekommenderar en lite kortare längd innerst.", vi: "Mình khuyên nên chọn độ dài ngắn hơn một chút ở góc trong.", phonetic: "/jɑːɡ ˌrɛkɔmɛnˈdeːrar ɛn ˈliːtɛ ˈkɔrːtarɛ lɛŋd ˈɪnːɛrst/" },
  { id: 34, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vill du ha mandelformade, fyrkantiga eller runda naglar?", vi: "Bạn muốn móng dáng hạnh nhân, móng vuông hay móng tròn?", phonetic: "/vɪl dʉː hɑː ˈmanːdɛlˌfɔrmadɛ ˈfʏrˌkantɪɡa ˈɛlːɛr ˈrɵnːda ˈnaɡːlar/" },
  { id: 35, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Den här nyansen passar väldigt fint till din hudton.", vi: "Tông màu này hợp với sắc da của bạn lắm đấy.", phonetic: "/deːn hɛːr nʏˈanːsɛn ˈpasːar ˈvɛlːdɪt fɪnt tɪl diːn ˈhʉːdˌtuːn/" },
  { id: 36, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vi kan göra gel, förstärkning med builder gel eller akryl.", vi: "Tụi mình có thể làm gel, đắp gel cứng hoặc đắp bột.", phonetic: "/viː kan ˈjœːra jeːl fœrˈstɛrkːnɪŋ meːd ˈbɪlːdɛr jeːl ˈɛlːɛr ɑˈkrʏːl/" },
  { id: 37, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vill du ha enfärgat, fransk manikyr eller chrome?", vi: "Bạn muốn sơn một màu, kiểu Pháp hay hiệu ứng chrome?", phonetic: "/vɪl dʉː hɑː ˈeːnˌfɛrɡat fransk mɑnɪˈkʏːr ˈɛlːɛr kroːm/" },
  { id: 38, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Jag anpassar böjen efter dina naturliga fransar.", vi: "Mình điều chỉnh độ cong theo hàng mi thật của bạn.", phonetic: "/jɑːɡ ˈanːpasːar ˈbœjːɛn ˈɛfːtɛr ˈdiːna nɑtʉːˈliːra ˈfranːsar/" },
  { id: 39, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Det är bäst att skona dina egna fransar så de håller sig friska.", vi: "Tốt nhất là giữ gìn mi thật để mi luôn khỏe mạnh.", phonetic: "/deːt ɛːr bɛst at ˈskuːna ˈdiːna ˈeːɡːna ˈfranːsar soː deː ˈhɔlːɛr sej ˈfrɪsːka/" },
  { id: 40, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Ska vi lägga till en djupgående fuktkur för händerna idag?", vi: "Hôm nay mình thêm bước dưỡng ẩm sâu cho tay nhé?", phonetic: "/skɑː viː ˈlɛɡːa tɪl ɛn ˈjʉːpˌɡoːɛnːdɛ ˈfɵktˌkʉːr fœr ˈhɛnːdarːa ɪˈdɑːɡ/" },
  { id: 41, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Undvik vatten och ånga på fransarna de första tjugofyra timmarna.", vi: "Tránh nước và hơi nóng lên mi trong hai mươi bốn giờ đầu nhé.", phonetic: "/ˈɵnːdviːk ˈvatːɛn ɔ ˈɔŋːa pɔː ˈfranːsarːa deː ˈfœsːta ˈɕʉːɡʊˌfyːra ˈtɪmːarːa/" },
  { id: 42, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Gnugga inte ögonen och använd oljefria produkter.", vi: "Đừng dụi mắt và hãy dùng sản phẩm không chứa dầu nhé.", phonetic: "/ˈɡnɵɡːa ˈɪnːtɛ ˈœːɡɔnɛn ɔ ˈanːvɛnd ˈɔlːjɛˌfriːa prʊˈdɵkːtɛr/" },
  { id: 43, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Borsta fransarna försiktigt varje morgon med borsten du får.", vi: "Chải mi nhẹ nhàng mỗi sáng bằng cọ được tặng kèm nhé.", phonetic: "/ˈbɔʂːta ˈfranːsarːa fœrˈsɪkːtɪt ˈvarːjɛ ˈmɔrːɔn meːd ˈbɔʂːtɛn dʉː fɔːr/" },
  { id: 44, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Det är dags för påfyllning om ungefär tre veckor.", vi: "Khoảng ba tuần nữa là tới lúc dặm lại rồi đấy.", phonetic: "/deːt ɛːr daks fœr ˈpoːˌfʏlːnɪŋ ɔm ɵnːfɛˈjɛːr treː ˈvɛkːɔr/" },
  { id: 45, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Smörj nagelbanden med nagelolja varje kväll.", vi: "Thoa dầu dưỡng viền móng mỗi tối nhé.", phonetic: "/smœrj ˈnɑːɡɛlˌbanːdɛn meːd ˈnɑːɡɛlˌɔlːja ˈvarːjɛ kvɛlː/" },
  { id: 46, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Använd gärna handskar när du diskar eller städar.", vi: "Bạn nhớ đeo găng tay khi rửa chén hoặc dọn dẹp nhé.", phonetic: "/ˈanːvɛnd ˈjɛːrna ˈhanːskar nɛːr dʉː ˈdɪsːkar ˈɛlːɛr ˈstɛːdar/" },
  { id: 47, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Vill du boka nästa tid redan innan du går idag?", vi: "Bạn có muốn đặt lịch lần tới ngay trước khi về hôm nay không?", phonetic: "/vɪl dʉː ˈbuːka ˈnɛsːta tiːd ˈreːdan ˈɪnːan dʉː ɡoːr ɪˈdɑːɡ/" },
  { id: 48, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Vi har en ledig tid på tisdag klockan tio.", vi: "Tụi mình còn trống lịch vào thứ ba lúc mười giờ.", phonetic: "/viː hɑːr ɛn ˈleːdɪɡ tiːd pɔː ˈtɪsːdɑːɡ ˈklɔkːan ˈtiːʊ/" },
  { id: 49, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Jag skickar en påminnelse dagen innan din tid.", vi: "Mình sẽ gửi tin nhắn nhắc lịch trước ngày hẹn một ngày.", phonetic: "/jɑːɡ ˈɕɪkːar ɛn ˈpoːˌmɪnːɛlsɛ ˈdɑːɡɛn ˈɪnːan diːn tiːd/" },
  { id: 50, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Tack så mycket för besöket! Vi ses nästa gång.", vi: "Cảm ơn bạn rất nhiều vì đã ghé tiệm! Hẹn gặp lại lần sau nhé.", phonetic: "/tak soː ˈmʏkːɛt fœr bɛˈsøːkɛt viː seːs ˈnɛsːta ɡɔŋ/" },
  { id: 51, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Jag desinficerar alla verktyg mellan varje kund.", vi: "Mình khử trùng toàn bộ dụng cụ giữa mỗi khách hàng.", phonetic: "/jɑːɡ dɛsɪnfɪˈseːrar ˈalːa ˈvɛrkˌtʏːɡ ˈmɛlːan ˈvarːjɛ kɵnd/" },
  { id: 52, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Vi följer säkerhetsrutiner för härdplast och lim.", vi: "Tụi mình tuân thủ quy trình an toàn với nhựa cứng và keo.", phonetic: "/viː ˈfœlːjɛr ˈsɛːkɛrˌheːtsrɵˌtiːnɛr fœr ˈhɛːrdˌplast ɔ liːm/" },
  { id: 53, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Jag arbetar i ett välventilerat rum med punktutsug.", vi: "Mình làm việc trong phòng thông thoáng có máy hút khí cục bộ.", phonetic: "/jɑːɡ ˈɑːrbɛtar ɪ ɛt ˈvɛːlˌvɛntɪˌleːrat rɵm meːd ˈpɵŋktˌʉːtsʉːɡ/" },
  { id: 54, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Jag byter handskar och dukar inför varje ny behandling.", vi: "Mình thay găng tay và khăn trải trước mỗi liệu trình mới.", phonetic: "/jɑːɡ ˈbʏːtɛr ˈhanːskar ɔ ˈdʉːkar ˈɪnːfœr ˈvarːjɛ nʏː bɛˈhanːdlɪŋ/" },
  { id: 55, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Pincetterna är rengjorda och redo för dagens pass.", vi: "Các cây nhíp đã được làm sạch và sẵn sàng cho ca làm hôm nay.", phonetic: "/pɪnˈsɛtːarːa ɛːr ˈreːnˌjuːrda ɔ ˈreːdu fœr ˈdɑːɡɛns pasː/" },
  { id: 56, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Vi håller arbetsstationen ren, organiserad och lugn.", vi: "Tụi mình giữ bàn làm việc sạch sẽ, gọn gàng và yên tĩnh.", phonetic: "/viː ˈhɔlːɛr ˈɑːrbɛtsˌstɑːˌɕuːnɛn reːn ɔrɡanɪˈseːrad ɔ lɵŋn/" },
  { id: 57, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Jag kontrollerar att limmet har rätt konsistens och fuktighet.", vi: "Mình kiểm tra xem keo có độ sệt và độ ẩm chuẩn chưa.", phonetic: "/jɑːɡ kɔntrɔˈleːrar at ˈlɪmːɛt hɑːr rɛt kɔnsɪsˈtɛnːs ɔ ˈfɵkːtɪˌheːt/" },
  { id: 58, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Engångsartiklar slängs i avsedd behållare direkt.", vi: "Đồ dùng một lần được bỏ vào thùng chuyên dụng ngay lập tức.", phonetic: "/ˈeːnˌɡɔŋsˌɑːrtɪklar slɛŋːs ɪ ˈɑːvˌsɛd bɛˈhɔlːarɛ dɪˈrɛkt/" },
  { id: 59, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Jag tvättar händerna noggrant före och efter varje moment.", vi: "Mình rửa tay kỹ trước và sau mỗi thao tác.", phonetic: "/jɑːɡ ˈtvɛtːar ˈhɛnːdarːa ˈnoːɡrant ˈfœːrɛ ɔ ˈɛfːtɛr ˈvarːjɛ mʊˈmɛnːt/" },
  { id: 60, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "All utrustning står på sin plats så arbetet flyter smidigt.", vi: "Mọi thiết bị đều đúng vị trí để công việc trôi chảy mượt mà.", phonetic: "/alː ˈʉːtˌrɵsːnɪŋ stoːr pɔː sɪn plats soː ɑrˈbeːtɛt ˈflʏːtɛr ˈsmiːdɪt/" },
  { id: 61, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Hur ser schemat ut för resten av veckan?", vi: "Lịch làm việc cho phần còn lại của tuần trông thế nào?", phonetic: "/hʉːr seːr ˈɕeːmat ʉːt fœr ˈrɛsːtɛn ɑːv ˈvɛkːan/" },
  { id: 62, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Jag har förberett allt inför nästa kund klocker ett.", vi: "Mình đã chuẩn bị xong mọi thứ cho khách tiếp theo lúc một giờ.", phonetic: "/jɑːɡ hɑːr ˈfœrːbɛrɛt alːt ˈɪnːfœr ˈnɛsːta kɵnd ˈklɔkːɛn ɛt/" },
  { id: 63, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Vi behöver beställa mer franslim och primer i veckan.", vi: "Tụi mình cần đặt thêm keo nối mi và primer trong tuần này.", phonetic: "/viː bɛˈhøːvɛr bɛˈstɛlːa meːr ˈfransˌliːm ɔ ˈpraɪmɛr ɪ ˈvɛkːan/" },
  { id: 64, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Kan du hjälpa mig att ta emot nästa kund i receptionen?", vi: "Bạn giúp mình đón khách tiếp theo ở quầy lễ tân được không?", phonetic: "/kan dʉː ˈjɛlːpa mej at tɑː ɛˈmʊːt ˈnɛsːta kɵnd ɪ rɛsɛpˈɕuːnɛn/" },
  { id: 65, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Vi samarbetar bra när vi stämmer av tiderna i förväg.", vi: "Tụi mình phối hợp nhịp nhàng khi rà soát giờ giấc từ trước.", phonetic: "/viː ˈsɑːmarˌbeːtar brɑː nɛːr viː ˈstɛmːɛr ɑːv ˈtiːdarːa ɪ fœrˈvɛːɡ/" },
  { id: 66, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Jag antecknar kundens önskemål direkt i bokningen.", vi: "Mình ghi chú mong muốn của khách thẳng vào lịch đặt.", phonetic: "/jɑːɡ ˈanːˌteːknar ˈkɵnːdɛns ˈœnːskɛˌmoːl dɪˈrɛkt ɪ ˈbuːknɪŋɛn/" },
  { id: 67, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Kunden blev jättenöjd med resultatet idag.", vi: "Khách hàng rất hài lòng với kết quả hôm nay.", phonetic: "/ˈkɵnːdɛn bleːv ˈjɛtːɛˌnœjd meːd rɛsɵlˈtɑːtɛt ɪˈdɑːɡ/" },
  { id: 68, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Vi städar av och fyller på förrådet innan vi stänger.", vi: "Tụi mình dọn dẹp và châm thêm đồ dự trữ trước khi đóng cửa.", phonetic: "/viː ˈstɛːdar ɑːv ɔ ˈfʏlːɛr pɔː fœˈroːdɛt ˈɪnːan viː ˈstɛŋːɛr/" },
  { id: 69, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Har någon avbokat sin tid på eftermiddagen?", vi: "Có ai hủy lịch buổi chiều nay không?", phonetic: "/hɑːr ˈnoːɡɔn ˈɑːvˌbuːkat sɪn tiːd pɔː ˈɛfːtɛrˌmɪdːaɡɛn/" },
  { id: 70, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Jag är redo att ta emot nästa bokning nu.", vi: "Mình đã sẵn sàng đón lượt đặt tiếp theo rồi.", phonetic: "/jɑːɡ ɛːr ˈreːdu at tɑː ɛˈmʊːt ˈnɛsːta ˈbuːknɪŋ nʉː/" },
  { id: 71, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Hur känns det nu när du ser dig i spegeln?", vi: "Giờ khi nhìn mình trong gương bạn thấy thế nào?", phonetic: "/hʉːr ɕɛnːs deː nʉː nɛːr dʉː seːr dej ɪ ˈspeːɡɛln/" },
  { id: 72, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Är det något jag kan justera lite till innan du går?", vi: "Có chỗ nào mình chỉnh thêm một chút trước khi bạn về không?", phonetic: "/ɛːr deː ˈnoːɡɔt jɑːɡ kan jɵsˈteːra ˈliːtɛ tɪl ˈɪnːan dʉː ɡoːr/" },
  { id: 73, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Betalningen går bra med kort eller Swish.", vi: "Thanh toán bằng thẻ hoặc Swish đều được nhé.", phonetic: "/bɛˈtɑːlnɪŋɛn ɡoːr brɑː meːd kɔʈ ˈɛlːɛr svɪʃ/" },
  { id: 74, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Här kommer kvittot. Varsågod!", vi: "Hóa đơn của bạn đây. Mời bạn nhận!", phonetic: "/hɛːr ˈkɔmːɛr ˈkvɪtːʊt ˈvɑːrʃɔˌɡuːd/" },
  { id: 75, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Tack för förtroendet och ha en riktigt fin dag!", vi: "Cảm ơn bạn đã tin tưởng và chúc bạn một ngày thật đẹp!", phonetic: "/tak fœr fœrˈtrʊːɛndɛt ɔ hɑː ɛn ˈrɪkːtɪt fiːn dɑːɡ/" },
  { id: 76, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Det var så roligt att få arbeta med dina naglar idag.", vi: "Hôm nay được làm móng cho bạn vui lắm luôn.", phonetic: "/deːt vɑːr soː ˈrʊːlɪt at foː ˈɑːrbɛta meːd ˈdiːna ˈnaɡːlar ɪˈdɑːɡ/" },
  { id: 77, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Glöm inte din väska och dina personliga saker.", vi: "Đừng quên túi xách và đồ cá nhân của bạn nhé.", phonetic: "/ɡlœm ˈɪnːtɛ diːn ˈvɛsːka ɔ ˈdiːna pɛʂʊnˈliːɡa ˈsɑːkɛr/" },
  { id: 78, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Vi finns här om du har några frågor hemma.", vi: "Tụi mình luôn ở đây nếu về nhà bạn có thắc mắc gì.", phonetic: "/viː fɪnːs hɛːr ɔm dʉː hɑːr ˈnoːɡra ˈfroːɡɔr ˈhɛmːa/" },
  { id: 79, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Ha en trevlig kväll och kör försiktigt hem!", vi: "Chúc bạn buổi tối vui vẻ và đi đường về cẩn thận nhé!", phonetic: "/hɑː ɛn ˈtreːvlɪɡ kvɛlː ɔ ɕœːr fœrˈsɪkːtɪt hɛm/" },
  { id: 80, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Välkommen tillbaka när du känner för det!", vi: "Chào mừng bạn quay lại bất cứ khi nào bạn muốn nhé!", phonetic: "/ˈvɛːlˌkɔmːɛn tɪlˈbɑːka nɛːr dʉː ˈɕɛnːɛr fœr deː/" },
  { id: 81, topic: "Đón tiếp khách hàng", sv: "När jag jobbar brukar jag säga: Hej! Välkommen till vår salong.", vi: "Khi làm việc mình hay nói: Xin chào! Chào mừng đến với tiệm của chúng tôi.", phonetic: "/hej ˈvɛːlˌkɔmːɛn tɪl voːr saˈlɔŋ/" },
  { id: 82, topic: "Đón tiếp khách hàng", sv: "Vid kundmottagning säger jag: God morgon! Hur mår du idag?", vi: "Khi đón tiếp mình nói: Chào buổi sáng! Hôm nay bạn cảm thấy thế nào?", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr moːr dʉː ɪˈdɑːɡ/" },
  { id: 83, topic: "Đón tiếp khách hàng", sv: "Under behandlingen säger jag lugnt: Hej och välkommen! Har du bokat tid?", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Xin chào và chào mừng! Bạn đã đặt lịch hẹn chưa?", phonetic: "/hej ɔ ˈvɛːlˌkɔmːɛn hɑːr dʉː ˈbuːkat tiːd/" },
  { id: 84, topic: "Đón tiếp khách hàng", sv: "Som nagel- och franstekniker säger jag: Varsågod och sitt ner här en stund.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Mời bạn ngồi xuống đây một lát.", phonetic: "/ˈvɑːrʃɔˌɡuːd ɔ sɪtː neːr hɛːr ɛn stɵnd/" },
  { id: 85, topic: "Đón tiếp khách hàng", sv: "I salongen säger jag ofta: Vad trevligt att se dig igen!", vi: "Trong tiệm mình thường nói: Thật vui được gặp lại bạn!", phonetic: "/vɑːd ˈtreːvlɪɡt at seː dej ɪˈjɛn/" },
  { id: 86, topic: "Đón tiếp khách hàng", sv: "När jag jobbar brukar jag säga: Välkommen in! Jag heter My Han och ska hjälpa dig idag.", vi: "Khi làm việc mình hay nói: Chào mừng vào tiệm! Mình tên là My Han và sẽ hỗ trợ bạn hôm nay.", phonetic: "/ˈvɛːlˌkɔmːɛn ɪn jɑːɡ ˈheːtɛr myː hɑn ɔ skɑː ˈjɛlːpa dej ɪˈdɑːɡ/" },
  { id: 87, topic: "Đón tiếp khách hàng", sv: "Vid kundmottagning säger jag: Hur var din dag hittills?", vi: "Khi đón tiếp mình nói: Ngày của bạn từ nãy đến giờ thế nào?", phonetic: "/hʉːr vɑːr diːn dɑːɡ ˈhɪtːɪls/" },
  { id: 88, topic: "Đón tiếp khách hàng", sv: "Under behandlingen säger jag lugnt: Jag är så glad att du kom hit idag.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Mình rất vui vì hôm nay bạn đã đến đây.", phonetic: "/jɑːɡ ɛːr soː ɡlɑːd at dʉː kɔm hɪt ɪˈdɑːɡ/" },
  { id: 89, topic: "Đón tiếp khách hàng", sv: "Som nagel- och franstekniker säger jag: Ta av dig jackan om du vill, så hänger jag upp den.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Bạn cởi áo khoác nếu muốn nhé, mình sẽ treo lên giúp.", phonetic: "/tɑː ɑːv dej ˈjakːan ɔm dʉː vɪl soː ˈhɛŋːɛr jɑːɡ ɵpː dɛn/" },
  { id: 90, topic: "Đón tiếp khách hàng", sv: "I salongen säger jag ofta: Känn dig som hemma här hos oss.", vi: "Trong tiệm mình thường nói: Hãy cứ tự nhiên như ở nhà khi ở chỗ tụi mình nhé.", phonetic: "/ɕɛnː dej sɔm ˈhɛmːa hɛːr huːs ɔsː/" },
  { id: 91, topic: "Mời nước khách", sv: "När jag jobbar brukar jag säga: Vill du ha något att dricka, kaffe eller vatten?", vi: "Khi làm việc mình hay nói: Bạn có muốn uống chút gì không, cà phê hay nước lọc?", phonetic: "/vɪl dʉː hɑː ˈnoːɡɔt at ˈdrɪkːa ˈkafːɛ ˈɛlːɛr ˈvatːɛn/" },
  { id: 92, topic: "Mời nước khách", sv: "Vid kundmottagning säger jag: Vill du ha ett glas kallt vatten medan du väntar?", vi: "Khi đón tiếp mình nói: Bạn có muốn một ly nước lạnh trong lúc chờ không?", phonetic: "/vɪl dʉː hɑː ɛt ɡlɑːs kalːt ˈvatːɛn ˈmeːdan dʉː ˈvɛnːtar/" },
  { id: 93, topic: "Mời nước khách", sv: "Under behandlingen säger jag lugnt: Jag kan bjuda på te eller kaffe om du önskar.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Mình có thể mời trà hoặc cà phê nếu bạn muốn.", phonetic: "/jɑːɡ kan ˈbjʉːda pɔː teː ˈɛlːɛr ˈkafːɛ ɔm dʉː ˈœnːskar/" },
  { id: 94, topic: "Mời nước khách", sv: "Som nagel- och franstekniker säger jag: Föredrar du varmt eller kallt vatten?", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Bạn thích nước ấm hay nước lạnh hơn?", phonetic: "/ˌfœrɛˈdrɑːr dʉː varmt ˈɛlːɛr kalːt ˈvatːɛn/" },
  { id: 95, topic: "Mời nước khách", sv: "I salongen säger jag ofta: Ska jag hälla upp lite te åt dig?", vi: "Trong tiệm mình thường nói: Mình rót thêm chút trà cho bạn nhé?", phonetic: "/skɑː jɑːɡ ˈhɛlːa ɵpː ˈliːtɛ teː oːt dej/" },
  { id: 96, topic: "Mời nước khách", sv: "När jag jobbar brukar jag säga: Här kommer ditt vatten. Varsågod!", vi: "Khi làm việc mình hay nói: Nước của bạn đây. Mời bạn dùng!", phonetic: "/hɛːr ˈkɔmːɛr dɪt ˈvatːɛn ˈvɑːrʃɔˌɡuːd/" },
  { id: 97, topic: "Mời nước khách", sv: "Vid kundmottagning säger jag: Vill du ha socker eller mjölk i kaffet?", vi: "Khi đón tiếp mình nói: Bạn có muốn thêm đường hay sữa vào cà phê không?", phonetic: "/vɪl dʉː hɑː ˈsɔkːɛr ˈɛlːɛr mjœlk ɪ ˈkafːɛt/" },
  { id: 98, topic: "Mời nước khách", sv: "Under behandlingen säger jag lugnt: Jag fixar en kopp varmt te direkt.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Mình pha một tách trà nóng ngay đây.", phonetic: "/jɑːɡ ˈfɪkːsar ɛn kɔpː varmt teː dɪˈrɛkt/" },
  { id: 99, topic: "Mời nước khách", sv: "Som nagel- och franstekniker säger jag: Vill du ha en liten kaka till kaffet?", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Bạn có muốn ăn thêm một chiếc bánh nhỏ kèm cà phê không?", phonetic: "/vɪl dʉː hɑː ɛn ˈliːtɛn ˈkɑːka tɪl ˈkafːɛt/" },
  { id: 100, topic: "Mời nước khách", sv: "I salongen säger jag ofta: Säg bara till om du vill ha påfyllning.", vi: "Trong tiệm mình thường nói: Cứ bảo mình nếu bạn muốn châm thêm nhé.", phonetic: "/sɛːj ˈbɑːra tɪl ɔm dʉː vɪl hɑː ˈpoːˌfʏlːnɪŋ/" },
  { id: 101, topic: "Thao tác nối mi / Spa", sv: "När jag jobbar brukar jag säga: Blunda och slappna av nu.", vi: "Khi làm việc mình hay nói: Hãy nhắm mắt lại và thư giãn nhé.", phonetic: "/ˈblɵnːda ɔ ˈslapːna ɑːv nʉː/" },
  { id: 102, topic: "Thao tác nối mi / Spa", sv: "Vid kundmottagning säger jag: Känns det bra och bekvämt på britsen?", vi: "Khi đón tiếp mình nói: Nằm trên giường liệu trình có thấy thoải mái không?", phonetic: "/ɕɛnːs deː brɑː ɔ bɛˈkvɛːmt pɔː brɪtːsɛn/" },
  { id: 103, topic: "Thao tác nối mi / Spa", sv: "Under behandlingen säger jag lugnt: Jag sätter på en mjuk ögonpad under fransarna nu.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Bây giờ mình dán miếng lót mắt mềm dưới hàng mi nhé.", phonetic: "/jɑːɡ ˈsɛtːɛr pɔː ɛn mjʉːk ˈœːɡɔnˌpad ɵnːdɛr ˈfranːsarːa nʉː/" },
  { id: 104, topic: "Thao tác nối mi / Spa", sv: "Som nagel- och franstekniker säger jag: Säg till direkt om det svider eller sticker till.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Báo ngay cho mình nếu thấy cay hoặc châm chích nhé.", phonetic: "/sɛːj tɪl dɪˈrɛkt ɔm deː ˈsviːdɛr ˈɛlːɛr ˈstɪkːɛr tɪl/" },
  { id: 105, topic: "Thao tác nối mi / Spa", sv: "I salongen säger jag ofta: Vi börjar med att rengöra fransarna noga.", vi: "Trong tiệm mình thường nói: Tụi mình bắt đầu bằng việc làm sạch mi thật kỹ.", phonetic: "/viː ˈbœrːjar meːd at ˈreːnˌjœːra ˈfranːsarːa ˈnoːɡa/" },
  { id: 106, topic: "Thao tác nối mi / Spa", sv: "När jag jobbar brukar jag säga: Nu applicerar jag limmet försiktigt på varje frans.", vi: "Khi làm việc mình hay nói: Giờ mình gắn keo cẩn thận lên từng sợi mi.", phonetic: "/nʉː ˌapːlɪˈseːrar jɑːɡ ˈlɪmːɛt fœrˈsɪkːtɪt pɔː ˈvarːjɛ frans/" },
  { id: 107, topic: "Thao tác nối mi / Spa", sv: "Vid kundmottagning säger jag: Känns tejpningen för stram på något ställe?", vi: "Khi đón tiếp mình nói: Miếng băng dán có bị căng ở chỗ nào không?", phonetic: "/ɕɛnːs ˈtɛjpnɪŋɛn fœr stram pɔː ˈnoːɡɔt ˈstɛlːɛ/" },
  { id: 108, topic: "Thao tác nối mi / Spa", sv: "Under behandlingen säger jag lugnt: Jag masserar hårbotten med lugna rörelser nu.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Bây giờ mình massage da đầu với các động tác nhẹ nhàng nhé.", phonetic: "/jɑːɡ maˈseːrar ˈhoːrˌbɔtːɛn meːd ˈlɵɡːna ˈrœːrɛlsɛr nʉː/" },
  { id: 109, topic: "Thao tác nối mi / Spa", sv: "Som nagel- och franstekniker säger jag: Är vattnet lagom varmt när jag sköljer håret?", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Nước có vừa độ ấm khi mình xả tóc không?", phonetic: "/ɛːr ˈvatːnɛt ˈlɑːɡɔm varmt nɛːr jɑːɡ ˈɕœlːjɛr ˈhoːrɛt/" },
  { id: 110, topic: "Thao tác nối mi / Spa", sv: "I salongen säger jag ofta: Nu är vi klara med behandlingen. Öppna ögonen sakta.", vi: "Trong tiệm mình thường nói: Xong liệu trình rồi đây. Bạn mở mắt từ từ nhé.", phonetic: "/nʉː ɛːr viː ˈklɑːra meːd bɛˈhanːdlɪŋɛn ˈœpːna ˈœːɡɔnɛn ˈsakːta/" },
  { id: 111, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "När jag jobbar brukar jag säga: Vilken stil gillar du mest, naturlig eller volym?", vi: "Khi làm việc mình hay nói: Bạn thích kiểu nào nhất, tự nhiên hay dày vol?", phonetic: "/ˈvɪlːkɛn stiːl ˈjɪlːar dʉː mɛst nɑtʉːˈliːr ˈɛlːɛr vɔˈlʏːm/" },
  { id: 112, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vid kundmottagning säger jag: Vill du ha en öppen docköga eller en mjuk kattöga?", vi: "Khi đón tiếp mình nói: Bạn muốn dáng mắt búp bê tròn to hay dáng mắt mèo dịu dàng?", phonetic: "/vɪl dʉː hɑː ɛn ˈœpːɛn ˈdɔkˌœːɡa ˈɛlːɛr ɛn mjʉːk ˈkatˌœːɡa/" },
  { id: 113, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Under behandlingen säger jag lugnt: Jag rekommenderar en lite kortare längd innerst.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Mình khuyên nên chọn độ dài ngắn hơn một chút ở góc trong.", phonetic: "/jɑːɡ ˌrɛkɔmɛnˈdeːrar ɛn ˈliːtɛ ˈkɔrːtarɛ lɛŋd ˈɪnːɛrst/" },
  { id: 114, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Som nagel- och franstekniker säger jag: Vill du ha mandelformade, fyrkantiga eller runda naglar?", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Bạn muốn móng dáng hạnh nhân, móng vuông hay móng tròn?", phonetic: "/vɪl dʉː hɑː ˈmanːdɛlˌfɔrmadɛ ˈfʏrˌkantɪɡa ˈɛlːɛr ˈrɵnːda ˈnaɡːlar/" },
  { id: 115, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "I salongen säger jag ofta: Den här nyansen passar väldigt fint till din hudton.", vi: "Trong tiệm mình thường nói: Tông màu này hợp với sắc da của bạn lắm đấy.", phonetic: "/deːn hɛːr nʏˈanːsɛn ˈpasːar ˈvɛlːdɪt fɪnt tɪl diːn ˈhʉːdˌtuːn/" },
  { id: 116, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "När jag jobbar brukar jag säga: Vi kan göra gel, förstärkning med builder gel eller akryl.", vi: "Khi làm việc mình hay nói: Tụi mình có thể làm gel, đắp gel cứng hoặc đắp bột.", phonetic: "/viː kan ˈjœːra jeːl fœrˈstɛrkːnɪŋ meːd ˈbɪlːdɛr jeːl ˈɛlːɛr ɑˈkrʏːl/" },
  { id: 117, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vid kundmottagning säger jag: Vill du ha enfärgat, fransk manikyr eller chrome?", vi: "Khi đón tiếp mình nói: Bạn muốn sơn một màu, kiểu Pháp hay hiệu ứng chrome?", phonetic: "/vɪl dʉː hɑː ˈeːnˌfɛrɡat fransk mɑnɪˈkʏːr ˈɛlːɛr kroːm/" },
  { id: 118, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Under behandlingen säger jag lugnt: Jag anpassar böjen efter dina naturliga fransar.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Mình điều chỉnh độ cong theo hàng mi thật của bạn.", phonetic: "/jɑːɡ ˈanːpasːar ˈbœjːɛn ˈɛfːtɛr ˈdiːna nɑtʉːˈliːra ˈfranːsar/" },
  { id: 119, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Som nagel- och franstekniker säger jag: Det är bäst att skona dina egna fransar så de håller sig friska.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Tốt nhất là giữ gìn mi thật để mi luôn khỏe mạnh.", phonetic: "/deːt ɛːr bɛst at ˈskuːna ˈdiːna ˈeːɡːna ˈfranːsar soː deː ˈhɔlːɛr sej ˈfrɪsːka/" },
  { id: 120, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "I salongen säger jag ofta: Ska vi lägga till en djupgående fuktkur för händerna idag?", vi: "Trong tiệm mình thường nói: Hôm nay mình thêm bước dưỡng ẩm sâu cho tay nhé?", phonetic: "/skɑː viː ˈlɛɡːa tɪl ɛn ˈjʉːpˌɡoːɛnːdɛ ˈfɵktˌkʉːr fœr ˈhɛnːdarːa ɪˈdɑːɡ/" },
  { id: 121, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "När jag jobbar brukar jag säga: Undvik vatten och ånga på fransarna de första tjugofyra timmarna.", vi: "Khi làm việc mình hay nói: Tránh nước và hơi nóng lên mi trong hai mươi bốn giờ đầu nhé.", phonetic: "/ˈɵnːdviːk ˈvatːɛn ɔ ˈɔŋːa pɔː ˈfranːsarːa deː ˈfœsːta ˈɕʉːɡʊˌfyːra ˈtɪmːarːa/" },
  { id: 122, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Vid kundmottagning säger jag: Gnugga inte ögonen och använd oljefria produkter.", vi: "Khi đón tiếp mình nói: Đừng dụi mắt và hãy dùng sản phẩm không chứa dầu nhé.", phonetic: "/ˈɡnɵɡːa ˈɪnːtɛ ˈœːɡɔnɛn ɔ ˈanːvɛnd ˈɔlːjɛˌfriːa prʊˈdɵkːtɛr/" },
  { id: 123, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Under behandlingen säger jag lugnt: Borsta fransarna försiktigt varje morgon med borsten du får.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Chải mi nhẹ nhàng mỗi sáng bằng cọ được tặng kèm nhé.", phonetic: "/ˈbɔʂːta ˈfranːsarːa fœrˈsɪkːtɪt ˈvarːjɛ ˈmɔrːɔn meːd ˈbɔʂːtɛn dʉː fɔːr/" },
  { id: 124, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Som nagel- och franstekniker säger jag: Det är dags för påfyllning om ungefär tre veckor.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Khoảng ba tuần nữa là tới lúc dặm lại rồi đấy.", phonetic: "/deːt ɛːr daks fœr ˈpoːˌfʏlːnɪŋ ɔm ɵnːfɛˈjɛːr treː ˈvɛkːɔr/" },
  { id: 125, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "I salongen säger jag ofta: Smörj nagelbanden med nagelolja varje kväll.", vi: "Trong tiệm mình thường nói: Thoa dầu dưỡng viền móng mỗi tối nhé.", phonetic: "/smœrj ˈnɑːɡɛlˌbanːdɛn meːd ˈnɑːɡɛlˌɔlːja ˈvarːjɛ kvɛlː/" },
  { id: 126, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "När jag jobbar brukar jag säga: Använd gärna handskar när du diskar eller städar.", vi: "Khi làm việc mình hay nói: Bạn nhớ đeo găng tay khi rửa chén hoặc dọn dẹp nhé.", phonetic: "/ˈanːvɛnd ˈjɛːrna ˈhanːskar nɛːr dʉː ˈdɪsːkar ˈɛlːɛr ˈstɛːdar/" },
  { id: 127, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Vid kundmottagning säger jag: Vill du boka nästa tid redan innan du går idag?", vi: "Khi đón tiếp mình nói: Bạn có muốn đặt lịch lần tới ngay trước khi về hôm nay không?", phonetic: "/vɪl dʉː ˈbuːka ˈnɛsːta tiːd ˈreːdan ˈɪnːan dʉː ɡoːr ɪˈdɑːɡ/" },
  { id: 128, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Under behandlingen säger jag lugnt: Vi har en ledig tid på tisdag klockan tio.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Tụi mình còn trống lịch vào thứ ba lúc mười giờ.", phonetic: "/viː hɑːr ɛn ˈleːdɪɡ tiːd pɔː ˈtɪsːdɑːɡ ˈklɔkːan ˈtiːʊ/" },
  { id: 129, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Som nagel- och franstekniker säger jag: Jag skickar en påminnelse dagen innan din tid.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Mình sẽ gửi tin nhắn nhắc lịch trước ngày hẹn một ngày.", phonetic: "/jɑːɡ ˈɕɪkːar ɛn ˈpoːˌmɪnːɛlsɛ ˈdɑːɡɛn ˈɪnːan diːn tiːd/" },
  { id: 130, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "I salongen säger jag ofta: Tack så mycket för besöket! Vi ses nästa gång.", vi: "Trong tiệm mình thường nói: Cảm ơn bạn rất nhiều vì đã ghé tiệm! Hẹn gặp lại lần sau nhé.", phonetic: "/tak soː ˈmʏkːɛt fœr bɛˈsøːkɛt viː seːs ˈnɛsːta ɡɔŋ/" },
  { id: 131, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "När jag jobbar brukar jag säga: Jag desinficerar alla verktyg mellan varje kund.", vi: "Khi làm việc mình hay nói: Mình khử trùng toàn bộ dụng cụ giữa mỗi khách hàng.", phonetic: "/jɑːɡ dɛsɪnfɪˈseːrar ˈalːa ˈvɛrkˌtʏːɡ ˈmɛlːan ˈvarːjɛ kɵnd/" },
  { id: 132, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Vid kundmottagning säger jag: Vi följer säkerhetsrutiner för härdplast och lim.", vi: "Khi đón tiếp mình nói: Tụi mình tuân thủ quy trình an toàn với nhựa cứng và keo.", phonetic: "/viː ˈfœlːjɛr ˈsɛːkɛrˌheːtsrɵˌtiːnɛr fœr ˈhɛːrdˌplast ɔ liːm/" },
  { id: 133, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Under behandlingen säger jag lugnt: Jag arbetar i ett välventilerat rum med punktutsug.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Mình làm việc trong phòng thông thoáng có máy hút khí cục bộ.", phonetic: "/jɑːɡ ˈɑːrbɛtar ɪ ɛt ˈvɛːlˌvɛntɪˌleːrat rɵm meːd ˈpɵŋktˌʉːtsʉːɡ/" },
  { id: 134, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Som nagel- och franstekniker säger jag: Jag byter handskar och dukar inför varje ny behandling.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Mình thay găng tay và khăn trải trước mỗi liệu trình mới.", phonetic: "/jɑːɡ ˈbʏːtɛr ˈhanːskar ɔ ˈdʉːkar ˈɪnːfœr ˈvarːjɛ nʏː bɛˈhanːdlɪŋ/" },
  { id: 135, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "I salongen säger jag ofta: Pincetterna är rengjorda och redo för dagens pass.", vi: "Trong tiệm mình thường nói: Các cây nhíp đã được làm sạch và sẵn sàng cho ca làm hôm nay.", phonetic: "/pɪnˈsɛtːarːa ɛːr ˈreːnˌjuːrda ɔ ˈreːdu fœr ˈdɑːɡɛns pasː/" },
  { id: 136, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "När jag jobbar brukar jag säga: Vi håller arbetsstationen ren, organiserad och lugn.", vi: "Khi làm việc mình hay nói: Tụi mình giữ bàn làm việc sạch sẽ, gọn gàng và yên tĩnh.", phonetic: "/viː ˈhɔlːɛr ˈɑːrbɛtsˌstɑːˌɕuːnɛn reːn ɔrɡanɪˈseːrad ɔ lɵŋn/" },
  { id: 137, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Vid kundmottagning säger jag: Jag kontrollerar att limmet har rätt konsistens och fuktighet.", vi: "Khi đón tiếp mình nói: Mình kiểm tra xem keo có độ sệt và độ ẩm chuẩn chưa.", phonetic: "/jɑːɡ kɔntrɔˈleːrar at ˈlɪmːɛt hɑːr rɛt kɔnsɪsˈtɛnːs ɔ ˈfɵkːtɪˌheːt/" },
  { id: 138, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Under behandlingen säger jag lugnt: Engångsartiklar slängs i avsedd behållare direkt.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Đồ dùng một lần được bỏ vào thùng chuyên dụng ngay lập tức.", phonetic: "/ˈeːnˌɡɔŋsˌɑːrtɪklar slɛŋːs ɪ ˈɑːvˌsɛd bɛˈhɔlːarɛ dɪˈrɛkt/" },
  { id: 139, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Som nagel- och franstekniker säger jag: Jag tvättar händerna noggrant före och efter varje moment.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Mình rửa tay kỹ trước và sau mỗi thao tác.", phonetic: "/jɑːɡ ˈtvɛtːar ˈhɛnːdarːa ˈnoːɡrant ˈfœːrɛ ɔ ˈɛfːtɛr ˈvarːjɛ mʊˈmɛnːt/" },
  { id: 140, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "I salongen säger jag ofta: All utrustning står på sin plats så arbetet flyter smidigt.", vi: "Trong tiệm mình thường nói: Mọi thiết bị đều đúng vị trí để công việc trôi chảy mượt mà.", phonetic: "/alː ˈʉːtˌrɵsːnɪŋ stoːr pɔː sɪn plats soː ɑrˈbeːtɛt ˈflʏːtɛr ˈsmiːdɪt/" },
  { id: 141, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "När jag jobbar brukar jag säga: Hur ser schemat ut för resten av veckan?", vi: "Khi làm việc mình hay nói: Lịch làm việc cho phần còn lại của tuần trông thế nào?", phonetic: "/hʉːr seːr ˈɕeːmat ʉːt fœr ˈrɛsːtɛn ɑːv ˈvɛkːan/" },
  { id: 142, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Vid kundmottagning säger jag: Jag har förberett allt inför nästa kund klocker ett.", vi: "Khi đón tiếp mình nói: Mình đã chuẩn bị xong mọi thứ cho khách tiếp theo lúc một giờ.", phonetic: "/jɑːɡ hɑːr ˈfœrːbɛrɛt alːt ˈɪnːfœr ˈnɛsːta kɵnd ˈklɔkːɛn ɛt/" },
  { id: 143, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Under behandlingen säger jag lugnt: Vi behöver beställa mer franslim och primer i veckan.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Tụi mình cần đặt thêm keo nối mi và primer trong tuần này.", phonetic: "/viː bɛˈhøːvɛr bɛˈstɛlːa meːr ˈfransˌliːm ɔ ˈpraɪmɛr ɪ ˈvɛkːan/" },
  { id: 144, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Som nagel- och franstekniker säger jag: Kan du hjälpa mig att ta emot nästa kund i receptionen?", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Bạn giúp mình đón khách tiếp theo ở quầy lễ tân được không?", phonetic: "/kan dʉː ˈjɛlːpa mej at tɑː ɛˈmʊːt ˈnɛsːta kɵnd ɪ rɛsɛpˈɕuːnɛn/" },
  { id: 145, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "I salongen säger jag ofta: Vi samarbetar bra när vi stämmer av tiderna i förväg.", vi: "Trong tiệm mình thường nói: Tụi mình phối hợp nhịp nhàng khi rà soát giờ giấc từ trước.", phonetic: "/viː ˈsɑːmarˌbeːtar brɑː nɛːr viː ˈstɛmːɛr ɑːv ˈtiːdarːa ɪ fœrˈvɛːɡ/" },
  { id: 146, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "När jag jobbar brukar jag säga: Jag antecknar kundens önskemål direkt i bokningen.", vi: "Khi làm việc mình hay nói: Mình ghi chú mong muốn của khách thẳng vào lịch đặt.", phonetic: "/jɑːɡ ˈanːˌteːknar ˈkɵnːdɛns ˈœnːskɛˌmoːl dɪˈrɛkt ɪ ˈbuːknɪŋɛn/" },
  { id: 147, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Vid kundmottagning säger jag: Kunden blev jättenöjd med resultatet idag.", vi: "Khi đón tiếp mình nói: Khách hàng rất hài lòng với kết quả hôm nay.", phonetic: "/ˈkɵnːdɛn bleːv ˈjɛtːɛˌnœjd meːd rɛsɵlˈtɑːtɛt ɪˈdɑːɡ/" },
  { id: 148, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Under behandlingen säger jag lugnt: Vi städar av och fyller på förrådet innan vi stänger.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Tụi mình dọn dẹp và châm thêm đồ dự trữ trước khi đóng cửa.", phonetic: "/viː ˈstɛːdar ɑːv ɔ ˈfʏlːɛr pɔː fœˈroːdɛt ˈɪnːan viː ˈstɛŋːɛr/" },
  { id: 149, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Som nagel- och franstekniker säger jag: Har någon avbokat sin tid på eftermiddagen?", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Có ai hủy lịch buổi chiều nay không?", phonetic: "/hɑːr ˈnoːɡɔn ˈɑːvˌbuːkat sɪn tiːd pɔː ˈɛfːtɛrˌmɪdːaɡɛn/" },
  { id: 150, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "I salongen säger jag ofta: Jag är redo att ta emot nästa bokning nu.", vi: "Trong tiệm mình thường nói: Mình đã sẵn sàng đón lượt đặt tiếp theo rồi.", phonetic: "/jɑːɡ ɛːr ˈreːdu at tɑː ɛˈmʊːt ˈnɛsːta ˈbuːknɪŋ nʉː/" },
  { id: 151, topic: "Phản hồi, thanh toán & chia tay khách", sv: "När jag jobbar brukar jag säga: Hur känns det nu när du ser dig i spegeln?", vi: "Khi làm việc mình hay nói: Giờ khi nhìn mình trong gương bạn thấy thế nào?", phonetic: "/hʉːr ɕɛnːs deː nʉː nɛːr dʉː seːr dej ɪ ˈspeːɡɛln/" },
  { id: 152, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Vid kundmottagning säger jag: Är det något jag kan justera lite till innan du går?", vi: "Khi đón tiếp mình nói: Có chỗ nào mình chỉnh thêm một chút trước khi bạn về không?", phonetic: "/ɛːr deː ˈnoːɡɔt jɑːɡ kan jɵsˈteːra ˈliːtɛ tɪl ˈɪnːan dʉː ɡoːr/" },
  { id: 153, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Under behandlingen säger jag lugnt: Betalningen går bra med kort eller Swish.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Thanh toán bằng thẻ hoặc Swish đều được nhé.", phonetic: "/bɛˈtɑːlnɪŋɛn ɡoːr brɑː meːd kɔʈ ˈɛlːɛr svɪʃ/" },
  { id: 154, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Som nagel- och franstekniker säger jag: Här kommer kvittot. Varsågod!", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Hóa đơn của bạn đây. Mời bạn nhận!", phonetic: "/hɛːr ˈkɔmːɛr ˈkvɪtːʊt ˈvɑːrʃɔˌɡuːd/" },
  { id: 155, topic: "Phản hồi, thanh toán & chia tay khách", sv: "I salongen säger jag ofta: Tack för förtroendet och ha en riktigt fin dag!", vi: "Trong tiệm mình thường nói: Cảm ơn bạn đã tin tưởng và chúc bạn một ngày thật đẹp!", phonetic: "/tak fœr fœrˈtrʊːɛndɛt ɔ hɑː ɛn ˈrɪkːtɪt fiːn dɑːɡ/" },
  { id: 156, topic: "Phản hồi, thanh toán & chia tay khách", sv: "När jag jobbar brukar jag säga: Det var så roligt att få arbeta med dina naglar idag.", vi: "Khi làm việc mình hay nói: Hôm nay được làm móng cho bạn vui lắm luôn.", phonetic: "/deːt vɑːr soː ˈrʊːlɪt at foː ˈɑːrbɛta meːd ˈdiːna ˈnaɡːlar ɪˈdɑːɡ/" },
  { id: 157, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Vid kundmottagning säger jag: Glöm inte din väska och dina personliga saker.", vi: "Khi đón tiếp mình nói: Đừng quên túi xách và đồ cá nhân của bạn nhé.", phonetic: "/ɡlœm ˈɪnːtɛ diːn ˈvɛsːka ɔ ˈdiːna pɛʂʊnˈliːɡa ˈsɑːkɛr/" },
  { id: 158, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Under behandlingen säger jag lugnt: Vi finns här om du har några frågor hemma.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Tụi mình luôn ở đây nếu về nhà bạn có thắc mắc gì.", phonetic: "/viː fɪnːs hɛːr ɔm dʉː hɑːr ˈnoːɡra ˈfroːɡɔr ˈhɛmːa/" },
  { id: 159, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Som nagel- och franstekniker säger jag: Ha en trevlig kväll och kör försiktigt hem!", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Chúc bạn buổi tối vui vẻ và đi đường về cẩn thận nhé!", phonetic: "/hɑː ɛn ˈtreːvlɪɡ kvɛlː ɔ ɕœːr fœrˈsɪkːtɪt hɛm/" },
  { id: 160, topic: "Phản hồi, thanh toán & chia tay khách", sv: "I salongen säger jag ofta: Välkommen tillbaka när du känner för det!", vi: "Trong tiệm mình thường nói: Chào mừng bạn quay lại bất cứ khi nào bạn muốn nhé!", phonetic: "/ˈvɛːlˌkɔmːɛn tɪlˈbɑːka nɛːr dʉː ˈɕɛnːɛr fœr deː/" },
  { id: 161, topic: "Đón tiếp khách hàng", sv: "Hej! Välkommen till vår salong. Det hjälper kunden att slappna av.", vi: "Xin chào! Chào mừng đến với tiệm của chúng tôi. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/hej ˈvɛːlˌkɔmːɛn tɪl voːr saˈlɔŋ/" },
  { id: 162, topic: "Đón tiếp khách hàng", sv: "God morgon! Hur mår du idag? Det är en viktig del av god service.", vi: "Chào buổi sáng! Hôm nay bạn cảm thấy thế nào? Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr moːr dʉː ɪˈdɑːɡ/" },
  { id: 163, topic: "Đón tiếp khách hàng", sv: "Hej och välkommen! Har du bokat tid? Det gör samtalet tydligt och vänligt.", vi: "Xin chào và chào mừng! Bạn đã đặt lịch hẹn chưa? Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/hej ɔ ˈvɛːlˌkɔmːɛn hɑːr dʉː ˈbuːkat tiːd/" },
  { id: 164, topic: "Đón tiếp khách hàng", sv: "Varsågod och sitt ner här en stund. Det känns naturligt och artigt.", vi: "Mời bạn ngồi xuống đây một lát. Câu này nghe tự nhiên và lịch sự.", phonetic: "/ˈvɑːrʃɔˌɡuːd ɔ sɪtː neːr hɛːr ɛn stɵnd/" },
  { id: 165, topic: "Đón tiếp khách hàng", sv: "Vad trevligt att se dig igen! Det skapar en trygg stämning.", vi: "Thật vui được gặp lại bạn! Cách nói này tạo cảm giác an tâm.", phonetic: "/vɑːd ˈtreːvlɪɡt at seː dej ɪˈjɛn/" },
  { id: 166, topic: "Đón tiếp khách hàng", sv: "Välkommen in! Jag heter My Han och ska hjälpa dig idag. Det hjälper kunden att slappna av.", vi: "Chào mừng vào tiệm! Mình tên là My Han và sẽ hỗ trợ bạn hôm nay. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/ˈvɛːlˌkɔmːɛn ɪn jɑːɡ ˈheːtɛr myː hɑn ɔ skɑː ˈjɛlːpa dej ɪˈdɑːɡ/" },
  { id: 167, topic: "Đón tiếp khách hàng", sv: "Hur var din dag hittills? Det är en viktig del av god service.", vi: "Ngày của bạn từ nãy đến giờ thế nào? Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/hʉːr vɑːr diːn dɑːɡ ˈhɪtːɪls/" },
  { id: 168, topic: "Đón tiếp khách hàng", sv: "Jag är så glad att du kom hit idag. Det gör samtalet tydligt och vänligt.", vi: "Mình rất vui vì hôm nay bạn đã đến đây. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/jɑːɡ ɛːr soː ɡlɑːd at dʉː kɔm hɪt ɪˈdɑːɡ/" },
  { id: 169, topic: "Đón tiếp khách hàng", sv: "Ta av dig jackan om du vill, så hänger jag upp den. Det känns naturligt och artigt.", vi: "Bạn cởi áo khoác nếu muốn nhé, mình sẽ treo lên giúp. Câu này nghe tự nhiên và lịch sự.", phonetic: "/tɑː ɑːv dej ˈjakːan ɔm dʉː vɪl soː ˈhɛŋːɛr jɑːɡ ɵpː dɛn/" },
  { id: 170, topic: "Đón tiếp khách hàng", sv: "Känn dig som hemma här hos oss. Det skapar en trygg stämning.", vi: "Hãy cứ tự nhiên như ở nhà khi ở chỗ tụi mình nhé. Cách nói này tạo cảm giác an tâm.", phonetic: "/ɕɛnː dej sɔm ˈhɛmːa hɛːr huːs ɔsː/" },
  { id: 171, topic: "Mời nước khách", sv: "Vill du ha något att dricka, kaffe eller vatten? Det hjälper kunden att slappna av.", vi: "Bạn có muốn uống chút gì không, cà phê hay nước lọc? Điều này giúp khách dễ thư giãn hơn.", phonetic: "/vɪl dʉː hɑː ˈnoːɡɔt at ˈdrɪkːa ˈkafːɛ ˈɛlːɛr ˈvatːɛn/" },
  { id: 172, topic: "Mời nước khách", sv: "Vill du ha ett glas kallt vatten medan du väntar? Det är en viktig del av god service.", vi: "Bạn có muốn một ly nước lạnh trong lúc chờ không? Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/vɪl dʉː hɑː ɛt ɡlɑːs kalːt ˈvatːɛn ˈmeːdan dʉː ˈvɛnːtar/" },
  { id: 173, topic: "Mời nước khách", sv: "Jag kan bjuda på te eller kaffe om du önskar. Det gör samtalet tydligt och vänligt.", vi: "Mình có thể mời trà hoặc cà phê nếu bạn muốn. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/jɑːɡ kan ˈbjʉːda pɔː teː ˈɛlːɛr ˈkafːɛ ɔm dʉː ˈœnːskar/" },
  { id: 174, topic: "Mời nước khách", sv: "Föredrar du varmt eller kallt vatten? Det känns naturligt och artigt.", vi: "Bạn thích nước ấm hay nước lạnh hơn? Câu này nghe tự nhiên và lịch sự.", phonetic: "/ˌfœrɛˈdrɑːr dʉː varmt ˈɛlːɛr kalːt ˈvatːɛn/" },
  { id: 175, topic: "Mời nước khách", sv: "Ska jag hälla upp lite te åt dig? Det skapar en trygg stämning.", vi: "Mình rót thêm chút trà cho bạn nhé? Cách nói này tạo cảm giác an tâm.", phonetic: "/skɑː jɑːɡ ˈhɛlːa ɵpː ˈliːtɛ teː oːt dej/" },
  { id: 176, topic: "Mời nước khách", sv: "Här kommer ditt vatten. Varsågod! Det hjälper kunden att slappna av.", vi: "Nước của bạn đây. Mời bạn dùng! Điều này giúp khách dễ thư giãn hơn.", phonetic: "/hɛːr ˈkɔmːɛr dɪt ˈvatːɛn ˈvɑːrʃɔˌɡuːd/" },
  { id: 177, topic: "Mời nước khách", sv: "Vill du ha socker eller mjölk i kaffet? Det är en viktig del av god service.", vi: "Bạn có muốn thêm đường hay sữa vào cà phê không? Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/vɪl dʉː hɑː ˈsɔkːɛr ˈɛlːɛr mjœlk ɪ ˈkafːɛt/" },
  { id: 178, topic: "Mời nước khách", sv: "Jag fixar en kopp varmt te direkt. Det gör samtalet tydligt och vänligt.", vi: "Mình pha một tách trà nóng ngay đây. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/jɑːɡ ˈfɪkːsar ɛn kɔpː varmt teː dɪˈrɛkt/" },
  { id: 179, topic: "Mời nước khách", sv: "Vill du ha en liten kaka till kaffet? Det känns naturligt och artigt.", vi: "Bạn có muốn ăn thêm một chiếc bánh nhỏ kèm cà phê không? Câu này nghe tự nhiên và lịch sự.", phonetic: "/vɪl dʉː hɑː ɛn ˈliːtɛn ˈkɑːka tɪl ˈkafːɛt/" },
  { id: 180, topic: "Mời nước khách", sv: "Säg bara till om du vill ha påfyllning. Det skapar en trygg stämning.", vi: "Cứ bảo mình nếu bạn muốn châm thêm nhé. Cách nói này tạo cảm giác an tâm.", phonetic: "/sɛːj ˈbɑːra tɪl ɔm dʉː vɪl hɑː ˈpoːˌfʏlːnɪŋ/" },
  { id: 181, topic: "Thao tác nối mi / Spa", sv: "Blunda och slappna av nu. Det hjälper kunden att slappna av.", vi: "Hãy nhắm mắt lại và thư giãn nhé. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/ˈblɵnːda ɔ ˈslapːna ɑːv nʉː/" },
  { id: 182, topic: "Thao tác nối mi / Spa", sv: "Känns det bra och bekvämt på britsen? Det är en viktig del av god service.", vi: "Nằm trên giường liệu trình có thấy thoải mái không? Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/ɕɛnːs deː brɑː ɔ bɛˈkvɛːmt pɔː brɪtːsɛn/" },
  { id: 183, topic: "Thao tác nối mi / Spa", sv: "Jag sätter på en mjuk ögonpad under fransarna nu. Det gör samtalet tydligt och vänligt.", vi: "Bây giờ mình dán miếng lót mắt mềm dưới hàng mi nhé. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/jɑːɡ ˈsɛtːɛr pɔː ɛn mjʉːk ˈœːɡɔnˌpad ɵnːdɛr ˈfranːsarːa nʉː/" },
  { id: 184, topic: "Thao tác nối mi / Spa", sv: "Säg till direkt om det svider eller sticker till. Det känns naturligt och artigt.", vi: "Báo ngay cho mình nếu thấy cay hoặc châm chích nhé. Câu này nghe tự nhiên và lịch sự.", phonetic: "/sɛːj tɪl dɪˈrɛkt ɔm deː ˈsviːdɛr ˈɛlːɛr ˈstɪkːɛr tɪl/" },
  { id: 185, topic: "Thao tác nối mi / Spa", sv: "Vi börjar med att rengöra fransarna noga. Det skapar en trygg stämning.", vi: "Tụi mình bắt đầu bằng việc làm sạch mi thật kỹ. Cách nói này tạo cảm giác an tâm.", phonetic: "/viː ˈbœrːjar meːd at ˈreːnˌjœːra ˈfranːsarːa ˈnoːɡa/" },
  { id: 186, topic: "Thao tác nối mi / Spa", sv: "Nu applicerar jag limmet försiktigt på varje frans. Det hjälper kunden att slappna av.", vi: "Giờ mình gắn keo cẩn thận lên từng sợi mi. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/nʉː ˌapːlɪˈseːrar jɑːɡ ˈlɪmːɛt fœrˈsɪkːtɪt pɔː ˈvarːjɛ frans/" },
  { id: 187, topic: "Thao tác nối mi / Spa", sv: "Känns tejpningen för stram på något ställe? Det är en viktig del av god service.", vi: "Miếng băng dán có bị căng ở chỗ nào không? Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/ɕɛnːs ˈtɛjpnɪŋɛn fœr stram pɔː ˈnoːɡɔt ˈstɛlːɛ/" },
  { id: 188, topic: "Thao tác nối mi / Spa", sv: "Jag masserar hårbotten med lugna rörelser nu. Det gör samtalet tydligt och vänligt.", vi: "Bây giờ mình massage da đầu với các động tác nhẹ nhàng nhé. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/jɑːɡ maˈseːrar ˈhoːrˌbɔtːɛn meːd ˈlɵɡːna ˈrœːrɛlsɛr nʉː/" },
  { id: 189, topic: "Thao tác nối mi / Spa", sv: "Är vattnet lagom varmt när jag sköljer håret? Det känns naturligt och artigt.", vi: "Nước có vừa độ ấm khi mình xả tóc không? Câu này nghe tự nhiên và lịch sự.", phonetic: "/ɛːr ˈvatːnɛt ˈlɑːɡɔm varmt nɛːr jɑːɡ ˈɕœlːjɛr ˈhoːrɛt/" },
  { id: 190, topic: "Thao tác nối mi / Spa", sv: "Nu är vi klara med behandlingen. Öppna ögonen sakta. Det skapar en trygg stämning.", vi: "Xong liệu trình rồi đây. Bạn mở mắt từ từ nhé. Cách nói này tạo cảm giác an tâm.", phonetic: "/nʉː ɛːr viː ˈklɑːra meːd bɛˈhanːdlɪŋɛn ˈœpːna ˈœːɡɔnɛn ˈsakːta/" },
  { id: 191, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vilken stil gillar du mest, naturlig eller volym? Det hjälper kunden att slappna av.", vi: "Bạn thích kiểu nào nhất, tự nhiên hay dày vol? Điều này giúp khách dễ thư giãn hơn.", phonetic: "/ˈvɪlːkɛn stiːl ˈjɪlːar dʉː mɛst nɑtʉːˈliːr ˈɛlːɛr vɔˈlʏːm/" },
  { id: 192, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vill du ha en öppen docköga eller en mjuk kattöga? Det är en viktig del av god service.", vi: "Bạn muốn dáng mắt búp bê tròn to hay dáng mắt mèo dịu dàng? Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/vɪl dʉː hɑː ɛn ˈœpːɛn ˈdɔkˌœːɡa ˈɛlːɛr ɛn mjʉːk ˈkatˌœːɡa/" },
  { id: 193, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Jag rekommenderar en lite kortare längd innerst. Det gör samtalet tydligt och vänligt.", vi: "Mình khuyên nên chọn độ dài ngắn hơn một chút ở góc trong. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/jɑːɡ ˌrɛkɔmɛnˈdeːrar ɛn ˈliːtɛ ˈkɔrːtarɛ lɛŋd ˈɪnːɛrst/" },
  { id: 194, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vill du ha mandelformade, fyrkantiga eller runda naglar? Det känns naturligt och artigt.", vi: "Bạn muốn móng dáng hạnh nhân, móng vuông hay móng tròn? Câu này nghe tự nhiên và lịch sự.", phonetic: "/vɪl dʉː hɑː ˈmanːdɛlˌfɔrmadɛ ˈfʏrˌkantɪɡa ˈɛlːɛr ˈrɵnːda ˈnaɡːlar/" },
  { id: 195, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Den här nyansen passar väldigt fint till din hudton. Det skapar en trygg stämning.", vi: "Tông màu này hợp với sắc da của bạn lắm đấy. Cách nói này tạo cảm giác an tâm.", phonetic: "/deːn hɛːr nʏˈanːsɛn ˈpasːar ˈvɛlːdɪt fɪnt tɪl diːn ˈhʉːdˌtuːn/" },
  { id: 196, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vi kan göra gel, förstärkning med builder gel eller akryl. Det hjälper kunden att slappna av.", vi: "Tụi mình có thể làm gel, đắp gel cứng hoặc đắp bột. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/viː kan ˈjœːra jeːl fœrˈstɛrkːnɪŋ meːd ˈbɪlːdɛr jeːl ˈɛlːɛr ɑˈkrʏːl/" },
  { id: 197, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vill du ha enfärgat, fransk manikyr eller chrome? Det är en viktig del av god service.", vi: "Bạn muốn sơn một màu, kiểu Pháp hay hiệu ứng chrome? Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/vɪl dʉː hɑː ˈeːnˌfɛrɡat fransk mɑnɪˈkʏːr ˈɛlːɛr kroːm/" },
  { id: 198, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Jag anpassar böjen efter dina naturliga fransar. Det gör samtalet tydligt och vänligt.", vi: "Mình điều chỉnh độ cong theo hàng mi thật của bạn. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/jɑːɡ ˈanːpasːar ˈbœjːɛn ˈɛfːtɛr ˈdiːna nɑtʉːˈliːra ˈfranːsar/" },
  { id: 199, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Det är bäst att skona dina egna fransar så de håller sig friska. Det känns naturligt och artigt.", vi: "Tốt nhất là giữ gìn mi thật để mi luôn khỏe mạnh. Câu này nghe tự nhiên và lịch sự.", phonetic: "/deːt ɛːr bɛst at ˈskuːna ˈdiːna ˈeːɡːna ˈfranːsar soː deː ˈhɔlːɛr sej ˈfrɪsːka/" },
  { id: 200, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Ska vi lägga till en djupgående fuktkur för händerna idag? Det skapar en trygg stämning.", vi: "Hôm nay mình thêm bước dưỡng ẩm sâu cho tay nhé? Cách nói này tạo cảm giác an tâm.", phonetic: "/skɑː viː ˈlɛɡːa tɪl ɛn ˈjʉːpˌɡoːɛnːdɛ ˈfɵktˌkʉːr fœr ˈhɛnːdarːa ɪˈdɑːɡ/" },
  { id: 201, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Undvik vatten och ånga på fransarna de första tjugofyra timmarna. Det hjälper kunden att slappna av.", vi: "Tránh nước và hơi nóng lên mi trong hai mươi bốn giờ đầu nhé. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/ˈɵnːdviːk ˈvatːɛn ɔ ˈɔŋːa pɔː ˈfranːsarːa deː ˈfœsːta ˈɕʉːɡʊˌfyːra ˈtɪmːarːa/" },
  { id: 202, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Gnugga inte ögonen och använd oljefria produkter. Det är en viktig del av god service.", vi: "Đừng dụi mắt và hãy dùng sản phẩm không chứa dầu nhé. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/ˈɡnɵɡːa ˈɪnːtɛ ˈœːɡɔnɛn ɔ ˈanːvɛnd ˈɔlːjɛˌfriːa prʊˈdɵkːtɛr/" },
  { id: 203, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Borsta fransarna försiktigt varje morgon med borsten du får. Det gör samtalet tydligt och vänligt.", vi: "Chải mi nhẹ nhàng mỗi sáng bằng cọ được tặng kèm nhé. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/ˈbɔʂːta ˈfranːsarːa fœrˈsɪkːtɪt ˈvarːjɛ ˈmɔrːɔn meːd ˈbɔʂːtɛn dʉː fɔːr/" },
  { id: 204, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Det är dags för påfyllning om ungefär tre veckor. Det känns naturligt och artigt.", vi: "Khoảng ba tuần nữa là tới lúc dặm lại rồi đấy. Câu này nghe tự nhiên và lịch sự.", phonetic: "/deːt ɛːr daks fœr ˈpoːˌfʏlːnɪŋ ɔm ɵnːfɛˈjɛːr treː ˈvɛkːɔr/" },
  { id: 205, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Smörj nagelbanden med nagelolja varje kväll. Det skapar en trygg stämning.", vi: "Thoa dầu dưỡng viền móng mỗi tối nhé. Cách nói này tạo cảm giác an tâm.", phonetic: "/smœrj ˈnɑːɡɛlˌbanːdɛn meːd ˈnɑːɡɛlˌɔlːja ˈvarːjɛ kvɛlː/" },
  { id: 206, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Använd gärna handskar när du diskar eller städar. Det hjälper kunden att slappna av.", vi: "Bạn nhớ đeo găng tay khi rửa chén hoặc dọn dẹp nhé. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/ˈanːvɛnd ˈjɛːrna ˈhanːskar nɛːr dʉː ˈdɪsːkar ˈɛlːɛr ˈstɛːdar/" },
  { id: 207, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Vill du boka nästa tid redan innan du går idag? Det är en viktig del av god service.", vi: "Bạn có muốn đặt lịch lần tới ngay trước khi về hôm nay không? Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/vɪl dʉː ˈbuːka ˈnɛsːta tiːd ˈreːdan ˈɪnːan dʉː ɡoːr ɪˈdɑːɡ/" },
  { id: 208, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Vi har en ledig tid på tisdag klockan tio. Det gör samtalet tydligt och vänligt.", vi: "Tụi mình còn trống lịch vào thứ ba lúc mười giờ. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/viː hɑːr ɛn ˈleːdɪɡ tiːd pɔː ˈtɪsːdɑːɡ ˈklɔkːan ˈtiːʊ/" },
  { id: 209, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Jag skickar en påminnelse dagen innan din tid. Det känns naturligt och artigt.", vi: "Mình sẽ gửi tin nhắn nhắc lịch trước ngày hẹn một ngày. Câu này nghe tự nhiên và lịch sự.", phonetic: "/jɑːɡ ˈɕɪkːar ɛn ˈpoːˌmɪnːɛlsɛ ˈdɑːɡɛn ˈɪnːan diːn tiːd/" },
  { id: 210, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Tack så mycket för besöket! Vi ses nästa gång. Det skapar en trygg stämning.", vi: "Cảm ơn bạn rất nhiều vì đã ghé tiệm! Hẹn gặp lại lần sau nhé. Cách nói này tạo cảm giác an tâm.", phonetic: "/tak soː ˈmʏkːɛt fœr bɛˈsøːkɛt viː seːs ˈnɛsːta ɡɔŋ/" },
  { id: 211, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Jag desinficerar alla verktyg mellan varje kund. Det hjälper kunden att slappna av.", vi: "Mình khử trùng toàn bộ dụng cụ giữa mỗi khách hàng. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/jɑːɡ dɛsɪnfɪˈseːrar ˈalːa ˈvɛrkˌtʏːɡ ˈmɛlːan ˈvarːjɛ kɵnd/" },
  { id: 212, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Vi följer säkerhetsrutiner för härdplast och lim. Det är en viktig del av god service.", vi: "Tụi mình tuân thủ quy trình an toàn với nhựa cứng và keo. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/viː ˈfœlːjɛr ˈsɛːkɛrˌheːtsrɵˌtiːnɛr fœr ˈhɛːrdˌplast ɔ liːm/" },
  { id: 213, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Jag arbetar i ett välventilerat rum med punktutsug. Det gör samtalet tydligt och vänligt.", vi: "Mình làm việc trong phòng thông thoáng có máy hút khí cục bộ. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/jɑːɡ ˈɑːrbɛtar ɪ ɛt ˈvɛːlˌvɛntɪˌleːrat rɵm meːd ˈpɵŋktˌʉːtsʉːɡ/" },
  { id: 214, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Jag byter handskar och dukar inför varje ny behandling. Det känns naturligt och artigt.", vi: "Mình thay găng tay và khăn trải trước mỗi liệu trình mới. Câu này nghe tự nhiên và lịch sự.", phonetic: "/jɑːɡ ˈbʏːtɛr ˈhanːskar ɔ ˈdʉːkar ˈɪnːfœr ˈvarːjɛ nʏː bɛˈhanːdlɪŋ/" },
  { id: 215, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Pincetterna är rengjorda och redo för dagens pass. Det skapar en trygg stämning.", vi: "Các cây nhíp đã được làm sạch và sẵn sàng cho ca làm hôm nay. Cách nói này tạo cảm giác an tâm.", phonetic: "/pɪnˈsɛtːarːa ɛːr ˈreːnˌjuːrda ɔ ˈreːdu fœr ˈdɑːɡɛns pasː/" },
  { id: 216, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Vi håller arbetsstationen ren, organiserad och lugn. Det hjälper kunden att slappna av.", vi: "Tụi mình giữ bàn làm việc sạch sẽ, gọn gàng và yên tĩnh. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/viː ˈhɔlːɛr ˈɑːrbɛtsˌstɑːˌɕuːnɛn reːn ɔrɡanɪˈseːrad ɔ lɵŋn/" },
  { id: 217, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Jag kontrollerar att limmet har rätt konsistens och fuktighet. Det är en viktig del av god service.", vi: "Mình kiểm tra xem keo có độ sệt và độ ẩm chuẩn chưa. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/jɑːɡ kɔntrɔˈleːrar at ˈlɪmːɛt hɑːr rɛt kɔnsɪsˈtɛnːs ɔ ˈfɵkːtɪˌheːt/" },
  { id: 218, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Engångsartiklar slängs i avsedd behållare direkt. Det gör samtalet tydligt och vänligt.", vi: "Đồ dùng một lần được bỏ vào thùng chuyên dụng ngay lập tức. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/ˈeːnˌɡɔŋsˌɑːrtɪklar slɛŋːs ɪ ˈɑːvˌsɛd bɛˈhɔlːarɛ dɪˈrɛkt/" },
  { id: 219, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Jag tvättar händerna noggrant före och efter varje moment. Det känns naturligt och artigt.", vi: "Mình rửa tay kỹ trước và sau mỗi thao tác. Câu này nghe tự nhiên và lịch sự.", phonetic: "/jɑːɡ ˈtvɛtːar ˈhɛnːdarːa ˈnoːɡrant ˈfœːrɛ ɔ ˈɛfːtɛr ˈvarːjɛ mʊˈmɛnːt/" },
  { id: 220, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "All utrustning står på sin plats så arbetet flyter smidigt. Det skapar en trygg stämning.", vi: "Mọi thiết bị đều đúng vị trí để công việc trôi chảy mượt mà. Cách nói này tạo cảm giác an tâm.", phonetic: "/alː ˈʉːtˌrɵsːnɪŋ stoːr pɔː sɪn plats soː ɑrˈbeːtɛt ˈflʏːtɛr ˈsmiːdɪt/" },
  { id: 221, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Hur ser schemat ut för resten av veckan? Det hjälper kunden att slappna av.", vi: "Lịch làm việc cho phần còn lại của tuần trông thế nào? Điều này giúp khách dễ thư giãn hơn.", phonetic: "/hʉːr seːr ˈɕeːmat ʉːt fœr ˈrɛsːtɛn ɑːv ˈvɛkːan/" },
  { id: 222, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Jag har förberett allt inför nästa kund klocker ett. Det är en viktig del av god service.", vi: "Mình đã chuẩn bị xong mọi thứ cho khách tiếp theo lúc một giờ. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/jɑːɡ hɑːr ˈfœrːbɛrɛt alːt ˈɪnːfœr ˈnɛsːta kɵnd ˈklɔkːɛn ɛt/" },
  { id: 223, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Vi behöver beställa mer franslim och primer i veckan. Det gör samtalet tydligt och vänligt.", vi: "Tụi mình cần đặt thêm keo nối mi và primer trong tuần này. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/viː bɛˈhøːvɛr bɛˈstɛlːa meːr ˈfransˌliːm ɔ ˈpraɪmɛr ɪ ˈvɛkːan/" },
  { id: 224, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Kan du hjälpa mig att ta emot nästa kund i receptionen? Det känns naturligt och artigt.", vi: "Bạn giúp mình đón khách tiếp theo ở quầy lễ tân được không? Câu này nghe tự nhiên và lịch sự.", phonetic: "/kan dʉː ˈjɛlːpa mej at tɑː ɛˈmʊːt ˈnɛsːta kɵnd ɪ rɛsɛpˈɕuːnɛn/" },
  { id: 225, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Vi samarbetar bra när vi stämmer av tiderna i förväg. Det skapar en trygg stämning.", vi: "Tụi mình phối hợp nhịp nhàng khi rà soát giờ giấc từ trước. Cách nói này tạo cảm giác an tâm.", phonetic: "/viː ˈsɑːmarˌbeːtar brɑː nɛːr viː ˈstɛmːɛr ɑːv ˈtiːdarːa ɪ fœrˈvɛːɡ/" },
  { id: 226, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Jag antecknar kundens önskemål direkt i bokningen. Det hjälper kunden att slappna av.", vi: "Mình ghi chú mong muốn của khách thẳng vào lịch đặt. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/jɑːɡ ˈanːˌteːknar ˈkɵnːdɛns ˈœnːskɛˌmoːl dɪˈrɛkt ɪ ˈbuːknɪŋɛn/" },
  { id: 227, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Kunden blev jättenöjd med resultatet idag. Det är en viktig del av god service.", vi: "Khách hàng rất hài lòng với kết quả hôm nay. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/ˈkɵnːdɛn bleːv ˈjɛtːɛˌnœjd meːd rɛsɵlˈtɑːtɛt ɪˈdɑːɡ/" },
  { id: 228, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Vi städar av och fyller på förrådet innan vi stänger. Det gör samtalet tydligt och vänligt.", vi: "Tụi mình dọn dẹp và châm thêm đồ dự trữ trước khi đóng cửa. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/viː ˈstɛːdar ɑːv ɔ ˈfʏlːɛr pɔː fœˈroːdɛt ˈɪnːan viː ˈstɛŋːɛr/" },
  { id: 229, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Har någon avbokat sin tid på eftermiddagen? Det känns naturligt och artigt.", vi: "Có ai hủy lịch buổi chiều nay không? Câu này nghe tự nhiên và lịch sự.", phonetic: "/hɑːr ˈnoːɡɔn ˈɑːvˌbuːkat sɪn tiːd pɔː ˈɛfːtɛrˌmɪdːaɡɛn/" },
  { id: 230, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Jag är redo att ta emot nästa bokning nu. Det skapar en trygg stämning.", vi: "Mình đã sẵn sàng đón lượt đặt tiếp theo rồi. Cách nói này tạo cảm giác an tâm.", phonetic: "/jɑːɡ ɛːr ˈreːdu at tɑː ɛˈmʊːt ˈnɛsːta ˈbuːknɪŋ nʉː/" },
  { id: 231, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Hur känns det nu när du ser dig i spegeln? Det hjälper kunden att slappna av.", vi: "Giờ khi nhìn mình trong gương bạn thấy thế nào? Điều này giúp khách dễ thư giãn hơn.", phonetic: "/hʉːr ɕɛnːs deː nʉː nɛːr dʉː seːr dej ɪ ˈspeːɡɛln/" },
  { id: 232, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Är det något jag kan justera lite till innan du går? Det är en viktig del av god service.", vi: "Có chỗ nào mình chỉnh thêm một chút trước khi bạn về không? Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/ɛːr deː ˈnoːɡɔt jɑːɡ kan jɵsˈteːra ˈliːtɛ tɪl ˈɪnːan dʉː ɡoːr/" },
  { id: 233, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Betalningen går bra med kort eller Swish. Det gör samtalet tydligt och vänligt.", vi: "Thanh toán bằng thẻ hoặc Swish đều được nhé. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/bɛˈtɑːlnɪŋɛn ɡoːr brɑː meːd kɔʈ ˈɛlːɛr svɪʃ/" },
  { id: 234, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Här kommer kvittot. Varsågod! Det känns naturligt och artigt.", vi: "Hóa đơn của bạn đây. Mời bạn nhận! Câu này nghe tự nhiên và lịch sự.", phonetic: "/hɛːr ˈkɔmːɛr ˈkvɪtːʊt ˈvɑːrʃɔˌɡuːd/" },
  { id: 235, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Tack för förtroendet och ha en riktigt fin dag! Det skapar en trygg stämning.", vi: "Cảm ơn bạn đã tin tưởng và chúc bạn một ngày thật đẹp! Cách nói này tạo cảm giác an tâm.", phonetic: "/tak fœr fœrˈtrʊːɛndɛt ɔ hɑː ɛn ˈrɪkːtɪt fiːn dɑːɡ/" },
  { id: 236, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Det var så roligt att få arbeta med dina naglar idag. Det hjälper kunden att slappna av.", vi: "Hôm nay được làm móng cho bạn vui lắm luôn. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/deːt vɑːr soː ˈrʊːlɪt at foː ˈɑːrbɛta meːd ˈdiːna ˈnaɡːlar ɪˈdɑːɡ/" },
  { id: 237, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Glöm inte din väska och dina personliga saker. Det är en viktig del av god service.", vi: "Đừng quên túi xách và đồ cá nhân của bạn nhé. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/ɡlœm ˈɪnːtɛ diːn ˈvɛsːka ɔ ˈdiːna pɛʂʊnˈliːɡa ˈsɑːkɛr/" },
  { id: 238, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Vi finns här om du har några frågor hemma. Det gör samtalet tydligt och vänligt.", vi: "Tụi mình luôn ở đây nếu về nhà bạn có thắc mắc gì. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/viː fɪnːs hɛːr ɔm dʉː hɑːr ˈnoːɡra ˈfroːɡɔr ˈhɛmːa/" },
  { id: 239, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Ha en trevlig kväll och kör försiktigt hem! Det känns naturligt och artigt.", vi: "Chúc bạn buổi tối vui vẻ và đi đường về cẩn thận nhé! Câu này nghe tự nhiên và lịch sự.", phonetic: "/hɑː ɛn ˈtreːvlɪɡ kvɛlː ɔ ɕœːr fœrˈsɪkːtɪt hɛm/" },
  { id: 240, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Välkommen tillbaka när du känner för det! Det skapar en trygg stämning.", vi: "Chào mừng bạn quay lại bất cứ khi nào bạn muốn nhé! Cách nói này tạo cảm giác an tâm.", phonetic: "/ˈvɛːlˌkɔmːɛn tɪlˈbɑːka nɛːr dʉː ˈɕɛnːɛr fœr deː/" },
  { id: 241, topic: "Đón tiếp khách hàng", sv: "Under behandlingen säger jag lugnt: Hej! Välkommen till vår salong.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Xin chào! Chào mừng đến với tiệm của chúng tôi.", phonetic: "/hej ˈvɛːlˌkɔmːɛn tɪl voːr saˈlɔŋ/" },
  { id: 242, topic: "Đón tiếp khách hàng", sv: "Som nagel- och franstekniker säger jag: God morgon! Hur mår du idag?", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Chào buổi sáng! Hôm nay bạn cảm thấy thế nào?", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr moːr dʉː ɪˈdɑːɡ/" },
  { id: 243, topic: "Đón tiếp khách hàng", sv: "I salongen säger jag ofta: Hej och välkommen! Har du bokat tid?", vi: "Trong tiệm mình thường nói: Xin chào và chào mừng! Bạn đã đặt lịch hẹn chưa?", phonetic: "/hej ɔ ˈvɛːlˌkɔmːɛn hɑːr dʉː ˈbuːkat tiːd/" },
  { id: 244, topic: "Đón tiếp khách hàng", sv: "När jag jobbar brukar jag säga: Varsågod och sitt ner här en stund.", vi: "Khi làm việc mình hay nói: Mời bạn ngồi xuống đây một lát.", phonetic: "/ˈvɑːrʃɔˌɡuːd ɔ sɪtː neːr hɛːr ɛn stɵnd/" },
  { id: 245, topic: "Đón tiếp khách hàng", sv: "Vid kundmottagning säger jag: Vad trevligt att se dig igen!", vi: "Khi đón tiếp mình nói: Thật vui được gặp lại bạn!", phonetic: "/vɑːd ˈtreːvlɪɡt at seː dej ɪˈjɛn/" },
  { id: 246, topic: "Đón tiếp khách hàng", sv: "Under behandlingen säger jag lugnt: Välkommen in! Jag heter My Han och ska hjälpa dig idag.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Chào mừng vào tiệm! Mình tên là My Han và sẽ hỗ trợ bạn hôm nay.", phonetic: "/ˈvɛːlˌkɔmːɛn ɪn jɑːɡ ˈheːtɛr myː hɑn ɔ skɑː ˈjɛlːpa dej ɪˈdɑːɡ/" },
  { id: 247, topic: "Đón tiếp khách hàng", sv: "Som nagel- och franstekniker säger jag: Hur var din dag hittills?", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Ngày của bạn từ nãy đến giờ thế nào?", phonetic: "/hʉːr vɑːr diːn dɑːɡ ˈhɪtːɪls/" },
  { id: 248, topic: "Đón tiếp khách hàng", sv: "I salongen säger jag ofta: Jag är så glad att du kom hit idag.", vi: "Trong tiệm mình thường nói: Mình rất vui vì hôm nay bạn đã đến đây.", phonetic: "/jɑːɡ ɛːr soː ɡlɑːd at dʉː kɔm hɪt ɪˈdɑːɡ/" },
  { id: 249, topic: "Đón tiếp khách hàng", sv: "När jag jobbar brukar jag säga: Ta av dig jackan om du vill, så hänger jag upp den.", vi: "Khi làm việc mình hay nói: Bạn cởi áo khoác nếu muốn nhé, mình sẽ treo lên giúp.", phonetic: "/tɑː ɑːv dej ˈjakːan ɔm dʉː vɪl soː ˈhɛŋːɛr jɑːɡ ɵpː dɛn/" },
  { id: 250, topic: "Đón tiếp khách hàng", sv: "Vid kundmottagning säger jag: Känn dig som hemma här hos oss.", vi: "Khi đón tiếp mình nói: Hãy cứ tự nhiên như ở nhà khi ở chỗ tụi mình nhé.", phonetic: "/ɕɛnː dej sɔm ˈhɛmːa hɛːr huːs ɔsː/" },
  { id: 251, topic: "Mời nước khách", sv: "Under behandlingen säger jag lugnt: Vill du ha något att dricka, kaffe eller vatten?", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Bạn có muốn uống chút gì không, cà phê hay nước lọc?", phonetic: "/vɪl dʉː hɑː ˈnoːɡɔt at ˈdrɪkːa ˈkafːɛ ˈɛlːɛr ˈvatːɛn/" },
  { id: 252, topic: "Mời nước khách", sv: "Som nagel- och franstekniker säger jag: Vill du ha ett glas kallt vatten medan du väntar?", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Bạn có muốn một ly nước lạnh trong lúc chờ không?", phonetic: "/vɪl dʉː hɑː ɛt ɡlɑːs kalːt ˈvatːɛn ˈmeːdan dʉː ˈvɛnːtar/" },
  { id: 253, topic: "Mời nước khách", sv: "I salongen säger jag ofta: Jag kan bjuda på te eller kaffe om du önskar.", vi: "Trong tiệm mình thường nói: Mình có thể mời trà hoặc cà phê nếu bạn muốn.", phonetic: "/jɑːɡ kan ˈbjʉːda pɔː teː ˈɛlːɛr ˈkafːɛ ɔm dʉː ˈœnːskar/" },
  { id: 254, topic: "Mời nước khách", sv: "När jag jobbar brukar jag säga: Föredrar du varmt eller kallt vatten?", vi: "Khi làm việc mình hay nói: Bạn thích nước ấm hay nước lạnh hơn?", phonetic: "/ˌfœrɛˈdrɑːr dʉː varmt ˈɛlːɛr kalːt ˈvatːɛn/" },
  { id: 255, topic: "Mời nước khách", sv: "Vid kundmottagning säger jag: Ska jag hälla upp lite te åt dig?", vi: "Khi đón tiếp mình nói: Mình rót thêm chút trà cho bạn nhé?", phonetic: "/skɑː jɑːɡ ˈhɛlːa ɵpː ˈliːtɛ teː oːt dej/" },
  { id: 256, topic: "Mời nước khách", sv: "Under behandlingen säger jag lugnt: Här kommer ditt vatten. Varsågod!", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Nước của bạn đây. Mời bạn dùng!", phonetic: "/hɛːr ˈkɔmːɛr dɪt ˈvatːɛn ˈvɑːrʃɔˌɡuːd/" },
  { id: 257, topic: "Mời nước khách", sv: "Som nagel- och franstekniker säger jag: Vill du ha socker eller mjölk i kaffet?", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Bạn có muốn thêm đường hay sữa vào cà phê không?", phonetic: "/vɪl dʉː hɑː ˈsɔkːɛr ˈɛlːɛr mjœlk ɪ ˈkafːɛt/" },
  { id: 258, topic: "Mời nước khách", sv: "I salongen säger jag ofta: Jag fixar en kopp varmt te direkt.", vi: "Trong tiệm mình thường nói: Mình pha một tách trà nóng ngay đây.", phonetic: "/jɑːɡ ˈfɪkːsar ɛn kɔpː varmt teː dɪˈrɛkt/" },
  { id: 259, topic: "Mời nước khách", sv: "När jag jobbar brukar jag säga: Vill du ha en liten kaka till kaffet?", vi: "Khi làm việc mình hay nói: Bạn có muốn ăn thêm một chiếc bánh nhỏ kèm cà phê không?", phonetic: "/vɪl dʉː hɑː ɛn ˈliːtɛn ˈkɑːka tɪl ˈkafːɛt/" },
  { id: 260, topic: "Mời nước khách", sv: "Vid kundmottagning säger jag: Säg bara till om du vill ha påfyllning.", vi: "Khi đón tiếp mình nói: Cứ bảo mình nếu bạn muốn châm thêm nhé.", phonetic: "/sɛːj ˈbɑːra tɪl ɔm dʉː vɪl hɑː ˈpoːˌfʏlːnɪŋ/" },
  { id: 261, topic: "Thao tác nối mi / Spa", sv: "Under behandlingen säger jag lugnt: Blunda och slappna av nu.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Hãy nhắm mắt lại và thư giãn nhé.", phonetic: "/ˈblɵnːda ɔ ˈslapːna ɑːv nʉː/" },
  { id: 262, topic: "Thao tác nối mi / Spa", sv: "Som nagel- och franstekniker säger jag: Känns det bra och bekvämt på britsen?", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Nằm trên giường liệu trình có thấy thoải mái không?", phonetic: "/ɕɛnːs deː brɑː ɔ bɛˈkvɛːmt pɔː brɪtːsɛn/" },
  { id: 263, topic: "Thao tác nối mi / Spa", sv: "I salongen säger jag ofta: Jag sätter på en mjuk ögonpad under fransarna nu.", vi: "Trong tiệm mình thường nói: Bây giờ mình dán miếng lót mắt mềm dưới hàng mi nhé.", phonetic: "/jɑːɡ ˈsɛtːɛr pɔː ɛn mjʉːk ˈœːɡɔnˌpad ɵnːdɛr ˈfranːsarːa nʉː/" },
  { id: 264, topic: "Thao tác nối mi / Spa", sv: "När jag jobbar brukar jag säga: Säg till direkt om det svider eller sticker till.", vi: "Khi làm việc mình hay nói: Báo ngay cho mình nếu thấy cay hoặc châm chích nhé.", phonetic: "/sɛːj tɪl dɪˈrɛkt ɔm deː ˈsviːdɛr ˈɛlːɛr ˈstɪkːɛr tɪl/" },
  { id: 265, topic: "Thao tác nối mi / Spa", sv: "Vid kundmottagning säger jag: Vi börjar med att rengöra fransarna noga.", vi: "Khi đón tiếp mình nói: Tụi mình bắt đầu bằng việc làm sạch mi thật kỹ.", phonetic: "/viː ˈbœrːjar meːd at ˈreːnˌjœːra ˈfranːsarːa ˈnoːɡa/" },
  { id: 266, topic: "Thao tác nối mi / Spa", sv: "Under behandlingen säger jag lugnt: Nu applicerar jag limmet försiktigt på varje frans.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Giờ mình gắn keo cẩn thận lên từng sợi mi.", phonetic: "/nʉː ˌapːlɪˈseːrar jɑːɡ ˈlɪmːɛt fœrˈsɪkːtɪt pɔː ˈvarːjɛ frans/" },
  { id: 267, topic: "Thao tác nối mi / Spa", sv: "Som nagel- och franstekniker säger jag: Känns tejpningen för stram på något ställe?", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Miếng băng dán có bị căng ở chỗ nào không?", phonetic: "/ɕɛnːs ˈtɛjpnɪŋɛn fœr stram pɔː ˈnoːɡɔt ˈstɛlːɛ/" },
  { id: 268, topic: "Thao tác nối mi / Spa", sv: "I salongen säger jag ofta: Jag masserar hårbotten med lugna rörelser nu.", vi: "Trong tiệm mình thường nói: Bây giờ mình massage da đầu với các động tác nhẹ nhàng nhé.", phonetic: "/jɑːɡ maˈseːrar ˈhoːrˌbɔtːɛn meːd ˈlɵɡːna ˈrœːrɛlsɛr nʉː/" },
  { id: 269, topic: "Thao tác nối mi / Spa", sv: "När jag jobbar brukar jag säga: Är vattnet lagom varmt när jag sköljer håret?", vi: "Khi làm việc mình hay nói: Nước có vừa độ ấm khi mình xả tóc không?", phonetic: "/ɛːr ˈvatːnɛt ˈlɑːɡɔm varmt nɛːr jɑːɡ ˈɕœlːjɛr ˈhoːrɛt/" },
  { id: 270, topic: "Thao tác nối mi / Spa", sv: "Vid kundmottagning säger jag: Nu är vi klara med behandlingen. Öppna ögonen sakta.", vi: "Khi đón tiếp mình nói: Xong liệu trình rồi đây. Bạn mở mắt từ từ nhé.", phonetic: "/nʉː ɛːr viː ˈklɑːra meːd bɛˈhanːdlɪŋɛn ˈœpːna ˈœːɡɔnɛn ˈsakːta/" },
  { id: 271, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Under behandlingen säger jag lugnt: Vilken stil gillar du mest, naturlig eller volym?", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Bạn thích kiểu nào nhất, tự nhiên hay dày vol?", phonetic: "/ˈvɪlːkɛn stiːl ˈjɪlːar dʉː mɛst nɑtʉːˈliːr ˈɛlːɛr vɔˈlʏːm/" },
  { id: 272, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Som nagel- och franstekniker säger jag: Vill du ha en öppen docköga eller en mjuk kattöga?", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Bạn muốn dáng mắt búp bê tròn to hay dáng mắt mèo dịu dàng?", phonetic: "/vɪl dʉː hɑː ɛn ˈœpːɛn ˈdɔkˌœːɡa ˈɛlːɛr ɛn mjʉːk ˈkatˌœːɡa/" },
  { id: 273, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "I salongen säger jag ofta: Jag rekommenderar en lite kortare längd innerst.", vi: "Trong tiệm mình thường nói: Mình khuyên nên chọn độ dài ngắn hơn một chút ở góc trong.", phonetic: "/jɑːɡ ˌrɛkɔmɛnˈdeːrar ɛn ˈliːtɛ ˈkɔrːtarɛ lɛŋd ˈɪnːɛrst/" },
  { id: 274, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "När jag jobbar brukar jag säga: Vill du ha mandelformade, fyrkantiga eller runda naglar?", vi: "Khi làm việc mình hay nói: Bạn muốn móng dáng hạnh nhân, móng vuông hay móng tròn?", phonetic: "/vɪl dʉː hɑː ˈmanːdɛlˌfɔrmadɛ ˈfʏrˌkantɪɡa ˈɛlːɛr ˈrɵnːda ˈnaɡːlar/" },
  { id: 275, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vid kundmottagning säger jag: Den här nyansen passar väldigt fint till din hudton.", vi: "Khi đón tiếp mình nói: Tông màu này hợp với sắc da của bạn lắm đấy.", phonetic: "/deːn hɛːr nʏˈanːsɛn ˈpasːar ˈvɛlːdɪt fɪnt tɪl diːn ˈhʉːdˌtuːn/" },
  { id: 276, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Under behandlingen säger jag lugnt: Vi kan göra gel, förstärkning med builder gel eller akryl.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Tụi mình có thể làm gel, đắp gel cứng hoặc đắp bột.", phonetic: "/viː kan ˈjœːra jeːl fœrˈstɛrkːnɪŋ meːd ˈbɪlːdɛr jeːl ˈɛlːɛr ɑˈkrʏːl/" },
  { id: 277, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Som nagel- och franstekniker säger jag: Vill du ha enfärgat, fransk manikyr eller chrome?", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Bạn muốn sơn một màu, kiểu Pháp hay hiệu ứng chrome?", phonetic: "/vɪl dʉː hɑː ˈeːnˌfɛrɡat fransk mɑnɪˈkʏːr ˈɛlːɛr kroːm/" },
  { id: 278, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "I salongen säger jag ofta: Jag anpassar böjen efter dina naturliga fransar.", vi: "Trong tiệm mình thường nói: Mình điều chỉnh độ cong theo hàng mi thật của bạn.", phonetic: "/jɑːɡ ˈanːpasːar ˈbœjːɛn ˈɛfːtɛr ˈdiːna nɑtʉːˈliːra ˈfranːsar/" },
  { id: 279, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "När jag jobbar brukar jag säga: Det är bäst att skona dina egna fransar så de håller sig friska.", vi: "Khi làm việc mình hay nói: Tốt nhất là giữ gìn mi thật để mi luôn khỏe mạnh.", phonetic: "/deːt ɛːr bɛst at ˈskuːna ˈdiːna ˈeːɡːna ˈfranːsar soː deː ˈhɔlːɛr sej ˈfrɪsːka/" },
  { id: 280, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vid kundmottagning säger jag: Ska vi lägga till en djupgående fuktkur för händerna idag?", vi: "Khi đón tiếp mình nói: Hôm nay mình thêm bước dưỡng ẩm sâu cho tay nhé?", phonetic: "/skɑː viː ˈlɛɡːa tɪl ɛn ˈjʉːpˌɡoːɛnːdɛ ˈfɵktˌkʉːr fœr ˈhɛnːdarːa ɪˈdɑːɡ/" },
  { id: 281, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Under behandlingen säger jag lugnt: Undvik vatten och ånga på fransarna de första tjugofyra timmarna.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Tránh nước và hơi nóng lên mi trong hai mươi bốn giờ đầu nhé.", phonetic: "/ˈɵnːdviːk ˈvatːɛn ɔ ˈɔŋːa pɔː ˈfranːsarːa deː ˈfœsːta ˈɕʉːɡʊˌfyːra ˈtɪmːarːa/" },
  { id: 282, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Som nagel- och franstekniker säger jag: Gnugga inte ögonen och använd oljefria produkter.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Đừng dụi mắt và hãy dùng sản phẩm không chứa dầu nhé.", phonetic: "/ˈɡnɵɡːa ˈɪnːtɛ ˈœːɡɔnɛn ɔ ˈanːvɛnd ˈɔlːjɛˌfriːa prʊˈdɵkːtɛr/" },
  { id: 283, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "I salongen säger jag ofta: Borsta fransarna försiktigt varje morgon med borsten du får.", vi: "Trong tiệm mình thường nói: Chải mi nhẹ nhàng mỗi sáng bằng cọ được tặng kèm nhé.", phonetic: "/ˈbɔʂːta ˈfranːsarːa fœrˈsɪkːtɪt ˈvarːjɛ ˈmɔrːɔn meːd ˈbɔʂːtɛn dʉː fɔːr/" },
  { id: 284, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "När jag jobbar brukar jag säga: Det är dags för påfyllning om ungefär tre veckor.", vi: "Khi làm việc mình hay nói: Khoảng ba tuần nữa là tới lúc dặm lại rồi đấy.", phonetic: "/deːt ɛːr daks fœr ˈpoːˌfʏlːnɪŋ ɔm ɵnːfɛˈjɛːr treː ˈvɛkːɔr/" },
  { id: 285, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Vid kundmottagning säger jag: Smörj nagelbanden med nagelolja varje kväll.", vi: "Khi đón tiếp mình nói: Thoa dầu dưỡng viền móng mỗi tối nhé.", phonetic: "/smœrj ˈnɑːɡɛlˌbanːdɛn meːd ˈnɑːɡɛlˌɔlːja ˈvarːjɛ kvɛlː/" },
  { id: 286, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Under behandlingen säger jag lugnt: Använd gärna handskar när du diskar eller städar.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Bạn nhớ đeo găng tay khi rửa chén hoặc dọn dẹp nhé.", phonetic: "/ˈanːvɛnd ˈjɛːrna ˈhanːskar nɛːr dʉː ˈdɪsːkar ˈɛlːɛr ˈstɛːdar/" },
  { id: 287, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Som nagel- och franstekniker säger jag: Vill du boka nästa tid redan innan du går idag?", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Bạn có muốn đặt lịch lần tới ngay trước khi về hôm nay không?", phonetic: "/vɪl dʉː ˈbuːka ˈnɛsːta tiːd ˈreːdan ˈɪnːan dʉː ɡoːr ɪˈdɑːɡ/" },
  { id: 288, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "I salongen säger jag ofta: Vi har en ledig tid på tisdag klockan tio.", vi: "Trong tiệm mình thường nói: Tụi mình còn trống lịch vào thứ ba lúc mười giờ.", phonetic: "/viː hɑːr ɛn ˈleːdɪɡ tiːd pɔː ˈtɪsːdɑːɡ ˈklɔkːan ˈtiːʊ/" },
  { id: 289, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "När jag jobbar brukar jag säga: Jag skickar en påminnelse dagen innan din tid.", vi: "Khi làm việc mình hay nói: Mình sẽ gửi tin nhắn nhắc lịch trước ngày hẹn một ngày.", phonetic: "/jɑːɡ ˈɕɪkːar ɛn ˈpoːˌmɪnːɛlsɛ ˈdɑːɡɛn ˈɪnːan diːn tiːd/" },
  { id: 290, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Vid kundmottagning säger jag: Tack så mycket för besöket! Vi ses nästa gång.", vi: "Khi đón tiếp mình nói: Cảm ơn bạn rất nhiều vì đã ghé tiệm! Hẹn gặp lại lần sau nhé.", phonetic: "/tak soː ˈmʏkːɛt fœr bɛˈsøːkɛt viː seːs ˈnɛsːta ɡɔŋ/" },
  { id: 291, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Under behandlingen säger jag lugnt: Jag desinficerar alla verktyg mellan varje kund.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Mình khử trùng toàn bộ dụng cụ giữa mỗi khách hàng.", phonetic: "/jɑːɡ dɛsɪnfɪˈseːrar ˈalːa ˈvɛrkˌtʏːɡ ˈmɛlːan ˈvarːjɛ kɵnd/" },
  { id: 292, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Som nagel- och franstekniker säger jag: Vi följer säkerhetsrutiner för härdplast och lim.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Tụi mình tuân thủ quy trình an toàn với nhựa cứng và keo.", phonetic: "/viː ˈfœlːjɛr ˈsɛːkɛrˌheːtsrɵˌtiːnɛr fœr ˈhɛːrdˌplast ɔ liːm/" },
  { id: 293, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "I salongen säger jag ofta: Jag arbetar i ett välventilerat rum med punktutsug.", vi: "Trong tiệm mình thường nói: Mình làm việc trong phòng thông thoáng có máy hút khí cục bộ.", phonetic: "/jɑːɡ ˈɑːrbɛtar ɪ ɛt ˈvɛːlˌvɛntɪˌleːrat rɵm meːd ˈpɵŋktˌʉːtsʉːɡ/" },
  { id: 294, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "När jag jobbar brukar jag säga: Jag byter handskar och dukar inför varje ny behandling.", vi: "Khi làm việc mình hay nói: Mình thay găng tay và khăn trải trước mỗi liệu trình mới.", phonetic: "/jɑːɡ ˈbʏːtɛr ˈhanːskar ɔ ˈdʉːkar ˈɪnːfœr ˈvarːjɛ nʏː bɛˈhanːdlɪŋ/" },
  { id: 295, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Vid kundmottagning säger jag: Pincetterna är rengjorda och redo för dagens pass.", vi: "Khi đón tiếp mình nói: Các cây nhíp đã được làm sạch và sẵn sàng cho ca làm hôm nay.", phonetic: "/pɪnˈsɛtːarːa ɛːr ˈreːnˌjuːrda ɔ ˈreːdu fœr ˈdɑːɡɛns pasː/" },
  { id: 296, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Under behandlingen säger jag lugnt: Vi håller arbetsstationen ren, organiserad och lugn.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Tụi mình giữ bàn làm việc sạch sẽ, gọn gàng và yên tĩnh.", phonetic: "/viː ˈhɔlːɛr ˈɑːrbɛtsˌstɑːˌɕuːnɛn reːn ɔrɡanɪˈseːrad ɔ lɵŋn/" },
  { id: 297, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Som nagel- och franstekniker säger jag: Jag kontrollerar att limmet har rätt konsistens och fuktighet.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Mình kiểm tra xem keo có độ sệt và độ ẩm chuẩn chưa.", phonetic: "/jɑːɡ kɔntrɔˈleːrar at ˈlɪmːɛt hɑːr rɛt kɔnsɪsˈtɛnːs ɔ ˈfɵkːtɪˌheːt/" },
  { id: 298, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "I salongen säger jag ofta: Engångsartiklar slängs i avsedd behållare direkt.", vi: "Trong tiệm mình thường nói: Đồ dùng một lần được bỏ vào thùng chuyên dụng ngay lập tức.", phonetic: "/ˈeːnˌɡɔŋsˌɑːrtɪklar slɛŋːs ɪ ˈɑːvˌsɛd bɛˈhɔlːarɛ dɪˈrɛkt/" },
  { id: 299, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "När jag jobbar brukar jag säga: Jag tvättar händerna noggrant före och efter varje moment.", vi: "Khi làm việc mình hay nói: Mình rửa tay kỹ trước và sau mỗi thao tác.", phonetic: "/jɑːɡ ˈtvɛtːar ˈhɛnːdarːa ˈnoːɡrant ˈfœːrɛ ɔ ˈɛfːtɛr ˈvarːjɛ mʊˈmɛnːt/" },
  { id: 300, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Vid kundmottagning säger jag: All utrustning står på sin plats så arbetet flyter smidigt.", vi: "Khi đón tiếp mình nói: Mọi thiết bị đều đúng vị trí để công việc trôi chảy mượt mà.", phonetic: "/alː ˈʉːtˌrɵsːnɪŋ stoːr pɔː sɪn plats soː ɑrˈbeːtɛt ˈflʏːtɛr ˈsmiːdɪt/" },
  { id: 301, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Under behandlingen säger jag lugnt: Hur ser schemat ut för resten av veckan?", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Lịch làm việc cho phần còn lại của tuần trông thế nào?", phonetic: "/hʉːr seːr ˈɕeːmat ʉːt fœr ˈrɛsːtɛn ɑːv ˈvɛkːan/" },
  { id: 302, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Som nagel- och franstekniker säger jag: Jag har förberett allt inför nästa kund klocker ett.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Mình đã chuẩn bị xong mọi thứ cho khách tiếp theo lúc một giờ.", phonetic: "/jɑːɡ hɑːr ˈfœrːbɛrɛt alːt ˈɪnːfœr ˈnɛsːta kɵnd ˈklɔkːɛn ɛt/" },
  { id: 303, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "I salongen säger jag ofta: Vi behöver beställa mer franslim och primer i veckan.", vi: "Trong tiệm mình thường nói: Tụi mình cần đặt thêm keo nối mi và primer trong tuần này.", phonetic: "/viː bɛˈhøːvɛr bɛˈstɛlːa meːr ˈfransˌliːm ɔ ˈpraɪmɛr ɪ ˈvɛkːan/" },
  { id: 304, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "När jag jobbar brukar jag säga: Kan du hjälpa mig att ta emot nästa kund i receptionen?", vi: "Khi làm việc mình hay nói: Bạn giúp mình đón khách tiếp theo ở quầy lễ tân được không?", phonetic: "/kan dʉː ˈjɛlːpa mej at tɑː ɛˈmʊːt ˈnɛsːta kɵnd ɪ rɛsɛpˈɕuːnɛn/" },
  { id: 305, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Vid kundmottagning säger jag: Vi samarbetar bra när vi stämmer av tiderna i förväg.", vi: "Khi đón tiếp mình nói: Tụi mình phối hợp nhịp nhàng khi rà soát giờ giấc từ trước.", phonetic: "/viː ˈsɑːmarˌbeːtar brɑː nɛːr viː ˈstɛmːɛr ɑːv ˈtiːdarːa ɪ fœrˈvɛːɡ/" },
  { id: 306, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Under behandlingen säger jag lugnt: Jag antecknar kundens önskemål direkt i bokningen.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Mình ghi chú mong muốn của khách thẳng vào lịch đặt.", phonetic: "/jɑːɡ ˈanːˌteːknar ˈkɵnːdɛns ˈœnːskɛˌmoːl dɪˈrɛkt ɪ ˈbuːknɪŋɛn/" },
  { id: 307, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Som nagel- och franstekniker säger jag: Kunden blev jättenöjd med resultatet idag.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Khách hàng rất hài lòng với kết quả hôm nay.", phonetic: "/ˈkɵnːdɛn bleːv ˈjɛtːɛˌnœjd meːd rɛsɵlˈtɑːtɛt ɪˈdɑːɡ/" },
  { id: 308, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "I salongen säger jag ofta: Vi städar av och fyller på förrådet innan vi stänger.", vi: "Trong tiệm mình thường nói: Tụi mình dọn dẹp và châm thêm đồ dự trữ trước khi đóng cửa.", phonetic: "/viː ˈstɛːdar ɑːv ɔ ˈfʏlːɛr pɔː fœˈroːdɛt ˈɪnːan viː ˈstɛŋːɛr/" },
  { id: 309, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "När jag jobbar brukar jag säga: Har någon avbokat sin tid på eftermiddagen?", vi: "Khi làm việc mình hay nói: Có ai hủy lịch buổi chiều nay không?", phonetic: "/hɑːr ˈnoːɡɔn ˈɑːvˌbuːkat sɪn tiːd pɔː ˈɛfːtɛrˌmɪdːaɡɛn/" },
  { id: 310, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Vid kundmottagning säger jag: Jag är redo att ta emot nästa bokning nu.", vi: "Khi đón tiếp mình nói: Mình đã sẵn sàng đón lượt đặt tiếp theo rồi.", phonetic: "/jɑːɡ ɛːr ˈreːdu at tɑː ɛˈmʊːt ˈnɛsːta ˈbuːknɪŋ nʉː/" },
  { id: 311, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Under behandlingen säger jag lugnt: Hur känns det nu när du ser dig i spegeln?", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Giờ khi nhìn mình trong gương bạn thấy thế nào?", phonetic: "/hʉːr ɕɛnːs deː nʉː nɛːr dʉː seːr dej ɪ ˈspeːɡɛln/" },
  { id: 312, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Som nagel- och franstekniker säger jag: Är det något jag kan justera lite till innan du går?", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Có chỗ nào mình chỉnh thêm một chút trước khi bạn về không?", phonetic: "/ɛːr deː ˈnoːɡɔt jɑːɡ kan jɵsˈteːra ˈliːtɛ tɪl ˈɪnːan dʉː ɡoːr/" },
  { id: 313, topic: "Phản hồi, thanh toán & chia tay khách", sv: "I salongen säger jag ofta: Betalningen går bra med kort eller Swish.", vi: "Trong tiệm mình thường nói: Thanh toán bằng thẻ hoặc Swish đều được nhé.", phonetic: "/bɛˈtɑːlnɪŋɛn ɡoːr brɑː meːd kɔʈ ˈɛlːɛr svɪʃ/" },
  { id: 314, topic: "Phản hồi, thanh toán & chia tay khách", sv: "När jag jobbar brukar jag säga: Här kommer kvittot. Varsågod!", vi: "Khi làm việc mình hay nói: Hóa đơn của bạn đây. Mời bạn nhận!", phonetic: "/hɛːr ˈkɔmːɛr ˈkvɪtːʊt ˈvɑːrʃɔˌɡuːd/" },
  { id: 315, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Vid kundmottagning säger jag: Tack för förtroendet och ha en riktigt fin dag!", vi: "Khi đón tiếp mình nói: Cảm ơn bạn đã tin tưởng và chúc bạn một ngày thật đẹp!", phonetic: "/tak fœr fœrˈtrʊːɛndɛt ɔ hɑː ɛn ˈrɪkːtɪt fiːn dɑːɡ/" },
  { id: 316, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Under behandlingen säger jag lugnt: Det var så roligt att få arbeta med dina naglar idag.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Hôm nay được làm móng cho bạn vui lắm luôn.", phonetic: "/deːt vɑːr soː ˈrʊːlɪt at foː ˈɑːrbɛta meːd ˈdiːna ˈnaɡːlar ɪˈdɑːɡ/" },
  { id: 317, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Som nagel- och franstekniker säger jag: Glöm inte din väska och dina personliga saker.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Đừng quên túi xách và đồ cá nhân của bạn nhé.", phonetic: "/ɡlœm ˈɪnːtɛ diːn ˈvɛsːka ɔ ˈdiːna pɛʂʊnˈliːɡa ˈsɑːkɛr/" },
  { id: 318, topic: "Phản hồi, thanh toán & chia tay khách", sv: "I salongen säger jag ofta: Vi finns här om du har några frågor hemma.", vi: "Trong tiệm mình thường nói: Tụi mình luôn ở đây nếu về nhà bạn có thắc mắc gì.", phonetic: "/viː fɪnːs hɛːr ɔm dʉː hɑːr ˈnoːɡra ˈfroːɡɔr ˈhɛmːa/" },
  { id: 319, topic: "Phản hồi, thanh toán & chia tay khách", sv: "När jag jobbar brukar jag säga: Ha en trevlig kväll och kör försiktigt hem!", vi: "Khi làm việc mình hay nói: Chúc bạn buổi tối vui vẻ và đi đường về cẩn thận nhé!", phonetic: "/hɑː ɛn ˈtreːvlɪɡ kvɛlː ɔ ɕœːr fœrˈsɪkːtɪt hɛm/" },
  { id: 320, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Vid kundmottagning säger jag: Välkommen tillbaka när du känner för det!", vi: "Khi đón tiếp mình nói: Chào mừng bạn quay lại bất cứ khi nào bạn muốn nhé!", phonetic: "/ˈvɛːlˌkɔmːɛn tɪlˈbɑːka nɛːr dʉː ˈɕɛnːɛr fœr deː/" },
  { id: 321, topic: "Đón tiếp khách hàng", sv: "Hej! Välkommen till vår salong. Det gör samtalet tydligt och vänligt.", vi: "Xin chào! Chào mừng đến với tiệm của chúng tôi. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/hej ˈvɛːlˌkɔmːɛn tɪl voːr saˈlɔŋ/" },
  { id: 322, topic: "Đón tiếp khách hàng", sv: "God morgon! Hur mår du idag? Det känns naturligt och artigt.", vi: "Chào buổi sáng! Hôm nay bạn cảm thấy thế nào? Câu này nghe tự nhiên và lịch sự.", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr moːr dʉː ɪˈdɑːɡ/" },
  { id: 323, topic: "Đón tiếp khách hàng", sv: "Hej och välkommen! Har du bokat tid? Det skapar en trygg stämning.", vi: "Xin chào và chào mừng! Bạn đã đặt lịch hẹn chưa? Cách nói này tạo cảm giác an tâm.", phonetic: "/hej ɔ ˈvɛːlˌkɔmːɛn hɑːr dʉː ˈbuːkat tiːd/" },
  { id: 324, topic: "Đón tiếp khách hàng", sv: "Varsågod och sitt ner här en stund. Det hjälper kunden att slappna av.", vi: "Mời bạn ngồi xuống đây một lát. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/ˈvɑːrʃɔˌɡuːd ɔ sɪtː neːr hɛːr ɛn stɵnd/" },
  { id: 325, topic: "Đón tiếp khách hàng", sv: "Vad trevligt att se dig igen! Det är en viktig del av god service.", vi: "Thật vui được gặp lại bạn! Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/vɑːd ˈtreːvlɪɡt at seː dej ɪˈjɛn/" },
  { id: 326, topic: "Đón tiếp khách hàng", sv: "Välkommen in! Jag heter My Han och ska hjälpa dig idag. Det gör samtalet tydligt och vänligt.", vi: "Chào mừng vào tiệm! Mình tên là My Han và sẽ hỗ trợ bạn hôm nay. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/ˈvɛːlˌkɔmːɛn ɪn jɑːɡ ˈheːtɛr myː hɑn ɔ skɑː ˈjɛlːpa dej ɪˈdɑːɡ/" },
  { id: 327, topic: "Đón tiếp khách hàng", sv: "Hur var din dag hittills? Det känns naturligt och artigt.", vi: "Ngày của bạn từ nãy đến giờ thế nào? Câu này nghe tự nhiên và lịch sự.", phonetic: "/hʉːr vɑːr diːn dɑːɡ ˈhɪtːɪls/" },
  { id: 328, topic: "Đón tiếp khách hàng", sv: "Jag är så glad att du kom hit idag. Det skapar en trygg stämning.", vi: "Mình rất vui vì hôm nay bạn đã đến đây. Cách nói này tạo cảm giác an tâm.", phonetic: "/jɑːɡ ɛːr soː ɡlɑːd at dʉː kɔm hɪt ɪˈdɑːɡ/" },
  { id: 329, topic: "Đón tiếp khách hàng", sv: "Ta av dig jackan om du vill, så hänger jag upp den. Det hjälper kunden att slappna av.", vi: "Bạn cởi áo khoác nếu muốn nhé, mình sẽ treo lên giúp. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/tɑː ɑːv dej ˈjakːan ɔm dʉː vɪl soː ˈhɛŋːɛr jɑːɡ ɵpː dɛn/" },
  { id: 330, topic: "Đón tiếp khách hàng", sv: "Känn dig som hemma här hos oss. Det är en viktig del av god service.", vi: "Hãy cứ tự nhiên như ở nhà khi ở chỗ tụi mình nhé. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/ɕɛnː dej sɔm ˈhɛmːa hɛːr huːs ɔsː/" },
  { id: 331, topic: "Mời nước khách", sv: "Vill du ha något att dricka, kaffe eller vatten? Det gör samtalet tydligt och vänligt.", vi: "Bạn có muốn uống chút gì không, cà phê hay nước lọc? Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/vɪl dʉː hɑː ˈnoːɡɔt at ˈdrɪkːa ˈkafːɛ ˈɛlːɛr ˈvatːɛn/" },
  { id: 332, topic: "Mời nước khách", sv: "Vill du ha ett glas kallt vatten medan du väntar? Det känns naturligt och artigt.", vi: "Bạn có muốn một ly nước lạnh trong lúc chờ không? Câu này nghe tự nhiên và lịch sự.", phonetic: "/vɪl dʉː hɑː ɛt ɡlɑːs kalːt ˈvatːɛn ˈmeːdan dʉː ˈvɛnːtar/" },
  { id: 333, topic: "Mời nước khách", sv: "Jag kan bjuda på te eller kaffe om du önskar. Det skapar en trygg stämning.", vi: "Mình có thể mời trà hoặc cà phê nếu bạn muốn. Cách nói này tạo cảm giác an tâm.", phonetic: "/jɑːɡ kan ˈbjʉːda pɔː teː ˈɛlːɛr ˈkafːɛ ɔm dʉː ˈœnːskar/" },
  { id: 334, topic: "Mời nước khách", sv: "Föredrar du varmt eller kallt vatten? Det hjälper kunden att slappna av.", vi: "Bạn thích nước ấm hay nước lạnh hơn? Điều này giúp khách dễ thư giãn hơn.", phonetic: "/ˌfœrɛˈdrɑːr dʉː varmt ˈɛlːɛr kalːt ˈvatːɛn/" },
  { id: 335, topic: "Mời nước khách", sv: "Ska jag hälla upp lite te åt dig? Det är en viktig del av god service.", vi: "Mình rót thêm chút trà cho bạn nhé? Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/skɑː jɑːɡ ˈhɛlːa ɵpː ˈliːtɛ teː oːt dej/" },
  { id: 336, topic: "Mời nước khách", sv: "Här kommer ditt vatten. Varsågod! Det gör samtalet tydligt och vänligt.", vi: "Nước của bạn đây. Mời bạn dùng! Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/hɛːr ˈkɔmːɛr dɪt ˈvatːɛn ˈvɑːrʃɔˌɡuːd/" },
  { id: 337, topic: "Mời nước khách", sv: "Vill du ha socker eller mjölk i kaffet? Det känns naturligt och artigt.", vi: "Bạn có muốn thêm đường hay sữa vào cà phê không? Câu này nghe tự nhiên và lịch sự.", phonetic: "/vɪl dʉː hɑː ˈsɔkːɛr ˈɛlːɛr mjœlk ɪ ˈkafːɛt/" },
  { id: 338, topic: "Mời nước khách", sv: "Jag fixar en kopp varmt te direkt. Det skapar en trygg stämning.", vi: "Mình pha một tách trà nóng ngay đây. Cách nói này tạo cảm giác an tâm.", phonetic: "/jɑːɡ ˈfɪkːsar ɛn kɔpː varmt teː dɪˈrɛkt/" },
  { id: 339, topic: "Mời nước khách", sv: "Vill du ha en liten kaka till kaffet? Det hjälper kunden att slappna av.", vi: "Bạn có muốn ăn thêm một chiếc bánh nhỏ kèm cà phê không? Điều này giúp khách dễ thư giãn hơn.", phonetic: "/vɪl dʉː hɑː ɛn ˈliːtɛn ˈkɑːka tɪl ˈkafːɛt/" },
  { id: 340, topic: "Mời nước khách", sv: "Säg bara till om du vill ha påfyllning. Det är en viktig del av god service.", vi: "Cứ bảo mình nếu bạn muốn châm thêm nhé. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/sɛːj ˈbɑːra tɪl ɔm dʉː vɪl hɑː ˈpoːˌfʏlːnɪŋ/" },
  { id: 341, topic: "Thao tác nối mi / Spa", sv: "Blunda och slappna av nu. Det gör samtalet tydligt och vänligt.", vi: "Hãy nhắm mắt lại và thư giãn nhé. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/ˈblɵnːda ɔ ˈslapːna ɑːv nʉː/" },
  { id: 342, topic: "Thao tác nối mi / Spa", sv: "Känns det bra och bekvämt på britsen? Det känns naturligt och artigt.", vi: "Nằm trên giường liệu trình có thấy thoải mái không? Câu này nghe tự nhiên và lịch sự.", phonetic: "/ɕɛnːs deː brɑː ɔ bɛˈkvɛːmt pɔː brɪtːsɛn/" },
  { id: 343, topic: "Thao tác nối mi / Spa", sv: "Jag sätter på en mjuk ögonpad under fransarna nu. Det skapar en trygg stämning.", vi: "Bây giờ mình dán miếng lót mắt mềm dưới hàng mi nhé. Cách nói này tạo cảm giác an tâm.", phonetic: "/jɑːɡ ˈsɛtːɛr pɔː ɛn mjʉːk ˈœːɡɔnˌpad ɵnːdɛr ˈfranːsarːa nʉː/" },
  { id: 344, topic: "Thao tác nối mi / Spa", sv: "Säg till direkt om det svider eller sticker till. Det hjälper kunden att slappna av.", vi: "Báo ngay cho mình nếu thấy cay hoặc châm chích nhé. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/sɛːj tɪl dɪˈrɛkt ɔm deː ˈsviːdɛr ˈɛlːɛr ˈstɪkːɛr tɪl/" },
  { id: 345, topic: "Thao tác nối mi / Spa", sv: "Vi börjar med att rengöra fransarna noga. Det är en viktig del av god service.", vi: "Tụi mình bắt đầu bằng việc làm sạch mi thật kỹ. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/viː ˈbœrːjar meːd at ˈreːnˌjœːra ˈfranːsarːa ˈnoːɡa/" },
  { id: 346, topic: "Thao tác nối mi / Spa", sv: "Nu applicerar jag limmet försiktigt på varje frans. Det gör samtalet tydligt och vänligt.", vi: "Giờ mình gắn keo cẩn thận lên từng sợi mi. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/nʉː ˌapːlɪˈseːrar jɑːɡ ˈlɪmːɛt fœrˈsɪkːtɪt pɔː ˈvarːjɛ frans/" },
  { id: 347, topic: "Thao tác nối mi / Spa", sv: "Känns tejpningen för stram på något ställe? Det känns naturligt och artigt.", vi: "Miếng băng dán có bị căng ở chỗ nào không? Câu này nghe tự nhiên và lịch sự.", phonetic: "/ɕɛnːs ˈtɛjpnɪŋɛn fœr stram pɔː ˈnoːɡɔt ˈstɛlːɛ/" },
  { id: 348, topic: "Thao tác nối mi / Spa", sv: "Jag masserar hårbotten med lugna rörelser nu. Det skapar en trygg stämning.", vi: "Bây giờ mình massage da đầu với các động tác nhẹ nhàng nhé. Cách nói này tạo cảm giác an tâm.", phonetic: "/jɑːɡ maˈseːrar ˈhoːrˌbɔtːɛn meːd ˈlɵɡːna ˈrœːrɛlsɛr nʉː/" },
  { id: 349, topic: "Thao tác nối mi / Spa", sv: "Är vattnet lagom varmt när jag sköljer håret? Det hjälper kunden att slappna av.", vi: "Nước có vừa độ ấm khi mình xả tóc không? Điều này giúp khách dễ thư giãn hơn.", phonetic: "/ɛːr ˈvatːnɛt ˈlɑːɡɔm varmt nɛːr jɑːɡ ˈɕœlːjɛr ˈhoːrɛt/" },
  { id: 350, topic: "Thao tác nối mi / Spa", sv: "Nu är vi klara med behandlingen. Öppna ögonen sakta. Det är en viktig del av god service.", vi: "Xong liệu trình rồi đây. Bạn mở mắt từ từ nhé. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/nʉː ɛːr viː ˈklɑːra meːd bɛˈhanːdlɪŋɛn ˈœpːna ˈœːɡɔnɛn ˈsakːta/" },
  { id: 351, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vilken stil gillar du mest, naturlig eller volym? Det gör samtalet tydligt och vänligt.", vi: "Bạn thích kiểu nào nhất, tự nhiên hay dày vol? Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/ˈvɪlːkɛn stiːl ˈjɪlːar dʉː mɛst nɑtʉːˈliːr ˈɛlːɛr vɔˈlʏːm/" },
  { id: 352, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vill du ha en öppen docköga eller en mjuk kattöga? Det känns naturligt och artigt.", vi: "Bạn muốn dáng mắt búp bê tròn to hay dáng mắt mèo dịu dàng? Câu này nghe tự nhiên và lịch sự.", phonetic: "/vɪl dʉː hɑː ɛn ˈœpːɛn ˈdɔkˌœːɡa ˈɛlːɛr ɛn mjʉːk ˈkatˌœːɡa/" },
  { id: 353, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Jag rekommenderar en lite kortare längd innerst. Det skapar en trygg stämning.", vi: "Mình khuyên nên chọn độ dài ngắn hơn một chút ở góc trong. Cách nói này tạo cảm giác an tâm.", phonetic: "/jɑːɡ ˌrɛkɔmɛnˈdeːrar ɛn ˈliːtɛ ˈkɔrːtarɛ lɛŋd ˈɪnːɛrst/" },
  { id: 354, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vill du ha mandelformade, fyrkantiga eller runda naglar? Det hjälper kunden att slappna av.", vi: "Bạn muốn móng dáng hạnh nhân, móng vuông hay móng tròn? Điều này giúp khách dễ thư giãn hơn.", phonetic: "/vɪl dʉː hɑː ˈmanːdɛlˌfɔrmadɛ ˈfʏrˌkantɪɡa ˈɛlːɛr ˈrɵnːda ˈnaɡːlar/" },
  { id: 355, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Den här nyansen passar väldigt fint till din hudton. Det är en viktig del av god service.", vi: "Tông màu này hợp với sắc da của bạn lắm đấy. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/deːn hɛːr nʏˈanːsɛn ˈpasːar ˈvɛlːdɪt fɪnt tɪl diːn ˈhʉːdˌtuːn/" },
  { id: 356, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vi kan göra gel, förstärkning med builder gel eller akryl. Det gör samtalet tydligt och vänligt.", vi: "Tụi mình có thể làm gel, đắp gel cứng hoặc đắp bột. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/viː kan ˈjœːra jeːl fœrˈstɛrkːnɪŋ meːd ˈbɪlːdɛr jeːl ˈɛlːɛr ɑˈkrʏːl/" },
  { id: 357, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vill du ha enfärgat, fransk manikyr eller chrome? Det känns naturligt och artigt.", vi: "Bạn muốn sơn một màu, kiểu Pháp hay hiệu ứng chrome? Câu này nghe tự nhiên và lịch sự.", phonetic: "/vɪl dʉː hɑː ˈeːnˌfɛrɡat fransk mɑnɪˈkʏːr ˈɛlːɛr kroːm/" },
  { id: 358, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Jag anpassar böjen efter dina naturliga fransar. Det skapar en trygg stämning.", vi: "Mình điều chỉnh độ cong theo hàng mi thật của bạn. Cách nói này tạo cảm giác an tâm.", phonetic: "/jɑːɡ ˈanːpasːar ˈbœjːɛn ˈɛfːtɛr ˈdiːna nɑtʉːˈliːra ˈfranːsar/" },
  { id: 359, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Det är bäst att skona dina egna fransar så de håller sig friska. Det hjälper kunden att slappna av.", vi: "Tốt nhất là giữ gìn mi thật để mi luôn khỏe mạnh. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/deːt ɛːr bɛst at ˈskuːna ˈdiːna ˈeːɡːna ˈfranːsar soː deː ˈhɔlːɛr sej ˈfrɪsːka/" },
  { id: 360, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Ska vi lägga till en djupgående fuktkur för händerna idag? Det är en viktig del av god service.", vi: "Hôm nay mình thêm bước dưỡng ẩm sâu cho tay nhé? Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/skɑː viː ˈlɛɡːa tɪl ɛn ˈjʉːpˌɡoːɛnːdɛ ˈfɵktˌkʉːr fœr ˈhɛnːdarːa ɪˈdɑːɡ/" },
  { id: 361, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Undvik vatten och ånga på fransarna de första tjugofyra timmarna. Det gör samtalet tydligt och vänligt.", vi: "Tránh nước và hơi nóng lên mi trong hai mươi bốn giờ đầu nhé. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/ˈɵnːdviːk ˈvatːɛn ɔ ˈɔŋːa pɔː ˈfranːsarːa deː ˈfœsːta ˈɕʉːɡʊˌfyːra ˈtɪmːarːa/" },
  { id: 362, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Gnugga inte ögonen och använd oljefria produkter. Det känns naturligt och artigt.", vi: "Đừng dụi mắt và hãy dùng sản phẩm không chứa dầu nhé. Câu này nghe tự nhiên và lịch sự.", phonetic: "/ˈɡnɵɡːa ˈɪnːtɛ ˈœːɡɔnɛn ɔ ˈanːvɛnd ˈɔlːjɛˌfriːa prʊˈdɵkːtɛr/" },
  { id: 363, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Borsta fransarna försiktigt varje morgon med borsten du får. Det skapar en trygg stämning.", vi: "Chải mi nhẹ nhàng mỗi sáng bằng cọ được tặng kèm nhé. Cách nói này tạo cảm giác an tâm.", phonetic: "/ˈbɔʂːta ˈfranːsarːa fœrˈsɪkːtɪt ˈvarːjɛ ˈmɔrːɔn meːd ˈbɔʂːtɛn dʉː fɔːr/" },
  { id: 364, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Det är dags för påfyllning om ungefär tre veckor. Det hjälper kunden att slappna av.", vi: "Khoảng ba tuần nữa là tới lúc dặm lại rồi đấy. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/deːt ɛːr daks fœr ˈpoːˌfʏlːnɪŋ ɔm ɵnːfɛˈjɛːr treː ˈvɛkːɔr/" },
  { id: 365, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Smörj nagelbanden med nagelolja varje kväll. Det är en viktig del av god service.", vi: "Thoa dầu dưỡng viền móng mỗi tối nhé. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/smœrj ˈnɑːɡɛlˌbanːdɛn meːd ˈnɑːɡɛlˌɔlːja ˈvarːjɛ kvɛlː/" },
  { id: 366, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Använd gärna handskar när du diskar eller städar. Det gör samtalet tydligt och vänligt.", vi: "Bạn nhớ đeo găng tay khi rửa chén hoặc dọn dẹp nhé. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/ˈanːvɛnd ˈjɛːrna ˈhanːskar nɛːr dʉː ˈdɪsːkar ˈɛlːɛr ˈstɛːdar/" },
  { id: 367, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Vill du boka nästa tid redan innan du går idag? Det känns naturligt och artigt.", vi: "Bạn có muốn đặt lịch lần tới ngay trước khi về hôm nay không? Câu này nghe tự nhiên và lịch sự.", phonetic: "/vɪl dʉː ˈbuːka ˈnɛsːta tiːd ˈreːdan ˈɪnːan dʉː ɡoːr ɪˈdɑːɡ/" },
  { id: 368, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Vi har en ledig tid på tisdag klockan tio. Det skapar en trygg stämning.", vi: "Tụi mình còn trống lịch vào thứ ba lúc mười giờ. Cách nói này tạo cảm giác an tâm.", phonetic: "/viː hɑːr ɛn ˈleːdɪɡ tiːd pɔː ˈtɪsːdɑːɡ ˈklɔkːan ˈtiːʊ/" },
  { id: 369, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Jag skickar en påminnelse dagen innan din tid. Det hjälper kunden att slappna av.", vi: "Mình sẽ gửi tin nhắn nhắc lịch trước ngày hẹn một ngày. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/jɑːɡ ˈɕɪkːar ɛn ˈpoːˌmɪnːɛlsɛ ˈdɑːɡɛn ˈɪnːan diːn tiːd/" },
  { id: 370, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Tack så mycket för besöket! Vi ses nästa gång. Det är en viktig del av god service.", vi: "Cảm ơn bạn rất nhiều vì đã ghé tiệm! Hẹn gặp lại lần sau nhé. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/tak soː ˈmʏkːɛt fœr bɛˈsøːkɛt viː seːs ˈnɛsːta ɡɔŋ/" },
  { id: 371, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Jag desinficerar alla verktyg mellan varje kund. Det gör samtalet tydligt och vänligt.", vi: "Mình khử trùng toàn bộ dụng cụ giữa mỗi khách hàng. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/jɑːɡ dɛsɪnfɪˈseːrar ˈalːa ˈvɛrkˌtʏːɡ ˈmɛlːan ˈvarːjɛ kɵnd/" },
  { id: 372, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Vi följer säkerhetsrutiner för härdplast och lim. Det känns naturligt och artigt.", vi: "Tụi mình tuân thủ quy trình an toàn với nhựa cứng và keo. Câu này nghe tự nhiên và lịch sự.", phonetic: "/viː ˈfœlːjɛr ˈsɛːkɛrˌheːtsrɵˌtiːnɛr fœr ˈhɛːrdˌplast ɔ liːm/" },
  { id: 373, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Jag arbetar i ett välventilerat rum med punktutsug. Det skapar en trygg stämning.", vi: "Mình làm việc trong phòng thông thoáng có máy hút khí cục bộ. Cách nói này tạo cảm giác an tâm.", phonetic: "/jɑːɡ ˈɑːrbɛtar ɪ ɛt ˈvɛːlˌvɛntɪˌleːrat rɵm meːd ˈpɵŋktˌʉːtsʉːɡ/" },
  { id: 374, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Jag byter handskar och dukar inför varje ny behandling. Det hjälper kunden att slappna av.", vi: "Mình thay găng tay và khăn trải trước mỗi liệu trình mới. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/jɑːɡ ˈbʏːtɛr ˈhanːskar ɔ ˈdʉːkar ˈɪnːfœr ˈvarːjɛ nʏː bɛˈhanːdlɪŋ/" },
  { id: 375, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Pincetterna är rengjorda och redo för dagens pass. Det är en viktig del av god service.", vi: "Các cây nhíp đã được làm sạch và sẵn sàng cho ca làm hôm nay. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/pɪnˈsɛtːarːa ɛːr ˈreːnˌjuːrda ɔ ˈreːdu fœr ˈdɑːɡɛns pasː/" },
  { id: 376, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Vi håller arbetsstationen ren, organiserad och lugn. Det gör samtalet tydligt och vänligt.", vi: "Tụi mình giữ bàn làm việc sạch sẽ, gọn gàng và yên tĩnh. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/viː ˈhɔlːɛr ˈɑːrbɛtsˌstɑːˌɕuːnɛn reːn ɔrɡanɪˈseːrad ɔ lɵŋn/" },
  { id: 377, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Jag kontrollerar att limmet har rätt konsistens och fuktighet. Det känns naturligt och artigt.", vi: "Mình kiểm tra xem keo có độ sệt và độ ẩm chuẩn chưa. Câu này nghe tự nhiên và lịch sự.", phonetic: "/jɑːɡ kɔntrɔˈleːrar at ˈlɪmːɛt hɑːr rɛt kɔnsɪsˈtɛnːs ɔ ˈfɵkːtɪˌheːt/" },
  { id: 378, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Engångsartiklar slängs i avsedd behållare direkt. Det skapar en trygg stämning.", vi: "Đồ dùng một lần được bỏ vào thùng chuyên dụng ngay lập tức. Cách nói này tạo cảm giác an tâm.", phonetic: "/ˈeːnˌɡɔŋsˌɑːrtɪklar slɛŋːs ɪ ˈɑːvˌsɛd bɛˈhɔlːarɛ dɪˈrɛkt/" },
  { id: 379, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Jag tvättar händerna noggrant före och efter varje moment. Det hjälper kunden att slappna av.", vi: "Mình rửa tay kỹ trước và sau mỗi thao tác. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/jɑːɡ ˈtvɛtːar ˈhɛnːdarːa ˈnoːɡrant ˈfœːrɛ ɔ ˈɛfːtɛr ˈvarːjɛ mʊˈmɛnːt/" },
  { id: 380, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "All utrustning står på sin plats så arbetet flyter smidigt. Det är en viktig del av god service.", vi: "Mọi thiết bị đều đúng vị trí để công việc trôi chảy mượt mà. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/alː ˈʉːtˌrɵsːnɪŋ stoːr pɔː sɪn plats soː ɑrˈbeːtɛt ˈflʏːtɛr ˈsmiːdɪt/" },
  { id: 381, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Hur ser schemat ut för resten av veckan? Det gör samtalet tydligt och vänligt.", vi: "Lịch làm việc cho phần còn lại của tuần trông thế nào? Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/hʉːr seːr ˈɕeːmat ʉːt fœr ˈrɛsːtɛn ɑːv ˈvɛkːan/" },
  { id: 382, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Jag har förberett allt inför nästa kund klocker ett. Det känns naturligt och artigt.", vi: "Mình đã chuẩn bị xong mọi thứ cho khách tiếp theo lúc một giờ. Câu này nghe tự nhiên và lịch sự.", phonetic: "/jɑːɡ hɑːr ˈfœrːbɛrɛt alːt ˈɪnːfœr ˈnɛsːta kɵnd ˈklɔkːɛn ɛt/" },
  { id: 383, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Vi behöver beställa mer franslim och primer i veckan. Det skapar en trygg stämning.", vi: "Tụi mình cần đặt thêm keo nối mi và primer trong tuần này. Cách nói này tạo cảm giác an tâm.", phonetic: "/viː bɛˈhøːvɛr bɛˈstɛlːa meːr ˈfransˌliːm ɔ ˈpraɪmɛr ɪ ˈvɛkːan/" },
  { id: 384, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Kan du hjälpa mig att ta emot nästa kund i receptionen? Det hjälper kunden att slappna av.", vi: "Bạn giúp mình đón khách tiếp theo ở quầy lễ tân được không? Điều này giúp khách dễ thư giãn hơn.", phonetic: "/kan dʉː ˈjɛlːpa mej at tɑː ɛˈmʊːt ˈnɛsːta kɵnd ɪ rɛsɛpˈɕuːnɛn/" },
  { id: 385, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Vi samarbetar bra när vi stämmer av tiderna i förväg. Det är en viktig del av god service.", vi: "Tụi mình phối hợp nhịp nhàng khi rà soát giờ giấc từ trước. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/viː ˈsɑːmarˌbeːtar brɑː nɛːr viː ˈstɛmːɛr ɑːv ˈtiːdarːa ɪ fœrˈvɛːɡ/" },
  { id: 386, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Jag antecknar kundens önskemål direkt i bokningen. Det gör samtalet tydligt och vänligt.", vi: "Mình ghi chú mong muốn của khách thẳng vào lịch đặt. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/jɑːɡ ˈanːˌteːknar ˈkɵnːdɛns ˈœnːskɛˌmoːl dɪˈrɛkt ɪ ˈbuːknɪŋɛn/" },
  { id: 387, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Kunden blev jättenöjd med resultatet idag. Det känns naturligt och artigt.", vi: "Khách hàng rất hài lòng với kết quả hôm nay. Câu này nghe tự nhiên và lịch sự.", phonetic: "/ˈkɵnːdɛn bleːv ˈjɛtːɛˌnœjd meːd rɛsɵlˈtɑːtɛt ɪˈdɑːɡ/" },
  { id: 388, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Vi städar av och fyller på förrådet innan vi stänger. Det skapar en trygg stämning.", vi: "Tụi mình dọn dẹp và châm thêm đồ dự trữ trước khi đóng cửa. Cách nói này tạo cảm giác an tâm.", phonetic: "/viː ˈstɛːdar ɑːv ɔ ˈfʏlːɛr pɔː fœˈroːdɛt ˈɪnːan viː ˈstɛŋːɛr/" },
  { id: 389, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Har någon avbokat sin tid på eftermiddagen? Det hjälper kunden att slappna av.", vi: "Có ai hủy lịch buổi chiều nay không? Điều này giúp khách dễ thư giãn hơn.", phonetic: "/hɑːr ˈnoːɡɔn ˈɑːvˌbuːkat sɪn tiːd pɔː ˈɛfːtɛrˌmɪdːaɡɛn/" },
  { id: 390, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Jag är redo att ta emot nästa bokning nu. Det är en viktig del av god service.", vi: "Mình đã sẵn sàng đón lượt đặt tiếp theo rồi. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/jɑːɡ ɛːr ˈreːdu at tɑː ɛˈmʊːt ˈnɛsːta ˈbuːknɪŋ nʉː/" },
  { id: 391, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Hur känns det nu när du ser dig i spegeln? Det gör samtalet tydligt och vänligt.", vi: "Giờ khi nhìn mình trong gương bạn thấy thế nào? Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/hʉːr ɕɛnːs deː nʉː nɛːr dʉː seːr dej ɪ ˈspeːɡɛln/" },
  { id: 392, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Är det något jag kan justera lite till innan du går? Det känns naturligt och artigt.", vi: "Có chỗ nào mình chỉnh thêm một chút trước khi bạn về không? Câu này nghe tự nhiên và lịch sự.", phonetic: "/ɛːr deː ˈnoːɡɔt jɑːɡ kan jɵsˈteːra ˈliːtɛ tɪl ˈɪnːan dʉː ɡoːr/" },
  { id: 393, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Betalningen går bra med kort eller Swish. Det skapar en trygg stämning.", vi: "Thanh toán bằng thẻ hoặc Swish đều được nhé. Cách nói này tạo cảm giác an tâm.", phonetic: "/bɛˈtɑːlnɪŋɛn ɡoːr brɑː meːd kɔʈ ˈɛlːɛr svɪʃ/" },
  { id: 394, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Här kommer kvittot. Varsågod! Det hjälper kunden att slappna av.", vi: "Hóa đơn của bạn đây. Mời bạn nhận! Điều này giúp khách dễ thư giãn hơn.", phonetic: "/hɛːr ˈkɔmːɛr ˈkvɪtːʊt ˈvɑːrʃɔˌɡuːd/" },
  { id: 395, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Tack för förtroendet och ha en riktigt fin dag! Det är en viktig del av god service.", vi: "Cảm ơn bạn đã tin tưởng và chúc bạn một ngày thật đẹp! Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/tak fœr fœrˈtrʊːɛndɛt ɔ hɑː ɛn ˈrɪkːtɪt fiːn dɑːɡ/" },
  { id: 396, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Det var så roligt att få arbeta med dina naglar idag. Det gör samtalet tydligt och vänligt.", vi: "Hôm nay được làm móng cho bạn vui lắm luôn. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/deːt vɑːr soː ˈrʊːlɪt at foː ˈɑːrbɛta meːd ˈdiːna ˈnaɡːlar ɪˈdɑːɡ/" },
  { id: 397, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Glöm inte din väska och dina personliga saker. Det känns naturligt och artigt.", vi: "Đừng quên túi xách và đồ cá nhân của bạn nhé. Câu này nghe tự nhiên và lịch sự.", phonetic: "/ɡlœm ˈɪnːtɛ diːn ˈvɛsːka ɔ ˈdiːna pɛʂʊnˈliːɡa ˈsɑːkɛr/" },
  { id: 398, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Vi finns här om du har några frågor hemma. Det skapar en trygg stämning.", vi: "Tụi mình luôn ở đây nếu về nhà bạn có thắc mắc gì. Cách nói này tạo cảm giác an tâm.", phonetic: "/viː fɪnːs hɛːr ɔm dʉː hɑːr ˈnoːɡra ˈfroːɡɔr ˈhɛmːa/" },
  { id: 399, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Ha en trevlig kväll och kör försiktigt hem! Det hjälper kunden att slappna av.", vi: "Chúc bạn buổi tối vui vẻ và đi đường về cẩn thận nhé! Điều này giúp khách dễ thư giãn hơn.", phonetic: "/hɑː ɛn ˈtreːvlɪɡ kvɛlː ɔ ɕœːr fœrˈsɪkːtɪt hɛm/" },
  { id: 400, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Välkommen tillbaka när du känner för det! Det är en viktig del av god service.", vi: "Chào mừng bạn quay lại bất cứ khi nào bạn muốn nhé! Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/ˈvɛːlˌkɔmːɛn tɪlˈbɑːka nɛːr dʉː ˈɕɛnːɛr fœr deː/" },
  { id: 401, topic: "Đón tiếp khách hàng", sv: "I salongen säger jag ofta: Hej! Välkommen till vår salong.", vi: "Trong tiệm mình thường nói: Xin chào! Chào mừng đến với tiệm của chúng tôi.", phonetic: "/hej ˈvɛːlˌkɔmːɛn tɪl voːr saˈlɔŋ/" },
  { id: 402, topic: "Đón tiếp khách hàng", sv: "När jag jobbar brukar jag säga: God morgon! Hur mår du idag?", vi: "Khi làm việc mình hay nói: Chào buổi sáng! Hôm nay bạn cảm thấy thế nào?", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr moːr dʉː ɪˈdɑːɡ/" },
  { id: 403, topic: "Đón tiếp khách hàng", sv: "Vid kundmottagning säger jag: Hej och välkommen! Har du bokat tid?", vi: "Khi đón tiếp mình nói: Xin chào và chào mừng! Bạn đã đặt lịch hẹn chưa?", phonetic: "/hej ɔ ˈvɛːlˌkɔmːɛn hɑːr dʉː ˈbuːkat tiːd/" },
  { id: 404, topic: "Đón tiếp khách hàng", sv: "Under behandlingen säger jag lugnt: Varsågod och sitt ner här en stund.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Mời bạn ngồi xuống đây một lát.", phonetic: "/ˈvɑːrʃɔˌɡuːd ɔ sɪtː neːr hɛːr ɛn stɵnd/" },
  { id: 405, topic: "Đón tiếp khách hàng", sv: "Som nagel- och franstekniker säger jag: Vad trevligt att se dig igen!", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Thật vui được gặp lại bạn!", phonetic: "/vɑːd ˈtreːvlɪɡt at seː dej ɪˈjɛn/" },
  { id: 406, topic: "Đón tiếp khách hàng", sv: "I salongen säger jag ofta: Välkommen in! Jag heter My Han och ska hjälpa dig idag.", vi: "Trong tiệm mình thường nói: Chào mừng vào tiệm! Mình tên là My Han và sẽ hỗ trợ bạn hôm nay.", phonetic: "/ˈvɛːlˌkɔmːɛn ɪn jɑːɡ ˈheːtɛr myː hɑn ɔ skɑː ˈjɛlːpa dej ɪˈdɑːɡ/" },
  { id: 407, topic: "Đón tiếp khách hàng", sv: "När jag jobbar brukar jag säga: Hur var din dag hittills?", vi: "Khi làm việc mình hay nói: Ngày của bạn từ nãy đến giờ thế nào?", phonetic: "/hʉːr vɑːr diːn dɑːɡ ˈhɪtːɪls/" },
  { id: 408, topic: "Đón tiếp khách hàng", sv: "Vid kundmottagning säger jag: Jag är så glad att du kom hit idag.", vi: "Khi đón tiếp mình nói: Mình rất vui vì hôm nay bạn đã đến đây.", phonetic: "/jɑːɡ ɛːr soː ɡlɑːd at dʉː kɔm hɪt ɪˈdɑːɡ/" },
  { id: 409, topic: "Đón tiếp khách hàng", sv: "Under behandlingen säger jag lugnt: Ta av dig jackan om du vill, så hänger jag upp den.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Bạn cởi áo khoác nếu muốn nhé, mình sẽ treo lên giúp.", phonetic: "/tɑː ɑːv dej ˈjakːan ɔm dʉː vɪl soː ˈhɛŋːɛr jɑːɡ ɵpː dɛn/" },
  { id: 410, topic: "Đón tiếp khách hàng", sv: "Som nagel- och franstekniker säger jag: Känn dig som hemma här hos oss.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Hãy cứ tự nhiên như ở nhà khi ở chỗ tụi mình nhé.", phonetic: "/ɕɛnː dej sɔm ˈhɛmːa hɛːr huːs ɔsː/" },
  { id: 411, topic: "Mời nước khách", sv: "I salongen säger jag ofta: Vill du ha något att dricka, kaffe eller vatten?", vi: "Trong tiệm mình thường nói: Bạn có muốn uống chút gì không, cà phê hay nước lọc?", phonetic: "/vɪl dʉː hɑː ˈnoːɡɔt at ˈdrɪkːa ˈkafːɛ ˈɛlːɛr ˈvatːɛn/" },
  { id: 412, topic: "Mời nước khách", sv: "När jag jobbar brukar jag säga: Vill du ha ett glas kallt vatten medan du väntar?", vi: "Khi làm việc mình hay nói: Bạn có muốn một ly nước lạnh trong lúc chờ không?", phonetic: "/vɪl dʉː hɑː ɛt ɡlɑːs kalːt ˈvatːɛn ˈmeːdan dʉː ˈvɛnːtar/" },
  { id: 413, topic: "Mời nước khách", sv: "Vid kundmottagning säger jag: Jag kan bjuda på te eller kaffe om du önskar.", vi: "Khi đón tiếp mình nói: Mình có thể mời trà hoặc cà phê nếu bạn muốn.", phonetic: "/jɑːɡ kan ˈbjʉːda pɔː teː ˈɛlːɛr ˈkafːɛ ɔm dʉː ˈœnːskar/" },
  { id: 414, topic: "Mời nước khách", sv: "Under behandlingen säger jag lugnt: Föredrar du varmt eller kallt vatten?", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Bạn thích nước ấm hay nước lạnh hơn?", phonetic: "/ˌfœrɛˈdrɑːr dʉː varmt ˈɛlːɛr kalːt ˈvatːɛn/" },
  { id: 415, topic: "Mời nước khách", sv: "Som nagel- och franstekniker säger jag: Ska jag hälla upp lite te åt dig?", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Mình rót thêm chút trà cho bạn nhé?", phonetic: "/skɑː jɑːɡ ˈhɛlːa ɵpː ˈliːtɛ teː oːt dej/" },
  { id: 416, topic: "Mời nước khách", sv: "I salongen säger jag ofta: Här kommer ditt vatten. Varsågod!", vi: "Trong tiệm mình thường nói: Nước của bạn đây. Mời bạn dùng!", phonetic: "/hɛːr ˈkɔmːɛr dɪt ˈvatːɛn ˈvɑːrʃɔˌɡuːd/" },
  { id: 417, topic: "Mời nước khách", sv: "När jag jobbar brukar jag säga: Vill du ha socker eller mjölk i kaffet?", vi: "Khi làm việc mình hay nói: Bạn có muốn thêm đường hay sữa vào cà phê không?", phonetic: "/vɪl dʉː hɑː ˈsɔkːɛr ˈɛlːɛr mjœlk ɪ ˈkafːɛt/" },
  { id: 418, topic: "Mời nước khách", sv: "Vid kundmottagning säger jag: Jag fixar en kopp varmt te direkt.", vi: "Khi đón tiếp mình nói: Mình pha một tách trà nóng ngay đây.", phonetic: "/jɑːɡ ˈfɪkːsar ɛn kɔpː varmt teː dɪˈrɛkt/" },
  { id: 419, topic: "Mời nước khách", sv: "Under behandlingen säger jag lugnt: Vill du ha en liten kaka till kaffet?", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Bạn có muốn ăn thêm một chiếc bánh nhỏ kèm cà phê không?", phonetic: "/vɪl dʉː hɑː ɛn ˈliːtɛn ˈkɑːka tɪl ˈkafːɛt/" },
  { id: 420, topic: "Mời nước khách", sv: "Som nagel- och franstekniker säger jag: Säg bara till om du vill ha påfyllning.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Cứ bảo mình nếu bạn muốn châm thêm nhé.", phonetic: "/sɛːj ˈbɑːra tɪl ɔm dʉː vɪl hɑː ˈpoːˌfʏlːnɪŋ/" },
  { id: 421, topic: "Thao tác nối mi / Spa", sv: "I salongen säger jag ofta: Blunda och slappna av nu.", vi: "Trong tiệm mình thường nói: Hãy nhắm mắt lại và thư giãn nhé.", phonetic: "/ˈblɵnːda ɔ ˈslapːna ɑːv nʉː/" },
  { id: 422, topic: "Thao tác nối mi / Spa", sv: "När jag jobbar brukar jag säga: Känns det bra och bekvämt på britsen?", vi: "Khi làm việc mình hay nói: Nằm trên giường liệu trình có thấy thoải mái không?", phonetic: "/ɕɛnːs deː brɑː ɔ bɛˈkvɛːmt pɔː brɪtːsɛn/" },
  { id: 423, topic: "Thao tác nối mi / Spa", sv: "Vid kundmottagning säger jag: Jag sätter på en mjuk ögonpad under fransarna nu.", vi: "Khi đón tiếp mình nói: Bây giờ mình dán miếng lót mắt mềm dưới hàng mi nhé.", phonetic: "/jɑːɡ ˈsɛtːɛr pɔː ɛn mjʉːk ˈœːɡɔnˌpad ɵnːdɛr ˈfranːsarːa nʉː/" },
  { id: 424, topic: "Thao tác nối mi / Spa", sv: "Under behandlingen säger jag lugnt: Säg till direkt om det svider eller sticker till.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Báo ngay cho mình nếu thấy cay hoặc châm chích nhé.", phonetic: "/sɛːj tɪl dɪˈrɛkt ɔm deː ˈsviːdɛr ˈɛlːɛr ˈstɪkːɛr tɪl/" },
  { id: 425, topic: "Thao tác nối mi / Spa", sv: "Som nagel- och franstekniker säger jag: Vi börjar med att rengöra fransarna noga.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Tụi mình bắt đầu bằng việc làm sạch mi thật kỹ.", phonetic: "/viː ˈbœrːjar meːd at ˈreːnˌjœːra ˈfranːsarːa ˈnoːɡa/" },
  { id: 426, topic: "Thao tác nối mi / Spa", sv: "I salongen säger jag ofta: Nu applicerar jag limmet försiktigt på varje frans.", vi: "Trong tiệm mình thường nói: Giờ mình gắn keo cẩn thận lên từng sợi mi.", phonetic: "/nʉː ˌapːlɪˈseːrar jɑːɡ ˈlɪmːɛt fœrˈsɪkːtɪt pɔː ˈvarːjɛ frans/" },
  { id: 427, topic: "Thao tác nối mi / Spa", sv: "När jag jobbar brukar jag säga: Känns tejpningen för stram på något ställe?", vi: "Khi làm việc mình hay nói: Miếng băng dán có bị căng ở chỗ nào không?", phonetic: "/ɕɛnːs ˈtɛjpnɪŋɛn fœr stram pɔː ˈnoːɡɔt ˈstɛlːɛ/" },
  { id: 428, topic: "Thao tác nối mi / Spa", sv: "Vid kundmottagning säger jag: Jag masserar hårbotten med lugna rörelser nu.", vi: "Khi đón tiếp mình nói: Bây giờ mình massage da đầu với các động tác nhẹ nhàng nhé.", phonetic: "/jɑːɡ maˈseːrar ˈhoːrˌbɔtːɛn meːd ˈlɵɡːna ˈrœːrɛlsɛr nʉː/" },
  { id: 429, topic: "Thao tác nối mi / Spa", sv: "Under behandlingen säger jag lugnt: Är vattnet lagom varmt när jag sköljer håret?", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Nước có vừa độ ấm khi mình xả tóc không?", phonetic: "/ɛːr ˈvatːnɛt ˈlɑːɡɔm varmt nɛːr jɑːɡ ˈɕœlːjɛr ˈhoːrɛt/" },
  { id: 430, topic: "Thao tác nối mi / Spa", sv: "Som nagel- och franstekniker säger jag: Nu är vi klara med behandlingen. Öppna ögonen sakta.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Xong liệu trình rồi đây. Bạn mở mắt từ từ nhé.", phonetic: "/nʉː ɛːr viː ˈklɑːra meːd bɛˈhanːdlɪŋɛn ˈœpːna ˈœːɡɔnɛn ˈsakːta/" },
  { id: 431, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "I salongen säger jag ofta: Vilken stil gillar du mest, naturlig eller volym?", vi: "Trong tiệm mình thường nói: Bạn thích kiểu nào nhất, tự nhiên hay dày vol?", phonetic: "/ˈvɪlːkɛn stiːl ˈjɪlːar dʉː mɛst nɑtʉːˈliːr ˈɛlːɛr vɔˈlʏːm/" },
  { id: 432, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "När jag jobbar brukar jag säga: Vill du ha en öppen docköga eller en mjuk kattöga?", vi: "Khi làm việc mình hay nói: Bạn muốn dáng mắt búp bê tròn to hay dáng mắt mèo dịu dàng?", phonetic: "/vɪl dʉː hɑː ɛn ˈœpːɛn ˈdɔkˌœːɡa ˈɛlːɛr ɛn mjʉːk ˈkatˌœːɡa/" },
  { id: 433, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vid kundmottagning säger jag: Jag rekommenderar en lite kortare längd innerst.", vi: "Khi đón tiếp mình nói: Mình khuyên nên chọn độ dài ngắn hơn một chút ở góc trong.", phonetic: "/jɑːɡ ˌrɛkɔmɛnˈdeːrar ɛn ˈliːtɛ ˈkɔrːtarɛ lɛŋd ˈɪnːɛrst/" },
  { id: 434, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Under behandlingen säger jag lugnt: Vill du ha mandelformade, fyrkantiga eller runda naglar?", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Bạn muốn móng dáng hạnh nhân, móng vuông hay móng tròn?", phonetic: "/vɪl dʉː hɑː ˈmanːdɛlˌfɔrmadɛ ˈfʏrˌkantɪɡa ˈɛlːɛr ˈrɵnːda ˈnaɡːlar/" },
  { id: 435, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Som nagel- och franstekniker säger jag: Den här nyansen passar väldigt fint till din hudton.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Tông màu này hợp với sắc da của bạn lắm đấy.", phonetic: "/deːn hɛːr nʏˈanːsɛn ˈpasːar ˈvɛlːdɪt fɪnt tɪl diːn ˈhʉːdˌtuːn/" },
  { id: 436, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "I salongen säger jag ofta: Vi kan göra gel, förstärkning med builder gel eller akryl.", vi: "Trong tiệm mình thường nói: Tụi mình có thể làm gel, đắp gel cứng hoặc đắp bột.", phonetic: "/viː kan ˈjœːra jeːl fœrˈstɛrkːnɪŋ meːd ˈbɪlːdɛr jeːl ˈɛlːɛr ɑˈkrʏːl/" },
  { id: 437, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "När jag jobbar brukar jag säga: Vill du ha enfärgat, fransk manikyr eller chrome?", vi: "Khi làm việc mình hay nói: Bạn muốn sơn một màu, kiểu Pháp hay hiệu ứng chrome?", phonetic: "/vɪl dʉː hɑː ˈeːnˌfɛrɡat fransk mɑnɪˈkʏːr ˈɛlːɛr kroːm/" },
  { id: 438, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vid kundmottagning säger jag: Jag anpassar böjen efter dina naturliga fransar.", vi: "Khi đón tiếp mình nói: Mình điều chỉnh độ cong theo hàng mi thật của bạn.", phonetic: "/jɑːɡ ˈanːpasːar ˈbœjːɛn ˈɛfːtɛr ˈdiːna nɑtʉːˈliːra ˈfranːsar/" },
  { id: 439, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Under behandlingen säger jag lugnt: Det är bäst att skona dina egna fransar så de håller sig friska.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Tốt nhất là giữ gìn mi thật để mi luôn khỏe mạnh.", phonetic: "/deːt ɛːr bɛst at ˈskuːna ˈdiːna ˈeːɡːna ˈfranːsar soː deː ˈhɔlːɛr sej ˈfrɪsːka/" },
  { id: 440, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Som nagel- och franstekniker säger jag: Ska vi lägga till en djupgående fuktkur för händerna idag?", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Hôm nay mình thêm bước dưỡng ẩm sâu cho tay nhé?", phonetic: "/skɑː viː ˈlɛɡːa tɪl ɛn ˈjʉːpˌɡoːɛnːdɛ ˈfɵktˌkʉːr fœr ˈhɛnːdarːa ɪˈdɑːɡ/" },
  { id: 441, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "I salongen säger jag ofta: Undvik vatten och ånga på fransarna de första tjugofyra timmarna.", vi: "Trong tiệm mình thường nói: Tránh nước và hơi nóng lên mi trong hai mươi bốn giờ đầu nhé.", phonetic: "/ˈɵnːdviːk ˈvatːɛn ɔ ˈɔŋːa pɔː ˈfranːsarːa deː ˈfœsːta ˈɕʉːɡʊˌfyːra ˈtɪmːarːa/" },
  { id: 442, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "När jag jobbar brukar jag säga: Gnugga inte ögonen och använd oljefria produkter.", vi: "Khi làm việc mình hay nói: Đừng dụi mắt và hãy dùng sản phẩm không chứa dầu nhé.", phonetic: "/ˈɡnɵɡːa ˈɪnːtɛ ˈœːɡɔnɛn ɔ ˈanːvɛnd ˈɔlːjɛˌfriːa prʊˈdɵkːtɛr/" },
  { id: 443, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Vid kundmottagning säger jag: Borsta fransarna försiktigt varje morgon med borsten du får.", vi: "Khi đón tiếp mình nói: Chải mi nhẹ nhàng mỗi sáng bằng cọ được tặng kèm nhé.", phonetic: "/ˈbɔʂːta ˈfranːsarːa fœrˈsɪkːtɪt ˈvarːjɛ ˈmɔrːɔn meːd ˈbɔʂːtɛn dʉː fɔːr/" },
  { id: 444, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Under behandlingen säger jag lugnt: Det är dags för påfyllning om ungefär tre veckor.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Khoảng ba tuần nữa là tới lúc dặm lại rồi đấy.", phonetic: "/deːt ɛːr daks fœr ˈpoːˌfʏlːnɪŋ ɔm ɵnːfɛˈjɛːr treː ˈvɛkːɔr/" },
  { id: 445, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Som nagel- och franstekniker säger jag: Smörj nagelbanden med nagelolja varje kväll.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Thoa dầu dưỡng viền móng mỗi tối nhé.", phonetic: "/smœrj ˈnɑːɡɛlˌbanːdɛn meːd ˈnɑːɡɛlˌɔlːja ˈvarːjɛ kvɛlː/" },
  { id: 446, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "I salongen säger jag ofta: Använd gärna handskar när du diskar eller städar.", vi: "Trong tiệm mình thường nói: Bạn nhớ đeo găng tay khi rửa chén hoặc dọn dẹp nhé.", phonetic: "/ˈanːvɛnd ˈjɛːrna ˈhanːskar nɛːr dʉː ˈdɪsːkar ˈɛlːɛr ˈstɛːdar/" },
  { id: 447, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "När jag jobbar brukar jag säga: Vill du boka nästa tid redan innan du går idag?", vi: "Khi làm việc mình hay nói: Bạn có muốn đặt lịch lần tới ngay trước khi về hôm nay không?", phonetic: "/vɪl dʉː ˈbuːka ˈnɛsːta tiːd ˈreːdan ˈɪnːan dʉː ɡoːr ɪˈdɑːɡ/" },
  { id: 448, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Vid kundmottagning säger jag: Vi har en ledig tid på tisdag klockan tio.", vi: "Khi đón tiếp mình nói: Tụi mình còn trống lịch vào thứ ba lúc mười giờ.", phonetic: "/viː hɑːr ɛn ˈleːdɪɡ tiːd pɔː ˈtɪsːdɑːɡ ˈklɔkːan ˈtiːʊ/" },
  { id: 449, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Under behandlingen säger jag lugnt: Jag skickar en påminnelse dagen innan din tid.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Mình sẽ gửi tin nhắn nhắc lịch trước ngày hẹn một ngày.", phonetic: "/jɑːɡ ˈɕɪkːar ɛn ˈpoːˌmɪnːɛlsɛ ˈdɑːɡɛn ˈɪnːan diːn tiːd/" },
  { id: 450, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Som nagel- och franstekniker säger jag: Tack så mycket för besöket! Vi ses nästa gång.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Cảm ơn bạn rất nhiều vì đã ghé tiệm! Hẹn gặp lại lần sau nhé.", phonetic: "/tak soː ˈmʏkːɛt fœr bɛˈsøːkɛt viː seːs ˈnɛsːta ɡɔŋ/" },
  { id: 451, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "I salongen säger jag ofta: Jag desinficerar alla verktyg mellan varje kund.", vi: "Trong tiệm mình thường nói: Mình khử trùng toàn bộ dụng cụ giữa mỗi khách hàng.", phonetic: "/jɑːɡ dɛsɪnfɪˈseːrar ˈalːa ˈvɛrkˌtʏːɡ ˈmɛlːan ˈvarːjɛ kɵnd/" },
  { id: 452, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "När jag jobbar brukar jag säga: Vi följer säkerhetsrutiner för härdplast och lim.", vi: "Khi làm việc mình hay nói: Tụi mình tuân thủ quy trình an toàn với nhựa cứng và keo.", phonetic: "/viː ˈfœlːjɛr ˈsɛːkɛrˌheːtsrɵˌtiːnɛr fœr ˈhɛːrdˌplast ɔ liːm/" },
  { id: 453, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Vid kundmottagning säger jag: Jag arbetar i ett välventilerat rum med punktutsug.", vi: "Khi đón tiếp mình nói: Mình làm việc trong phòng thông thoáng có máy hút khí cục bộ.", phonetic: "/jɑːɡ ˈɑːrbɛtar ɪ ɛt ˈvɛːlˌvɛntɪˌleːrat rɵm meːd ˈpɵŋktˌʉːtsʉːɡ/" },
  { id: 454, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Under behandlingen säger jag lugnt: Jag byter handskar och dukar inför varje ny behandling.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Mình thay găng tay và khăn trải trước mỗi liệu trình mới.", phonetic: "/jɑːɡ ˈbʏːtɛr ˈhanːskar ɔ ˈdʉːkar ˈɪnːfœr ˈvarːjɛ nʏː bɛˈhanːdlɪŋ/" },
  { id: 455, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Som nagel- och franstekniker säger jag: Pincetterna är rengjorda och redo för dagens pass.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Các cây nhíp đã được làm sạch và sẵn sàng cho ca làm hôm nay.", phonetic: "/pɪnˈsɛtːarːa ɛːr ˈreːnˌjuːrda ɔ ˈreːdu fœr ˈdɑːɡɛns pasː/" },
  { id: 456, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "I salongen säger jag ofta: Vi håller arbetsstationen ren, organiserad och lugn.", vi: "Trong tiệm mình thường nói: Tụi mình giữ bàn làm việc sạch sẽ, gọn gàng và yên tĩnh.", phonetic: "/viː ˈhɔlːɛr ˈɑːrbɛtsˌstɑːˌɕuːnɛn reːn ɔrɡanɪˈseːrad ɔ lɵŋn/" },
  { id: 457, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "När jag jobbar brukar jag säga: Jag kontrollerar att limmet har rätt konsistens och fuktighet.", vi: "Khi làm việc mình hay nói: Mình kiểm tra xem keo có độ sệt và độ ẩm chuẩn chưa.", phonetic: "/jɑːɡ kɔntrɔˈleːrar at ˈlɪmːɛt hɑːr rɛt kɔnsɪsˈtɛnːs ɔ ˈfɵkːtɪˌheːt/" },
  { id: 458, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Vid kundmottagning säger jag: Engångsartiklar slängs i avsedd behållare direkt.", vi: "Khi đón tiếp mình nói: Đồ dùng một lần được bỏ vào thùng chuyên dụng ngay lập tức.", phonetic: "/ˈeːnˌɡɔŋsˌɑːrtɪklar slɛŋːs ɪ ˈɑːvˌsɛd bɛˈhɔlːarɛ dɪˈrɛkt/" },
  { id: 459, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Under behandlingen säger jag lugnt: Jag tvättar händerna noggrant före och efter varje moment.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Mình rửa tay kỹ trước và sau mỗi thao tác.", phonetic: "/jɑːɡ ˈtvɛtːar ˈhɛnːdarːa ˈnoːɡrant ˈfœːrɛ ɔ ˈɛfːtɛr ˈvarːjɛ mʊˈmɛnːt/" },
  { id: 460, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Som nagel- och franstekniker säger jag: All utrustning står på sin plats så arbetet flyter smidigt.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Mọi thiết bị đều đúng vị trí để công việc trôi chảy mượt mà.", phonetic: "/alː ˈʉːtˌrɵsːnɪŋ stoːr pɔː sɪn plats soː ɑrˈbeːtɛt ˈflʏːtɛr ˈsmiːdɪt/" },
  { id: 461, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "I salongen säger jag ofta: Hur ser schemat ut för resten av veckan?", vi: "Trong tiệm mình thường nói: Lịch làm việc cho phần còn lại của tuần trông thế nào?", phonetic: "/hʉːr seːr ˈɕeːmat ʉːt fœr ˈrɛsːtɛn ɑːv ˈvɛkːan/" },
  { id: 462, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "När jag jobbar brukar jag säga: Jag har förberett allt inför nästa kund klocker ett.", vi: "Khi làm việc mình hay nói: Mình đã chuẩn bị xong mọi thứ cho khách tiếp theo lúc một giờ.", phonetic: "/jɑːɡ hɑːr ˈfœrːbɛrɛt alːt ˈɪnːfœr ˈnɛsːta kɵnd ˈklɔkːɛn ɛt/" },
  { id: 463, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Vid kundmottagning säger jag: Vi behöver beställa mer franslim och primer i veckan.", vi: "Khi đón tiếp mình nói: Tụi mình cần đặt thêm keo nối mi và primer trong tuần này.", phonetic: "/viː bɛˈhøːvɛr bɛˈstɛlːa meːr ˈfransˌliːm ɔ ˈpraɪmɛr ɪ ˈvɛkːan/" },
  { id: 464, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Under behandlingen säger jag lugnt: Kan du hjälpa mig att ta emot nästa kund i receptionen?", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Bạn giúp mình đón khách tiếp theo ở quầy lễ tân được không?", phonetic: "/kan dʉː ˈjɛlːpa mej at tɑː ɛˈmʊːt ˈnɛsːta kɵnd ɪ rɛsɛpˈɕuːnɛn/" },
  { id: 465, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Som nagel- och franstekniker säger jag: Vi samarbetar bra när vi stämmer av tiderna i förväg.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Tụi mình phối hợp nhịp nhàng khi rà soát giờ giấc từ trước.", phonetic: "/viː ˈsɑːmarˌbeːtar brɑː nɛːr viː ˈstɛmːɛr ɑːv ˈtiːdarːa ɪ fœrˈvɛːɡ/" },
  { id: 466, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "I salongen säger jag ofta: Jag antecknar kundens önskemål direkt i bokningen.", vi: "Trong tiệm mình thường nói: Mình ghi chú mong muốn của khách thẳng vào lịch đặt.", phonetic: "/jɑːɡ ˈanːˌteːknar ˈkɵnːdɛns ˈœnːskɛˌmoːl dɪˈrɛkt ɪ ˈbuːknɪŋɛn/" },
  { id: 467, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "När jag jobbar brukar jag säga: Kunden blev jättenöjd med resultatet idag.", vi: "Khi làm việc mình hay nói: Khách hàng rất hài lòng với kết quả hôm nay.", phonetic: "/ˈkɵnːdɛn bleːv ˈjɛtːɛˌnœjd meːd rɛsɵlˈtɑːtɛt ɪˈdɑːɡ/" },
  { id: 468, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Vid kundmottagning säger jag: Vi städar av och fyller på förrådet innan vi stänger.", vi: "Khi đón tiếp mình nói: Tụi mình dọn dẹp và châm thêm đồ dự trữ trước khi đóng cửa.", phonetic: "/viː ˈstɛːdar ɑːv ɔ ˈfʏlːɛr pɔː fœˈroːdɛt ˈɪnːan viː ˈstɛŋːɛr/" },
  { id: 469, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Under behandlingen säger jag lugnt: Har någon avbokat sin tid på eftermiddagen?", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Có ai hủy lịch buổi chiều nay không?", phonetic: "/hɑːr ˈnoːɡɔn ˈɑːvˌbuːkat sɪn tiːd pɔː ˈɛfːtɛrˌmɪdːaɡɛn/" },
  { id: 470, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Som nagel- och franstekniker säger jag: Jag är redo att ta emot nästa bokning nu.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Mình đã sẵn sàng đón lượt đặt tiếp theo rồi.", phonetic: "/jɑːɡ ɛːr ˈreːdu at tɑː ɛˈmʊːt ˈnɛsːta ˈbuːknɪŋ nʉː/" },
  { id: 471, topic: "Phản hồi, thanh toán & chia tay khách", sv: "I salongen säger jag ofta: Hur känns det nu när du ser dig i spegeln?", vi: "Trong tiệm mình thường nói: Giờ khi nhìn mình trong gương bạn thấy thế nào?", phonetic: "/hʉːr ɕɛnːs deː nʉː nɛːr dʉː seːr dej ɪ ˈspeːɡɛln/" },
  { id: 472, topic: "Phản hồi, thanh toán & chia tay khách", sv: "När jag jobbar brukar jag säga: Är det något jag kan justera lite till innan du går?", vi: "Khi làm việc mình hay nói: Có chỗ nào mình chỉnh thêm một chút trước khi bạn về không?", phonetic: "/ɛːr deː ˈnoːɡɔt jɑːɡ kan jɵsˈteːra ˈliːtɛ tɪl ˈɪnːan dʉː ɡoːr/" },
  { id: 473, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Vid kundmottagning säger jag: Betalningen går bra med kort eller Swish.", vi: "Khi đón tiếp mình nói: Thanh toán bằng thẻ hoặc Swish đều được nhé.", phonetic: "/bɛˈtɑːlnɪŋɛn ɡoːr brɑː meːd kɔʈ ˈɛlːɛr svɪʃ/" },
  { id: 474, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Under behandlingen säger jag lugnt: Här kommer kvittot. Varsågod!", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Hóa đơn của bạn đây. Mời bạn nhận!", phonetic: "/hɛːr ˈkɔmːɛr ˈkvɪtːʊt ˈvɑːrʃɔˌɡuːd/" },
  { id: 475, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Som nagel- och franstekniker säger jag: Tack för förtroendet och ha en riktigt fin dag!", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Cảm ơn bạn đã tin tưởng và chúc bạn một ngày thật đẹp!", phonetic: "/tak fœr fœrˈtrʊːɛndɛt ɔ hɑː ɛn ˈrɪkːtɪt fiːn dɑːɡ/" },
  { id: 476, topic: "Phản hồi, thanh toán & chia tay khách", sv: "I salongen säger jag ofta: Det var så roligt att få arbeta med dina naglar idag.", vi: "Trong tiệm mình thường nói: Hôm nay được làm móng cho bạn vui lắm luôn.", phonetic: "/deːt vɑːr soː ˈrʊːlɪt at foː ˈɑːrbɛta meːd ˈdiːna ˈnaɡːlar ɪˈdɑːɡ/" },
  { id: 477, topic: "Phản hồi, thanh toán & chia tay khách", sv: "När jag jobbar brukar jag säga: Glöm inte din väska och dina personliga saker.", vi: "Khi làm việc mình hay nói: Đừng quên túi xách và đồ cá nhân của bạn nhé.", phonetic: "/ɡlœm ˈɪnːtɛ diːn ˈvɛsːka ɔ ˈdiːna pɛʂʊnˈliːɡa ˈsɑːkɛr/" },
  { id: 478, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Vid kundmottagning säger jag: Vi finns här om du har några frågor hemma.", vi: "Khi đón tiếp mình nói: Tụi mình luôn ở đây nếu về nhà bạn có thắc mắc gì.", phonetic: "/viː fɪnːs hɛːr ɔm dʉː hɑːr ˈnoːɡra ˈfroːɡɔr ˈhɛmːa/" },
  { id: 479, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Under behandlingen säger jag lugnt: Ha en trevlig kväll och kör försiktigt hem!", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Chúc bạn buổi tối vui vẻ và đi đường về cẩn thận nhé!", phonetic: "/hɑː ɛn ˈtreːvlɪɡ kvɛlː ɔ ɕœːr fœrˈsɪkːtɪt hɛm/" },
  { id: 480, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Som nagel- och franstekniker säger jag: Välkommen tillbaka när du känner för det!", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Chào mừng bạn quay lại bất cứ khi nào bạn muốn nhé!", phonetic: "/ˈvɛːlˌkɔmːɛn tɪlˈbɑːka nɛːr dʉː ˈɕɛnːɛr fœr deː/" },
  { id: 481, topic: "Đón tiếp khách hàng", sv: "Hej! Välkommen till vår salong. Det skapar en trygg stämning.", vi: "Xin chào! Chào mừng đến với tiệm của chúng tôi. Cách nói này tạo cảm giác an tâm.", phonetic: "/hej ˈvɛːlˌkɔmːɛn tɪl voːr saˈlɔŋ/" },
  { id: 482, topic: "Đón tiếp khách hàng", sv: "God morgon! Hur mår du idag? Det hjälper kunden att slappna av.", vi: "Chào buổi sáng! Hôm nay bạn cảm thấy thế nào? Điều này giúp khách dễ thư giãn hơn.", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr moːr dʉː ɪˈdɑːɡ/" },
  { id: 483, topic: "Đón tiếp khách hàng", sv: "Hej och välkommen! Har du bokat tid? Det är en viktig del av god service.", vi: "Xin chào và chào mừng! Bạn đã đặt lịch hẹn chưa? Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/hej ɔ ˈvɛːlˌkɔmːɛn hɑːr dʉː ˈbuːkat tiːd/" },
  { id: 484, topic: "Đón tiếp khách hàng", sv: "Varsågod och sitt ner här en stund. Det gör samtalet tydligt och vänligt.", vi: "Mời bạn ngồi xuống đây một lát. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/ˈvɑːrʃɔˌɡuːd ɔ sɪtː neːr hɛːr ɛn stɵnd/" },
  { id: 485, topic: "Đón tiếp khách hàng", sv: "Vad trevligt att se dig igen! Det känns naturligt och artigt.", vi: "Thật vui được gặp lại bạn! Câu này nghe tự nhiên và lịch sự.", phonetic: "/vɑːd ˈtreːvlɪɡt at seː dej ɪˈjɛn/" },
  { id: 486, topic: "Đón tiếp khách hàng", sv: "Välkommen in! Jag heter My Han och ska hjälpa dig idag. Det skapar en trygg stämning.", vi: "Chào mừng vào tiệm! Mình tên là My Han và sẽ hỗ trợ bạn hôm nay. Cách nói này tạo cảm giác an tâm.", phonetic: "/ˈvɛːlˌkɔmːɛn ɪn jɑːɡ ˈheːtɛr myː hɑn ɔ skɑː ˈjɛlːpa dej ɪˈdɑːɡ/" },
  { id: 487, topic: "Đón tiếp khách hàng", sv: "Hur var din dag hittills? Det hjälper kunden att slappna av.", vi: "Ngày của bạn từ nãy đến giờ thế nào? Điều này giúp khách dễ thư giãn hơn.", phonetic: "/hʉːr vɑːr diːn dɑːɡ ˈhɪtːɪls/" },
  { id: 488, topic: "Đón tiếp khách hàng", sv: "Jag är så glad att du kom hit idag. Det är en viktig del av god service.", vi: "Mình rất vui vì hôm nay bạn đã đến đây. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/jɑːɡ ɛːr soː ɡlɑːd at dʉː kɔm hɪt ɪˈdɑːɡ/" },
  { id: 489, topic: "Đón tiếp khách hàng", sv: "Ta av dig jackan om du vill, så hänger jag upp den. Det gör samtalet tydligt och vänligt.", vi: "Bạn cởi áo khoác nếu muốn nhé, mình sẽ treo lên giúp. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/tɑː ɑːv dej ˈjakːan ɔm dʉː vɪl soː ˈhɛŋːɛr jɑːɡ ɵpː dɛn/" },
  { id: 490, topic: "Đón tiếp khách hàng", sv: "Känn dig som hemma här hos oss. Det känns naturligt och artigt.", vi: "Hãy cứ tự nhiên như ở nhà khi ở chỗ tụi mình nhé. Câu này nghe tự nhiên và lịch sự.", phonetic: "/ɕɛnː dej sɔm ˈhɛmːa hɛːr huːs ɔsː/" },
  { id: 491, topic: "Mời nước khách", sv: "Vill du ha något att dricka, kaffe eller vatten? Det skapar en trygg stämning.", vi: "Bạn có muốn uống chút gì không, cà phê hay nước lọc? Cách nói này tạo cảm giác an tâm.", phonetic: "/vɪl dʉː hɑː ˈnoːɡɔt at ˈdrɪkːa ˈkafːɛ ˈɛlːɛr ˈvatːɛn/" },
  { id: 492, topic: "Mời nước khách", sv: "Vill du ha ett glas kallt vatten medan du väntar? Det hjälper kunden att slappna av.", vi: "Bạn có muốn một ly nước lạnh trong lúc chờ không? Điều này giúp khách dễ thư giãn hơn.", phonetic: "/vɪl dʉː hɑː ɛt ɡlɑːs kalːt ˈvatːɛn ˈmeːdan dʉː ˈvɛnːtar/" },
  { id: 493, topic: "Mời nước khách", sv: "Jag kan bjuda på te eller kaffe om du önskar. Det är en viktig del av god service.", vi: "Mình có thể mời trà hoặc cà phê nếu bạn muốn. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/jɑːɡ kan ˈbjʉːda pɔː teː ˈɛlːɛr ˈkafːɛ ɔm dʉː ˈœnːskar/" },
  { id: 494, topic: "Mời nước khách", sv: "Föredrar du varmt eller kallt vatten? Det gör samtalet tydligt och vänligt.", vi: "Bạn thích nước ấm hay nước lạnh hơn? Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/ˌfœrɛˈdrɑːr dʉː varmt ˈɛlːɛr kalːt ˈvatːɛn/" },
  { id: 495, topic: "Mời nước khách", sv: "Ska jag hälla upp lite te åt dig? Det känns naturligt och artigt.", vi: "Mình rót thêm chút trà cho bạn nhé? Câu này nghe tự nhiên và lịch sự.", phonetic: "/skɑː jɑːɡ ˈhɛlːa ɵpː ˈliːtɛ teː oːt dej/" },
  { id: 496, topic: "Mời nước khách", sv: "Här kommer ditt vatten. Varsågod! Det skapar en trygg stämning.", vi: "Nước của bạn đây. Mời bạn dùng! Cách nói này tạo cảm giác an tâm.", phonetic: "/hɛːr ˈkɔmːɛr dɪt ˈvatːɛn ˈvɑːrʃɔˌɡuːd/" },
  { id: 497, topic: "Mời nước khách", sv: "Vill du ha socker eller mjölk i kaffet? Det hjälper kunden att slappna av.", vi: "Bạn có muốn thêm đường hay sữa vào cà phê không? Điều này giúp khách dễ thư giãn hơn.", phonetic: "/vɪl dʉː hɑː ˈsɔkːɛr ˈɛlːɛr mjœlk ɪ ˈkafːɛt/" },
  { id: 498, topic: "Mời nước khách", sv: "Jag fixar en kopp varmt te direkt. Det är en viktig del av god service.", vi: "Mình pha một tách trà nóng ngay đây. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/jɑːɡ ˈfɪkːsar ɛn kɔpː varmt teː dɪˈrɛkt/" },
  { id: 499, topic: "Mời nước khách", sv: "Vill du ha en liten kaka till kaffet? Det gör samtalet tydligt och vänligt.", vi: "Bạn có muốn ăn thêm một chiếc bánh nhỏ kèm cà phê không? Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/vɪl dʉː hɑː ɛn ˈliːtɛn ˈkɑːka tɪl ˈkafːɛt/" },
  { id: 500, topic: "Mời nước khách", sv: "Säg bara till om du vill ha påfyllning. Det känns naturligt och artigt.", vi: "Cứ bảo mình nếu bạn muốn châm thêm nhé. Câu này nghe tự nhiên và lịch sự.", phonetic: "/sɛːj ˈbɑːra tɪl ɔm dʉː vɪl hɑː ˈpoːˌfʏlːnɪŋ/" },
  { id: 501, topic: "Thao tác nối mi / Spa", sv: "Blunda och slappna av nu. Det skapar en trygg stämning.", vi: "Hãy nhắm mắt lại và thư giãn nhé. Cách nói này tạo cảm giác an tâm.", phonetic: "/ˈblɵnːda ɔ ˈslapːna ɑːv nʉː/" },
  { id: 502, topic: "Thao tác nối mi / Spa", sv: "Känns det bra och bekvämt på britsen? Det hjälper kunden att slappna av.", vi: "Nằm trên giường liệu trình có thấy thoải mái không? Điều này giúp khách dễ thư giãn hơn.", phonetic: "/ɕɛnːs deː brɑː ɔ bɛˈkvɛːmt pɔː brɪtːsɛn/" },
  { id: 503, topic: "Thao tác nối mi / Spa", sv: "Jag sätter på en mjuk ögonpad under fransarna nu. Det är en viktig del av god service.", vi: "Bây giờ mình dán miếng lót mắt mềm dưới hàng mi nhé. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/jɑːɡ ˈsɛtːɛr pɔː ɛn mjʉːk ˈœːɡɔnˌpad ɵnːdɛr ˈfranːsarːa nʉː/" },
  { id: 504, topic: "Thao tác nối mi / Spa", sv: "Säg till direkt om det svider eller sticker till. Det gör samtalet tydligt och vänligt.", vi: "Báo ngay cho mình nếu thấy cay hoặc châm chích nhé. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/sɛːj tɪl dɪˈrɛkt ɔm deː ˈsviːdɛr ˈɛlːɛr ˈstɪkːɛr tɪl/" },
  { id: 505, topic: "Thao tác nối mi / Spa", sv: "Vi börjar med att rengöra fransarna noga. Det känns naturligt och artigt.", vi: "Tụi mình bắt đầu bằng việc làm sạch mi thật kỹ. Câu này nghe tự nhiên và lịch sự.", phonetic: "/viː ˈbœrːjar meːd at ˈreːnˌjœːra ˈfranːsarːa ˈnoːɡa/" },
  { id: 506, topic: "Thao tác nối mi / Spa", sv: "Nu applicerar jag limmet försiktigt på varje frans. Det skapar en trygg stämning.", vi: "Giờ mình gắn keo cẩn thận lên từng sợi mi. Cách nói này tạo cảm giác an tâm.", phonetic: "/nʉː ˌapːlɪˈseːrar jɑːɡ ˈlɪmːɛt fœrˈsɪkːtɪt pɔː ˈvarːjɛ frans/" },
  { id: 507, topic: "Thao tác nối mi / Spa", sv: "Känns tejpningen för stram på något ställe? Det hjälper kunden att slappna av.", vi: "Miếng băng dán có bị căng ở chỗ nào không? Điều này giúp khách dễ thư giãn hơn.", phonetic: "/ɕɛnːs ˈtɛjpnɪŋɛn fœr stram pɔː ˈnoːɡɔt ˈstɛlːɛ/" },
  { id: 508, topic: "Thao tác nối mi / Spa", sv: "Jag masserar hårbotten med lugna rörelser nu. Det är en viktig del av god service.", vi: "Bây giờ mình massage da đầu với các động tác nhẹ nhàng nhé. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/jɑːɡ maˈseːrar ˈhoːrˌbɔtːɛn meːd ˈlɵɡːna ˈrœːrɛlsɛr nʉː/" },
  { id: 509, topic: "Thao tác nối mi / Spa", sv: "Är vattnet lagom varmt när jag sköljer håret? Det gör samtalet tydligt och vänligt.", vi: "Nước có vừa độ ấm khi mình xả tóc không? Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/ɛːr ˈvatːnɛt ˈlɑːɡɔm varmt nɛːr jɑːɡ ˈɕœlːjɛr ˈhoːrɛt/" },
  { id: 510, topic: "Thao tác nối mi / Spa", sv: "Nu är vi klara med behandlingen. Öppna ögonen sakta. Det känns naturligt och artigt.", vi: "Xong liệu trình rồi đây. Bạn mở mắt từ từ nhé. Câu này nghe tự nhiên và lịch sự.", phonetic: "/nʉː ɛːr viː ˈklɑːra meːd bɛˈhanːdlɪŋɛn ˈœpːna ˈœːɡɔnɛn ˈsakːta/" },
  { id: 511, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vilken stil gillar du mest, naturlig eller volym? Det skapar en trygg stämning.", vi: "Bạn thích kiểu nào nhất, tự nhiên hay dày vol? Cách nói này tạo cảm giác an tâm.", phonetic: "/ˈvɪlːkɛn stiːl ˈjɪlːar dʉː mɛst nɑtʉːˈliːr ˈɛlːɛr vɔˈlʏːm/" },
  { id: 512, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vill du ha en öppen docköga eller en mjuk kattöga? Det hjälper kunden att slappna av.", vi: "Bạn muốn dáng mắt búp bê tròn to hay dáng mắt mèo dịu dàng? Điều này giúp khách dễ thư giãn hơn.", phonetic: "/vɪl dʉː hɑː ɛn ˈœpːɛn ˈdɔkˌœːɡa ˈɛlːɛr ɛn mjʉːk ˈkatˌœːɡa/" },
  { id: 513, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Jag rekommenderar en lite kortare längd innerst. Det är en viktig del av god service.", vi: "Mình khuyên nên chọn độ dài ngắn hơn một chút ở góc trong. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/jɑːɡ ˌrɛkɔmɛnˈdeːrar ɛn ˈliːtɛ ˈkɔrːtarɛ lɛŋd ˈɪnːɛrst/" },
  { id: 514, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vill du ha mandelformade, fyrkantiga eller runda naglar? Det gör samtalet tydligt och vänligt.", vi: "Bạn muốn móng dáng hạnh nhân, móng vuông hay móng tròn? Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/vɪl dʉː hɑː ˈmanːdɛlˌfɔrmadɛ ˈfʏrˌkantɪɡa ˈɛlːɛr ˈrɵnːda ˈnaɡːlar/" },
  { id: 515, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Den här nyansen passar väldigt fint till din hudton. Det känns naturligt och artigt.", vi: "Tông màu này hợp với sắc da của bạn lắm đấy. Câu này nghe tự nhiên và lịch sự.", phonetic: "/deːn hɛːr nʏˈanːsɛn ˈpasːar ˈvɛlːdɪt fɪnt tɪl diːn ˈhʉːdˌtuːn/" },
  { id: 516, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vi kan göra gel, förstärkning med builder gel eller akryl. Det skapar en trygg stämning.", vi: "Tụi mình có thể làm gel, đắp gel cứng hoặc đắp bột. Cách nói này tạo cảm giác an tâm.", phonetic: "/viː kan ˈjœːra jeːl fœrˈstɛrkːnɪŋ meːd ˈbɪlːdɛr jeːl ˈɛlːɛr ɑˈkrʏːl/" },
  { id: 517, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vill du ha enfärgat, fransk manikyr eller chrome? Det hjälper kunden att slappna av.", vi: "Bạn muốn sơn một màu, kiểu Pháp hay hiệu ứng chrome? Điều này giúp khách dễ thư giãn hơn.", phonetic: "/vɪl dʉː hɑː ˈeːnˌfɛrɡat fransk mɑnɪˈkʏːr ˈɛlːɛr kroːm/" },
  { id: 518, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Jag anpassar böjen efter dina naturliga fransar. Det är en viktig del av god service.", vi: "Mình điều chỉnh độ cong theo hàng mi thật của bạn. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/jɑːɡ ˈanːpasːar ˈbœjːɛn ˈɛfːtɛr ˈdiːna nɑtʉːˈliːra ˈfranːsar/" },
  { id: 519, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Det är bäst att skona dina egna fransar så de håller sig friska. Det gör samtalet tydligt och vänligt.", vi: "Tốt nhất là giữ gìn mi thật để mi luôn khỏe mạnh. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/deːt ɛːr bɛst at ˈskuːna ˈdiːna ˈeːɡːna ˈfranːsar soː deː ˈhɔlːɛr sej ˈfrɪsːka/" },
  { id: 520, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Ska vi lägga till en djupgående fuktkur för händerna idag? Det känns naturligt och artigt.", vi: "Hôm nay mình thêm bước dưỡng ẩm sâu cho tay nhé? Câu này nghe tự nhiên và lịch sự.", phonetic: "/skɑː viː ˈlɛɡːa tɪl ɛn ˈjʉːpˌɡoːɛnːdɛ ˈfɵktˌkʉːr fœr ˈhɛnːdarːa ɪˈdɑːɡ/" },
  { id: 521, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Undvik vatten och ånga på fransarna de första tjugofyra timmarna. Det skapar en trygg stämning.", vi: "Tránh nước và hơi nóng lên mi trong hai mươi bốn giờ đầu nhé. Cách nói này tạo cảm giác an tâm.", phonetic: "/ˈɵnːdviːk ˈvatːɛn ɔ ˈɔŋːa pɔː ˈfranːsarːa deː ˈfœsːta ˈɕʉːɡʊˌfyːra ˈtɪmːarːa/" },
  { id: 522, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Gnugga inte ögonen och använd oljefria produkter. Det hjälper kunden att slappna av.", vi: "Đừng dụi mắt và hãy dùng sản phẩm không chứa dầu nhé. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/ˈɡnɵɡːa ˈɪnːtɛ ˈœːɡɔnɛn ɔ ˈanːvɛnd ˈɔlːjɛˌfriːa prʊˈdɵkːtɛr/" },
  { id: 523, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Borsta fransarna försiktigt varje morgon med borsten du får. Det är en viktig del av god service.", vi: "Chải mi nhẹ nhàng mỗi sáng bằng cọ được tặng kèm nhé. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/ˈbɔʂːta ˈfranːsarːa fœrˈsɪkːtɪt ˈvarːjɛ ˈmɔrːɔn meːd ˈbɔʂːtɛn dʉː fɔːr/" },
  { id: 524, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Det är dags för påfyllning om ungefär tre veckor. Det gör samtalet tydligt och vänligt.", vi: "Khoảng ba tuần nữa là tới lúc dặm lại rồi đấy. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/deːt ɛːr daks fœr ˈpoːˌfʏlːnɪŋ ɔm ɵnːfɛˈjɛːr treː ˈvɛkːɔr/" },
  { id: 525, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Smörj nagelbanden med nagelolja varje kväll. Det känns naturligt och artigt.", vi: "Thoa dầu dưỡng viền móng mỗi tối nhé. Câu này nghe tự nhiên và lịch sự.", phonetic: "/smœrj ˈnɑːɡɛlˌbanːdɛn meːd ˈnɑːɡɛlˌɔlːja ˈvarːjɛ kvɛlː/" },
  { id: 526, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Använd gärna handskar när du diskar eller städar. Det skapar en trygg stämning.", vi: "Bạn nhớ đeo găng tay khi rửa chén hoặc dọn dẹp nhé. Cách nói này tạo cảm giác an tâm.", phonetic: "/ˈanːvɛnd ˈjɛːrna ˈhanːskar nɛːr dʉː ˈdɪsːkar ˈɛlːɛr ˈstɛːdar/" },
  { id: 527, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Vill du boka nästa tid redan innan du går idag? Det hjälper kunden att slappna av.", vi: "Bạn có muốn đặt lịch lần tới ngay trước khi về hôm nay không? Điều này giúp khách dễ thư giãn hơn.", phonetic: "/vɪl dʉː ˈbuːka ˈnɛsːta tiːd ˈreːdan ˈɪnːan dʉː ɡoːr ɪˈdɑːɡ/" },
  { id: 528, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Vi har en ledig tid på tisdag klockan tio. Det är en viktig del av god service.", vi: "Tụi mình còn trống lịch vào thứ ba lúc mười giờ. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/viː hɑːr ɛn ˈleːdɪɡ tiːd pɔː ˈtɪsːdɑːɡ ˈklɔkːan ˈtiːʊ/" },
  { id: 529, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Jag skickar en påminnelse dagen innan din tid. Det gör samtalet tydligt och vänligt.", vi: "Mình sẽ gửi tin nhắn nhắc lịch trước ngày hẹn một ngày. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/jɑːɡ ˈɕɪkːar ɛn ˈpoːˌmɪnːɛlsɛ ˈdɑːɡɛn ˈɪnːan diːn tiːd/" },
  { id: 530, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Tack så mycket för besöket! Vi ses nästa gång. Det känns naturligt och artigt.", vi: "Cảm ơn bạn rất nhiều vì đã ghé tiệm! Hẹn gặp lại lần sau nhé. Câu này nghe tự nhiên và lịch sự.", phonetic: "/tak soː ˈmʏkːɛt fœr bɛˈsøːkɛt viː seːs ˈnɛsːta ɡɔŋ/" },
  { id: 531, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Jag desinficerar alla verktyg mellan varje kund. Det skapar en trygg stämning.", vi: "Mình khử trùng toàn bộ dụng cụ giữa mỗi khách hàng. Cách nói này tạo cảm giác an tâm.", phonetic: "/jɑːɡ dɛsɪnfɪˈseːrar ˈalːa ˈvɛrkˌtʏːɡ ˈmɛlːan ˈvarːjɛ kɵnd/" },
  { id: 532, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Vi följer säkerhetsrutiner för härdplast och lim. Det hjälper kunden att slappna av.", vi: "Tụi mình tuân thủ quy trình an toàn với nhựa cứng và keo. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/viː ˈfœlːjɛr ˈsɛːkɛrˌheːtsrɵˌtiːnɛr fœr ˈhɛːrdˌplast ɔ liːm/" },
  { id: 533, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Jag arbetar i ett välventilerat rum med punktutsug. Det är en viktig del av god service.", vi: "Mình làm việc trong phòng thông thoáng có máy hút khí cục bộ. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/jɑːɡ ˈɑːrbɛtar ɪ ɛt ˈvɛːlˌvɛntɪˌleːrat rɵm meːd ˈpɵŋktˌʉːtsʉːɡ/" },
  { id: 534, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Jag byter handskar och dukar inför varje ny behandling. Det gör samtalet tydligt och vänligt.", vi: "Mình thay găng tay và khăn trải trước mỗi liệu trình mới. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/jɑːɡ ˈbʏːtɛr ˈhanːskar ɔ ˈdʉːkar ˈɪnːfœr ˈvarːjɛ nʏː bɛˈhanːdlɪŋ/" },
  { id: 535, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Pincetterna är rengjorda och redo för dagens pass. Det känns naturligt och artigt.", vi: "Các cây nhíp đã được làm sạch và sẵn sàng cho ca làm hôm nay. Câu này nghe tự nhiên và lịch sự.", phonetic: "/pɪnˈsɛtːarːa ɛːr ˈreːnˌjuːrda ɔ ˈreːdu fœr ˈdɑːɡɛns pasː/" },
  { id: 536, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Vi håller arbetsstationen ren, organiserad och lugn. Det skapar en trygg stämning.", vi: "Tụi mình giữ bàn làm việc sạch sẽ, gọn gàng và yên tĩnh. Cách nói này tạo cảm giác an tâm.", phonetic: "/viː ˈhɔlːɛr ˈɑːrbɛtsˌstɑːˌɕuːnɛn reːn ɔrɡanɪˈseːrad ɔ lɵŋn/" },
  { id: 537, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Jag kontrollerar att limmet har rätt konsistens och fuktighet. Det hjälper kunden att slappna av.", vi: "Mình kiểm tra xem keo có độ sệt và độ ẩm chuẩn chưa. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/jɑːɡ kɔntrɔˈleːrar at ˈlɪmːɛt hɑːr rɛt kɔnsɪsˈtɛnːs ɔ ˈfɵkːtɪˌheːt/" },
  { id: 538, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Engångsartiklar slängs i avsedd behållare direkt. Det är en viktig del av god service.", vi: "Đồ dùng một lần được bỏ vào thùng chuyên dụng ngay lập tức. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/ˈeːnˌɡɔŋsˌɑːrtɪklar slɛŋːs ɪ ˈɑːvˌsɛd bɛˈhɔlːarɛ dɪˈrɛkt/" },
  { id: 539, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Jag tvättar händerna noggrant före och efter varje moment. Det gör samtalet tydligt och vänligt.", vi: "Mình rửa tay kỹ trước và sau mỗi thao tác. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/jɑːɡ ˈtvɛtːar ˈhɛnːdarːa ˈnoːɡrant ˈfœːrɛ ɔ ˈɛfːtɛr ˈvarːjɛ mʊˈmɛnːt/" },
  { id: 540, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "All utrustning står på sin plats så arbetet flyter smidigt. Det känns naturligt och artigt.", vi: "Mọi thiết bị đều đúng vị trí để công việc trôi chảy mượt mà. Câu này nghe tự nhiên và lịch sự.", phonetic: "/alː ˈʉːtˌrɵsːnɪŋ stoːr pɔː sɪn plats soː ɑrˈbeːtɛt ˈflʏːtɛr ˈsmiːdɪt/" },
  { id: 541, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Hur ser schemat ut för resten av veckan? Det skapar en trygg stämning.", vi: "Lịch làm việc cho phần còn lại của tuần trông thế nào? Cách nói này tạo cảm giác an tâm.", phonetic: "/hʉːr seːr ˈɕeːmat ʉːt fœr ˈrɛsːtɛn ɑːv ˈvɛkːan/" },
  { id: 542, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Jag har förberett allt inför nästa kund klocker ett. Det hjälper kunden att slappna av.", vi: "Mình đã chuẩn bị xong mọi thứ cho khách tiếp theo lúc một giờ. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/jɑːɡ hɑːr ˈfœrːbɛrɛt alːt ˈɪnːfœr ˈnɛsːta kɵnd ˈklɔkːɛn ɛt/" },
  { id: 543, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Vi behöver beställa mer franslim och primer i veckan. Det är en viktig del av god service.", vi: "Tụi mình cần đặt thêm keo nối mi và primer trong tuần này. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/viː bɛˈhøːvɛr bɛˈstɛlːa meːr ˈfransˌliːm ɔ ˈpraɪmɛr ɪ ˈvɛkːan/" },
  { id: 544, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Kan du hjälpa mig att ta emot nästa kund i receptionen? Det gör samtalet tydligt och vänligt.", vi: "Bạn giúp mình đón khách tiếp theo ở quầy lễ tân được không? Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/kan dʉː ˈjɛlːpa mej at tɑː ɛˈmʊːt ˈnɛsːta kɵnd ɪ rɛsɛpˈɕuːnɛn/" },
  { id: 545, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Vi samarbetar bra när vi stämmer av tiderna i förväg. Det känns naturligt och artigt.", vi: "Tụi mình phối hợp nhịp nhàng khi rà soát giờ giấc từ trước. Câu này nghe tự nhiên và lịch sự.", phonetic: "/viː ˈsɑːmarˌbeːtar brɑː nɛːr viː ˈstɛmːɛr ɑːv ˈtiːdarːa ɪ fœrˈvɛːɡ/" },
  { id: 546, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Jag antecknar kundens önskemål direkt i bokningen. Det skapar en trygg stämning.", vi: "Mình ghi chú mong muốn của khách thẳng vào lịch đặt. Cách nói này tạo cảm giác an tâm.", phonetic: "/jɑːɡ ˈanːˌteːknar ˈkɵnːdɛns ˈœnːskɛˌmoːl dɪˈrɛkt ɪ ˈbuːknɪŋɛn/" },
  { id: 547, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Kunden blev jättenöjd med resultatet idag. Det hjälper kunden att slappna av.", vi: "Khách hàng rất hài lòng với kết quả hôm nay. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/ˈkɵnːdɛn bleːv ˈjɛtːɛˌnœjd meːd rɛsɵlˈtɑːtɛt ɪˈdɑːɡ/" },
  { id: 548, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Vi städar av och fyller på förrådet innan vi stänger. Det är en viktig del av god service.", vi: "Tụi mình dọn dẹp và châm thêm đồ dự trữ trước khi đóng cửa. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/viː ˈstɛːdar ɑːv ɔ ˈfʏlːɛr pɔː fœˈroːdɛt ˈɪnːan viː ˈstɛŋːɛr/" },
  { id: 549, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Har någon avbokat sin tid på eftermiddagen? Det gör samtalet tydligt och vänligt.", vi: "Có ai hủy lịch buổi chiều nay không? Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/hɑːr ˈnoːɡɔn ˈɑːvˌbuːkat sɪn tiːd pɔː ˈɛfːtɛrˌmɪdːaɡɛn/" },
  { id: 550, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Jag är redo att ta emot nästa bokning nu. Det känns naturligt och artigt.", vi: "Mình đã sẵn sàng đón lượt đặt tiếp theo rồi. Câu này nghe tự nhiên và lịch sự.", phonetic: "/jɑːɡ ɛːr ˈreːdu at tɑː ɛˈmʊːt ˈnɛsːta ˈbuːknɪŋ nʉː/" },
  { id: 551, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Hur känns det nu när du ser dig i spegeln? Det skapar en trygg stämning.", vi: "Giờ khi nhìn mình trong gương bạn thấy thế nào? Cách nói này tạo cảm giác an tâm.", phonetic: "/hʉːr ɕɛnːs deː nʉː nɛːr dʉː seːr dej ɪ ˈspeːɡɛln/" },
  { id: 552, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Är det något jag kan justera lite till innan du går? Det hjälper kunden att slappna av.", vi: "Có chỗ nào mình chỉnh thêm một chút trước khi bạn về không? Điều này giúp khách dễ thư giãn hơn.", phonetic: "/ɛːr deː ˈnoːɡɔt jɑːɡ kan jɵsˈteːra ˈliːtɛ tɪl ˈɪnːan dʉː ɡoːr/" },
  { id: 553, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Betalningen går bra med kort eller Swish. Det är en viktig del av god service.", vi: "Thanh toán bằng thẻ hoặc Swish đều được nhé. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/bɛˈtɑːlnɪŋɛn ɡoːr brɑː meːd kɔʈ ˈɛlːɛr svɪʃ/" },
  { id: 554, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Här kommer kvittot. Varsågod! Det gör samtalet tydligt och vänligt.", vi: "Hóa đơn của bạn đây. Mời bạn nhận! Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/hɛːr ˈkɔmːɛr ˈkvɪtːʊt ˈvɑːrʃɔˌɡuːd/" },
  { id: 555, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Tack för förtroendet och ha en riktigt fin dag! Det känns naturligt och artigt.", vi: "Cảm ơn bạn đã tin tưởng và chúc bạn một ngày thật đẹp! Câu này nghe tự nhiên và lịch sự.", phonetic: "/tak fœr fœrˈtrʊːɛndɛt ɔ hɑː ɛn ˈrɪkːtɪt fiːn dɑːɡ/" },
  { id: 556, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Det var så roligt att få arbeta med dina naglar idag. Det skapar en trygg stämning.", vi: "Hôm nay được làm móng cho bạn vui lắm luôn. Cách nói này tạo cảm giác an tâm.", phonetic: "/deːt vɑːr soː ˈrʊːlɪt at foː ˈɑːrbɛta meːd ˈdiːna ˈnaɡːlar ɪˈdɑːɡ/" },
  { id: 557, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Glöm inte din väska och dina personliga saker. Det hjälper kunden att slappna av.", vi: "Đừng quên túi xách và đồ cá nhân của bạn nhé. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/ɡlœm ˈɪnːtɛ diːn ˈvɛsːka ɔ ˈdiːna pɛʂʊnˈliːɡa ˈsɑːkɛr/" },
  { id: 558, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Vi finns här om du har några frågor hemma. Det är en viktig del av god service.", vi: "Tụi mình luôn ở đây nếu về nhà bạn có thắc mắc gì. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/viː fɪnːs hɛːr ɔm dʉː hɑːr ˈnoːɡra ˈfroːɡɔr ˈhɛmːa/" },
  { id: 559, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Ha en trevlig kväll och kör försiktigt hem! Det gör samtalet tydligt och vänligt.", vi: "Chúc bạn buổi tối vui vẻ và đi đường về cẩn thận nhé! Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/hɑː ɛn ˈtreːvlɪɡ kvɛlː ɔ ɕœːr fœrˈsɪkːtɪt hɛm/" },
  { id: 560, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Välkommen tillbaka när du känner för det! Det känns naturligt och artigt.", vi: "Chào mừng bạn quay lại bất cứ khi nào bạn muốn nhé! Câu này nghe tự nhiên và lịch sự.", phonetic: "/ˈvɛːlˌkɔmːɛn tɪlˈbɑːka nɛːr dʉː ˈɕɛnːɛr fœr deː/" },
  { id: 561, topic: "Đón tiếp khách hàng", sv: "Vid kundmottagning säger jag: Hej! Välkommen till vår salong.", vi: "Khi đón tiếp mình nói: Xin chào! Chào mừng đến với tiệm của chúng tôi.", phonetic: "/hej ˈvɛːlˌkɔmːɛn tɪl voːr saˈlɔŋ/" },
  { id: 562, topic: "Đón tiếp khách hàng", sv: "Under behandlingen säger jag lugnt: God morgon! Hur mår du idag?", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Chào buổi sáng! Hôm nay bạn cảm thấy thế nào?", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr moːr dʉː ɪˈdɑːɡ/" },
  { id: 563, topic: "Đón tiếp khách hàng", sv: "Som nagel- och franstekniker säger jag: Hej och välkommen! Har du bokat tid?", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Xin chào và chào mừng! Bạn đã đặt lịch hẹn chưa?", phonetic: "/hej ɔ ˈvɛːlˌkɔmːɛn hɑːr dʉː ˈbuːkat tiːd/" },
  { id: 564, topic: "Đón tiếp khách hàng", sv: "I salongen säger jag ofta: Varsågod och sitt ner här en stund.", vi: "Trong tiệm mình thường nói: Mời bạn ngồi xuống đây một lát.", phonetic: "/ˈvɑːrʃɔˌɡuːd ɔ sɪtː neːr hɛːr ɛn stɵnd/" },
  { id: 565, topic: "Đón tiếp khách hàng", sv: "När jag jobbar brukar jag säga: Vad trevligt att se dig igen!", vi: "Khi làm việc mình hay nói: Thật vui được gặp lại bạn!", phonetic: "/vɑːd ˈtreːvlɪɡt at seː dej ɪˈjɛn/" },
  { id: 566, topic: "Đón tiếp khách hàng", sv: "Vid kundmottagning säger jag: Välkommen in! Jag heter My Han och ska hjälpa dig idag.", vi: "Khi đón tiếp mình nói: Chào mừng vào tiệm! Mình tên là My Han và sẽ hỗ trợ bạn hôm nay.", phonetic: "/ˈvɛːlˌkɔmːɛn ɪn jɑːɡ ˈheːtɛr myː hɑn ɔ skɑː ˈjɛlːpa dej ɪˈdɑːɡ/" },
  { id: 567, topic: "Đón tiếp khách hàng", sv: "Under behandlingen säger jag lugnt: Hur var din dag hittills?", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Ngày của bạn từ nãy đến giờ thế nào?", phonetic: "/hʉːr vɑːr diːn dɑːɡ ˈhɪtːɪls/" },
  { id: 568, topic: "Đón tiếp khách hàng", sv: "Som nagel- och franstekniker säger jag: Jag är så glad att du kom hit idag.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Mình rất vui vì hôm nay bạn đã đến đây.", phonetic: "/jɑːɡ ɛːr soː ɡlɑːd at dʉː kɔm hɪt ɪˈdɑːɡ/" },
  { id: 569, topic: "Đón tiếp khách hàng", sv: "I salongen säger jag ofta: Ta av dig jackan om du vill, så hänger jag upp den.", vi: "Trong tiệm mình thường nói: Bạn cởi áo khoác nếu muốn nhé, mình sẽ treo lên giúp.", phonetic: "/tɑː ɑːv dej ˈjakːan ɔm dʉː vɪl soː ˈhɛŋːɛr jɑːɡ ɵpː dɛn/" },
  { id: 570, topic: "Đón tiếp khách hàng", sv: "När jag jobbar brukar jag säga: Känn dig som hemma här hos oss.", vi: "Khi làm việc mình hay nói: Hãy cứ tự nhiên như ở nhà khi ở chỗ tụi mình nhé.", phonetic: "/ɕɛnː dej sɔm ˈhɛmːa hɛːr huːs ɔsː/" },
  { id: 571, topic: "Mời nước khách", sv: "Vid kundmottagning säger jag: Vill du ha något att dricka, kaffe eller vatten?", vi: "Khi đón tiếp mình nói: Bạn có muốn uống chút gì không, cà phê hay nước lọc?", phonetic: "/vɪl dʉː hɑː ˈnoːɡɔt at ˈdrɪkːa ˈkafːɛ ˈɛlːɛr ˈvatːɛn/" },
  { id: 572, topic: "Mời nước khách", sv: "Under behandlingen säger jag lugnt: Vill du ha ett glas kallt vatten medan du väntar?", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Bạn có muốn một ly nước lạnh trong lúc chờ không?", phonetic: "/vɪl dʉː hɑː ɛt ɡlɑːs kalːt ˈvatːɛn ˈmeːdan dʉː ˈvɛnːtar/" },
  { id: 573, topic: "Mời nước khách", sv: "Som nagel- och franstekniker säger jag: Jag kan bjuda på te eller kaffe om du önskar.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Mình có thể mời trà hoặc cà phê nếu bạn muốn.", phonetic: "/jɑːɡ kan ˈbjʉːda pɔː teː ˈɛlːɛr ˈkafːɛ ɔm dʉː ˈœnːskar/" },
  { id: 574, topic: "Mời nước khách", sv: "I salongen säger jag ofta: Föredrar du varmt eller kallt vatten?", vi: "Trong tiệm mình thường nói: Bạn thích nước ấm hay nước lạnh hơn?", phonetic: "/ˌfœrɛˈdrɑːr dʉː varmt ˈɛlːɛr kalːt ˈvatːɛn/" },
  { id: 575, topic: "Mời nước khách", sv: "När jag jobbar brukar jag säga: Ska jag hälla upp lite te åt dig?", vi: "Khi làm việc mình hay nói: Mình rót thêm chút trà cho bạn nhé?", phonetic: "/skɑː jɑːɡ ˈhɛlːa ɵpː ˈliːtɛ teː oːt dej/" },
  { id: 576, topic: "Mời nước khách", sv: "Vid kundmottagning säger jag: Här kommer ditt vatten. Varsågod!", vi: "Khi đón tiếp mình nói: Nước của bạn đây. Mời bạn dùng!", phonetic: "/hɛːr ˈkɔmːɛr dɪt ˈvatːɛn ˈvɑːrʃɔˌɡuːd/" },
  { id: 577, topic: "Mời nước khách", sv: "Under behandlingen säger jag lugnt: Vill du ha socker eller mjölk i kaffet?", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Bạn có muốn thêm đường hay sữa vào cà phê không?", phonetic: "/vɪl dʉː hɑː ˈsɔkːɛr ˈɛlːɛr mjœlk ɪ ˈkafːɛt/" },
  { id: 578, topic: "Mời nước khách", sv: "Som nagel- och franstekniker säger jag: Jag fixar en kopp varmt te direkt.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Mình pha một tách trà nóng ngay đây.", phonetic: "/jɑːɡ ˈfɪkːsar ɛn kɔpː varmt teː dɪˈrɛkt/" },
  { id: 579, topic: "Mời nước khách", sv: "I salongen säger jag ofta: Vill du ha en liten kaka till kaffet?", vi: "Trong tiệm mình thường nói: Bạn có muốn ăn thêm một chiếc bánh nhỏ kèm cà phê không?", phonetic: "/vɪl dʉː hɑː ɛn ˈliːtɛn ˈkɑːka tɪl ˈkafːɛt/" },
  { id: 580, topic: "Mời nước khách", sv: "När jag jobbar brukar jag säga: Säg bara till om du vill ha påfyllning.", vi: "Khi làm việc mình hay nói: Cứ bảo mình nếu bạn muốn châm thêm nhé.", phonetic: "/sɛːj ˈbɑːra tɪl ɔm dʉː vɪl hɑː ˈpoːˌfʏlːnɪŋ/" },
  { id: 581, topic: "Thao tác nối mi / Spa", sv: "Vid kundmottagning säger jag: Blunda och slappna av nu.", vi: "Khi đón tiếp mình nói: Hãy nhắm mắt lại và thư giãn nhé.", phonetic: "/ˈblɵnːda ɔ ˈslapːna ɑːv nʉː/" },
  { id: 582, topic: "Thao tác nối mi / Spa", sv: "Under behandlingen säger jag lugnt: Känns det bra och bekvämt på britsen?", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Nằm trên giường liệu trình có thấy thoải mái không?", phonetic: "/ɕɛnːs deː brɑː ɔ bɛˈkvɛːmt pɔː brɪtːsɛn/" },
  { id: 583, topic: "Thao tác nối mi / Spa", sv: "Som nagel- och franstekniker säger jag: Jag sätter på en mjuk ögonpad under fransarna nu.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Bây giờ mình dán miếng lót mắt mềm dưới hàng mi nhé.", phonetic: "/jɑːɡ ˈsɛtːɛr pɔː ɛn mjʉːk ˈœːɡɔnˌpad ɵnːdɛr ˈfranːsarːa nʉː/" },
  { id: 584, topic: "Thao tác nối mi / Spa", sv: "I salongen säger jag ofta: Säg till direkt om det svider eller sticker till.", vi: "Trong tiệm mình thường nói: Báo ngay cho mình nếu thấy cay hoặc châm chích nhé.", phonetic: "/sɛːj tɪl dɪˈrɛkt ɔm deː ˈsviːdɛr ˈɛlːɛr ˈstɪkːɛr tɪl/" },
  { id: 585, topic: "Thao tác nối mi / Spa", sv: "När jag jobbar brukar jag säga: Vi börjar med att rengöra fransarna noga.", vi: "Khi làm việc mình hay nói: Tụi mình bắt đầu bằng việc làm sạch mi thật kỹ.", phonetic: "/viː ˈbœrːjar meːd at ˈreːnˌjœːra ˈfranːsarːa ˈnoːɡa/" },
  { id: 586, topic: "Thao tác nối mi / Spa", sv: "Vid kundmottagning säger jag: Nu applicerar jag limmet försiktigt på varje frans.", vi: "Khi đón tiếp mình nói: Giờ mình gắn keo cẩn thận lên từng sợi mi.", phonetic: "/nʉː ˌapːlɪˈseːrar jɑːɡ ˈlɪmːɛt fœrˈsɪkːtɪt pɔː ˈvarːjɛ frans/" },
  { id: 587, topic: "Thao tác nối mi / Spa", sv: "Under behandlingen säger jag lugnt: Känns tejpningen för stram på något ställe?", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Miếng băng dán có bị căng ở chỗ nào không?", phonetic: "/ɕɛnːs ˈtɛjpnɪŋɛn fœr stram pɔː ˈnoːɡɔt ˈstɛlːɛ/" },
  { id: 588, topic: "Thao tác nối mi / Spa", sv: "Som nagel- och franstekniker säger jag: Jag masserar hårbotten med lugna rörelser nu.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Bây giờ mình massage da đầu với các động tác nhẹ nhàng nhé.", phonetic: "/jɑːɡ maˈseːrar ˈhoːrˌbɔtːɛn meːd ˈlɵɡːna ˈrœːrɛlsɛr nʉː/" },
  { id: 589, topic: "Thao tác nối mi / Spa", sv: "I salongen säger jag ofta: Är vattnet lagom varmt när jag sköljer håret?", vi: "Trong tiệm mình thường nói: Nước có vừa độ ấm khi mình xả tóc không?", phonetic: "/ɛːr ˈvatːnɛt ˈlɑːɡɔm varmt nɛːr jɑːɡ ˈɕœlːjɛr ˈhoːrɛt/" },
  { id: 590, topic: "Thao tác nối mi / Spa", sv: "När jag jobbar brukar jag säga: Nu är vi klara med behandlingen. Öppna ögonen sakta.", vi: "Khi làm việc mình hay nói: Xong liệu trình rồi đây. Bạn mở mắt từ từ nhé.", phonetic: "/nʉː ɛːr viː ˈklɑːra meːd bɛˈhanːdlɪŋɛn ˈœpːna ˈœːɡɔnɛn ˈsakːta/" },
  { id: 591, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vid kundmottagning säger jag: Vilken stil gillar du mest, naturlig eller volym?", vi: "Khi đón tiếp mình nói: Bạn thích kiểu nào nhất, tự nhiên hay dày vol?", phonetic: "/ˈvɪlːkɛn stiːl ˈjɪlːar dʉː mɛst nɑtʉːˈliːr ˈɛlːɛr vɔˈlʏːm/" },
  { id: 592, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Under behandlingen säger jag lugnt: Vill du ha en öppen docköga eller en mjuk kattöga?", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Bạn muốn dáng mắt búp bê tròn to hay dáng mắt mèo dịu dàng?", phonetic: "/vɪl dʉː hɑː ɛn ˈœpːɛn ˈdɔkˌœːɡa ˈɛlːɛr ɛn mjʉːk ˈkatˌœːɡa/" },
  { id: 593, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Som nagel- och franstekniker säger jag: Jag rekommenderar en lite kortare längd innerst.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Mình khuyên nên chọn độ dài ngắn hơn một chút ở góc trong.", phonetic: "/jɑːɡ ˌrɛkɔmɛnˈdeːrar ɛn ˈliːtɛ ˈkɔrːtarɛ lɛŋd ˈɪnːɛrst/" },
  { id: 594, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "I salongen säger jag ofta: Vill du ha mandelformade, fyrkantiga eller runda naglar?", vi: "Trong tiệm mình thường nói: Bạn muốn móng dáng hạnh nhân, móng vuông hay móng tròn?", phonetic: "/vɪl dʉː hɑː ˈmanːdɛlˌfɔrmadɛ ˈfʏrˌkantɪɡa ˈɛlːɛr ˈrɵnːda ˈnaɡːlar/" },
  { id: 595, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "När jag jobbar brukar jag säga: Den här nyansen passar väldigt fint till din hudton.", vi: "Khi làm việc mình hay nói: Tông màu này hợp với sắc da của bạn lắm đấy.", phonetic: "/deːn hɛːr nʏˈanːsɛn ˈpasːar ˈvɛlːdɪt fɪnt tɪl diːn ˈhʉːdˌtuːn/" },
  { id: 596, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vid kundmottagning säger jag: Vi kan göra gel, förstärkning med builder gel eller akryl.", vi: "Khi đón tiếp mình nói: Tụi mình có thể làm gel, đắp gel cứng hoặc đắp bột.", phonetic: "/viː kan ˈjœːra jeːl fœrˈstɛrkːnɪŋ meːd ˈbɪlːdɛr jeːl ˈɛlːɛr ɑˈkrʏːl/" },
  { id: 597, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Under behandlingen säger jag lugnt: Vill du ha enfärgat, fransk manikyr eller chrome?", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Bạn muốn sơn một màu, kiểu Pháp hay hiệu ứng chrome?", phonetic: "/vɪl dʉː hɑː ˈeːnˌfɛrɡat fransk mɑnɪˈkʏːr ˈɛlːɛr kroːm/" },
  { id: 598, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Som nagel- och franstekniker säger jag: Jag anpassar böjen efter dina naturliga fransar.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Mình điều chỉnh độ cong theo hàng mi thật của bạn.", phonetic: "/jɑːɡ ˈanːpasːar ˈbœjːɛn ˈɛfːtɛr ˈdiːna nɑtʉːˈliːra ˈfranːsar/" },
  { id: 599, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "I salongen säger jag ofta: Det är bäst att skona dina egna fransar så de håller sig friska.", vi: "Trong tiệm mình thường nói: Tốt nhất là giữ gìn mi thật để mi luôn khỏe mạnh.", phonetic: "/deːt ɛːr bɛst at ˈskuːna ˈdiːna ˈeːɡːna ˈfranːsar soː deː ˈhɔlːɛr sej ˈfrɪsːka/" },
  { id: 600, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "När jag jobbar brukar jag säga: Ska vi lägga till en djupgående fuktkur för händerna idag?", vi: "Khi làm việc mình hay nói: Hôm nay mình thêm bước dưỡng ẩm sâu cho tay nhé?", phonetic: "/skɑː viː ˈlɛɡːa tɪl ɛn ˈjʉːpˌɡoːɛnːdɛ ˈfɵktˌkʉːr fœr ˈhɛnːdarːa ɪˈdɑːɡ/" },
  { id: 601, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Vid kundmottagning säger jag: Undvik vatten och ånga på fransarna de första tjugofyra timmarna.", vi: "Khi đón tiếp mình nói: Tránh nước và hơi nóng lên mi trong hai mươi bốn giờ đầu nhé.", phonetic: "/ˈɵnːdviːk ˈvatːɛn ɔ ˈɔŋːa pɔː ˈfranːsarːa deː ˈfœsːta ˈɕʉːɡʊˌfyːra ˈtɪmːarːa/" },
  { id: 602, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Under behandlingen säger jag lugnt: Gnugga inte ögonen och använd oljefria produkter.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Đừng dụi mắt và hãy dùng sản phẩm không chứa dầu nhé.", phonetic: "/ˈɡnɵɡːa ˈɪnːtɛ ˈœːɡɔnɛn ɔ ˈanːvɛnd ˈɔlːjɛˌfriːa prʊˈdɵkːtɛr/" },
  { id: 603, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Som nagel- och franstekniker säger jag: Borsta fransarna försiktigt varje morgon med borsten du får.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Chải mi nhẹ nhàng mỗi sáng bằng cọ được tặng kèm nhé.", phonetic: "/ˈbɔʂːta ˈfranːsarːa fœrˈsɪkːtɪt ˈvarːjɛ ˈmɔrːɔn meːd ˈbɔʂːtɛn dʉː fɔːr/" },
  { id: 604, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "I salongen säger jag ofta: Det är dags för påfyllning om ungefär tre veckor.", vi: "Trong tiệm mình thường nói: Khoảng ba tuần nữa là tới lúc dặm lại rồi đấy.", phonetic: "/deːt ɛːr daks fœr ˈpoːˌfʏlːnɪŋ ɔm ɵnːfɛˈjɛːr treː ˈvɛkːɔr/" },
  { id: 605, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "När jag jobbar brukar jag säga: Smörj nagelbanden med nagelolja varje kväll.", vi: "Khi làm việc mình hay nói: Thoa dầu dưỡng viền móng mỗi tối nhé.", phonetic: "/smœrj ˈnɑːɡɛlˌbanːdɛn meːd ˈnɑːɡɛlˌɔlːja ˈvarːjɛ kvɛlː/" },
  { id: 606, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Vid kundmottagning säger jag: Använd gärna handskar när du diskar eller städar.", vi: "Khi đón tiếp mình nói: Bạn nhớ đeo găng tay khi rửa chén hoặc dọn dẹp nhé.", phonetic: "/ˈanːvɛnd ˈjɛːrna ˈhanːskar nɛːr dʉː ˈdɪsːkar ˈɛlːɛr ˈstɛːdar/" },
  { id: 607, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Under behandlingen säger jag lugnt: Vill du boka nästa tid redan innan du går idag?", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Bạn có muốn đặt lịch lần tới ngay trước khi về hôm nay không?", phonetic: "/vɪl dʉː ˈbuːka ˈnɛsːta tiːd ˈreːdan ˈɪnːan dʉː ɡoːr ɪˈdɑːɡ/" },
  { id: 608, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Som nagel- och franstekniker säger jag: Vi har en ledig tid på tisdag klockan tio.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Tụi mình còn trống lịch vào thứ ba lúc mười giờ.", phonetic: "/viː hɑːr ɛn ˈleːdɪɡ tiːd pɔː ˈtɪsːdɑːɡ ˈklɔkːan ˈtiːʊ/" },
  { id: 609, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "I salongen säger jag ofta: Jag skickar en påminnelse dagen innan din tid.", vi: "Trong tiệm mình thường nói: Mình sẽ gửi tin nhắn nhắc lịch trước ngày hẹn một ngày.", phonetic: "/jɑːɡ ˈɕɪkːar ɛn ˈpoːˌmɪnːɛlsɛ ˈdɑːɡɛn ˈɪnːan diːn tiːd/" },
  { id: 610, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "När jag jobbar brukar jag säga: Tack så mycket för besöket! Vi ses nästa gång.", vi: "Khi làm việc mình hay nói: Cảm ơn bạn rất nhiều vì đã ghé tiệm! Hẹn gặp lại lần sau nhé.", phonetic: "/tak soː ˈmʏkːɛt fœr bɛˈsøːkɛt viː seːs ˈnɛsːta ɡɔŋ/" },
  { id: 611, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Vid kundmottagning säger jag: Jag desinficerar alla verktyg mellan varje kund.", vi: "Khi đón tiếp mình nói: Mình khử trùng toàn bộ dụng cụ giữa mỗi khách hàng.", phonetic: "/jɑːɡ dɛsɪnfɪˈseːrar ˈalːa ˈvɛrkˌtʏːɡ ˈmɛlːan ˈvarːjɛ kɵnd/" },
  { id: 612, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Under behandlingen säger jag lugnt: Vi följer säkerhetsrutiner för härdplast och lim.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Tụi mình tuân thủ quy trình an toàn với nhựa cứng và keo.", phonetic: "/viː ˈfœlːjɛr ˈsɛːkɛrˌheːtsrɵˌtiːnɛr fœr ˈhɛːrdˌplast ɔ liːm/" },
  { id: 613, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Som nagel- och franstekniker säger jag: Jag arbetar i ett välventilerat rum med punktutsug.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Mình làm việc trong phòng thông thoáng có máy hút khí cục bộ.", phonetic: "/jɑːɡ ˈɑːrbɛtar ɪ ɛt ˈvɛːlˌvɛntɪˌleːrat rɵm meːd ˈpɵŋktˌʉːtsʉːɡ/" },
  { id: 614, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "I salongen säger jag ofta: Jag byter handskar och dukar inför varje ny behandling.", vi: "Trong tiệm mình thường nói: Mình thay găng tay và khăn trải trước mỗi liệu trình mới.", phonetic: "/jɑːɡ ˈbʏːtɛr ˈhanːskar ɔ ˈdʉːkar ˈɪnːfœr ˈvarːjɛ nʏː bɛˈhanːdlɪŋ/" },
  { id: 615, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "När jag jobbar brukar jag säga: Pincetterna är rengjorda och redo för dagens pass.", vi: "Khi làm việc mình hay nói: Các cây nhíp đã được làm sạch và sẵn sàng cho ca làm hôm nay.", phonetic: "/pɪnˈsɛtːarːa ɛːr ˈreːnˌjuːrda ɔ ˈreːdu fœr ˈdɑːɡɛns pasː/" },
  { id: 616, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Vid kundmottagning säger jag: Vi håller arbetsstationen ren, organiserad och lugn.", vi: "Khi đón tiếp mình nói: Tụi mình giữ bàn làm việc sạch sẽ, gọn gàng và yên tĩnh.", phonetic: "/viː ˈhɔlːɛr ˈɑːrbɛtsˌstɑːˌɕuːnɛn reːn ɔrɡanɪˈseːrad ɔ lɵŋn/" },
  { id: 617, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Under behandlingen säger jag lugnt: Jag kontrollerar att limmet har rätt konsistens och fuktighet.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Mình kiểm tra xem keo có độ sệt và độ ẩm chuẩn chưa.", phonetic: "/jɑːɡ kɔntrɔˈleːrar at ˈlɪmːɛt hɑːr rɛt kɔnsɪsˈtɛnːs ɔ ˈfɵkːtɪˌheːt/" },
  { id: 618, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Som nagel- och franstekniker säger jag: Engångsartiklar slängs i avsedd behållare direkt.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Đồ dùng một lần được bỏ vào thùng chuyên dụng ngay lập tức.", phonetic: "/ˈeːnˌɡɔŋsˌɑːrtɪklar slɛŋːs ɪ ˈɑːvˌsɛd bɛˈhɔlːarɛ dɪˈrɛkt/" },
  { id: 619, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "I salongen säger jag ofta: Jag tvättar händerna noggrant före och efter varje moment.", vi: "Trong tiệm mình thường nói: Mình rửa tay kỹ trước và sau mỗi thao tác.", phonetic: "/jɑːɡ ˈtvɛtːar ˈhɛnːdarːa ˈnoːɡrant ˈfœːrɛ ɔ ˈɛfːtɛr ˈvarːjɛ mʊˈmɛnːt/" },
  { id: 620, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "När jag jobbar brukar jag säga: All utrustning står på sin plats så arbetet flyter smidigt.", vi: "Khi làm việc mình hay nói: Mọi thiết bị đều đúng vị trí để công việc trôi chảy mượt mà.", phonetic: "/alː ˈʉːtˌrɵsːnɪŋ stoːr pɔː sɪn plats soː ɑrˈbeːtɛt ˈflʏːtɛr ˈsmiːdɪt/" },
  { id: 621, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Vid kundmottagning säger jag: Hur ser schemat ut för resten av veckan?", vi: "Khi đón tiếp mình nói: Lịch làm việc cho phần còn lại của tuần trông thế nào?", phonetic: "/hʉːr seːr ˈɕeːmat ʉːt fœr ˈrɛsːtɛn ɑːv ˈvɛkːan/" },
  { id: 622, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Under behandlingen säger jag lugnt: Jag har förberett allt inför nästa kund klocker ett.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Mình đã chuẩn bị xong mọi thứ cho khách tiếp theo lúc một giờ.", phonetic: "/jɑːɡ hɑːr ˈfœrːbɛrɛt alːt ˈɪnːfœr ˈnɛsːta kɵnd ˈklɔkːɛn ɛt/" },
  { id: 623, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Som nagel- och franstekniker säger jag: Vi behöver beställa mer franslim och primer i veckan.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Tụi mình cần đặt thêm keo nối mi và primer trong tuần này.", phonetic: "/viː bɛˈhøːvɛr bɛˈstɛlːa meːr ˈfransˌliːm ɔ ˈpraɪmɛr ɪ ˈvɛkːan/" },
  { id: 624, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "I salongen säger jag ofta: Kan du hjälpa mig att ta emot nästa kund i receptionen?", vi: "Trong tiệm mình thường nói: Bạn giúp mình đón khách tiếp theo ở quầy lễ tân được không?", phonetic: "/kan dʉː ˈjɛlːpa mej at tɑː ɛˈmʊːt ˈnɛsːta kɵnd ɪ rɛsɛpˈɕuːnɛn/" },
  { id: 625, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "När jag jobbar brukar jag säga: Vi samarbetar bra när vi stämmer av tiderna i förväg.", vi: "Khi làm việc mình hay nói: Tụi mình phối hợp nhịp nhàng khi rà soát giờ giấc từ trước.", phonetic: "/viː ˈsɑːmarˌbeːtar brɑː nɛːr viː ˈstɛmːɛr ɑːv ˈtiːdarːa ɪ fœrˈvɛːɡ/" },
  { id: 626, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Vid kundmottagning säger jag: Jag antecknar kundens önskemål direkt i bokningen.", vi: "Khi đón tiếp mình nói: Mình ghi chú mong muốn của khách thẳng vào lịch đặt.", phonetic: "/jɑːɡ ˈanːˌteːknar ˈkɵnːdɛns ˈœnːskɛˌmoːl dɪˈrɛkt ɪ ˈbuːknɪŋɛn/" },
  { id: 627, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Under behandlingen säger jag lugnt: Kunden blev jättenöjd med resultatet idag.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Khách hàng rất hài lòng với kết quả hôm nay.", phonetic: "/ˈkɵnːdɛn bleːv ˈjɛtːɛˌnœjd meːd rɛsɵlˈtɑːtɛt ɪˈdɑːɡ/" },
  { id: 628, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Som nagel- och franstekniker säger jag: Vi städar av och fyller på förrådet innan vi stänger.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Tụi mình dọn dẹp và châm thêm đồ dự trữ trước khi đóng cửa.", phonetic: "/viː ˈstɛːdar ɑːv ɔ ˈfʏlːɛr pɔː fœˈroːdɛt ˈɪnːan viː ˈstɛŋːɛr/" },
  { id: 629, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "I salongen säger jag ofta: Har någon avbokat sin tid på eftermiddagen?", vi: "Trong tiệm mình thường nói: Có ai hủy lịch buổi chiều nay không?", phonetic: "/hɑːr ˈnoːɡɔn ˈɑːvˌbuːkat sɪn tiːd pɔː ˈɛfːtɛrˌmɪdːaɡɛn/" },
  { id: 630, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "När jag jobbar brukar jag säga: Jag är redo att ta emot nästa bokning nu.", vi: "Khi làm việc mình hay nói: Mình đã sẵn sàng đón lượt đặt tiếp theo rồi.", phonetic: "/jɑːɡ ɛːr ˈreːdu at tɑː ɛˈmʊːt ˈnɛsːta ˈbuːknɪŋ nʉː/" },
  { id: 631, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Vid kundmottagning säger jag: Hur känns det nu när du ser dig i spegeln?", vi: "Khi đón tiếp mình nói: Giờ khi nhìn mình trong gương bạn thấy thế nào?", phonetic: "/hʉːr ɕɛnːs deː nʉː nɛːr dʉː seːr dej ɪ ˈspeːɡɛln/" },
  { id: 632, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Under behandlingen säger jag lugnt: Är det något jag kan justera lite till innan du går?", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Có chỗ nào mình chỉnh thêm một chút trước khi bạn về không?", phonetic: "/ɛːr deː ˈnoːɡɔt jɑːɡ kan jɵsˈteːra ˈliːtɛ tɪl ˈɪnːan dʉː ɡoːr/" },
  { id: 633, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Som nagel- och franstekniker säger jag: Betalningen går bra med kort eller Swish.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Thanh toán bằng thẻ hoặc Swish đều được nhé.", phonetic: "/bɛˈtɑːlnɪŋɛn ɡoːr brɑː meːd kɔʈ ˈɛlːɛr svɪʃ/" },
  { id: 634, topic: "Phản hồi, thanh toán & chia tay khách", sv: "I salongen säger jag ofta: Här kommer kvittot. Varsågod!", vi: "Trong tiệm mình thường nói: Hóa đơn của bạn đây. Mời bạn nhận!", phonetic: "/hɛːr ˈkɔmːɛr ˈkvɪtːʊt ˈvɑːrʃɔˌɡuːd/" },
  { id: 635, topic: "Phản hồi, thanh toán & chia tay khách", sv: "När jag jobbar brukar jag säga: Tack för förtroendet och ha en riktigt fin dag!", vi: "Khi làm việc mình hay nói: Cảm ơn bạn đã tin tưởng và chúc bạn một ngày thật đẹp!", phonetic: "/tak fœr fœrˈtrʊːɛndɛt ɔ hɑː ɛn ˈrɪkːtɪt fiːn dɑːɡ/" },
  { id: 636, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Vid kundmottagning säger jag: Det var så roligt att få arbeta med dina naglar idag.", vi: "Khi đón tiếp mình nói: Hôm nay được làm móng cho bạn vui lắm luôn.", phonetic: "/deːt vɑːr soː ˈrʊːlɪt at foː ˈɑːrbɛta meːd ˈdiːna ˈnaɡːlar ɪˈdɑːɡ/" },
  { id: 637, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Under behandlingen säger jag lugnt: Glöm inte din väska och dina personliga saker.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Đừng quên túi xách và đồ cá nhân của bạn nhé.", phonetic: "/ɡlœm ˈɪnːtɛ diːn ˈvɛsːka ɔ ˈdiːna pɛʂʊnˈliːɡa ˈsɑːkɛr/" },
  { id: 638, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Som nagel- och franstekniker säger jag: Vi finns här om du har några frågor hemma.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Tụi mình luôn ở đây nếu về nhà bạn có thắc mắc gì.", phonetic: "/viː fɪnːs hɛːr ɔm dʉː hɑːr ˈnoːɡra ˈfroːɡɔr ˈhɛmːa/" },
  { id: 639, topic: "Phản hồi, thanh toán & chia tay khách", sv: "I salongen säger jag ofta: Ha en trevlig kväll och kör försiktigt hem!", vi: "Trong tiệm mình thường nói: Chúc bạn buổi tối vui vẻ và đi đường về cẩn thận nhé!", phonetic: "/hɑː ɛn ˈtreːvlɪɡ kvɛlː ɔ ɕœːr fœrˈsɪkːtɪt hɛm/" },
  { id: 640, topic: "Phản hồi, thanh toán & chia tay khách", sv: "När jag jobbar brukar jag säga: Välkommen tillbaka när du känner för det!", vi: "Khi làm việc mình hay nói: Chào mừng bạn quay lại bất cứ khi nào bạn muốn nhé!", phonetic: "/ˈvɛːlˌkɔmːɛn tɪlˈbɑːka nɛːr dʉː ˈɕɛnːɛr fœr deː/" },
  { id: 641, topic: "Đón tiếp khách hàng", sv: "Hej! Välkommen till vår salong. Det är en viktig del av god service.", vi: "Xin chào! Chào mừng đến với tiệm của chúng tôi. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/hej ˈvɛːlˌkɔmːɛn tɪl voːr saˈlɔŋ/" },
  { id: 642, topic: "Đón tiếp khách hàng", sv: "God morgon! Hur mår du idag? Det gör samtalet tydligt och vänligt.", vi: "Chào buổi sáng! Hôm nay bạn cảm thấy thế nào? Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr moːr dʉː ɪˈdɑːɡ/" },
  { id: 643, topic: "Đón tiếp khách hàng", sv: "Hej och välkommen! Har du bokat tid? Det känns naturligt och artigt.", vi: "Xin chào và chào mừng! Bạn đã đặt lịch hẹn chưa? Câu này nghe tự nhiên và lịch sự.", phonetic: "/hej ɔ ˈvɛːlˌkɔmːɛn hɑːr dʉː ˈbuːkat tiːd/" },
  { id: 644, topic: "Đón tiếp khách hàng", sv: "Varsågod och sitt ner här en stund. Det skapar en trygg stämning.", vi: "Mời bạn ngồi xuống đây một lát. Cách nói này tạo cảm giác an tâm.", phonetic: "/ˈvɑːrʃɔˌɡuːd ɔ sɪtː neːr hɛːr ɛn stɵnd/" },
  { id: 645, topic: "Đón tiếp khách hàng", sv: "Vad trevligt att se dig igen! Det hjälper kunden att slappna av.", vi: "Thật vui được gặp lại bạn! Điều này giúp khách dễ thư giãn hơn.", phonetic: "/vɑːd ˈtreːvlɪɡt at seː dej ɪˈjɛn/" },
  { id: 646, topic: "Đón tiếp khách hàng", sv: "Välkommen in! Jag heter My Han och ska hjälpa dig idag. Det är en viktig del av god service.", vi: "Chào mừng vào tiệm! Mình tên là My Han và sẽ hỗ trợ bạn hôm nay. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/ˈvɛːlˌkɔmːɛn ɪn jɑːɡ ˈheːtɛr myː hɑn ɔ skɑː ˈjɛlːpa dej ɪˈdɑːɡ/" },
  { id: 647, topic: "Đón tiếp khách hàng", sv: "Hur var din dag hittills? Det gör samtalet tydligt och vänligt.", vi: "Ngày của bạn từ nãy đến giờ thế nào? Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/hʉːr vɑːr diːn dɑːɡ ˈhɪtːɪls/" },
  { id: 648, topic: "Đón tiếp khách hàng", sv: "Jag är så glad att du kom hit idag. Det känns naturligt och artigt.", vi: "Mình rất vui vì hôm nay bạn đã đến đây. Câu này nghe tự nhiên và lịch sự.", phonetic: "/jɑːɡ ɛːr soː ɡlɑːd at dʉː kɔm hɪt ɪˈdɑːɡ/" },
  { id: 649, topic: "Đón tiếp khách hàng", sv: "Ta av dig jackan om du vill, så hänger jag upp den. Det skapar en trygg stämning.", vi: "Bạn cởi áo khoác nếu muốn nhé, mình sẽ treo lên giúp. Cách nói này tạo cảm giác an tâm.", phonetic: "/tɑː ɑːv dej ˈjakːan ɔm dʉː vɪl soː ˈhɛŋːɛr jɑːɡ ɵpː dɛn/" },
  { id: 650, topic: "Đón tiếp khách hàng", sv: "Känn dig som hemma här hos oss. Det hjälper kunden att slappna av.", vi: "Hãy cứ tự nhiên như ở nhà khi ở chỗ tụi mình nhé. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/ɕɛnː dej sɔm ˈhɛmːa hɛːr huːs ɔsː/" },
  { id: 651, topic: "Mời nước khách", sv: "Vill du ha något att dricka, kaffe eller vatten? Det är en viktig del av god service.", vi: "Bạn có muốn uống chút gì không, cà phê hay nước lọc? Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/vɪl dʉː hɑː ˈnoːɡɔt at ˈdrɪkːa ˈkafːɛ ˈɛlːɛr ˈvatːɛn/" },
  { id: 652, topic: "Mời nước khách", sv: "Vill du ha ett glas kallt vatten medan du väntar? Det gör samtalet tydligt och vänligt.", vi: "Bạn có muốn một ly nước lạnh trong lúc chờ không? Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/vɪl dʉː hɑː ɛt ɡlɑːs kalːt ˈvatːɛn ˈmeːdan dʉː ˈvɛnːtar/" },
  { id: 653, topic: "Mời nước khách", sv: "Jag kan bjuda på te eller kaffe om du önskar. Det känns naturligt och artigt.", vi: "Mình có thể mời trà hoặc cà phê nếu bạn muốn. Câu này nghe tự nhiên và lịch sự.", phonetic: "/jɑːɡ kan ˈbjʉːda pɔː teː ˈɛlːɛr ˈkafːɛ ɔm dʉː ˈœnːskar/" },
  { id: 654, topic: "Mời nước khách", sv: "Föredrar du varmt eller kallt vatten? Det skapar en trygg stämning.", vi: "Bạn thích nước ấm hay nước lạnh hơn? Cách nói này tạo cảm giác an tâm.", phonetic: "/ˌfœrɛˈdrɑːr dʉː varmt ˈɛlːɛr kalːt ˈvatːɛn/" },
  { id: 655, topic: "Mời nước khách", sv: "Ska jag hälla upp lite te åt dig? Det hjälper kunden att slappna av.", vi: "Mình rót thêm chút trà cho bạn nhé? Điều này giúp khách dễ thư giãn hơn.", phonetic: "/skɑː jɑːɡ ˈhɛlːa ɵpː ˈliːtɛ teː oːt dej/" },
  { id: 656, topic: "Mời nước khách", sv: "Här kommer ditt vatten. Varsågod! Det är en viktig del av god service.", vi: "Nước của bạn đây. Mời bạn dùng! Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/hɛːr ˈkɔmːɛr dɪt ˈvatːɛn ˈvɑːrʃɔˌɡuːd/" },
  { id: 657, topic: "Mời nước khách", sv: "Vill du ha socker eller mjölk i kaffet? Det gör samtalet tydligt och vänligt.", vi: "Bạn có muốn thêm đường hay sữa vào cà phê không? Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/vɪl dʉː hɑː ˈsɔkːɛr ˈɛlːɛr mjœlk ɪ ˈkafːɛt/" },
  { id: 658, topic: "Mời nước khách", sv: "Jag fixar en kopp varmt te direkt. Det känns naturligt och artigt.", vi: "Mình pha một tách trà nóng ngay đây. Câu này nghe tự nhiên và lịch sự.", phonetic: "/jɑːɡ ˈfɪkːsar ɛn kɔpː varmt teː dɪˈrɛkt/" },
  { id: 659, topic: "Mời nước khách", sv: "Vill du ha en liten kaka till kaffet? Det skapar en trygg stämning.", vi: "Bạn có muốn ăn thêm một chiếc bánh nhỏ kèm cà phê không? Cách nói này tạo cảm giác an tâm.", phonetic: "/vɪl dʉː hɑː ɛn ˈliːtɛn ˈkɑːka tɪl ˈkafːɛt/" },
  { id: 660, topic: "Mời nước khách", sv: "Säg bara till om du vill ha påfyllning. Det hjälper kunden att slappna av.", vi: "Cứ bảo mình nếu bạn muốn châm thêm nhé. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/sɛːj ˈbɑːra tɪl ɔm dʉː vɪl hɑː ˈpoːˌfʏlːnɪŋ/" },
  { id: 661, topic: "Thao tác nối mi / Spa", sv: "Blunda och slappna av nu. Det är en viktig del av god service.", vi: "Hãy nhắm mắt lại và thư giãn nhé. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/ˈblɵnːda ɔ ˈslapːna ɑːv nʉː/" },
  { id: 662, topic: "Thao tác nối mi / Spa", sv: "Känns det bra och bekvämt på britsen? Det gör samtalet tydligt och vänligt.", vi: "Nằm trên giường liệu trình có thấy thoải mái không? Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/ɕɛnːs deː brɑː ɔ bɛˈkvɛːmt pɔː brɪtːsɛn/" },
  { id: 663, topic: "Thao tác nối mi / Spa", sv: "Jag sätter på en mjuk ögonpad under fransarna nu. Det känns naturligt och artigt.", vi: "Bây giờ mình dán miếng lót mắt mềm dưới hàng mi nhé. Câu này nghe tự nhiên và lịch sự.", phonetic: "/jɑːɡ ˈsɛtːɛr pɔː ɛn mjʉːk ˈœːɡɔnˌpad ɵnːdɛr ˈfranːsarːa nʉː/" },
  { id: 664, topic: "Thao tác nối mi / Spa", sv: "Säg till direkt om det svider eller sticker till. Det skapar en trygg stämning.", vi: "Báo ngay cho mình nếu thấy cay hoặc châm chích nhé. Cách nói này tạo cảm giác an tâm.", phonetic: "/sɛːj tɪl dɪˈrɛkt ɔm deː ˈsviːdɛr ˈɛlːɛr ˈstɪkːɛr tɪl/" },
  { id: 665, topic: "Thao tác nối mi / Spa", sv: "Vi börjar med att rengöra fransarna noga. Det hjälper kunden att slappna av.", vi: "Tụi mình bắt đầu bằng việc làm sạch mi thật kỹ. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/viː ˈbœrːjar meːd at ˈreːnˌjœːra ˈfranːsarːa ˈnoːɡa/" },
  { id: 666, topic: "Thao tác nối mi / Spa", sv: "Nu applicerar jag limmet försiktigt på varje frans. Det är en viktig del av god service.", vi: "Giờ mình gắn keo cẩn thận lên từng sợi mi. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/nʉː ˌapːlɪˈseːrar jɑːɡ ˈlɪmːɛt fœrˈsɪkːtɪt pɔː ˈvarːjɛ frans/" },
  { id: 667, topic: "Thao tác nối mi / Spa", sv: "Känns tejpningen för stram på något ställe? Det gör samtalet tydligt och vänligt.", vi: "Miếng băng dán có bị căng ở chỗ nào không? Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/ɕɛnːs ˈtɛjpnɪŋɛn fœr stram pɔː ˈnoːɡɔt ˈstɛlːɛ/" },
  { id: 668, topic: "Thao tác nối mi / Spa", sv: "Jag masserar hårbotten med lugna rörelser nu. Det känns naturligt och artigt.", vi: "Bây giờ mình massage da đầu với các động tác nhẹ nhàng nhé. Câu này nghe tự nhiên và lịch sự.", phonetic: "/jɑːɡ maˈseːrar ˈhoːrˌbɔtːɛn meːd ˈlɵɡːna ˈrœːrɛlsɛr nʉː/" },
  { id: 669, topic: "Thao tác nối mi / Spa", sv: "Är vattnet lagom varmt när jag sköljer håret? Det skapar en trygg stämning.", vi: "Nước có vừa độ ấm khi mình xả tóc không? Cách nói này tạo cảm giác an tâm.", phonetic: "/ɛːr ˈvatːnɛt ˈlɑːɡɔm varmt nɛːr jɑːɡ ˈɕœlːjɛr ˈhoːrɛt/" },
  { id: 670, topic: "Thao tác nối mi / Spa", sv: "Nu är vi klara med behandlingen. Öppna ögonen sakta. Det hjälper kunden att slappna av.", vi: "Xong liệu trình rồi đây. Bạn mở mắt từ từ nhé. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/nʉː ɛːr viː ˈklɑːra meːd bɛˈhanːdlɪŋɛn ˈœpːna ˈœːɡɔnɛn ˈsakːta/" },
  { id: 671, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vilken stil gillar du mest, naturlig eller volym? Det är en viktig del av god service.", vi: "Bạn thích kiểu nào nhất, tự nhiên hay dày vol? Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/ˈvɪlːkɛn stiːl ˈjɪlːar dʉː mɛst nɑtʉːˈliːr ˈɛlːɛr vɔˈlʏːm/" },
  { id: 672, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vill du ha en öppen docköga eller en mjuk kattöga? Det gör samtalet tydligt och vänligt.", vi: "Bạn muốn dáng mắt búp bê tròn to hay dáng mắt mèo dịu dàng? Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/vɪl dʉː hɑː ɛn ˈœpːɛn ˈdɔkˌœːɡa ˈɛlːɛr ɛn mjʉːk ˈkatˌœːɡa/" },
  { id: 673, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Jag rekommenderar en lite kortare längd innerst. Det känns naturligt och artigt.", vi: "Mình khuyên nên chọn độ dài ngắn hơn một chút ở góc trong. Câu này nghe tự nhiên và lịch sự.", phonetic: "/jɑːɡ ˌrɛkɔmɛnˈdeːrar ɛn ˈliːtɛ ˈkɔrːtarɛ lɛŋd ˈɪnːɛrst/" },
  { id: 674, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vill du ha mandelformade, fyrkantiga eller runda naglar? Det skapar en trygg stämning.", vi: "Bạn muốn móng dáng hạnh nhân, móng vuông hay móng tròn? Cách nói này tạo cảm giác an tâm.", phonetic: "/vɪl dʉː hɑː ˈmanːdɛlˌfɔrmadɛ ˈfʏrˌkantɪɡa ˈɛlːɛr ˈrɵnːda ˈnaɡːlar/" },
  { id: 675, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Den här nyansen passar väldigt fint till din hudton. Det hjälper kunden att slappna av.", vi: "Tông màu này hợp với sắc da của bạn lắm đấy. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/deːn hɛːr nʏˈanːsɛn ˈpasːar ˈvɛlːdɪt fɪnt tɪl diːn ˈhʉːdˌtuːn/" },
  { id: 676, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vi kan göra gel, förstärkning med builder gel eller akryl. Det är en viktig del av god service.", vi: "Tụi mình có thể làm gel, đắp gel cứng hoặc đắp bột. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/viː kan ˈjœːra jeːl fœrˈstɛrkːnɪŋ meːd ˈbɪlːdɛr jeːl ˈɛlːɛr ɑˈkrʏːl/" },
  { id: 677, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vill du ha enfärgat, fransk manikyr eller chrome? Det gör samtalet tydligt och vänligt.", vi: "Bạn muốn sơn một màu, kiểu Pháp hay hiệu ứng chrome? Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/vɪl dʉː hɑː ˈeːnˌfɛrɡat fransk mɑnɪˈkʏːr ˈɛlːɛr kroːm/" },
  { id: 678, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Jag anpassar böjen efter dina naturliga fransar. Det känns naturligt och artigt.", vi: "Mình điều chỉnh độ cong theo hàng mi thật của bạn. Câu này nghe tự nhiên và lịch sự.", phonetic: "/jɑːɡ ˈanːpasːar ˈbœjːɛn ˈɛfːtɛr ˈdiːna nɑtʉːˈliːra ˈfranːsar/" },
  { id: 679, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Det är bäst att skona dina egna fransar så de håller sig friska. Det skapar en trygg stämning.", vi: "Tốt nhất là giữ gìn mi thật để mi luôn khỏe mạnh. Cách nói này tạo cảm giác an tâm.", phonetic: "/deːt ɛːr bɛst at ˈskuːna ˈdiːna ˈeːɡːna ˈfranːsar soː deː ˈhɔlːɛr sej ˈfrɪsːka/" },
  { id: 680, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Ska vi lägga till en djupgående fuktkur för händerna idag? Det hjälper kunden att slappna av.", vi: "Hôm nay mình thêm bước dưỡng ẩm sâu cho tay nhé? Điều này giúp khách dễ thư giãn hơn.", phonetic: "/skɑː viː ˈlɛɡːa tɪl ɛn ˈjʉːpˌɡoːɛnːdɛ ˈfɵktˌkʉːr fœr ˈhɛnːdarːa ɪˈdɑːɡ/" },
  { id: 681, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Undvik vatten och ånga på fransarna de första tjugofyra timmarna. Det är en viktig del av god service.", vi: "Tránh nước và hơi nóng lên mi trong hai mươi bốn giờ đầu nhé. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/ˈɵnːdviːk ˈvatːɛn ɔ ˈɔŋːa pɔː ˈfranːsarːa deː ˈfœsːta ˈɕʉːɡʊˌfyːra ˈtɪmːarːa/" },
  { id: 682, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Gnugga inte ögonen och använd oljefria produkter. Det gör samtalet tydligt och vänligt.", vi: "Đừng dụi mắt và hãy dùng sản phẩm không chứa dầu nhé. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/ˈɡnɵɡːa ˈɪnːtɛ ˈœːɡɔnɛn ɔ ˈanːvɛnd ˈɔlːjɛˌfriːa prʊˈdɵkːtɛr/" },
  { id: 683, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Borsta fransarna försiktigt varje morgon med borsten du får. Det känns naturligt och artigt.", vi: "Chải mi nhẹ nhàng mỗi sáng bằng cọ được tặng kèm nhé. Câu này nghe tự nhiên và lịch sự.", phonetic: "/ˈbɔʂːta ˈfranːsarːa fœrˈsɪkːtɪt ˈvarːjɛ ˈmɔrːɔn meːd ˈbɔʂːtɛn dʉː fɔːr/" },
  { id: 684, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Det är dags för påfyllning om ungefär tre veckor. Det skapar en trygg stämning.", vi: "Khoảng ba tuần nữa là tới lúc dặm lại rồi đấy. Cách nói này tạo cảm giác an tâm.", phonetic: "/deːt ɛːr daks fœr ˈpoːˌfʏlːnɪŋ ɔm ɵnːfɛˈjɛːr treː ˈvɛkːɔr/" },
  { id: 685, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Smörj nagelbanden med nagelolja varje kväll. Det hjälper kunden att slappna av.", vi: "Thoa dầu dưỡng viền móng mỗi tối nhé. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/smœrj ˈnɑːɡɛlˌbanːdɛn meːd ˈnɑːɡɛlˌɔlːja ˈvarːjɛ kvɛlː/" },
  { id: 686, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Använd gärna handskar när du diskar eller städar. Det är en viktig del av god service.", vi: "Bạn nhớ đeo găng tay khi rửa chén hoặc dọn dẹp nhé. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/ˈanːvɛnd ˈjɛːrna ˈhanːskar nɛːr dʉː ˈdɪsːkar ˈɛlːɛr ˈstɛːdar/" },
  { id: 687, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Vill du boka nästa tid redan innan du går idag? Det gör samtalet tydligt och vänligt.", vi: "Bạn có muốn đặt lịch lần tới ngay trước khi về hôm nay không? Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/vɪl dʉː ˈbuːka ˈnɛsːta tiːd ˈreːdan ˈɪnːan dʉː ɡoːr ɪˈdɑːɡ/" },
  { id: 688, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Vi har en ledig tid på tisdag klockan tio. Det känns naturligt och artigt.", vi: "Tụi mình còn trống lịch vào thứ ba lúc mười giờ. Câu này nghe tự nhiên và lịch sự.", phonetic: "/viː hɑːr ɛn ˈleːdɪɡ tiːd pɔː ˈtɪsːdɑːɡ ˈklɔkːan ˈtiːʊ/" },
  { id: 689, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Jag skickar en påminnelse dagen innan din tid. Det skapar en trygg stämning.", vi: "Mình sẽ gửi tin nhắn nhắc lịch trước ngày hẹn một ngày. Cách nói này tạo cảm giác an tâm.", phonetic: "/jɑːɡ ˈɕɪkːar ɛn ˈpoːˌmɪnːɛlsɛ ˈdɑːɡɛn ˈɪnːan diːn tiːd/" },
  { id: 690, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Tack så mycket för besöket! Vi ses nästa gång. Det hjälper kunden att slappna av.", vi: "Cảm ơn bạn rất nhiều vì đã ghé tiệm! Hẹn gặp lại lần sau nhé. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/tak soː ˈmʏkːɛt fœr bɛˈsøːkɛt viː seːs ˈnɛsːta ɡɔŋ/" },
  { id: 691, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Jag desinficerar alla verktyg mellan varje kund. Det är en viktig del av god service.", vi: "Mình khử trùng toàn bộ dụng cụ giữa mỗi khách hàng. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/jɑːɡ dɛsɪnfɪˈseːrar ˈalːa ˈvɛrkˌtʏːɡ ˈmɛlːan ˈvarːjɛ kɵnd/" },
  { id: 692, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Vi följer säkerhetsrutiner för härdplast och lim. Det gör samtalet tydligt och vänligt.", vi: "Tụi mình tuân thủ quy trình an toàn với nhựa cứng và keo. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/viː ˈfœlːjɛr ˈsɛːkɛrˌheːtsrɵˌtiːnɛr fœr ˈhɛːrdˌplast ɔ liːm/" },
  { id: 693, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Jag arbetar i ett välventilerat rum med punktutsug. Det känns naturligt och artigt.", vi: "Mình làm việc trong phòng thông thoáng có máy hút khí cục bộ. Câu này nghe tự nhiên và lịch sự.", phonetic: "/jɑːɡ ˈɑːrbɛtar ɪ ɛt ˈvɛːlˌvɛntɪˌleːrat rɵm meːd ˈpɵŋktˌʉːtsʉːɡ/" },
  { id: 694, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Jag byter handskar och dukar inför varje ny behandling. Det skapar en trygg stämning.", vi: "Mình thay găng tay và khăn trải trước mỗi liệu trình mới. Cách nói này tạo cảm giác an tâm.", phonetic: "/jɑːɡ ˈbʏːtɛr ˈhanːskar ɔ ˈdʉːkar ˈɪnːfœr ˈvarːjɛ nʏː bɛˈhanːdlɪŋ/" },
  { id: 695, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Pincetterna är rengjorda och redo för dagens pass. Det hjälper kunden att slappna av.", vi: "Các cây nhíp đã được làm sạch và sẵn sàng cho ca làm hôm nay. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/pɪnˈsɛtːarːa ɛːr ˈreːnˌjuːrda ɔ ˈreːdu fœr ˈdɑːɡɛns pasː/" },
  { id: 696, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Vi håller arbetsstationen ren, organiserad och lugn. Det är en viktig del av god service.", vi: "Tụi mình giữ bàn làm việc sạch sẽ, gọn gàng và yên tĩnh. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/viː ˈhɔlːɛr ˈɑːrbɛtsˌstɑːˌɕuːnɛn reːn ɔrɡanɪˈseːrad ɔ lɵŋn/" },
  { id: 697, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Jag kontrollerar att limmet har rätt konsistens och fuktighet. Det gör samtalet tydligt och vänligt.", vi: "Mình kiểm tra xem keo có độ sệt và độ ẩm chuẩn chưa. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/jɑːɡ kɔntrɔˈleːrar at ˈlɪmːɛt hɑːr rɛt kɔnsɪsˈtɛnːs ɔ ˈfɵkːtɪˌheːt/" },
  { id: 698, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Engångsartiklar slängs i avsedd behållare direkt. Det känns naturligt och artigt.", vi: "Đồ dùng một lần được bỏ vào thùng chuyên dụng ngay lập tức. Câu này nghe tự nhiên và lịch sự.", phonetic: "/ˈeːnˌɡɔŋsˌɑːrtɪklar slɛŋːs ɪ ˈɑːvˌsɛd bɛˈhɔlːarɛ dɪˈrɛkt/" },
  { id: 699, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Jag tvättar händerna noggrant före och efter varje moment. Det skapar en trygg stämning.", vi: "Mình rửa tay kỹ trước và sau mỗi thao tác. Cách nói này tạo cảm giác an tâm.", phonetic: "/jɑːɡ ˈtvɛtːar ˈhɛnːdarːa ˈnoːɡrant ˈfœːrɛ ɔ ˈɛfːtɛr ˈvarːjɛ mʊˈmɛnːt/" },
  { id: 700, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "All utrustning står på sin plats så arbetet flyter smidigt. Det hjälper kunden att slappna av.", vi: "Mọi thiết bị đều đúng vị trí để công việc trôi chảy mượt mà. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/alː ˈʉːtˌrɵsːnɪŋ stoːr pɔː sɪn plats soː ɑrˈbeːtɛt ˈflʏːtɛr ˈsmiːdɪt/" },
  { id: 701, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Hur ser schemat ut för resten av veckan? Det är en viktig del av god service.", vi: "Lịch làm việc cho phần còn lại của tuần trông thế nào? Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/hʉːr seːr ˈɕeːmat ʉːt fœr ˈrɛsːtɛn ɑːv ˈvɛkːan/" },
  { id: 702, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Jag har förberett allt inför nästa kund klocker ett. Det gör samtalet tydligt och vänligt.", vi: "Mình đã chuẩn bị xong mọi thứ cho khách tiếp theo lúc một giờ. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/jɑːɡ hɑːr ˈfœrːbɛrɛt alːt ˈɪnːfœr ˈnɛsːta kɵnd ˈklɔkːɛn ɛt/" },
  { id: 703, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Vi behöver beställa mer franslim och primer i veckan. Det känns naturligt och artigt.", vi: "Tụi mình cần đặt thêm keo nối mi và primer trong tuần này. Câu này nghe tự nhiên và lịch sự.", phonetic: "/viː bɛˈhøːvɛr bɛˈstɛlːa meːr ˈfransˌliːm ɔ ˈpraɪmɛr ɪ ˈvɛkːan/" },
  { id: 704, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Kan du hjälpa mig att ta emot nästa kund i receptionen? Det skapar en trygg stämning.", vi: "Bạn giúp mình đón khách tiếp theo ở quầy lễ tân được không? Cách nói này tạo cảm giác an tâm.", phonetic: "/kan dʉː ˈjɛlːpa mej at tɑː ɛˈmʊːt ˈnɛsːta kɵnd ɪ rɛsɛpˈɕuːnɛn/" },
  { id: 705, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Vi samarbetar bra när vi stämmer av tiderna i förväg. Det hjälper kunden att slappna av.", vi: "Tụi mình phối hợp nhịp nhàng khi rà soát giờ giấc từ trước. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/viː ˈsɑːmarˌbeːtar brɑː nɛːr viː ˈstɛmːɛr ɑːv ˈtiːdarːa ɪ fœrˈvɛːɡ/" },
  { id: 706, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Jag antecknar kundens önskemål direkt i bokningen. Det är en viktig del av god service.", vi: "Mình ghi chú mong muốn của khách thẳng vào lịch đặt. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/jɑːɡ ˈanːˌteːknar ˈkɵnːdɛns ˈœnːskɛˌmoːl dɪˈrɛkt ɪ ˈbuːknɪŋɛn/" },
  { id: 707, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Kunden blev jättenöjd med resultatet idag. Det gör samtalet tydligt och vänligt.", vi: "Khách hàng rất hài lòng với kết quả hôm nay. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/ˈkɵnːdɛn bleːv ˈjɛtːɛˌnœjd meːd rɛsɵlˈtɑːtɛt ɪˈdɑːɡ/" },
  { id: 708, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Vi städar av och fyller på förrådet innan vi stänger. Det känns naturligt och artigt.", vi: "Tụi mình dọn dẹp và châm thêm đồ dự trữ trước khi đóng cửa. Câu này nghe tự nhiên và lịch sự.", phonetic: "/viː ˈstɛːdar ɑːv ɔ ˈfʏlːɛr pɔː fœˈroːdɛt ˈɪnːan viː ˈstɛŋːɛr/" },
  { id: 709, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Har någon avbokat sin tid på eftermiddagen? Det skapar en trygg stämning.", vi: "Có ai hủy lịch buổi chiều nay không? Cách nói này tạo cảm giác an tâm.", phonetic: "/hɑːr ˈnoːɡɔn ˈɑːvˌbuːkat sɪn tiːd pɔː ˈɛfːtɛrˌmɪdːaɡɛn/" },
  { id: 710, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Jag är redo att ta emot nästa bokning nu. Det hjälper kunden att slappna av.", vi: "Mình đã sẵn sàng đón lượt đặt tiếp theo rồi. Điều này giúp khách dễ thư giãn hơn.", phonetic: "/jɑːɡ ɛːr ˈreːdu at tɑː ɛˈmʊːt ˈnɛsːta ˈbuːknɪŋ nʉː/" },
  { id: 711, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Hur känns det nu när du ser dig i spegeln? Det är en viktig del av god service.", vi: "Giờ khi nhìn mình trong gương bạn thấy thế nào? Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/hʉːr ɕɛnːs deː nʉː nɛːr dʉː seːr dej ɪ ˈspeːɡɛln/" },
  { id: 712, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Är det något jag kan justera lite till innan du går? Det gör samtalet tydligt och vänligt.", vi: "Có chỗ nào mình chỉnh thêm một chút trước khi bạn về không? Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/ɛːr deː ˈnoːɡɔt jɑːɡ kan jɵsˈteːra ˈliːtɛ tɪl ˈɪnːan dʉː ɡoːr/" },
  { id: 713, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Betalningen går bra med kort eller Swish. Det känns naturligt och artigt.", vi: "Thanh toán bằng thẻ hoặc Swish đều được nhé. Câu này nghe tự nhiên và lịch sự.", phonetic: "/bɛˈtɑːlnɪŋɛn ɡoːr brɑː meːd kɔʈ ˈɛlːɛr svɪʃ/" },
  { id: 714, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Här kommer kvittot. Varsågod! Det skapar en trygg stämning.", vi: "Hóa đơn của bạn đây. Mời bạn nhận! Cách nói này tạo cảm giác an tâm.", phonetic: "/hɛːr ˈkɔmːɛr ˈkvɪtːʊt ˈvɑːrʃɔˌɡuːd/" },
  { id: 715, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Tack för förtroendet och ha en riktigt fin dag! Det hjälper kunden att slappna av.", vi: "Cảm ơn bạn đã tin tưởng và chúc bạn một ngày thật đẹp! Điều này giúp khách dễ thư giãn hơn.", phonetic: "/tak fœr fœrˈtrʊːɛndɛt ɔ hɑː ɛn ˈrɪkːtɪt fiːn dɑːɡ/" },
  { id: 716, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Det var så roligt att få arbeta med dina naglar idag. Det är en viktig del av god service.", vi: "Hôm nay được làm móng cho bạn vui lắm luôn. Đây là một phần quan trọng của dịch vụ tốt.", phonetic: "/deːt vɑːr soː ˈrʊːlɪt at foː ˈɑːrbɛta meːd ˈdiːna ˈnaɡːlar ɪˈdɑːɡ/" },
  { id: 717, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Glöm inte din väska och dina personliga saker. Det gör samtalet tydligt och vänligt.", vi: "Đừng quên túi xách và đồ cá nhân của bạn nhé. Cách này giúp cuộc trò chuyện rõ ràng và thân thiện.", phonetic: "/ɡlœm ˈɪnːtɛ diːn ˈvɛsːka ɔ ˈdiːna pɛʂʊnˈliːɡa ˈsɑːkɛr/" },
  { id: 718, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Vi finns här om du har några frågor hemma. Det känns naturligt och artigt.", vi: "Tụi mình luôn ở đây nếu về nhà bạn có thắc mắc gì. Câu này nghe tự nhiên và lịch sự.", phonetic: "/viː fɪnːs hɛːr ɔm dʉː hɑːr ˈnoːɡra ˈfroːɡɔr ˈhɛmːa/" },
  { id: 719, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Ha en trevlig kväll och kör försiktigt hem! Det skapar en trygg stämning.", vi: "Chúc bạn buổi tối vui vẻ và đi đường về cẩn thận nhé! Cách nói này tạo cảm giác an tâm.", phonetic: "/hɑː ɛn ˈtreːvlɪɡ kvɛlː ɔ ɕœːr fœrˈsɪkːtɪt hɛm/" },
  { id: 720, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Välkommen tillbaka när du känner för det! Det hjälper kunden att slappna av.", vi: "Chào mừng bạn quay lại bất cứ khi nào bạn muốn nhé! Điều này giúp khách dễ thư giãn hơn.", phonetic: "/ˈvɛːlˌkɔmːɛn tɪlˈbɑːka nɛːr dʉː ˈɕɛnːɛr fœr deː/" },
  { id: 721, topic: "Đón tiếp khách hàng", sv: "Som nagel- och franstekniker säger jag: Hej! Välkommen till vår salong.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Xin chào! Chào mừng đến với tiệm của chúng tôi.", phonetic: "/hej ˈvɛːlˌkɔmːɛn tɪl voːr saˈlɔŋ/" },
  { id: 722, topic: "Đón tiếp khách hàng", sv: "I salongen säger jag ofta: God morgon! Hur mår du idag?", vi: "Trong tiệm mình thường nói: Chào buổi sáng! Hôm nay bạn cảm thấy thế nào?", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr moːr dʉː ɪˈdɑːɡ/" },
  { id: 723, topic: "Đón tiếp khách hàng", sv: "När jag jobbar brukar jag säga: Hej och välkommen! Har du bokat tid?", vi: "Khi làm việc mình hay nói: Xin chào và chào mừng! Bạn đã đặt lịch hẹn chưa?", phonetic: "/hej ɔ ˈvɛːlˌkɔmːɛn hɑːr dʉː ˈbuːkat tiːd/" },
  { id: 724, topic: "Đón tiếp khách hàng", sv: "Vid kundmottagning säger jag: Varsågod och sitt ner här en stund.", vi: "Khi đón tiếp mình nói: Mời bạn ngồi xuống đây một lát.", phonetic: "/ˈvɑːrʃɔˌɡuːd ɔ sɪtː neːr hɛːr ɛn stɵnd/" },
  { id: 725, topic: "Đón tiếp khách hàng", sv: "Under behandlingen säger jag lugnt: Vad trevligt att se dig igen!", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Thật vui được gặp lại bạn!", phonetic: "/vɑːd ˈtreːvlɪɡt at seː dej ɪˈjɛn/" },
  { id: 726, topic: "Đón tiếp khách hàng", sv: "Som nagel- och franstekniker säger jag: Välkommen in! Jag heter My Han och ska hjälpa dig idag.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Chào mừng vào tiệm! Mình tên là My Han và sẽ hỗ trợ bạn hôm nay.", phonetic: "/ˈvɛːlˌkɔmːɛn ɪn jɑːɡ ˈheːtɛr myː hɑn ɔ skɑː ˈjɛlːpa dej ɪˈdɑːɡ/" },
  { id: 727, topic: "Đón tiếp khách hàng", sv: "I salongen säger jag ofta: Hur var din dag hittills?", vi: "Trong tiệm mình thường nói: Ngày của bạn từ nãy đến giờ thế nào?", phonetic: "/hʉːr vɑːr diːn dɑːɡ ˈhɪtːɪls/" },
  { id: 728, topic: "Đón tiếp khách hàng", sv: "När jag jobbar brukar jag säga: Jag är så glad att du kom hit idag.", vi: "Khi làm việc mình hay nói: Mình rất vui vì hôm nay bạn đã đến đây.", phonetic: "/jɑːɡ ɛːr soː ɡlɑːd at dʉː kɔm hɪt ɪˈdɑːɡ/" },
  { id: 729, topic: "Đón tiếp khách hàng", sv: "Vid kundmottagning säger jag: Ta av dig jackan om du vill, så hänger jag upp den.", vi: "Khi đón tiếp mình nói: Bạn cởi áo khoác nếu muốn nhé, mình sẽ treo lên giúp.", phonetic: "/tɑː ɑːv dej ˈjakːan ɔm dʉː vɪl soː ˈhɛŋːɛr jɑːɡ ɵpː dɛn/" },
  { id: 730, topic: "Đón tiếp khách hàng", sv: "Under behandlingen säger jag lugnt: Känn dig som hemma här hos oss.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Hãy cứ tự nhiên như ở nhà khi ở chỗ tụi mình nhé.", phonetic: "/ɕɛnː dej sɔm ˈhɛmːa hɛːr huːs ɔsː/" },
  { id: 731, topic: "Mời nước khách", sv: "Som nagel- och franstekniker säger jag: Vill du ha något att dricka, kaffe eller vatten?", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Bạn có muốn uống chút gì không, cà phê hay nước lọc?", phonetic: "/vɪl dʉː hɑː ˈnoːɡɔt at ˈdrɪkːa ˈkafːɛ ˈɛlːɛr ˈvatːɛn/" },
  { id: 732, topic: "Mời nước khách", sv: "I salongen säger jag ofta: Vill du ha ett glas kallt vatten medan du väntar?", vi: "Trong tiệm mình thường nói: Bạn có muốn một ly nước lạnh trong lúc chờ không?", phonetic: "/vɪl dʉː hɑː ɛt ɡlɑːs kalːt ˈvatːɛn ˈmeːdan dʉː ˈvɛnːtar/" },
  { id: 733, topic: "Mời nước khách", sv: "När jag jobbar brukar jag säga: Jag kan bjuda på te eller kaffe om du önskar.", vi: "Khi làm việc mình hay nói: Mình có thể mời trà hoặc cà phê nếu bạn muốn.", phonetic: "/jɑːɡ kan ˈbjʉːda pɔː teː ˈɛlːɛr ˈkafːɛ ɔm dʉː ˈœnːskar/" },
  { id: 734, topic: "Mời nước khách", sv: "Vid kundmottagning säger jag: Föredrar du varmt eller kallt vatten?", vi: "Khi đón tiếp mình nói: Bạn thích nước ấm hay nước lạnh hơn?", phonetic: "/ˌfœrɛˈdrɑːr dʉː varmt ˈɛlːɛr kalːt ˈvatːɛn/" },
  { id: 735, topic: "Mời nước khách", sv: "Under behandlingen säger jag lugnt: Ska jag hälla upp lite te åt dig?", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Mình rót thêm chút trà cho bạn nhé?", phonetic: "/skɑː jɑːɡ ˈhɛlːa ɵpː ˈliːtɛ teː oːt dej/" },
  { id: 736, topic: "Mời nước khách", sv: "Som nagel- och franstekniker säger jag: Här kommer ditt vatten. Varsågod!", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Nước của bạn đây. Mời bạn dùng!", phonetic: "/hɛːr ˈkɔmːɛr dɪt ˈvatːɛn ˈvɑːrʃɔˌɡuːd/" },
  { id: 737, topic: "Mời nước khách", sv: "I salongen säger jag ofta: Vill du ha socker eller mjölk i kaffet?", vi: "Trong tiệm mình thường nói: Bạn có muốn thêm đường hay sữa vào cà phê không?", phonetic: "/vɪl dʉː hɑː ˈsɔkːɛr ˈɛlːɛr mjœlk ɪ ˈkafːɛt/" },
  { id: 738, topic: "Mời nước khách", sv: "När jag jobbar brukar jag säga: Jag fixar en kopp varmt te direkt.", vi: "Khi làm việc mình hay nói: Mình pha một tách trà nóng ngay đây.", phonetic: "/jɑːɡ ˈfɪkːsar ɛn kɔpː varmt teː dɪˈrɛkt/" },
  { id: 739, topic: "Mời nước khách", sv: "Vid kundmottagning säger jag: Vill du ha en liten kaka till kaffet?", vi: "Khi đón tiếp mình nói: Bạn có muốn ăn thêm một chiếc bánh nhỏ kèm cà phê không?", phonetic: "/vɪl dʉː hɑː ɛn ˈliːtɛn ˈkɑːka tɪl ˈkafːɛt/" },
  { id: 740, topic: "Mời nước khách", sv: "Under behandlingen säger jag lugnt: Säg bara till om du vill ha påfyllning.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Cứ bảo mình nếu bạn muốn châm thêm nhé.", phonetic: "/sɛːj ˈbɑːra tɪl ɔm dʉː vɪl hɑː ˈpoːˌfʏlːnɪŋ/" },
  { id: 741, topic: "Thao tác nối mi / Spa", sv: "Som nagel- och franstekniker säger jag: Blunda och slappna av nu.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Hãy nhắm mắt lại và thư giãn nhé.", phonetic: "/ˈblɵnːda ɔ ˈslapːna ɑːv nʉː/" },
  { id: 742, topic: "Thao tác nối mi / Spa", sv: "I salongen säger jag ofta: Känns det bra och bekvämt på britsen?", vi: "Trong tiệm mình thường nói: Nằm trên giường liệu trình có thấy thoải mái không?", phonetic: "/ɕɛnːs deː brɑː ɔ bɛˈkvɛːmt pɔː brɪtːsɛn/" },
  { id: 743, topic: "Thao tác nối mi / Spa", sv: "När jag jobbar brukar jag säga: Jag sätter på en mjuk ögonpad under fransarna nu.", vi: "Khi làm việc mình hay nói: Bây giờ mình dán miếng lót mắt mềm dưới hàng mi nhé.", phonetic: "/jɑːɡ ˈsɛtːɛr pɔː ɛn mjʉːk ˈœːɡɔnˌpad ɵnːdɛr ˈfranːsarːa nʉː/" },
  { id: 744, topic: "Thao tác nối mi / Spa", sv: "Vid kundmottagning säger jag: Säg till direkt om det svider eller sticker till.", vi: "Khi đón tiếp mình nói: Báo ngay cho mình nếu thấy cay hoặc châm chích nhé.", phonetic: "/sɛːj tɪl dɪˈrɛkt ɔm deː ˈsviːdɛr ˈɛlːɛr ˈstɪkːɛr tɪl/" },
  { id: 745, topic: "Thao tác nối mi / Spa", sv: "Under behandlingen säger jag lugnt: Vi börjar med att rengöra fransarna noga.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Tụi mình bắt đầu bằng việc làm sạch mi thật kỹ.", phonetic: "/viː ˈbœrːjar meːd at ˈreːnˌjœːra ˈfranːsarːa ˈnoːɡa/" },
  { id: 746, topic: "Thao tác nối mi / Spa", sv: "Som nagel- och franstekniker säger jag: Nu applicerar jag limmet försiktigt på varje frans.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Giờ mình gắn keo cẩn thận lên từng sợi mi.", phonetic: "/nʉː ˌapːlɪˈseːrar jɑːɡ ˈlɪmːɛt fœrˈsɪkːtɪt pɔː ˈvarːjɛ frans/" },
  { id: 747, topic: "Thao tác nối mi / Spa", sv: "I salongen säger jag ofta: Känns tejpningen för stram på något ställe?", vi: "Trong tiệm mình thường nói: Miếng băng dán có bị căng ở chỗ nào không?", phonetic: "/ɕɛnːs ˈtɛjpnɪŋɛn fœr stram pɔː ˈnoːɡɔt ˈstɛlːɛ/" },
  { id: 748, topic: "Thao tác nối mi / Spa", sv: "När jag jobbar brukar jag säga: Jag masserar hårbotten med lugna rörelser nu.", vi: "Khi làm việc mình hay nói: Bây giờ mình massage da đầu với các động tác nhẹ nhàng nhé.", phonetic: "/jɑːɡ maˈseːrar ˈhoːrˌbɔtːɛn meːd ˈlɵɡːna ˈrœːrɛlsɛr nʉː/" },
  { id: 749, topic: "Thao tác nối mi / Spa", sv: "Vid kundmottagning säger jag: Är vattnet lagom varmt när jag sköljer håret?", vi: "Khi đón tiếp mình nói: Nước có vừa độ ấm khi mình xả tóc không?", phonetic: "/ɛːr ˈvatːnɛt ˈlɑːɡɔm varmt nɛːr jɑːɡ ˈɕœlːjɛr ˈhoːrɛt/" },
  { id: 750, topic: "Thao tác nối mi / Spa", sv: "Under behandlingen säger jag lugnt: Nu är vi klara med behandlingen. Öppna ögonen sakta.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Xong liệu trình rồi đây. Bạn mở mắt từ từ nhé.", phonetic: "/nʉː ɛːr viː ˈklɑːra meːd bɛˈhanːdlɪŋɛn ˈœpːna ˈœːɡɔnɛn ˈsakːta/" },
  { id: 751, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Som nagel- och franstekniker säger jag: Vilken stil gillar du mest, naturlig eller volym?", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Bạn thích kiểu nào nhất, tự nhiên hay dày vol?", phonetic: "/ˈvɪlːkɛn stiːl ˈjɪlːar dʉː mɛst nɑtʉːˈliːr ˈɛlːɛr vɔˈlʏːm/" },
  { id: 752, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "I salongen säger jag ofta: Vill du ha en öppen docköga eller en mjuk kattöga?", vi: "Trong tiệm mình thường nói: Bạn muốn dáng mắt búp bê tròn to hay dáng mắt mèo dịu dàng?", phonetic: "/vɪl dʉː hɑː ɛn ˈœpːɛn ˈdɔkˌœːɡa ˈɛlːɛr ɛn mjʉːk ˈkatˌœːɡa/" },
  { id: 753, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "När jag jobbar brukar jag säga: Jag rekommenderar en lite kortare längd innerst.", vi: "Khi làm việc mình hay nói: Mình khuyên nên chọn độ dài ngắn hơn một chút ở góc trong.", phonetic: "/jɑːɡ ˌrɛkɔmɛnˈdeːrar ɛn ˈliːtɛ ˈkɔrːtarɛ lɛŋd ˈɪnːɛrst/" },
  { id: 754, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vid kundmottagning säger jag: Vill du ha mandelformade, fyrkantiga eller runda naglar?", vi: "Khi đón tiếp mình nói: Bạn muốn móng dáng hạnh nhân, móng vuông hay móng tròn?", phonetic: "/vɪl dʉː hɑː ˈmanːdɛlˌfɔrmadɛ ˈfʏrˌkantɪɡa ˈɛlːɛr ˈrɵnːda ˈnaɡːlar/" },
  { id: 755, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Under behandlingen säger jag lugnt: Den här nyansen passar väldigt fint till din hudton.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Tông màu này hợp với sắc da của bạn lắm đấy.", phonetic: "/deːn hɛːr nʏˈanːsɛn ˈpasːar ˈvɛlːdɪt fɪnt tɪl diːn ˈhʉːdˌtuːn/" },
  { id: 756, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Som nagel- och franstekniker säger jag: Vi kan göra gel, förstärkning med builder gel eller akryl.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Tụi mình có thể làm gel, đắp gel cứng hoặc đắp bột.", phonetic: "/viː kan ˈjœːra jeːl fœrˈstɛrkːnɪŋ meːd ˈbɪlːdɛr jeːl ˈɛlːɛr ɑˈkrʏːl/" },
  { id: 757, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "I salongen säger jag ofta: Vill du ha enfärgat, fransk manikyr eller chrome?", vi: "Trong tiệm mình thường nói: Bạn muốn sơn một màu, kiểu Pháp hay hiệu ứng chrome?", phonetic: "/vɪl dʉː hɑː ˈeːnˌfɛrɡat fransk mɑnɪˈkʏːr ˈɛlːɛr kroːm/" },
  { id: 758, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "När jag jobbar brukar jag säga: Jag anpassar böjen efter dina naturliga fransar.", vi: "Khi làm việc mình hay nói: Mình điều chỉnh độ cong theo hàng mi thật của bạn.", phonetic: "/jɑːɡ ˈanːpasːar ˈbœjːɛn ˈɛfːtɛr ˈdiːna nɑtʉːˈliːra ˈfranːsar/" },
  { id: 759, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Vid kundmottagning säger jag: Det är bäst att skona dina egna fransar så de håller sig friska.", vi: "Khi đón tiếp mình nói: Tốt nhất là giữ gìn mi thật để mi luôn khỏe mạnh.", phonetic: "/deːt ɛːr bɛst at ˈskuːna ˈdiːna ˈeːɡːna ˈfranːsar soː deː ˈhɔlːɛr sej ˈfrɪsːka/" },
  { id: 760, topic: "Tư vấn kiểu dáng & dịch vụ", sv: "Under behandlingen säger jag lugnt: Ska vi lägga till en djupgående fuktkur för händerna idag?", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Hôm nay mình thêm bước dưỡng ẩm sâu cho tay nhé?", phonetic: "/skɑː viː ˈlɛɡːa tɪl ɛn ˈjʉːpˌɡoːɛnːdɛ ˈfɵktˌkʉːr fœr ˈhɛnːdarːa ɪˈdɑːɡ/" },
  { id: 761, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Som nagel- och franstekniker säger jag: Undvik vatten och ånga på fransarna de första tjugofyra timmarna.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Tránh nước và hơi nóng lên mi trong hai mươi bốn giờ đầu nhé.", phonetic: "/ˈɵnːdviːk ˈvatːɛn ɔ ˈɔŋːa pɔː ˈfranːsarːa deː ˈfœsːta ˈɕʉːɡʊˌfyːra ˈtɪmːarːa/" },
  { id: 762, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "I salongen säger jag ofta: Gnugga inte ögonen och använd oljefria produkter.", vi: "Trong tiệm mình thường nói: Đừng dụi mắt và hãy dùng sản phẩm không chứa dầu nhé.", phonetic: "/ˈɡnɵɡːa ˈɪnːtɛ ˈœːɡɔnɛn ɔ ˈanːvɛnd ˈɔlːjɛˌfriːa prʊˈdɵkːtɛr/" },
  { id: 763, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "När jag jobbar brukar jag säga: Borsta fransarna försiktigt varje morgon med borsten du får.", vi: "Khi làm việc mình hay nói: Chải mi nhẹ nhàng mỗi sáng bằng cọ được tặng kèm nhé.", phonetic: "/ˈbɔʂːta ˈfranːsarːa fœrˈsɪkːtɪt ˈvarːjɛ ˈmɔrːɔn meːd ˈbɔʂːtɛn dʉː fɔːr/" },
  { id: 764, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Vid kundmottagning säger jag: Det är dags för påfyllning om ungefär tre veckor.", vi: "Khi đón tiếp mình nói: Khoảng ba tuần nữa là tới lúc dặm lại rồi đấy.", phonetic: "/deːt ɛːr daks fœr ˈpoːˌfʏlːnɪŋ ɔm ɵnːfɛˈjɛːr treː ˈvɛkːɔr/" },
  { id: 765, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Under behandlingen säger jag lugnt: Smörj nagelbanden med nagelolja varje kväll.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Thoa dầu dưỡng viền móng mỗi tối nhé.", phonetic: "/smœrj ˈnɑːɡɛlˌbanːdɛn meːd ˈnɑːɡɛlˌɔlːja ˈvarːjɛ kvɛlː/" },
  { id: 766, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Som nagel- och franstekniker säger jag: Använd gärna handskar när du diskar eller städar.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Bạn nhớ đeo găng tay khi rửa chén hoặc dọn dẹp nhé.", phonetic: "/ˈanːvɛnd ˈjɛːrna ˈhanːskar nɛːr dʉː ˈdɪsːkar ˈɛlːɛr ˈstɛːdar/" },
  { id: 767, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "I salongen säger jag ofta: Vill du boka nästa tid redan innan du går idag?", vi: "Trong tiệm mình thường nói: Bạn có muốn đặt lịch lần tới ngay trước khi về hôm nay không?", phonetic: "/vɪl dʉː ˈbuːka ˈnɛsːta tiːd ˈreːdan ˈɪnːan dʉː ɡoːr ɪˈdɑːɡ/" },
  { id: 768, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "När jag jobbar brukar jag säga: Vi har en ledig tid på tisdag klockan tio.", vi: "Khi làm việc mình hay nói: Tụi mình còn trống lịch vào thứ ba lúc mười giờ.", phonetic: "/viː hɑːr ɛn ˈleːdɪɡ tiːd pɔː ˈtɪsːdɑːɡ ˈklɔkːan ˈtiːʊ/" },
  { id: 769, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Vid kundmottagning säger jag: Jag skickar en påminnelse dagen innan din tid.", vi: "Khi đón tiếp mình nói: Mình sẽ gửi tin nhắn nhắc lịch trước ngày hẹn một ngày.", phonetic: "/jɑːɡ ˈɕɪkːar ɛn ˈpoːˌmɪnːɛlsɛ ˈdɑːɡɛn ˈɪnːan diːn tiːd/" },
  { id: 770, topic: "Chăm sóc sau dịch vụ & đặt lịch", sv: "Under behandlingen säger jag lugnt: Tack så mycket för besöket! Vi ses nästa gång.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Cảm ơn bạn rất nhiều vì đã ghé tiệm! Hẹn gặp lại lần sau nhé.", phonetic: "/tak soː ˈmʏkːɛt fœr bɛˈsøːkɛt viː seːs ˈnɛsːta ɡɔŋ/" },
  { id: 771, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Som nagel- och franstekniker säger jag: Jag desinficerar alla verktyg mellan varje kund.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Mình khử trùng toàn bộ dụng cụ giữa mỗi khách hàng.", phonetic: "/jɑːɡ dɛsɪnfɪˈseːrar ˈalːa ˈvɛrkˌtʏːɡ ˈmɛlːan ˈvarːjɛ kɵnd/" },
  { id: 772, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "I salongen säger jag ofta: Vi följer säkerhetsrutiner för härdplast och lim.", vi: "Trong tiệm mình thường nói: Tụi mình tuân thủ quy trình an toàn với nhựa cứng và keo.", phonetic: "/viː ˈfœlːjɛr ˈsɛːkɛrˌheːtsrɵˌtiːnɛr fœr ˈhɛːrdˌplast ɔ liːm/" },
  { id: 773, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "När jag jobbar brukar jag säga: Jag arbetar i ett välventilerat rum med punktutsug.", vi: "Khi làm việc mình hay nói: Mình làm việc trong phòng thông thoáng có máy hút khí cục bộ.", phonetic: "/jɑːɡ ˈɑːrbɛtar ɪ ɛt ˈvɛːlˌvɛntɪˌleːrat rɵm meːd ˈpɵŋktˌʉːtsʉːɡ/" },
  { id: 774, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Vid kundmottagning säger jag: Jag byter handskar och dukar inför varje ny behandling.", vi: "Khi đón tiếp mình nói: Mình thay găng tay và khăn trải trước mỗi liệu trình mới.", phonetic: "/jɑːɡ ˈbʏːtɛr ˈhanːskar ɔ ˈdʉːkar ˈɪnːfœr ˈvarːjɛ nʏː bɛˈhanːdlɪŋ/" },
  { id: 775, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Under behandlingen säger jag lugnt: Pincetterna är rengjorda och redo för dagens pass.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Các cây nhíp đã được làm sạch và sẵn sàng cho ca làm hôm nay.", phonetic: "/pɪnˈsɛtːarːa ɛːr ˈreːnˌjuːrda ɔ ˈreːdu fœr ˈdɑːɡɛns pasː/" },
  { id: 776, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Som nagel- och franstekniker säger jag: Vi håller arbetsstationen ren, organiserad och lugn.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Tụi mình giữ bàn làm việc sạch sẽ, gọn gàng và yên tĩnh.", phonetic: "/viː ˈhɔlːɛr ˈɑːrbɛtsˌstɑːˌɕuːnɛn reːn ɔrɡanɪˈseːrad ɔ lɵŋn/" },
  { id: 777, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "I salongen säger jag ofta: Jag kontrollerar att limmet har rätt konsistens och fuktighet.", vi: "Trong tiệm mình thường nói: Mình kiểm tra xem keo có độ sệt và độ ẩm chuẩn chưa.", phonetic: "/jɑːɡ kɔntrɔˈleːrar at ˈlɪmːɛt hɑːr rɛt kɔnsɪsˈtɛnːs ɔ ˈfɵkːtɪˌheːt/" },
  { id: 778, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "När jag jobbar brukar jag säga: Engångsartiklar slängs i avsedd behållare direkt.", vi: "Khi làm việc mình hay nói: Đồ dùng một lần được bỏ vào thùng chuyên dụng ngay lập tức.", phonetic: "/ˈeːnˌɡɔŋsˌɑːrtɪklar slɛŋːs ɪ ˈɑːvˌsɛd bɛˈhɔlːarɛ dɪˈrɛkt/" },
  { id: 779, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Vid kundmottagning säger jag: Jag tvättar händerna noggrant före och efter varje moment.", vi: "Khi đón tiếp mình nói: Mình rửa tay kỹ trước và sau mỗi thao tác.", phonetic: "/jɑːɡ ˈtvɛtːar ˈhɛnːdarːa ˈnoːɡrant ˈfœːrɛ ɔ ˈɛfːtɛr ˈvarːjɛ mʊˈmɛnːt/" },
  { id: 780, topic: "Vệ sinh, an toàn & chuẩn bị dụng cụ", sv: "Under behandlingen säger jag lugnt: All utrustning står på sin plats så arbetet flyter smidigt.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Mọi thiết bị đều đúng vị trí để công việc trôi chảy mượt mà.", phonetic: "/alː ˈʉːtˌrɵsːnɪŋ stoːr pɔː sɪn plats soː ɑrˈbeːtɛt ˈflʏːtɛr ˈsmiːdɪt/" },
  { id: 781, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Som nagel- och franstekniker säger jag: Hur ser schemat ut för resten av veckan?", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Lịch làm việc cho phần còn lại của tuần trông thế nào?", phonetic: "/hʉːr seːr ˈɕeːmat ʉːt fœr ˈrɛsːtɛn ɑːv ˈvɛkːan/" },
  { id: 782, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "I salongen säger jag ofta: Jag har förberett allt inför nästa kund klocker ett.", vi: "Trong tiệm mình thường nói: Mình đã chuẩn bị xong mọi thứ cho khách tiếp theo lúc một giờ.", phonetic: "/jɑːɡ hɑːr ˈfœrːbɛrɛt alːt ˈɪnːfœr ˈnɛsːta kɵnd ˈklɔkːɛn ɛt/" },
  { id: 783, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "När jag jobbar brukar jag säga: Vi behöver beställa mer franslim och primer i veckan.", vi: "Khi làm việc mình hay nói: Tụi mình cần đặt thêm keo nối mi và primer trong tuần này.", phonetic: "/viː bɛˈhøːvɛr bɛˈstɛlːa meːr ˈfransˌliːm ɔ ˈpraɪmɛr ɪ ˈvɛkːan/" },
  { id: 784, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Vid kundmottagning säger jag: Kan du hjälpa mig att ta emot nästa kund i receptionen?", vi: "Khi đón tiếp mình nói: Bạn giúp mình đón khách tiếp theo ở quầy lễ tân được không?", phonetic: "/kan dʉː ˈjɛlːpa mej at tɑː ɛˈmʊːt ˈnɛsːta kɵnd ɪ rɛsɛpˈɕuːnɛn/" },
  { id: 785, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Under behandlingen säger jag lugnt: Vi samarbetar bra när vi stämmer av tiderna i förväg.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Tụi mình phối hợp nhịp nhàng khi rà soát giờ giấc từ trước.", phonetic: "/viː ˈsɑːmarˌbeːtar brɑː nɛːr viː ˈstɛmːɛr ɑːv ˈtiːdarːa ɪ fœrˈvɛːɡ/" },
  { id: 786, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Som nagel- och franstekniker säger jag: Jag antecknar kundens önskemål direkt i bokningen.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Mình ghi chú mong muốn của khách thẳng vào lịch đặt.", phonetic: "/jɑːɡ ˈanːˌteːknar ˈkɵnːdɛns ˈœnːskɛˌmoːl dɪˈrɛkt ɪ ˈbuːknɪŋɛn/" },
  { id: 787, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "I salongen säger jag ofta: Kunden blev jättenöjd med resultatet idag.", vi: "Trong tiệm mình thường nói: Khách hàng rất hài lòng với kết quả hôm nay.", phonetic: "/ˈkɵnːdɛn bleːv ˈjɛtːɛˌnœjd meːd rɛsɵlˈtɑːtɛt ɪˈdɑːɡ/" },
  { id: 788, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "När jag jobbar brukar jag säga: Vi städar av och fyller på förrådet innan vi stänger.", vi: "Khi làm việc mình hay nói: Tụi mình dọn dẹp và châm thêm đồ dự trữ trước khi đóng cửa.", phonetic: "/viː ˈstɛːdar ɑːv ɔ ˈfʏlːɛr pɔː fœˈroːdɛt ˈɪnːan viː ˈstɛŋːɛr/" },
  { id: 789, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Vid kundmottagning säger jag: Har någon avbokat sin tid på eftermiddagen?", vi: "Khi đón tiếp mình nói: Có ai hủy lịch buổi chiều nay không?", phonetic: "/hɑːr ˈnoːɡɔn ˈɑːvˌbuːkat sɪn tiːd pɔː ˈɛfːtɛrˌmɪdːaɡɛn/" },
  { id: 790, topic: "Trao đổi đồng nghiệp & quản lý công việc", sv: "Under behandlingen säger jag lugnt: Jag är redo att ta emot nästa bokning nu.", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Mình đã sẵn sàng đón lượt đặt tiếp theo rồi.", phonetic: "/jɑːɡ ɛːr ˈreːdu at tɑː ɛˈmʊːt ˈnɛsːta ˈbuːknɪŋ nʉː/" },
  { id: 791, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Som nagel- och franstekniker säger jag: Hur känns det nu när du ser dig i spegeln?", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Giờ khi nhìn mình trong gương bạn thấy thế nào?", phonetic: "/hʉːr ɕɛnːs deː nʉː nɛːr dʉː seːr dej ɪ ˈspeːɡɛln/" },
  { id: 792, topic: "Phản hồi, thanh toán & chia tay khách", sv: "I salongen säger jag ofta: Är det något jag kan justera lite till innan du går?", vi: "Trong tiệm mình thường nói: Có chỗ nào mình chỉnh thêm một chút trước khi bạn về không?", phonetic: "/ɛːr deː ˈnoːɡɔt jɑːɡ kan jɵsˈteːra ˈliːtɛ tɪl ˈɪnːan dʉː ɡoːr/" },
  { id: 793, topic: "Phản hồi, thanh toán & chia tay khách", sv: "När jag jobbar brukar jag säga: Betalningen går bra med kort eller Swish.", vi: "Khi làm việc mình hay nói: Thanh toán bằng thẻ hoặc Swish đều được nhé.", phonetic: "/bɛˈtɑːlnɪŋɛn ɡoːr brɑː meːd kɔʈ ˈɛlːɛr svɪʃ/" },
  { id: 794, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Vid kundmottagning säger jag: Här kommer kvittot. Varsågod!", vi: "Khi đón tiếp mình nói: Hóa đơn của bạn đây. Mời bạn nhận!", phonetic: "/hɛːr ˈkɔmːɛr ˈkvɪtːʊt ˈvɑːrʃɔˌɡuːd/" },
  { id: 795, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Under behandlingen säger jag lugnt: Tack för förtroendet och ha en riktigt fin dag!", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Cảm ơn bạn đã tin tưởng và chúc bạn một ngày thật đẹp!", phonetic: "/tak fœr fœrˈtrʊːɛndɛt ɔ hɑː ɛn ˈrɪkːtɪt fiːn dɑːɡ/" },
  { id: 796, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Som nagel- och franstekniker säger jag: Det var så roligt att få arbeta med dina naglar idag.", vi: "Với vai trò kỹ thuật viên nail & mi mình nói: Hôm nay được làm móng cho bạn vui lắm luôn.", phonetic: "/deːt vɑːr soː ˈrʊːlɪt at foː ˈɑːrbɛta meːd ˈdiːna ˈnaɡːlar ɪˈdɑːɡ/" },
  { id: 797, topic: "Phản hồi, thanh toán & chia tay khách", sv: "I salongen säger jag ofta: Glöm inte din väska och dina personliga saker.", vi: "Trong tiệm mình thường nói: Đừng quên túi xách và đồ cá nhân của bạn nhé.", phonetic: "/ɡlœm ˈɪnːtɛ diːn ˈvɛsːka ɔ ˈdiːna pɛʂʊnˈliːɡa ˈsɑːkɛr/" },
  { id: 798, topic: "Phản hồi, thanh toán & chia tay khách", sv: "När jag jobbar brukar jag säga: Vi finns här om du har några frågor hemma.", vi: "Khi làm việc mình hay nói: Tụi mình luôn ở đây nếu về nhà bạn có thắc mắc gì.", phonetic: "/viː fɪnːs hɛːr ɔm dʉː hɑːr ˈnoːɡra ˈfroːɡɔr ˈhɛmːa/" },
  { id: 799, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Vid kundmottagning säger jag: Ha en trevlig kväll och kör försiktigt hem!", vi: "Khi đón tiếp mình nói: Chúc bạn buổi tối vui vẻ và đi đường về cẩn thận nhé!", phonetic: "/hɑː ɛn ˈtreːvlɪɡ kvɛlː ɔ ɕœːr fœrˈsɪkːtɪt hɛm/" },
  { id: 800, topic: "Phản hồi, thanh toán & chia tay khách", sv: "Under behandlingen säger jag lugnt: Välkommen tillbaka när du känner för det!", vi: "Trong lúc làm liệu trình mình nói nhẹ nhàng: Chào mừng bạn quay lại bất cứ khi nào bạn muốn nhé!", phonetic: "/ˈvɛːlˌkɔmːɛn tɪlˈbɑːka nɛːr dʉː ˈɕɛnːɛr fœr deː/" },
  { id: 801, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "God morgon! Hur har du sovit?", vi: "Chào buổi sáng! Bạn ngủ có ngon không?", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr hɑːr dʉː ˈsʊːvɪt/" },
  { id: 802, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag vaknade tidigt idag och tog en lugn start.", vi: "Hôm nay mình dậy sớm và khởi đầu thật nhẹ nhàng.", phonetic: "/jɑːɡ ˈvɑːknadɛ ˈtiːdɪt ɪˈdɑːɡ ɔ tʊːɡ ɛn lɵŋn stɑʈ/" },
  { id: 803, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Vad ska vi äta till middag ikväll?", vi: "Tối nay tụi mình sẽ ăn gì nhỉ?", phonetic: "/vɑːd skɑː viː ˈɛːta tɪl ˈmɪdːɑːɡ ɪˈkvɛlː/" },
  { id: 804, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag håller på att laga mat i köket nu.", vi: "Bây giờ mình đang nấu ăn trong bếp.", phonetic: "/jɑːɡ ˈhɔlːɛr pɔː at ˈlɑːɡa mɑːt ɪ ˈɕøːkɛt nʉː/" },
  { id: 805, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Kan du upprepa det lite långsammare, tack?", vi: "Bạn lặp lại chậm hơn một chút được không, cảm ơn bạn?", phonetic: "/kan dʉː ɵpːrɛˈpɑː deː ˈliːtɛ ˈlɔŋːsamːarɛ tak/" },
  { id: 806, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag förstår ungefär vad du menar, men jag övar fortfarande.", vi: "Mình hiểu đại khái ý bạn, nhưng mình vẫn đang luyện thêm.", phonetic: "/jɑːɡ fœrˈstoːr ɵnːfɛˈjɛːr vɑːd dʉː ˈmeːnar mɛn jɑːɡ ˈøːvar ˈfɔrtˌfarːandɛ/" },
  { id: 807, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Det här ordet är nytt för mig. Vad betyder det?", vi: "Từ này mới với mình. Nó có nghĩa là gì vậy?", phonetic: "/deːt hɛːr ˈuːɖɛt ɛːr nʏt fœr mej vɑːd bɛˈtʏːdɛr deː/" },
  { id: 808, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag övar på att prata svenska varje dag.", vi: "Mình luyện nói tiếng Thụy Điển mỗi ngày.", phonetic: "/jɑːɡ ˈøːvar pɔː at ˈprɑːta ˈsvɛnːska ˈvarːjɛ dɑːɡ/" },
  { id: 809, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Det blir lättare ju mer man pratar.", vi: "Càng nói nhiều thì sẽ càng dễ hơn.", phonetic: "/deːt bliːr ˈlɛtːarɛ jʉː meːr man ˈprɑːtar/" },
  { id: 810, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Tack för hjälpen, det betydde mycket!", vi: "Cảm ơn vì đã giúp đỡ, điều đó có ý nghĩa lắm!", phonetic: "/tak fœr ˈjɛlːpɛn deː bɛˈtʏːdːɛ ˈmʏkːɛt/" },
  { id: 811, topic: "Gia đình & người thân", sv: "Jag pratar med min man varje dag om framtiden.", vi: "Mình trò chuyện với chồng mỗi ngày về tương lai.", phonetic: "/jɑːɡ ˈprɑːtar meːd miːn man ˈvarːjɛ dɑːɡ ɔm ˈfrɑːmˌtiːdɛn/" },
  { id: 812, topic: "Gia đình & người thân", sv: "Vi planerar vårt nya liv tillsammans i lugn takt.", vi: "Tụi mình lên kế hoạch cho cuộc sống mới cùng nhau một cách chầm chậm.", phonetic: "/viː plɑˈneːrar voːʈ ˈnʏːa liːv tɪlˈsamːanːs ɪ lɵŋn tɑkt/" },
  { id: 813, topic: "Gia đình & người thân", sv: "Jag tänker ofta på min mormor hemma.", vi: "Mình thường nhớ tới bà ngoại ở nhà.", phonetic: "/jɑːɡ ˈtɛŋːkɛr ˈɔfːta pɔː miːn ˈmʊːrmʊr ˈhɛmːa/" },
  { id: 814, topic: "Gia đình & người thân", sv: "Familjen betyder allt när man är långt hemifrån.", vi: "Gia đình có ý nghĩa tất cả khi ở xa nhà.", phonetic: "/fɑˈmiːljɛn bɛˈtʏːdɛr alːt nɛːr man ɛːr lɔŋt ˈhɛmːɪˌfroːn/" },
  { id: 815, topic: "Gia đình & người thân", sv: "Vi ringer videosamtal på helgen när alla är lediga.", vi: "Tụi mình gọi video vào cuối tuần khi ai cũng rảnh.", phonetic: "/viː ˈrɪŋːɛr ˈviːdɛʊˌsamːtɑːl pɔː ˈhɛlːjɛn nɛːr ˈalːa ɛːr ˈleːdɪɡa/" },
  { id: 816, topic: "Gia đình & người thân", sv: "Han lagar god mat och stöttar mig alltid.", vi: "Anh ấy nấu ăn ngon và luôn ủng hộ mình.", phonetic: "/han ˈlɑːɡar ɡuːd mɑːt ɔ ˈstœtːar mej ˈalːtiːd/" },
  { id: 817, topic: "Gia đình & người thân", sv: "Att hjälpa varandra gör vardagen enklare.", vi: "Giúp đỡ lẫn nhau khiến cuộc sống hằng ngày nhẹ nhàng hơn.", phonetic: "/at ˈjɛlːpa vɑˈranːdra jøːr ˈvɑːrˌdɑːɡɛn ˈɛŋːklarɛ/" },
  { id: 818, topic: "Gia đình & người thân", sv: "Jag vill gärna bjuda hem familjen på middag någon gång.", vi: "Mình rất muốn mời gia đình đến nhà ăn tối một dịp nào đó.", phonetic: "/jɑːɡ vɪl ˈjɛːrna ˈbjʉːda hɛm fɑˈmiːljɛn pɔː ˈmɪdːɑːɡ ˈnoːɡɔn ɡɔŋ/" },
  { id: 819, topic: "Gia đình & người thân", sv: "Det känns tryggt att ha någon som förstår en.", vi: "Thật vững tâm khi có người thấu hiểu mình.", phonetic: "/deːt ɕɛnːs trʏɡt at hɑː ˈnoːɡɔn sɔm fœrˈstoːr ɛn/" },
  { id: 820, topic: "Gia đình & người thân", sv: "Vi delar både glädje och små bekymmer.", vi: "Tụi mình chia sẻ cả niềm vui lẫn những nỗi lo nhỏ.", phonetic: "/viː ˈdeːlar ˈboːdɛ ˈɡlɛːdjɛ ɔ smoː bɛˈɕʏmːɛr/" },
  { id: 821, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag gillar att ta en promenad i parken efter jobbet.", vi: "Mình thích đi dạo trong công viên sau giờ làm.", phonetic: "/jɑːɡ ˈjɪlːar at tɑː ɛn prʊmɛˈnɑːd ɪ ˈparːkɛn ˈɛfːtɛr ˈjɔbːɛt/" },
  { id: 822, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Frisk luft och grönska hjälper mig att ladda om.", vi: "Không khí trong lành và cây xanh giúp mình nạp lại năng lượng.", phonetic: "/frɪsk lɵft ɔ ˈɡrœnːska ˈjɛlːpɛr mej at ˈladːa ɔm/" },
  { id: 823, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vilken vacker utsikt över sjön och skogen!", vi: "Khung cảnh nhìn ra hồ và rừng đẹp quá!", phonetic: "/ˈvɪlːkɛn ˈvakːɛr ˈʉːtˌsɪkːt ˈøːvɛr ɕøːn ɔ ˈskuːɡɛn/" },
  { id: 824, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag brukar ta foton på naturen när vi reser.", vi: "Mình hay chụp ảnh thiên nhiên khi tụi mình đi du lịch.", phonetic: "/jɑːɡ ˈbrʉːkar tɑː ˈfuːtɔn pɔː nɑtʉːˈreːn nɛːr viː ˈreːsɛr/" },
  { id: 825, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vi åker gärna iväg på helgutflykter till nya platser.", vi: "Tụi mình thích đi chơi cuối tuần tới những vùng đất mới.", phonetic: "/viː ˈoːkɛr ˈjɛːrna ɪˈvɛːɡ pɔː ˈhɛljˌʉːtflʏkːtɛr tɪl ˈnʏːa ˈplatːsɛr/" },
  { id: 826, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Ljuset på morgonen och kvällen är så fint att fotografera.", vi: "Ánh sáng buổi sáng và buổi chiều tối chụp ảnh đẹp lắm.", phonetic: "/ˈjʉːsɛt pɔː ˈmɔrːɔnɛn ɔ ˈkvɛlːɛn ɛːr soː fiːnt at fʊtʊɡrɑˈfeːra/" },
  { id: 827, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Det är så tyst och rofyllt här borta vid vattnet.", vi: "Ở khu vực ven nước này thật yên tĩnh và thanh bình.", phonetic: "/deːt ɛːr soː tʏst ɔ ˈrʊːˌfʏlt hɛːr ˈbɔrːta viːd ˈvatːnɛt/" },
  { id: 828, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vi tar det lugnt och njuter av resan i vårt eget tempo.", vi: "Tụi mình đi thong thả và tận hưởng chuyến đi theo nhịp của riêng mình.", phonetic: "/viː tɑːr deː lɵŋt ɔ ˈnjʉːtɛr ɑːv ˈreːsan ɪ voːʈ ˈeːɡɛt ˈtɛmːpʊ/" },
  { id: 829, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag älskar när solen tittar fram mellan molnen.", vi: "Mình thích khoảnh khắc mặt trời ló dạng giữa những đám mây.", phonetic: "/jɑːɡ ˈɛlːskar nɛːr ˈsuːlɛn ˈtɪtːar fram ˈmɛlːan ˈmuːlnɛn/" },
  { id: 830, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Att komma ut i naturen rensar tankarna.", vi: "Ra ngoài thiên nhiên giúp đầu óc thư thái hẳn.", phonetic: "/at ˈkɔmːa ʉːt ɪ nɑtʉːˈreːn ˈrɛnːsar ˈtaŋːkarːa/" },
  { id: 831, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På kvällen gillar jag att varva ner hemma med en bra film.", vi: "Buổi tối mình thích thư giãn ở nhà với một bộ phim hay.", phonetic: "/pɔː ˈkvɛlːɛn ˈjɪlːar jɑːɡ at ˈvarːva neːr ˈhɛmːa meːd ɛn brɑː fɪlm/" },
  { id: 832, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det är skönt att krypa upp i soffan efter en aktiv dag.", vi: "Thật dễ chịu khi cuộn mình trên ghế sofa sau một ngày năng động.", phonetic: "/deːt ɛːr ɕøːnt at ˈkrʏːpa ɵpː ɪ ˈsɔfːan ˈɛfːtɛr ɛn ˈakːtɪv dɑːɡ/" },
  { id: 833, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vi spelar sällskapsspel och ordlekar när vi är många.", vi: "Tụi mình chơi board game và trò nối chữ khi có đông người.", phonetic: "/viː ˈsɛlːskɑpsˌspeːl ɔ ˈuːɖˌleːkar nɛːr viː ɛːr ˈmɔŋːa/" },
  { id: 834, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det är så kul att skratta tillsammans över en spelomgång.", vi: "Cùng cười rôm rả qua một ván chơi vui thật đấy.", phonetic: "/deːt ɛːr soː kʉːl at ˈskratːa tɪlˈsamːanːs ˈøːvɛr ɛn ˈspeːlˌɔmːɡɔŋ/" },
  { id: 835, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Jag gillar att ha det städat och mysigt omkring mig.", vi: "Mình thích giữ không gian gọn gàng và ấm cúng quanh mình.", phonetic: "/jɑːɡ ˈjɪlːar at hɑː deː ˈstɛːdat ɔ ˈmʏːsɪt ɔmˈkrɪŋ mej/" },
  { id: 836, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "En varm dusch och tystnad hjälper mig att somna gott.", vi: "Một trận tắm nước ấm và sự yên tĩnh giúp mình ngủ ngon.", phonetic: "/ɛn varm dɵʃ ɔ ˈtʏsːtnɑd ˈjɛlːpɛr mej at ˈsɔmːna ɡɔt/" },
  { id: 837, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Jag tar gärna en kort paus när jag behöver samla kraft.", vi: "Mình hay nghỉ giải lao ngắn khi cần lấy lại sức.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn kɔʈ paɵs nɛːr jɑːɡ bɛˈhøːvɛr ˈsamːla krɑft/" },
  { id: 838, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vilken film eller serie tyckte du bäst om nyligen?", vi: "Gần đây bạn thích phim điện ảnh hay phim bộ nào nhất?", phonetic: "/ˈvɪlːkɛn fɪlm ˈɛlːɛr ˈseːrɪɛ ˈtʏkːtɛ dʉː bɛst ɔm ˈnʏːˌliːɡɛn/" },
  { id: 839, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vi gör en enkel fika med kaffe och frukt idag.", vi: "Hôm nay tụi mình làm bữa fika nhẹ nhàng với cà phê và trái cây.", phonetic: "/viː jøːr ɛn ˈɛŋːkɛl ˈfiːka meːd ˈkafːɛ ɔ frɵkt ɪˈdɑːɡ/" },
  { id: 840, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det känns skönt att bara vara sig själv i lugn och ro.", vi: "Thật thoải mái khi được là chính mình trong yên bình.", phonetic: "/deːt ɕɛnːs ɕøːnt at ˈbɑːra ˈvɑːra sej ɕɛlv ɪ lɵŋn ɔ rʊː/" },
  { id: 841, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Ursäkta, vet du var närmaste busshållplats ligger?", vi: "Xin lỗi, bạn có biết trạm xe buýt gần nhất ở đâu không?", phonetic: "/ˈʉːˌʂɛkːta veːt dʉː vɑːr ˈnɛrmastɛ ˈbɵsˌhɔlːplats ˈlɪɡːɛr/" },
  { id: 842, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag behöver köpa frukt, grönsaker och bröd idag.", vi: "Hôm nay mình cần mua trái cây, rau củ và bánh mì.", phonetic: "/jɑːɡ bɛˈhøːvɛr ˈɕøːpa frɵkt ˈɡrœnˌsɑːkɛr ɔ brøːd ɪˈdɑːɡ/" },
  { id: 843, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hur mycket kostar det här totalt?", vi: "Món này tổng cộng giá bao nhiêu vậy?", phonetic: "/hʉːr ˈmʏkːɛt ˈkɔsːtar deːt hɛːr tʊˈtɑlt/" },
  { id: 844, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag tar gärna en påse, tack så mycket.", vi: "Cho mình xin một túi nhé, cảm ơn bạn nhiều.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn ˈpoːsɛ tak soː ˈmʏkːɛt/" },
  { id: 845, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Det är ganska svalt ute idag, så jag tar en tröja.", vi: "Hôm nay ngoài trời khá mát nên mình mặc thêm áo len.", phonetic: "/deːt ɛːr ˈɡanːsa svɑlt ˈʉːtɛ ɪˈdɑːɡ soː jɑːɡ tɑːr ɛn ˈtrœjːa/" },
  { id: 846, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Vi åker kollektivt eller går när det inte är så långt.", vi: "Tụi mình đi phương tiện công cộng hoặc đi bộ khi không quá xa.", phonetic: "/viː ˈoːkɛr kʊlːɛkˈtiːvt ˈɛlːɛr ɡoːr nɛːr deː ˈɪnːtɛ ɛːr soː lɔŋt/" },
  { id: 847, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag sparar undan lite varje månad för framtida planer.", vi: "Mình dành dụm một chút mỗi tháng cho các kế hoạch tương lai.", phonetic: "/jɑːɡ ˈspɑːrar ˈɵnːdan ˈliːtɛ ˈvarːjɛ ˈmoːnad fœr ˈfrɑːmˌtiːda ˈplɑːnɛr/" },
  { id: 848, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Vädret växlar snabbt, så det är bra att ha paraply med.", vi: "Thời tiết đổi nhanh lắm nên mang theo ô là tốt nhất.", phonetic: "/ˈvɛːdrɛt ˈvɛkːslar snɑpt soː deːt ɛːr brɑː at hɑː pɑrɑˈplʏː meːd/" },
  { id: 849, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag gillar tydliga och enkla rutiner i vardagen.", vi: "Mình thích những thói quen rõ ràng và đơn giản trong ngày.", phonetic: "/jɑːɡ ˈjɪlːar ˈtʏːdliɡa ɔ ˈɛŋːkla rɵˈtiːnɛr ɪ ˈvɑːrˌdɑːɡɛn/" },
  { id: 850, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Varje litet steg framåt räknas.", vi: "Mỗi bước tiến nhỏ về phía trước đều đáng quý.", phonetic: "/ˈvarːjɛ ˈliːtɛt steːɡ ˈfrɑːmˌɔːt ˈrɛkːnas/" },
  { id: 851, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag pratar med vänner säger jag: God morgon! Hur har du sovit?", vi: "Khi trò chuyện với bạn bè mình nói: Chào buổi sáng! Bạn ngủ có ngon không?", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr hɑːr dʉː ˈsʊːvɪt/" },
  { id: 852, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Hemma och på fritiden säger jag: Jag vaknade tidigt idag och tog en lugn start.", vi: "Ở nhà và lúc rảnh mình nói: Hôm nay mình dậy sớm và khởi đầu thật nhẹ nhàng.", phonetic: "/jɑːɡ ˈvɑːknadɛ ˈtiːdɪt ɪˈdɑːɡ ɔ tʊːɡ ɛn lɵŋn stɑʈ/" },
  { id: 853, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag tränar svenska säger jag: Vad ska vi äta till middag ikväll?", vi: "Khi luyện tiếng Thụy Điển mình nói: Tối nay tụi mình sẽ ăn gì nhỉ?", phonetic: "/vɑːd skɑː viː ˈɛːta tɪl ˈmɪdːɑːɡ ɪˈkvɛlː/" },
  { id: 854, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "På utflykt eller promenad säger jag: Jag håller på att laga mat i köket nu.", vi: "Khi đi chơi hoặc đi dạo mình nói: Bây giờ mình đang nấu ăn trong bếp.", phonetic: "/jɑːɡ ˈhɔlːɛr pɔː at ˈlɑːɡa mɑːt ɪ ˈɕøːkɛt nʉː/" },
  { id: 855, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "I vardagen säger jag: Kan du upprepa det lite långsammare, tack?", vi: "Trong đời sống hằng ngày mình nói: Bạn lặp lại chậm hơn một chút được không, cảm ơn bạn?", phonetic: "/kan dʉː ɵpːrɛˈpɑː deː ˈliːtɛ ˈlɔŋːsamːarɛ tak/" },
  { id: 856, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag pratar med vänner säger jag: Jag förstår ungefär vad du menar, men jag övar fortfarande.", vi: "Khi trò chuyện với bạn bè mình nói: Mình hiểu đại khái ý bạn, nhưng mình vẫn đang luyện thêm.", phonetic: "/jɑːɡ fœrˈstoːr ɵnːfɛˈjɛːr vɑːd dʉː ˈmeːnar mɛn jɑːɡ ˈøːvar ˈfɔrtˌfarːandɛ/" },
  { id: 857, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Hemma och på fritiden säger jag: Det här ordet är nytt för mig. Vad betyder det?", vi: "Ở nhà và lúc rảnh mình nói: Từ này mới với mình. Nó có nghĩa là gì vậy?", phonetic: "/deːt hɛːr ˈuːɖɛt ɛːr nʏt fœr mej vɑːd bɛˈtʏːdɛr deː/" },
  { id: 858, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag tränar svenska säger jag: Jag övar på att prata svenska varje dag.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình luyện nói tiếng Thụy Điển mỗi ngày.", phonetic: "/jɑːɡ ˈøːvar pɔː at ˈprɑːta ˈsvɛnːska ˈvarːjɛ dɑːɡ/" },
  { id: 859, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "På utflykt eller promenad säger jag: Det blir lättare ju mer man pratar.", vi: "Khi đi chơi hoặc đi dạo mình nói: Càng nói nhiều thì sẽ càng dễ hơn.", phonetic: "/deːt bliːr ˈlɛtːarɛ jʉː meːr man ˈprɑːtar/" },
  { id: 860, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "I vardagen säger jag: Tack för hjälpen, det betydde mycket!", vi: "Trong đời sống hằng ngày mình nói: Cảm ơn vì đã giúp đỡ, điều đó có ý nghĩa lắm!", phonetic: "/tak fœr ˈjɛlːpɛn deː bɛˈtʏːdːɛ ˈmʏkːɛt/" },
  { id: 861, topic: "Gia đình & người thân", sv: "När jag pratar med vänner säger jag: Jag pratar med min man varje dag om framtiden.", vi: "Khi trò chuyện với bạn bè mình nói: Mình trò chuyện với chồng mỗi ngày về tương lai.", phonetic: "/jɑːɡ ˈprɑːtar meːd miːn man ˈvarːjɛ dɑːɡ ɔm ˈfrɑːmˌtiːdɛn/" },
  { id: 862, topic: "Gia đình & người thân", sv: "Hemma och på fritiden säger jag: Vi planerar vårt nya liv tillsammans i lugn takt.", vi: "Ở nhà và lúc rảnh mình nói: Tụi mình lên kế hoạch cho cuộc sống mới cùng nhau một cách chầm chậm.", phonetic: "/viː plɑˈneːrar voːʈ ˈnʏːa liːv tɪlˈsamːanːs ɪ lɵŋn tɑkt/" },
  { id: 863, topic: "Gia đình & người thân", sv: "När jag tränar svenska säger jag: Jag tänker ofta på min mormor hemma.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình thường nhớ tới bà ngoại ở nhà.", phonetic: "/jɑːɡ ˈtɛŋːkɛr ˈɔfːta pɔː miːn ˈmʊːrmʊr ˈhɛmːa/" },
  { id: 864, topic: "Gia đình & người thân", sv: "På utflykt eller promenad säger jag: Familjen betyder allt när man är långt hemifrån.", vi: "Khi đi chơi hoặc đi dạo mình nói: Gia đình có ý nghĩa tất cả khi ở xa nhà.", phonetic: "/fɑˈmiːljɛn bɛˈtʏːdɛr alːt nɛːr man ɛːr lɔŋt ˈhɛmːɪˌfroːn/" },
  { id: 865, topic: "Gia đình & người thân", sv: "I vardagen säger jag: Vi ringer videosamtal på helgen när alla är lediga.", vi: "Trong đời sống hằng ngày mình nói: Tụi mình gọi video vào cuối tuần khi ai cũng rảnh.", phonetic: "/viː ˈrɪŋːɛr ˈviːdɛʊˌsamːtɑːl pɔː ˈhɛlːjɛn nɛːr ˈalːa ɛːr ˈleːdɪɡa/" },
  { id: 866, topic: "Gia đình & người thân", sv: "När jag pratar med vänner säger jag: Han lagar god mat och stöttar mig alltid.", vi: "Khi trò chuyện với bạn bè mình nói: Anh ấy nấu ăn ngon và luôn ủng hộ mình.", phonetic: "/han ˈlɑːɡar ɡuːd mɑːt ɔ ˈstœtːar mej ˈalːtiːd/" },
  { id: 867, topic: "Gia đình & người thân", sv: "Hemma och på fritiden säger jag: Att hjälpa varandra gör vardagen enklare.", vi: "Ở nhà và lúc rảnh mình nói: Giúp đỡ lẫn nhau khiến cuộc sống hằng ngày nhẹ nhàng hơn.", phonetic: "/at ˈjɛlːpa vɑˈranːdra jøːr ˈvɑːrˌdɑːɡɛn ˈɛŋːklarɛ/" },
  { id: 868, topic: "Gia đình & người thân", sv: "När jag tränar svenska säger jag: Jag vill gärna bjuda hem familjen på middag någon gång.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình rất muốn mời gia đình đến nhà ăn tối một dịp nào đó.", phonetic: "/jɑːɡ vɪl ˈjɛːrna ˈbjʉːda hɛm fɑˈmiːljɛn pɔː ˈmɪdːɑːɡ ˈnoːɡɔn ɡɔŋ/" },
  { id: 869, topic: "Gia đình & người thân", sv: "På utflykt eller promenad säger jag: Det känns tryggt att ha någon som förstår en.", vi: "Khi đi chơi hoặc đi dạo mình nói: Thật vững tâm khi có người thấu hiểu mình.", phonetic: "/deːt ɕɛnːs trʏɡt at hɑː ˈnoːɡɔn sɔm fœrˈstoːr ɛn/" },
  { id: 870, topic: "Gia đình & người thân", sv: "I vardagen säger jag: Vi delar både glädje och små bekymmer.", vi: "Trong đời sống hằng ngày mình nói: Tụi mình chia sẻ cả niềm vui lẫn những nỗi lo nhỏ.", phonetic: "/viː ˈdeːlar ˈboːdɛ ˈɡlɛːdjɛ ɔ smoː bɛˈɕʏmːɛr/" },
  { id: 871, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag pratar med vänner säger jag: Jag gillar att ta en promenad i parken efter jobbet.", vi: "Khi trò chuyện với bạn bè mình nói: Mình thích đi dạo trong công viên sau giờ làm.", phonetic: "/jɑːɡ ˈjɪlːar at tɑː ɛn prʊmɛˈnɑːd ɪ ˈparːkɛn ˈɛfːtɛr ˈjɔbːɛt/" },
  { id: 872, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Hemma och på fritiden säger jag: Frisk luft och grönska hjälper mig att ladda om.", vi: "Ở nhà và lúc rảnh mình nói: Không khí trong lành và cây xanh giúp mình nạp lại năng lượng.", phonetic: "/frɪsk lɵft ɔ ˈɡrœnːska ˈjɛlːpɛr mej at ˈladːa ɔm/" },
  { id: 873, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag tränar svenska säger jag: Vilken vacker utsikt över sjön och skogen!", vi: "Khi luyện tiếng Thụy Điển mình nói: Khung cảnh nhìn ra hồ và rừng đẹp quá!", phonetic: "/ˈvɪlːkɛn ˈvakːɛr ˈʉːtˌsɪkːt ˈøːvɛr ɕøːn ɔ ˈskuːɡɛn/" },
  { id: 874, topic: "Thiên nhiên, đi dạo & du lịch", sv: "På utflykt eller promenad säger jag: Jag brukar ta foton på naturen när vi reser.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình hay chụp ảnh thiên nhiên khi tụi mình đi du lịch.", phonetic: "/jɑːɡ ˈbrʉːkar tɑː ˈfuːtɔn pɔː nɑtʉːˈreːn nɛːr viː ˈreːsɛr/" },
  { id: 875, topic: "Thiên nhiên, đi dạo & du lịch", sv: "I vardagen säger jag: Vi åker gärna iväg på helgutflykter till nya platser.", vi: "Trong đời sống hằng ngày mình nói: Tụi mình thích đi chơi cuối tuần tới những vùng đất mới.", phonetic: "/viː ˈoːkɛr ˈjɛːrna ɪˈvɛːɡ pɔː ˈhɛljˌʉːtflʏkːtɛr tɪl ˈnʏːa ˈplatːsɛr/" },
  { id: 876, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag pratar med vänner säger jag: Ljuset på morgonen och kvällen är så fint att fotografera.", vi: "Khi trò chuyện với bạn bè mình nói: Ánh sáng buổi sáng và buổi chiều tối chụp ảnh đẹp lắm.", phonetic: "/ˈjʉːsɛt pɔː ˈmɔrːɔnɛn ɔ ˈkvɛlːɛn ɛːr soː fiːnt at fʊtʊɡrɑˈfeːra/" },
  { id: 877, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Hemma och på fritiden säger jag: Det är så tyst och rofyllt här borta vid vattnet.", vi: "Ở nhà và lúc rảnh mình nói: Ở khu vực ven nước này thật yên tĩnh và thanh bình.", phonetic: "/deːt ɛːr soː tʏst ɔ ˈrʊːˌfʏlt hɛːr ˈbɔrːta viːd ˈvatːnɛt/" },
  { id: 878, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag tränar svenska säger jag: Vi tar det lugnt och njuter av resan i vårt eget tempo.", vi: "Khi luyện tiếng Thụy Điển mình nói: Tụi mình đi thong thả và tận hưởng chuyến đi theo nhịp của riêng mình.", phonetic: "/viː tɑːr deː lɵŋt ɔ ˈnjʉːtɛr ɑːv ˈreːsan ɪ voːʈ ˈeːɡɛt ˈtɛmːpʊ/" },
  { id: 879, topic: "Thiên nhiên, đi dạo & du lịch", sv: "På utflykt eller promenad säger jag: Jag älskar när solen tittar fram mellan molnen.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình thích khoảnh khắc mặt trời ló dạng giữa những đám mây.", phonetic: "/jɑːɡ ˈɛlːskar nɛːr ˈsuːlɛn ˈtɪtːar fram ˈmɛlːan ˈmuːlnɛn/" },
  { id: 880, topic: "Thiên nhiên, đi dạo & du lịch", sv: "I vardagen säger jag: Att komma ut i naturen rensar tankarna.", vi: "Trong đời sống hằng ngày mình nói: Ra ngoài thiên nhiên giúp đầu óc thư thái hẳn.", phonetic: "/at ˈkɔmːa ʉːt ɪ nɑtʉːˈreːn ˈrɛnːsar ˈtaŋːkarːa/" },
  { id: 881, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag pratar med vänner säger jag: På kvällen gillar jag att varva ner hemma med en bra film.", vi: "Khi trò chuyện với bạn bè mình nói: Buổi tối mình thích thư giãn ở nhà với một bộ phim hay.", phonetic: "/pɔː ˈkvɛlːɛn ˈjɪlːar jɑːɡ at ˈvarːva neːr ˈhɛmːa meːd ɛn brɑː fɪlm/" },
  { id: 882, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Hemma och på fritiden säger jag: Det är skönt att krypa upp i soffan efter en aktiv dag.", vi: "Ở nhà và lúc rảnh mình nói: Thật dễ chịu khi cuộn mình trên ghế sofa sau một ngày năng động.", phonetic: "/deːt ɛːr ɕøːnt at ˈkrʏːpa ɵpː ɪ ˈsɔfːan ˈɛfːtɛr ɛn ˈakːtɪv dɑːɡ/" },
  { id: 883, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag tränar svenska säger jag: Vi spelar sällskapsspel och ordlekar när vi är många.", vi: "Khi luyện tiếng Thụy Điển mình nói: Tụi mình chơi board game và trò nối chữ khi có đông người.", phonetic: "/viː ˈsɛlːskɑpsˌspeːl ɔ ˈuːɖˌleːkar nɛːr viː ɛːr ˈmɔŋːa/" },
  { id: 884, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På utflykt eller promenad säger jag: Det är så kul att skratta tillsammans över en spelomgång.", vi: "Khi đi chơi hoặc đi dạo mình nói: Cùng cười rôm rả qua một ván chơi vui thật đấy.", phonetic: "/deːt ɛːr soː kʉːl at ˈskratːa tɪlˈsamːanːs ˈøːvɛr ɛn ˈspeːlˌɔmːɡɔŋ/" },
  { id: 885, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "I vardagen säger jag: Jag gillar att ha det städat och mysigt omkring mig.", vi: "Trong đời sống hằng ngày mình nói: Mình thích giữ không gian gọn gàng và ấm cúng quanh mình.", phonetic: "/jɑːɡ ˈjɪlːar at hɑː deː ˈstɛːdat ɔ ˈmʏːsɪt ɔmˈkrɪŋ mej/" },
  { id: 886, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag pratar med vänner säger jag: En varm dusch och tystnad hjälper mig att somna gott.", vi: "Khi trò chuyện với bạn bè mình nói: Một trận tắm nước ấm và sự yên tĩnh giúp mình ngủ ngon.", phonetic: "/ɛn varm dɵʃ ɔ ˈtʏsːtnɑd ˈjɛlːpɛr mej at ˈsɔmːna ɡɔt/" },
  { id: 887, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Hemma och på fritiden säger jag: Jag tar gärna en kort paus när jag behöver samla kraft.", vi: "Ở nhà và lúc rảnh mình nói: Mình hay nghỉ giải lao ngắn khi cần lấy lại sức.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn kɔʈ paɵs nɛːr jɑːɡ bɛˈhøːvɛr ˈsamːla krɑft/" },
  { id: 888, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag tränar svenska säger jag: Vilken film eller serie tyckte du bäst om nyligen?", vi: "Khi luyện tiếng Thụy Điển mình nói: Gần đây bạn thích phim điện ảnh hay phim bộ nào nhất?", phonetic: "/ˈvɪlːkɛn fɪlm ˈɛlːɛr ˈseːrɪɛ ˈtʏkːtɛ dʉː bɛst ɔm ˈnʏːˌliːɡɛn/" },
  { id: 889, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På utflykt eller promenad säger jag: Vi gör en enkel fika med kaffe och frukt idag.", vi: "Khi đi chơi hoặc đi dạo mình nói: Hôm nay tụi mình làm bữa fika nhẹ nhàng với cà phê và trái cây.", phonetic: "/viː jøːr ɛn ˈɛŋːkɛl ˈfiːka meːd ˈkafːɛ ɔ frɵkt ɪˈdɑːɡ/" },
  { id: 890, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "I vardagen säger jag: Det känns skönt att bara vara sig själv i lugn och ro.", vi: "Trong đời sống hằng ngày mình nói: Thật thoải mái khi được là chính mình trong yên bình.", phonetic: "/deːt ɕɛnːs ɕøːnt at ˈbɑːra ˈvɑːra sej ɕɛlv ɪ lɵŋn ɔ rʊː/" },
  { id: 891, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag pratar med vänner säger jag: Ursäkta, vet du var närmaste busshållplats ligger?", vi: "Khi trò chuyện với bạn bè mình nói: Xin lỗi, bạn có biết trạm xe buýt gần nhất ở đâu không?", phonetic: "/ˈʉːˌʂɛkːta veːt dʉː vɑːr ˈnɛrmastɛ ˈbɵsˌhɔlːplats ˈlɪɡːɛr/" },
  { id: 892, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hemma och på fritiden säger jag: Jag behöver köpa frukt, grönsaker och bröd idag.", vi: "Ở nhà và lúc rảnh mình nói: Hôm nay mình cần mua trái cây, rau củ và bánh mì.", phonetic: "/jɑːɡ bɛˈhøːvɛr ˈɕøːpa frɵkt ˈɡrœnˌsɑːkɛr ɔ brøːd ɪˈdɑːɡ/" },
  { id: 893, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag tränar svenska säger jag: Hur mycket kostar det här totalt?", vi: "Khi luyện tiếng Thụy Điển mình nói: Món này tổng cộng giá bao nhiêu vậy?", phonetic: "/hʉːr ˈmʏkːɛt ˈkɔsːtar deːt hɛːr tʊˈtɑlt/" },
  { id: 894, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "På utflykt eller promenad säger jag: Jag tar gärna en påse, tack så mycket.", vi: "Khi đi chơi hoặc đi dạo mình nói: Cho mình xin một túi nhé, cảm ơn bạn nhiều.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn ˈpoːsɛ tak soː ˈmʏkːɛt/" },
  { id: 895, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "I vardagen säger jag: Det är ganska svalt ute idag, så jag tar en tröja.", vi: "Trong đời sống hằng ngày mình nói: Hôm nay ngoài trời khá mát nên mình mặc thêm áo len.", phonetic: "/deːt ɛːr ˈɡanːsa svɑlt ˈʉːtɛ ɪˈdɑːɡ soː jɑːɡ tɑːr ɛn ˈtrœjːa/" },
  { id: 896, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag pratar med vänner säger jag: Vi åker kollektivt eller går när det inte är så långt.", vi: "Khi trò chuyện với bạn bè mình nói: Tụi mình đi phương tiện công cộng hoặc đi bộ khi không quá xa.", phonetic: "/viː ˈoːkɛr kʊlːɛkˈtiːvt ˈɛlːɛr ɡoːr nɛːr deː ˈɪnːtɛ ɛːr soː lɔŋt/" },
  { id: 897, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hemma och på fritiden säger jag: Jag sparar undan lite varje månad för framtida planer.", vi: "Ở nhà và lúc rảnh mình nói: Mình dành dụm một chút mỗi tháng cho các kế hoạch tương lai.", phonetic: "/jɑːɡ ˈspɑːrar ˈɵnːdan ˈliːtɛ ˈvarːjɛ ˈmoːnad fœr ˈfrɑːmˌtiːda ˈplɑːnɛr/" },
  { id: 898, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag tränar svenska säger jag: Vädret växlar snabbt, så det är bra att ha paraply med.", vi: "Khi luyện tiếng Thụy Điển mình nói: Thời tiết đổi nhanh lắm nên mang theo ô là tốt nhất.", phonetic: "/ˈvɛːdrɛt ˈvɛkːslar snɑpt soː deːt ɛːr brɑː at hɑː pɑrɑˈplʏː meːd/" },
  { id: 899, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "På utflykt eller promenad säger jag: Jag gillar tydliga och enkla rutiner i vardagen.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình thích những thói quen rõ ràng và đơn giản trong ngày.", phonetic: "/jɑːɡ ˈjɪlːar ˈtʏːdliɡa ɔ ˈɛŋːkla rɵˈtiːnɛr ɪ ˈvɑːrˌdɑːɡɛn/" },
  { id: 900, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "I vardagen säger jag: Varje litet steg framåt räknas.", vi: "Trong đời sống hằng ngày mình nói: Mỗi bước tiến nhỏ về phía trước đều đáng quý.", phonetic: "/ˈvarːjɛ ˈliːtɛt steːɡ ˈfrɑːmˌɔːt ˈrɛkːnas/" },
  { id: 901, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "God morgon! Hur har du sovit? Det passar bra i många situationer.", vi: "Chào buổi sáng! Bạn ngủ có ngon không? Câu này dùng được trong nhiều tình huống.", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr hɑːr dʉː ˈsʊːvɪt/" },
  { id: 902, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag vaknade tidigt idag och tog en lugn start. Det hjälper mig att uttrycka mig klart.", vi: "Hôm nay mình dậy sớm và khởi đầu thật nhẹ nhàng. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ ˈvɑːknadɛ ˈtiːdɪt ɪˈdɑːɡ ɔ tʊːɡ ɛn lɵŋn stɑʈ/" },
  { id: 903, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Vad ska vi äta till middag ikväll? Det känns avslappnat och vardagligt.", vi: "Tối nay tụi mình sẽ ăn gì nhỉ? Nghe rất tự nhiên và gần gũi.", phonetic: "/vɑːd skɑː viː ˈɛːta tɪl ˈmɪdːɑːɡ ɪˈkvɛlː/" },
  { id: 904, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag håller på att laga mat i köket nu. Det är ett bra uttryck att kunna.", vi: "Bây giờ mình đang nấu ăn trong bếp. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈhɔlːɛr pɔː at ˈlɑːɡa mɑːt ɪ ˈɕøːkɛt nʉː/" },
  { id: 905, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Kan du upprepa det lite långsammare, tack? Jag använder det gärna i samtal.", vi: "Bạn lặp lại chậm hơn một chút được không, cảm ơn bạn? Mình thích dùng câu này khi trò chuyện.", phonetic: "/kan dʉː ɵpːrɛˈpɑː deː ˈliːtɛ ˈlɔŋːsamːarɛ tak/" },
  { id: 906, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag förstår ungefär vad du menar, men jag övar fortfarande. Det passar bra i många situationer.", vi: "Mình hiểu đại khái ý bạn, nhưng mình vẫn đang luyện thêm. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ fœrˈstoːr ɵnːfɛˈjɛːr vɑːd dʉː ˈmeːnar mɛn jɑːɡ ˈøːvar ˈfɔrtˌfarːandɛ/" },
  { id: 907, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Det här ordet är nytt för mig. Vad betyder det? Det hjälper mig att uttrycka mig klart.", vi: "Từ này mới với mình. Nó có nghĩa là gì vậy? Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/deːt hɛːr ˈuːɖɛt ɛːr nʏt fœr mej vɑːd bɛˈtʏːdɛr deː/" },
  { id: 908, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag övar på att prata svenska varje dag. Det känns avslappnat och vardagligt.", vi: "Mình luyện nói tiếng Thụy Điển mỗi ngày. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ ˈøːvar pɔː at ˈprɑːta ˈsvɛnːska ˈvarːjɛ dɑːɡ/" },
  { id: 909, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Det blir lättare ju mer man pratar. Det är ett bra uttryck att kunna.", vi: "Càng nói nhiều thì sẽ càng dễ hơn. Đây là cách diễn đạt hay nên biết.", phonetic: "/deːt bliːr ˈlɛtːarɛ jʉː meːr man ˈprɑːtar/" },
  { id: 910, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Tack för hjälpen, det betydde mycket! Jag använder det gärna i samtal.", vi: "Cảm ơn vì đã giúp đỡ, điều đó có ý nghĩa lắm! Mình thích dùng câu này khi trò chuyện.", phonetic: "/tak fœr ˈjɛlːpɛn deː bɛˈtʏːdːɛ ˈmʏkːɛt/" },
  { id: 911, topic: "Gia đình & người thân", sv: "Jag pratar med min man varje dag om framtiden. Det passar bra i många situationer.", vi: "Mình trò chuyện với chồng mỗi ngày về tương lai. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ ˈprɑːtar meːd miːn man ˈvarːjɛ dɑːɡ ɔm ˈfrɑːmˌtiːdɛn/" },
  { id: 912, topic: "Gia đình & người thân", sv: "Vi planerar vårt nya liv tillsammans i lugn takt. Det hjälper mig att uttrycka mig klart.", vi: "Tụi mình lên kế hoạch cho cuộc sống mới cùng nhau một cách chầm chậm. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/viː plɑˈneːrar voːʈ ˈnʏːa liːv tɪlˈsamːanːs ɪ lɵŋn tɑkt/" },
  { id: 913, topic: "Gia đình & người thân", sv: "Jag tänker ofta på min mormor hemma. Det känns avslappnat och vardagligt.", vi: "Mình thường nhớ tới bà ngoại ở nhà. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ ˈtɛŋːkɛr ˈɔfːta pɔː miːn ˈmʊːrmʊr ˈhɛmːa/" },
  { id: 914, topic: "Gia đình & người thân", sv: "Familjen betyder allt när man är långt hemifrån. Det är ett bra uttryck att kunna.", vi: "Gia đình có ý nghĩa tất cả khi ở xa nhà. Đây là cách diễn đạt hay nên biết.", phonetic: "/fɑˈmiːljɛn bɛˈtʏːdɛr alːt nɛːr man ɛːr lɔŋt ˈhɛmːɪˌfroːn/" },
  { id: 915, topic: "Gia đình & người thân", sv: "Vi ringer videosamtal på helgen när alla är lediga. Jag använder det gärna i samtal.", vi: "Tụi mình gọi video vào cuối tuần khi ai cũng rảnh. Mình thích dùng câu này khi trò chuyện.", phonetic: "/viː ˈrɪŋːɛr ˈviːdɛʊˌsamːtɑːl pɔː ˈhɛlːjɛn nɛːr ˈalːa ɛːr ˈleːdɪɡa/" },
  { id: 916, topic: "Gia đình & người thân", sv: "Han lagar god mat och stöttar mig alltid. Det passar bra i många situationer.", vi: "Anh ấy nấu ăn ngon và luôn ủng hộ mình. Câu này dùng được trong nhiều tình huống.", phonetic: "/han ˈlɑːɡar ɡuːd mɑːt ɔ ˈstœtːar mej ˈalːtiːd/" },
  { id: 917, topic: "Gia đình & người thân", sv: "Att hjälpa varandra gör vardagen enklare. Det hjälper mig att uttrycka mig klart.", vi: "Giúp đỡ lẫn nhau khiến cuộc sống hằng ngày nhẹ nhàng hơn. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/at ˈjɛlːpa vɑˈranːdra jøːr ˈvɑːrˌdɑːɡɛn ˈɛŋːklarɛ/" },
  { id: 918, topic: "Gia đình & người thân", sv: "Jag vill gärna bjuda hem familjen på middag någon gång. Det känns avslappnat och vardagligt.", vi: "Mình rất muốn mời gia đình đến nhà ăn tối một dịp nào đó. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ vɪl ˈjɛːrna ˈbjʉːda hɛm fɑˈmiːljɛn pɔː ˈmɪdːɑːɡ ˈnoːɡɔn ɡɔŋ/" },
  { id: 919, topic: "Gia đình & người thân", sv: "Det känns tryggt att ha någon som förstår en. Det är ett bra uttryck att kunna.", vi: "Thật vững tâm khi có người thấu hiểu mình. Đây là cách diễn đạt hay nên biết.", phonetic: "/deːt ɕɛnːs trʏɡt at hɑː ˈnoːɡɔn sɔm fœrˈstoːr ɛn/" },
  { id: 920, topic: "Gia đình & người thân", sv: "Vi delar både glädje och små bekymmer. Jag använder det gärna i samtal.", vi: "Tụi mình chia sẻ cả niềm vui lẫn những nỗi lo nhỏ. Mình thích dùng câu này khi trò chuyện.", phonetic: "/viː ˈdeːlar ˈboːdɛ ˈɡlɛːdjɛ ɔ smoː bɛˈɕʏmːɛr/" },
  { id: 921, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag gillar att ta en promenad i parken efter jobbet. Det passar bra i många situationer.", vi: "Mình thích đi dạo trong công viên sau giờ làm. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ ˈjɪlːar at tɑː ɛn prʊmɛˈnɑːd ɪ ˈparːkɛn ˈɛfːtɛr ˈjɔbːɛt/" },
  { id: 922, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Frisk luft och grönska hjälper mig att ladda om. Det hjälper mig att uttrycka mig klart.", vi: "Không khí trong lành và cây xanh giúp mình nạp lại năng lượng. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/frɪsk lɵft ɔ ˈɡrœnːska ˈjɛlːpɛr mej at ˈladːa ɔm/" },
  { id: 923, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vilken vacker utsikt över sjön och skogen! Det känns avslappnat och vardagligt.", vi: "Khung cảnh nhìn ra hồ và rừng đẹp quá! Nghe rất tự nhiên và gần gũi.", phonetic: "/ˈvɪlːkɛn ˈvakːɛr ˈʉːtˌsɪkːt ˈøːvɛr ɕøːn ɔ ˈskuːɡɛn/" },
  { id: 924, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag brukar ta foton på naturen när vi reser. Det är ett bra uttryck att kunna.", vi: "Mình hay chụp ảnh thiên nhiên khi tụi mình đi du lịch. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈbrʉːkar tɑː ˈfuːtɔn pɔː nɑtʉːˈreːn nɛːr viː ˈreːsɛr/" },
  { id: 925, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vi åker gärna iväg på helgutflykter till nya platser. Jag använder det gärna i samtal.", vi: "Tụi mình thích đi chơi cuối tuần tới những vùng đất mới. Mình thích dùng câu này khi trò chuyện.", phonetic: "/viː ˈoːkɛr ˈjɛːrna ɪˈvɛːɡ pɔː ˈhɛljˌʉːtflʏkːtɛr tɪl ˈnʏːa ˈplatːsɛr/" },
  { id: 926, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Ljuset på morgonen och kvällen är så fint att fotografera. Det passar bra i många situationer.", vi: "Ánh sáng buổi sáng và buổi chiều tối chụp ảnh đẹp lắm. Câu này dùng được trong nhiều tình huống.", phonetic: "/ˈjʉːsɛt pɔː ˈmɔrːɔnɛn ɔ ˈkvɛlːɛn ɛːr soː fiːnt at fʊtʊɡrɑˈfeːra/" },
  { id: 927, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Det är så tyst och rofyllt här borta vid vattnet. Det hjälper mig att uttrycka mig klart.", vi: "Ở khu vực ven nước này thật yên tĩnh và thanh bình. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/deːt ɛːr soː tʏst ɔ ˈrʊːˌfʏlt hɛːr ˈbɔrːta viːd ˈvatːnɛt/" },
  { id: 928, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vi tar det lugnt och njuter av resan i vårt eget tempo. Det känns avslappnat och vardagligt.", vi: "Tụi mình đi thong thả và tận hưởng chuyến đi theo nhịp của riêng mình. Nghe rất tự nhiên và gần gũi.", phonetic: "/viː tɑːr deː lɵŋt ɔ ˈnjʉːtɛr ɑːv ˈreːsan ɪ voːʈ ˈeːɡɛt ˈtɛmːpʊ/" },
  { id: 929, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag älskar när solen tittar fram mellan molnen. Det är ett bra uttryck att kunna.", vi: "Mình thích khoảnh khắc mặt trời ló dạng giữa những đám mây. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈɛlːskar nɛːr ˈsuːlɛn ˈtɪtːar fram ˈmɛlːan ˈmuːlnɛn/" },
  { id: 930, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Att komma ut i naturen rensar tankarna. Jag använder det gärna i samtal.", vi: "Ra ngoài thiên nhiên giúp đầu óc thư thái hẳn. Mình thích dùng câu này khi trò chuyện.", phonetic: "/at ˈkɔmːa ʉːt ɪ nɑtʉːˈreːn ˈrɛnːsar ˈtaŋːkarːa/" },
  { id: 931, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På kvällen gillar jag att varva ner hemma med en bra film. Det passar bra i många situationer.", vi: "Buổi tối mình thích thư giãn ở nhà với một bộ phim hay. Câu này dùng được trong nhiều tình huống.", phonetic: "/pɔː ˈkvɛlːɛn ˈjɪlːar jɑːɡ at ˈvarːva neːr ˈhɛmːa meːd ɛn brɑː fɪlm/" },
  { id: 932, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det är skönt att krypa upp i soffan efter en aktiv dag. Det hjälper mig att uttrycka mig klart.", vi: "Thật dễ chịu khi cuộn mình trên ghế sofa sau một ngày năng động. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/deːt ɛːr ɕøːnt at ˈkrʏːpa ɵpː ɪ ˈsɔfːan ˈɛfːtɛr ɛn ˈakːtɪv dɑːɡ/" },
  { id: 933, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vi spelar sällskapsspel och ordlekar när vi är många. Det känns avslappnat och vardagligt.", vi: "Tụi mình chơi board game và trò nối chữ khi có đông người. Nghe rất tự nhiên và gần gũi.", phonetic: "/viː ˈsɛlːskɑpsˌspeːl ɔ ˈuːɖˌleːkar nɛːr viː ɛːr ˈmɔŋːa/" },
  { id: 934, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det är så kul att skratta tillsammans över en spelomgång. Det är ett bra uttryck att kunna.", vi: "Cùng cười rôm rả qua một ván chơi vui thật đấy. Đây là cách diễn đạt hay nên biết.", phonetic: "/deːt ɛːr soː kʉːl at ˈskratːa tɪlˈsamːanːs ˈøːvɛr ɛn ˈspeːlˌɔmːɡɔŋ/" },
  { id: 935, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Jag gillar att ha det städat och mysigt omkring mig. Jag använder det gärna i samtal.", vi: "Mình thích giữ không gian gọn gàng và ấm cúng quanh mình. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ ˈjɪlːar at hɑː deː ˈstɛːdat ɔ ˈmʏːsɪt ɔmˈkrɪŋ mej/" },
  { id: 936, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "En varm dusch och tystnad hjälper mig att somna gott. Det passar bra i många situationer.", vi: "Một trận tắm nước ấm và sự yên tĩnh giúp mình ngủ ngon. Câu này dùng được trong nhiều tình huống.", phonetic: "/ɛn varm dɵʃ ɔ ˈtʏsːtnɑd ˈjɛlːpɛr mej at ˈsɔmːna ɡɔt/" },
  { id: 937, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Jag tar gärna en kort paus när jag behöver samla kraft. Det hjälper mig att uttrycka mig klart.", vi: "Mình hay nghỉ giải lao ngắn khi cần lấy lại sức. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn kɔʈ paɵs nɛːr jɑːɡ bɛˈhøːvɛr ˈsamːla krɑft/" },
  { id: 938, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vilken film eller serie tyckte du bäst om nyligen? Det känns avslappnat och vardagligt.", vi: "Gần đây bạn thích phim điện ảnh hay phim bộ nào nhất? Nghe rất tự nhiên và gần gũi.", phonetic: "/ˈvɪlːkɛn fɪlm ˈɛlːɛr ˈseːrɪɛ ˈtʏkːtɛ dʉː bɛst ɔm ˈnʏːˌliːɡɛn/" },
  { id: 939, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vi gör en enkel fika med kaffe och frukt idag. Det är ett bra uttryck att kunna.", vi: "Hôm nay tụi mình làm bữa fika nhẹ nhàng với cà phê và trái cây. Đây là cách diễn đạt hay nên biết.", phonetic: "/viː jøːr ɛn ˈɛŋːkɛl ˈfiːka meːd ˈkafːɛ ɔ frɵkt ɪˈdɑːɡ/" },
  { id: 940, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det känns skönt att bara vara sig själv i lugn och ro. Jag använder det gärna i samtal.", vi: "Thật thoải mái khi được là chính mình trong yên bình. Mình thích dùng câu này khi trò chuyện.", phonetic: "/deːt ɕɛnːs ɕøːnt at ˈbɑːra ˈvɑːra sej ɕɛlv ɪ lɵŋn ɔ rʊː/" },
  { id: 941, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Ursäkta, vet du var närmaste busshållplats ligger? Det passar bra i många situationer.", vi: "Xin lỗi, bạn có biết trạm xe buýt gần nhất ở đâu không? Câu này dùng được trong nhiều tình huống.", phonetic: "/ˈʉːˌʂɛkːta veːt dʉː vɑːr ˈnɛrmastɛ ˈbɵsˌhɔlːplats ˈlɪɡːɛr/" },
  { id: 942, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag behöver köpa frukt, grönsaker och bröd idag. Det hjälper mig att uttrycka mig klart.", vi: "Hôm nay mình cần mua trái cây, rau củ và bánh mì. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ bɛˈhøːvɛr ˈɕøːpa frɵkt ˈɡrœnˌsɑːkɛr ɔ brøːd ɪˈdɑːɡ/" },
  { id: 943, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hur mycket kostar det här totalt? Det känns avslappnat och vardagligt.", vi: "Món này tổng cộng giá bao nhiêu vậy? Nghe rất tự nhiên và gần gũi.", phonetic: "/hʉːr ˈmʏkːɛt ˈkɔsːtar deːt hɛːr tʊˈtɑlt/" },
  { id: 944, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag tar gärna en påse, tack så mycket. Det är ett bra uttryck att kunna.", vi: "Cho mình xin một túi nhé, cảm ơn bạn nhiều. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn ˈpoːsɛ tak soː ˈmʏkːɛt/" },
  { id: 945, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Det är ganska svalt ute idag, så jag tar en tröja. Jag använder det gärna i samtal.", vi: "Hôm nay ngoài trời khá mát nên mình mặc thêm áo len. Mình thích dùng câu này khi trò chuyện.", phonetic: "/deːt ɛːr ˈɡanːsa svɑlt ˈʉːtɛ ɪˈdɑːɡ soː jɑːɡ tɑːr ɛn ˈtrœjːa/" },
  { id: 946, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Vi åker kollektivt eller går när det inte är så långt. Det passar bra i många situationer.", vi: "Tụi mình đi phương tiện công cộng hoặc đi bộ khi không quá xa. Câu này dùng được trong nhiều tình huống.", phonetic: "/viː ˈoːkɛr kʊlːɛkˈtiːvt ˈɛlːɛr ɡoːr nɛːr deː ˈɪnːtɛ ɛːr soː lɔŋt/" },
  { id: 947, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag sparar undan lite varje månad för framtida planer. Det hjälper mig att uttrycka mig klart.", vi: "Mình dành dụm một chút mỗi tháng cho các kế hoạch tương lai. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ ˈspɑːrar ˈɵnːdan ˈliːtɛ ˈvarːjɛ ˈmoːnad fœr ˈfrɑːmˌtiːda ˈplɑːnɛr/" },
  { id: 948, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Vädret växlar snabbt, så det är bra att ha paraply med. Det känns avslappnat och vardagligt.", vi: "Thời tiết đổi nhanh lắm nên mang theo ô là tốt nhất. Nghe rất tự nhiên và gần gũi.", phonetic: "/ˈvɛːdrɛt ˈvɛkːslar snɑpt soː deːt ɛːr brɑː at hɑː pɑrɑˈplʏː meːd/" },
  { id: 949, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag gillar tydliga och enkla rutiner i vardagen. Det är ett bra uttryck att kunna.", vi: "Mình thích những thói quen rõ ràng và đơn giản trong ngày. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈjɪlːar ˈtʏːdliɡa ɔ ˈɛŋːkla rɵˈtiːnɛr ɪ ˈvɑːrˌdɑːɡɛn/" },
  { id: 950, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Varje litet steg framåt räknas. Jag använder det gärna i samtal.", vi: "Mỗi bước tiến nhỏ về phía trước đều đáng quý. Mình thích dùng câu này khi trò chuyện.", phonetic: "/ˈvarːjɛ ˈliːtɛt steːɡ ˈfrɑːmˌɔːt ˈrɛkːnas/" },
  { id: 951, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag tränar svenska säger jag: God morgon! Hur har du sovit?", vi: "Khi luyện tiếng Thụy Điển mình nói: Chào buổi sáng! Bạn ngủ có ngon không?", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr hɑːr dʉː ˈsʊːvɪt/" },
  { id: 952, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "På utflykt eller promenad säger jag: Jag vaknade tidigt idag och tog en lugn start.", vi: "Khi đi chơi hoặc đi dạo mình nói: Hôm nay mình dậy sớm và khởi đầu thật nhẹ nhàng.", phonetic: "/jɑːɡ ˈvɑːknadɛ ˈtiːdɪt ɪˈdɑːɡ ɔ tʊːɡ ɛn lɵŋn stɑʈ/" },
  { id: 953, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "I vardagen säger jag: Vad ska vi äta till middag ikväll?", vi: "Trong đời sống hằng ngày mình nói: Tối nay tụi mình sẽ ăn gì nhỉ?", phonetic: "/vɑːd skɑː viː ˈɛːta tɪl ˈmɪdːɑːɡ ɪˈkvɛlː/" },
  { id: 954, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag pratar med vänner säger jag: Jag håller på att laga mat i köket nu.", vi: "Khi trò chuyện với bạn bè mình nói: Bây giờ mình đang nấu ăn trong bếp.", phonetic: "/jɑːɡ ˈhɔlːɛr pɔː at ˈlɑːɡa mɑːt ɪ ˈɕøːkɛt nʉː/" },
  { id: 955, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Hemma och på fritiden säger jag: Kan du upprepa det lite långsammare, tack?", vi: "Ở nhà và lúc rảnh mình nói: Bạn lặp lại chậm hơn một chút được không, cảm ơn bạn?", phonetic: "/kan dʉː ɵpːrɛˈpɑː deː ˈliːtɛ ˈlɔŋːsamːarɛ tak/" },
  { id: 956, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag tränar svenska säger jag: Jag förstår ungefär vad du menar, men jag övar fortfarande.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình hiểu đại khái ý bạn, nhưng mình vẫn đang luyện thêm.", phonetic: "/jɑːɡ fœrˈstoːr ɵnːfɛˈjɛːr vɑːd dʉː ˈmeːnar mɛn jɑːɡ ˈøːvar ˈfɔrtˌfarːandɛ/" },
  { id: 957, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "På utflykt eller promenad säger jag: Det här ordet är nytt för mig. Vad betyder det?", vi: "Khi đi chơi hoặc đi dạo mình nói: Từ này mới với mình. Nó có nghĩa là gì vậy?", phonetic: "/deːt hɛːr ˈuːɖɛt ɛːr nʏt fœr mej vɑːd bɛˈtʏːdɛr deː/" },
  { id: 958, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "I vardagen säger jag: Jag övar på att prata svenska varje dag.", vi: "Trong đời sống hằng ngày mình nói: Mình luyện nói tiếng Thụy Điển mỗi ngày.", phonetic: "/jɑːɡ ˈøːvar pɔː at ˈprɑːta ˈsvɛnːska ˈvarːjɛ dɑːɡ/" },
  { id: 959, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag pratar med vänner säger jag: Det blir lättare ju mer man pratar.", vi: "Khi trò chuyện với bạn bè mình nói: Càng nói nhiều thì sẽ càng dễ hơn.", phonetic: "/deːt bliːr ˈlɛtːarɛ jʉː meːr man ˈprɑːtar/" },
  { id: 960, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Hemma och på fritiden säger jag: Tack för hjälpen, det betydde mycket!", vi: "Ở nhà và lúc rảnh mình nói: Cảm ơn vì đã giúp đỡ, điều đó có ý nghĩa lắm!", phonetic: "/tak fœr ˈjɛlːpɛn deː bɛˈtʏːdːɛ ˈmʏkːɛt/" },
  { id: 961, topic: "Gia đình & người thân", sv: "När jag tränar svenska säger jag: Jag pratar med min man varje dag om framtiden.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình trò chuyện với chồng mỗi ngày về tương lai.", phonetic: "/jɑːɡ ˈprɑːtar meːd miːn man ˈvarːjɛ dɑːɡ ɔm ˈfrɑːmˌtiːdɛn/" },
  { id: 962, topic: "Gia đình & người thân", sv: "På utflykt eller promenad säger jag: Vi planerar vårt nya liv tillsammans i lugn takt.", vi: "Khi đi chơi hoặc đi dạo mình nói: Tụi mình lên kế hoạch cho cuộc sống mới cùng nhau một cách chầm chậm.", phonetic: "/viː plɑˈneːrar voːʈ ˈnʏːa liːv tɪlˈsamːanːs ɪ lɵŋn tɑkt/" },
  { id: 963, topic: "Gia đình & người thân", sv: "I vardagen säger jag: Jag tänker ofta på min mormor hemma.", vi: "Trong đời sống hằng ngày mình nói: Mình thường nhớ tới bà ngoại ở nhà.", phonetic: "/jɑːɡ ˈtɛŋːkɛr ˈɔfːta pɔː miːn ˈmʊːrmʊr ˈhɛmːa/" },
  { id: 964, topic: "Gia đình & người thân", sv: "När jag pratar med vänner säger jag: Familjen betyder allt när man är långt hemifrån.", vi: "Khi trò chuyện với bạn bè mình nói: Gia đình có ý nghĩa tất cả khi ở xa nhà.", phonetic: "/fɑˈmiːljɛn bɛˈtʏːdɛr alːt nɛːr man ɛːr lɔŋt ˈhɛmːɪˌfroːn/" },
  { id: 965, topic: "Gia đình & người thân", sv: "Hemma och på fritiden säger jag: Vi ringer videosamtal på helgen när alla är lediga.", vi: "Ở nhà và lúc rảnh mình nói: Tụi mình gọi video vào cuối tuần khi ai cũng rảnh.", phonetic: "/viː ˈrɪŋːɛr ˈviːdɛʊˌsamːtɑːl pɔː ˈhɛlːjɛn nɛːr ˈalːa ɛːr ˈleːdɪɡa/" },
  { id: 966, topic: "Gia đình & người thân", sv: "När jag tränar svenska säger jag: Han lagar god mat och stöttar mig alltid.", vi: "Khi luyện tiếng Thụy Điển mình nói: Anh ấy nấu ăn ngon và luôn ủng hộ mình.", phonetic: "/han ˈlɑːɡar ɡuːd mɑːt ɔ ˈstœtːar mej ˈalːtiːd/" },
  { id: 967, topic: "Gia đình & người thân", sv: "På utflykt eller promenad säger jag: Att hjälpa varandra gör vardagen enklare.", vi: "Khi đi chơi hoặc đi dạo mình nói: Giúp đỡ lẫn nhau khiến cuộc sống hằng ngày nhẹ nhàng hơn.", phonetic: "/at ˈjɛlːpa vɑˈranːdra jøːr ˈvɑːrˌdɑːɡɛn ˈɛŋːklarɛ/" },
  { id: 968, topic: "Gia đình & người thân", sv: "I vardagen säger jag: Jag vill gärna bjuda hem familjen på middag någon gång.", vi: "Trong đời sống hằng ngày mình nói: Mình rất muốn mời gia đình đến nhà ăn tối một dịp nào đó.", phonetic: "/jɑːɡ vɪl ˈjɛːrna ˈbjʉːda hɛm fɑˈmiːljɛn pɔː ˈmɪdːɑːɡ ˈnoːɡɔn ɡɔŋ/" },
  { id: 969, topic: "Gia đình & người thân", sv: "När jag pratar med vänner säger jag: Det känns tryggt att ha någon som förstår en.", vi: "Khi trò chuyện với bạn bè mình nói: Thật vững tâm khi có người thấu hiểu mình.", phonetic: "/deːt ɕɛnːs trʏɡt at hɑː ˈnoːɡɔn sɔm fœrˈstoːr ɛn/" },
  { id: 970, topic: "Gia đình & người thân", sv: "Hemma och på fritiden säger jag: Vi delar både glädje och små bekymmer.", vi: "Ở nhà và lúc rảnh mình nói: Tụi mình chia sẻ cả niềm vui lẫn những nỗi lo nhỏ.", phonetic: "/viː ˈdeːlar ˈboːdɛ ˈɡlɛːdjɛ ɔ smoː bɛˈɕʏmːɛr/" },
  { id: 971, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag tränar svenska säger jag: Jag gillar att ta en promenad i parken efter jobbet.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình thích đi dạo trong công viên sau giờ làm.", phonetic: "/jɑːɡ ˈjɪlːar at tɑː ɛn prʊmɛˈnɑːd ɪ ˈparːkɛn ˈɛfːtɛr ˈjɔbːɛt/" },
  { id: 972, topic: "Thiên nhiên, đi dạo & du lịch", sv: "På utflykt eller promenad säger jag: Frisk luft och grönska hjälper mig att ladda om.", vi: "Khi đi chơi hoặc đi dạo mình nói: Không khí trong lành và cây xanh giúp mình nạp lại năng lượng.", phonetic: "/frɪsk lɵft ɔ ˈɡrœnːska ˈjɛlːpɛr mej at ˈladːa ɔm/" },
  { id: 973, topic: "Thiên nhiên, đi dạo & du lịch", sv: "I vardagen säger jag: Vilken vacker utsikt över sjön och skogen!", vi: "Trong đời sống hằng ngày mình nói: Khung cảnh nhìn ra hồ và rừng đẹp quá!", phonetic: "/ˈvɪlːkɛn ˈvakːɛr ˈʉːtˌsɪkːt ˈøːvɛr ɕøːn ɔ ˈskuːɡɛn/" },
  { id: 974, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag pratar med vänner säger jag: Jag brukar ta foton på naturen när vi reser.", vi: "Khi trò chuyện với bạn bè mình nói: Mình hay chụp ảnh thiên nhiên khi tụi mình đi du lịch.", phonetic: "/jɑːɡ ˈbrʉːkar tɑː ˈfuːtɔn pɔː nɑtʉːˈreːn nɛːr viː ˈreːsɛr/" },
  { id: 975, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Hemma och på fritiden säger jag: Vi åker gärna iväg på helgutflykter till nya platser.", vi: "Ở nhà và lúc rảnh mình nói: Tụi mình thích đi chơi cuối tuần tới những vùng đất mới.", phonetic: "/viː ˈoːkɛr ˈjɛːrna ɪˈvɛːɡ pɔː ˈhɛljˌʉːtflʏkːtɛr tɪl ˈnʏːa ˈplatːsɛr/" },
  { id: 976, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag tränar svenska säger jag: Ljuset på morgonen och kvällen är så fint att fotografera.", vi: "Khi luyện tiếng Thụy Điển mình nói: Ánh sáng buổi sáng và buổi chiều tối chụp ảnh đẹp lắm.", phonetic: "/ˈjʉːsɛt pɔː ˈmɔrːɔnɛn ɔ ˈkvɛlːɛn ɛːr soː fiːnt at fʊtʊɡrɑˈfeːra/" },
  { id: 977, topic: "Thiên nhiên, đi dạo & du lịch", sv: "På utflykt eller promenad säger jag: Det är så tyst och rofyllt här borta vid vattnet.", vi: "Khi đi chơi hoặc đi dạo mình nói: Ở khu vực ven nước này thật yên tĩnh và thanh bình.", phonetic: "/deːt ɛːr soː tʏst ɔ ˈrʊːˌfʏlt hɛːr ˈbɔrːta viːd ˈvatːnɛt/" },
  { id: 978, topic: "Thiên nhiên, đi dạo & du lịch", sv: "I vardagen säger jag: Vi tar det lugnt och njuter av resan i vårt eget tempo.", vi: "Trong đời sống hằng ngày mình nói: Tụi mình đi thong thả và tận hưởng chuyến đi theo nhịp của riêng mình.", phonetic: "/viː tɑːr deː lɵŋt ɔ ˈnjʉːtɛr ɑːv ˈreːsan ɪ voːʈ ˈeːɡɛt ˈtɛmːpʊ/" },
  { id: 979, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag pratar med vänner säger jag: Jag älskar när solen tittar fram mellan molnen.", vi: "Khi trò chuyện với bạn bè mình nói: Mình thích khoảnh khắc mặt trời ló dạng giữa những đám mây.", phonetic: "/jɑːɡ ˈɛlːskar nɛːr ˈsuːlɛn ˈtɪtːar fram ˈmɛlːan ˈmuːlnɛn/" },
  { id: 980, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Hemma och på fritiden säger jag: Att komma ut i naturen rensar tankarna.", vi: "Ở nhà và lúc rảnh mình nói: Ra ngoài thiên nhiên giúp đầu óc thư thái hẳn.", phonetic: "/at ˈkɔmːa ʉːt ɪ nɑtʉːˈreːn ˈrɛnːsar ˈtaŋːkarːa/" },
  { id: 981, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag tränar svenska säger jag: På kvällen gillar jag att varva ner hemma med en bra film.", vi: "Khi luyện tiếng Thụy Điển mình nói: Buổi tối mình thích thư giãn ở nhà với một bộ phim hay.", phonetic: "/pɔː ˈkvɛlːɛn ˈjɪlːar jɑːɡ at ˈvarːva neːr ˈhɛmːa meːd ɛn brɑː fɪlm/" },
  { id: 982, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På utflykt eller promenad säger jag: Det är skönt att krypa upp i soffan efter en aktiv dag.", vi: "Khi đi chơi hoặc đi dạo mình nói: Thật dễ chịu khi cuộn mình trên ghế sofa sau một ngày năng động.", phonetic: "/deːt ɛːr ɕøːnt at ˈkrʏːpa ɵpː ɪ ˈsɔfːan ˈɛfːtɛr ɛn ˈakːtɪv dɑːɡ/" },
  { id: 983, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "I vardagen säger jag: Vi spelar sällskapsspel och ordlekar när vi är många.", vi: "Trong đời sống hằng ngày mình nói: Tụi mình chơi board game và trò nối chữ khi có đông người.", phonetic: "/viː ˈsɛlːskɑpsˌspeːl ɔ ˈuːɖˌleːkar nɛːr viː ɛːr ˈmɔŋːa/" },
  { id: 984, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag pratar med vänner säger jag: Det är så kul att skratta tillsammans över en spelomgång.", vi: "Khi trò chuyện với bạn bè mình nói: Cùng cười rôm rả qua một ván chơi vui thật đấy.", phonetic: "/deːt ɛːr soː kʉːl at ˈskratːa tɪlˈsamːanːs ˈøːvɛr ɛn ˈspeːlˌɔmːɡɔŋ/" },
  { id: 985, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Hemma och på fritiden säger jag: Jag gillar att ha det städat och mysigt omkring mig.", vi: "Ở nhà và lúc rảnh mình nói: Mình thích giữ không gian gọn gàng và ấm cúng quanh mình.", phonetic: "/jɑːɡ ˈjɪlːar at hɑː deː ˈstɛːdat ɔ ˈmʏːsɪt ɔmˈkrɪŋ mej/" },
  { id: 986, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag tränar svenska säger jag: En varm dusch och tystnad hjälper mig att somna gott.", vi: "Khi luyện tiếng Thụy Điển mình nói: Một trận tắm nước ấm và sự yên tĩnh giúp mình ngủ ngon.", phonetic: "/ɛn varm dɵʃ ɔ ˈtʏsːtnɑd ˈjɛlːpɛr mej at ˈsɔmːna ɡɔt/" },
  { id: 987, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På utflykt eller promenad säger jag: Jag tar gärna en kort paus när jag behöver samla kraft.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình hay nghỉ giải lao ngắn khi cần lấy lại sức.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn kɔʈ paɵs nɛːr jɑːɡ bɛˈhøːvɛr ˈsamːla krɑft/" },
  { id: 988, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "I vardagen säger jag: Vilken film eller serie tyckte du bäst om nyligen?", vi: "Trong đời sống hằng ngày mình nói: Gần đây bạn thích phim điện ảnh hay phim bộ nào nhất?", phonetic: "/ˈvɪlːkɛn fɪlm ˈɛlːɛr ˈseːrɪɛ ˈtʏkːtɛ dʉː bɛst ɔm ˈnʏːˌliːɡɛn/" },
  { id: 989, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag pratar med vänner säger jag: Vi gör en enkel fika med kaffe och frukt idag.", vi: "Khi trò chuyện với bạn bè mình nói: Hôm nay tụi mình làm bữa fika nhẹ nhàng với cà phê và trái cây.", phonetic: "/viː jøːr ɛn ˈɛŋːkɛl ˈfiːka meːd ˈkafːɛ ɔ frɵkt ɪˈdɑːɡ/" },
  { id: 990, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Hemma och på fritiden säger jag: Det känns skönt att bara vara sig själv i lugn och ro.", vi: "Ở nhà và lúc rảnh mình nói: Thật thoải mái khi được là chính mình trong yên bình.", phonetic: "/deːt ɕɛnːs ɕøːnt at ˈbɑːra ˈvɑːra sej ɕɛlv ɪ lɵŋn ɔ rʊː/" },
  { id: 991, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag tränar svenska säger jag: Ursäkta, vet du var närmaste busshållplats ligger?", vi: "Khi luyện tiếng Thụy Điển mình nói: Xin lỗi, bạn có biết trạm xe buýt gần nhất ở đâu không?", phonetic: "/ˈʉːˌʂɛkːta veːt dʉː vɑːr ˈnɛrmastɛ ˈbɵsˌhɔlːplats ˈlɪɡːɛr/" },
  { id: 992, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "På utflykt eller promenad säger jag: Jag behöver köpa frukt, grönsaker och bröd idag.", vi: "Khi đi chơi hoặc đi dạo mình nói: Hôm nay mình cần mua trái cây, rau củ và bánh mì.", phonetic: "/jɑːɡ bɛˈhøːvɛr ˈɕøːpa frɵkt ˈɡrœnˌsɑːkɛr ɔ brøːd ɪˈdɑːɡ/" },
  { id: 993, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "I vardagen säger jag: Hur mycket kostar det här totalt?", vi: "Trong đời sống hằng ngày mình nói: Món này tổng cộng giá bao nhiêu vậy?", phonetic: "/hʉːr ˈmʏkːɛt ˈkɔsːtar deːt hɛːr tʊˈtɑlt/" },
  { id: 994, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag pratar med vänner säger jag: Jag tar gärna en påse, tack så mycket.", vi: "Khi trò chuyện với bạn bè mình nói: Cho mình xin một túi nhé, cảm ơn bạn nhiều.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn ˈpoːsɛ tak soː ˈmʏkːɛt/" },
  { id: 995, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hemma och på fritiden säger jag: Det är ganska svalt ute idag, så jag tar en tröja.", vi: "Ở nhà và lúc rảnh mình nói: Hôm nay ngoài trời khá mát nên mình mặc thêm áo len.", phonetic: "/deːt ɛːr ˈɡanːsa svɑlt ˈʉːtɛ ɪˈdɑːɡ soː jɑːɡ tɑːr ɛn ˈtrœjːa/" },
  { id: 996, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag tränar svenska säger jag: Vi åker kollektivt eller går när det inte är så långt.", vi: "Khi luyện tiếng Thụy Điển mình nói: Tụi mình đi phương tiện công cộng hoặc đi bộ khi không quá xa.", phonetic: "/viː ˈoːkɛr kʊlːɛkˈtiːvt ˈɛlːɛr ɡoːr nɛːr deː ˈɪnːtɛ ɛːr soː lɔŋt/" },
  { id: 997, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "På utflykt eller promenad säger jag: Jag sparar undan lite varje månad för framtida planer.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình dành dụm một chút mỗi tháng cho các kế hoạch tương lai.", phonetic: "/jɑːɡ ˈspɑːrar ˈɵnːdan ˈliːtɛ ˈvarːjɛ ˈmoːnad fœr ˈfrɑːmˌtiːda ˈplɑːnɛr/" },
  { id: 998, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "I vardagen säger jag: Vädret växlar snabbt, så det är bra att ha paraply med.", vi: "Trong đời sống hằng ngày mình nói: Thời tiết đổi nhanh lắm nên mang theo ô là tốt nhất.", phonetic: "/ˈvɛːdrɛt ˈvɛkːslar snɑpt soː deːt ɛːr brɑː at hɑː pɑrɑˈplʏː meːd/" },
  { id: 999, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag pratar med vänner säger jag: Jag gillar tydliga och enkla rutiner i vardagen.", vi: "Khi trò chuyện với bạn bè mình nói: Mình thích những thói quen rõ ràng và đơn giản trong ngày.", phonetic: "/jɑːɡ ˈjɪlːar ˈtʏːdliɡa ɔ ˈɛŋːkla rɵˈtiːnɛr ɪ ˈvɑːrˌdɑːɡɛn/" },
  { id: 1000, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hemma och på fritiden säger jag: Varje litet steg framåt räknas.", vi: "Ở nhà và lúc rảnh mình nói: Mỗi bước tiến nhỏ về phía trước đều đáng quý.", phonetic: "/ˈvarːjɛ ˈliːtɛt steːɡ ˈfrɑːmˌɔːt ˈrɛkːnas/" },
  { id: 1001, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "God morgon! Hur har du sovit? Det känns avslappnat och vardagligt.", vi: "Chào buổi sáng! Bạn ngủ có ngon không? Nghe rất tự nhiên và gần gũi.", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr hɑːr dʉː ˈsʊːvɪt/" },
  { id: 1002, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag vaknade tidigt idag och tog en lugn start. Det är ett bra uttryck att kunna.", vi: "Hôm nay mình dậy sớm và khởi đầu thật nhẹ nhàng. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈvɑːknadɛ ˈtiːdɪt ɪˈdɑːɡ ɔ tʊːɡ ɛn lɵŋn stɑʈ/" },
  { id: 1003, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Vad ska vi äta till middag ikväll? Jag använder det gärna i samtal.", vi: "Tối nay tụi mình sẽ ăn gì nhỉ? Mình thích dùng câu này khi trò chuyện.", phonetic: "/vɑːd skɑː viː ˈɛːta tɪl ˈmɪdːɑːɡ ɪˈkvɛlː/" },
  { id: 1004, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag håller på att laga mat i köket nu. Det passar bra i många situationer.", vi: "Bây giờ mình đang nấu ăn trong bếp. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ ˈhɔlːɛr pɔː at ˈlɑːɡa mɑːt ɪ ˈɕøːkɛt nʉː/" },
  { id: 1005, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Kan du upprepa det lite långsammare, tack? Det hjälper mig att uttrycka mig klart.", vi: "Bạn lặp lại chậm hơn một chút được không, cảm ơn bạn? Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/kan dʉː ɵpːrɛˈpɑː deː ˈliːtɛ ˈlɔŋːsamːarɛ tak/" },
  { id: 1006, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag förstår ungefär vad du menar, men jag övar fortfarande. Det känns avslappnat och vardagligt.", vi: "Mình hiểu đại khái ý bạn, nhưng mình vẫn đang luyện thêm. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ fœrˈstoːr ɵnːfɛˈjɛːr vɑːd dʉː ˈmeːnar mɛn jɑːɡ ˈøːvar ˈfɔrtˌfarːandɛ/" },
  { id: 1007, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Det här ordet är nytt för mig. Vad betyder det? Det är ett bra uttryck att kunna.", vi: "Từ này mới với mình. Nó có nghĩa là gì vậy? Đây là cách diễn đạt hay nên biết.", phonetic: "/deːt hɛːr ˈuːɖɛt ɛːr nʏt fœr mej vɑːd bɛˈtʏːdɛr deː/" },
  { id: 1008, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag övar på att prata svenska varje dag. Jag använder det gärna i samtal.", vi: "Mình luyện nói tiếng Thụy Điển mỗi ngày. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ ˈøːvar pɔː at ˈprɑːta ˈsvɛnːska ˈvarːjɛ dɑːɡ/" },
  { id: 1009, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Det blir lättare ju mer man pratar. Det passar bra i många situationer.", vi: "Càng nói nhiều thì sẽ càng dễ hơn. Câu này dùng được trong nhiều tình huống.", phonetic: "/deːt bliːr ˈlɛtːarɛ jʉː meːr man ˈprɑːtar/" },
  { id: 1010, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Tack för hjälpen, det betydde mycket! Det hjälper mig att uttrycka mig klart.", vi: "Cảm ơn vì đã giúp đỡ, điều đó có ý nghĩa lắm! Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/tak fœr ˈjɛlːpɛn deː bɛˈtʏːdːɛ ˈmʏkːɛt/" },
  { id: 1011, topic: "Gia đình & người thân", sv: "Jag pratar med min man varje dag om framtiden. Det känns avslappnat och vardagligt.", vi: "Mình trò chuyện với chồng mỗi ngày về tương lai. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ ˈprɑːtar meːd miːn man ˈvarːjɛ dɑːɡ ɔm ˈfrɑːmˌtiːdɛn/" },
  { id: 1012, topic: "Gia đình & người thân", sv: "Vi planerar vårt nya liv tillsammans i lugn takt. Det är ett bra uttryck att kunna.", vi: "Tụi mình lên kế hoạch cho cuộc sống mới cùng nhau một cách chầm chậm. Đây là cách diễn đạt hay nên biết.", phonetic: "/viː plɑˈneːrar voːʈ ˈnʏːa liːv tɪlˈsamːanːs ɪ lɵŋn tɑkt/" },
  { id: 1013, topic: "Gia đình & người thân", sv: "Jag tänker ofta på min mormor hemma. Jag använder det gärna i samtal.", vi: "Mình thường nhớ tới bà ngoại ở nhà. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ ˈtɛŋːkɛr ˈɔfːta pɔː miːn ˈmʊːrmʊr ˈhɛmːa/" },
  { id: 1014, topic: "Gia đình & người thân", sv: "Familjen betyder allt när man är långt hemifrån. Det passar bra i många situationer.", vi: "Gia đình có ý nghĩa tất cả khi ở xa nhà. Câu này dùng được trong nhiều tình huống.", phonetic: "/fɑˈmiːljɛn bɛˈtʏːdɛr alːt nɛːr man ɛːr lɔŋt ˈhɛmːɪˌfroːn/" },
  { id: 1015, topic: "Gia đình & người thân", sv: "Vi ringer videosamtal på helgen när alla är lediga. Det hjälper mig att uttrycka mig klart.", vi: "Tụi mình gọi video vào cuối tuần khi ai cũng rảnh. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/viː ˈrɪŋːɛr ˈviːdɛʊˌsamːtɑːl pɔː ˈhɛlːjɛn nɛːr ˈalːa ɛːr ˈleːdɪɡa/" },
  { id: 1016, topic: "Gia đình & người thân", sv: "Han lagar god mat och stöttar mig alltid. Det känns avslappnat och vardagligt.", vi: "Anh ấy nấu ăn ngon và luôn ủng hộ mình. Nghe rất tự nhiên và gần gũi.", phonetic: "/han ˈlɑːɡar ɡuːd mɑːt ɔ ˈstœtːar mej ˈalːtiːd/" },
  { id: 1017, topic: "Gia đình & người thân", sv: "Att hjälpa varandra gör vardagen enklare. Det är ett bra uttryck att kunna.", vi: "Giúp đỡ lẫn nhau khiến cuộc sống hằng ngày nhẹ nhàng hơn. Đây là cách diễn đạt hay nên biết.", phonetic: "/at ˈjɛlːpa vɑˈranːdra jøːr ˈvɑːrˌdɑːɡɛn ˈɛŋːklarɛ/" },
  { id: 1018, topic: "Gia đình & người thân", sv: "Jag vill gärna bjuda hem familjen på middag någon gång. Jag använder det gärna i samtal.", vi: "Mình rất muốn mời gia đình đến nhà ăn tối một dịp nào đó. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ vɪl ˈjɛːrna ˈbjʉːda hɛm fɑˈmiːljɛn pɔː ˈmɪdːɑːɡ ˈnoːɡɔn ɡɔŋ/" },
  { id: 1019, topic: "Gia đình & người thân", sv: "Det känns tryggt att ha någon som förstår en. Det passar bra i många situationer.", vi: "Thật vững tâm khi có người thấu hiểu mình. Câu này dùng được trong nhiều tình huống.", phonetic: "/deːt ɕɛnːs trʏɡt at hɑː ˈnoːɡɔn sɔm fœrˈstoːr ɛn/" },
  { id: 1020, topic: "Gia đình & người thân", sv: "Vi delar både glädje och små bekymmer. Det hjälper mig att uttrycka mig klart.", vi: "Tụi mình chia sẻ cả niềm vui lẫn những nỗi lo nhỏ. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/viː ˈdeːlar ˈboːdɛ ˈɡlɛːdjɛ ɔ smoː bɛˈɕʏmːɛr/" },
  { id: 1021, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag gillar att ta en promenad i parken efter jobbet. Det känns avslappnat och vardagligt.", vi: "Mình thích đi dạo trong công viên sau giờ làm. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ ˈjɪlːar at tɑː ɛn prʊmɛˈnɑːd ɪ ˈparːkɛn ˈɛfːtɛr ˈjɔbːɛt/" },
  { id: 1022, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Frisk luft och grönska hjälper mig att ladda om. Det är ett bra uttryck att kunna.", vi: "Không khí trong lành và cây xanh giúp mình nạp lại năng lượng. Đây là cách diễn đạt hay nên biết.", phonetic: "/frɪsk lɵft ɔ ˈɡrœnːska ˈjɛlːpɛr mej at ˈladːa ɔm/" },
  { id: 1023, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vilken vacker utsikt över sjön och skogen! Jag använder det gärna i samtal.", vi: "Khung cảnh nhìn ra hồ và rừng đẹp quá! Mình thích dùng câu này khi trò chuyện.", phonetic: "/ˈvɪlːkɛn ˈvakːɛr ˈʉːtˌsɪkːt ˈøːvɛr ɕøːn ɔ ˈskuːɡɛn/" },
  { id: 1024, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag brukar ta foton på naturen när vi reser. Det passar bra i många situationer.", vi: "Mình hay chụp ảnh thiên nhiên khi tụi mình đi du lịch. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ ˈbrʉːkar tɑː ˈfuːtɔn pɔː nɑtʉːˈreːn nɛːr viː ˈreːsɛr/" },
  { id: 1025, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vi åker gärna iväg på helgutflykter till nya platser. Det hjälper mig att uttrycka mig klart.", vi: "Tụi mình thích đi chơi cuối tuần tới những vùng đất mới. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/viː ˈoːkɛr ˈjɛːrna ɪˈvɛːɡ pɔː ˈhɛljˌʉːtflʏkːtɛr tɪl ˈnʏːa ˈplatːsɛr/" },
  { id: 1026, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Ljuset på morgonen och kvällen är så fint att fotografera. Det känns avslappnat och vardagligt.", vi: "Ánh sáng buổi sáng và buổi chiều tối chụp ảnh đẹp lắm. Nghe rất tự nhiên và gần gũi.", phonetic: "/ˈjʉːsɛt pɔː ˈmɔrːɔnɛn ɔ ˈkvɛlːɛn ɛːr soː fiːnt at fʊtʊɡrɑˈfeːra/" },
  { id: 1027, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Det är så tyst och rofyllt här borta vid vattnet. Det är ett bra uttryck att kunna.", vi: "Ở khu vực ven nước này thật yên tĩnh và thanh bình. Đây là cách diễn đạt hay nên biết.", phonetic: "/deːt ɛːr soː tʏst ɔ ˈrʊːˌfʏlt hɛːr ˈbɔrːta viːd ˈvatːnɛt/" },
  { id: 1028, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vi tar det lugnt och njuter av resan i vårt eget tempo. Jag använder det gärna i samtal.", vi: "Tụi mình đi thong thả và tận hưởng chuyến đi theo nhịp của riêng mình. Mình thích dùng câu này khi trò chuyện.", phonetic: "/viː tɑːr deː lɵŋt ɔ ˈnjʉːtɛr ɑːv ˈreːsan ɪ voːʈ ˈeːɡɛt ˈtɛmːpʊ/" },
  { id: 1029, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag älskar när solen tittar fram mellan molnen. Det passar bra i många situationer.", vi: "Mình thích khoảnh khắc mặt trời ló dạng giữa những đám mây. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ ˈɛlːskar nɛːr ˈsuːlɛn ˈtɪtːar fram ˈmɛlːan ˈmuːlnɛn/" },
  { id: 1030, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Att komma ut i naturen rensar tankarna. Det hjälper mig att uttrycka mig klart.", vi: "Ra ngoài thiên nhiên giúp đầu óc thư thái hẳn. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/at ˈkɔmːa ʉːt ɪ nɑtʉːˈreːn ˈrɛnːsar ˈtaŋːkarːa/" },
  { id: 1031, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På kvällen gillar jag att varva ner hemma med en bra film. Det känns avslappnat och vardagligt.", vi: "Buổi tối mình thích thư giãn ở nhà với một bộ phim hay. Nghe rất tự nhiên và gần gũi.", phonetic: "/pɔː ˈkvɛlːɛn ˈjɪlːar jɑːɡ at ˈvarːva neːr ˈhɛmːa meːd ɛn brɑː fɪlm/" },
  { id: 1032, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det är skönt att krypa upp i soffan efter en aktiv dag. Det är ett bra uttryck att kunna.", vi: "Thật dễ chịu khi cuộn mình trên ghế sofa sau một ngày năng động. Đây là cách diễn đạt hay nên biết.", phonetic: "/deːt ɛːr ɕøːnt at ˈkrʏːpa ɵpː ɪ ˈsɔfːan ˈɛfːtɛr ɛn ˈakːtɪv dɑːɡ/" },
  { id: 1033, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vi spelar sällskapsspel och ordlekar när vi är många. Jag använder det gärna i samtal.", vi: "Tụi mình chơi board game và trò nối chữ khi có đông người. Mình thích dùng câu này khi trò chuyện.", phonetic: "/viː ˈsɛlːskɑpsˌspeːl ɔ ˈuːɖˌleːkar nɛːr viː ɛːr ˈmɔŋːa/" },
  { id: 1034, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det är så kul att skratta tillsammans över en spelomgång. Det passar bra i många situationer.", vi: "Cùng cười rôm rả qua một ván chơi vui thật đấy. Câu này dùng được trong nhiều tình huống.", phonetic: "/deːt ɛːr soː kʉːl at ˈskratːa tɪlˈsamːanːs ˈøːvɛr ɛn ˈspeːlˌɔmːɡɔŋ/" },
  { id: 1035, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Jag gillar att ha det städat och mysigt omkring mig. Det hjälper mig att uttrycka mig klart.", vi: "Mình thích giữ không gian gọn gàng và ấm cúng quanh mình. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ ˈjɪlːar at hɑː deː ˈstɛːdat ɔ ˈmʏːsɪt ɔmˈkrɪŋ mej/" },
  { id: 1036, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "En varm dusch och tystnad hjälper mig att somna gott. Det känns avslappnat och vardagligt.", vi: "Một trận tắm nước ấm và sự yên tĩnh giúp mình ngủ ngon. Nghe rất tự nhiên và gần gũi.", phonetic: "/ɛn varm dɵʃ ɔ ˈtʏsːtnɑd ˈjɛlːpɛr mej at ˈsɔmːna ɡɔt/" },
  { id: 1037, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Jag tar gärna en kort paus när jag behöver samla kraft. Det är ett bra uttryck att kunna.", vi: "Mình hay nghỉ giải lao ngắn khi cần lấy lại sức. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn kɔʈ paɵs nɛːr jɑːɡ bɛˈhøːvɛr ˈsamːla krɑft/" },
  { id: 1038, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vilken film eller serie tyckte du bäst om nyligen? Jag använder det gärna i samtal.", vi: "Gần đây bạn thích phim điện ảnh hay phim bộ nào nhất? Mình thích dùng câu này khi trò chuyện.", phonetic: "/ˈvɪlːkɛn fɪlm ˈɛlːɛr ˈseːrɪɛ ˈtʏkːtɛ dʉː bɛst ɔm ˈnʏːˌliːɡɛn/" },
  { id: 1039, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vi gör en enkel fika med kaffe och frukt idag. Det passar bra i många situationer.", vi: "Hôm nay tụi mình làm bữa fika nhẹ nhàng với cà phê và trái cây. Câu này dùng được trong nhiều tình huống.", phonetic: "/viː jøːr ɛn ˈɛŋːkɛl ˈfiːka meːd ˈkafːɛ ɔ frɵkt ɪˈdɑːɡ/" },
  { id: 1040, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det känns skönt att bara vara sig själv i lugn och ro. Det hjälper mig att uttrycka mig klart.", vi: "Thật thoải mái khi được là chính mình trong yên bình. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/deːt ɕɛnːs ɕøːnt at ˈbɑːra ˈvɑːra sej ɕɛlv ɪ lɵŋn ɔ rʊː/" },
  { id: 1041, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Ursäkta, vet du var närmaste busshållplats ligger? Det känns avslappnat och vardagligt.", vi: "Xin lỗi, bạn có biết trạm xe buýt gần nhất ở đâu không? Nghe rất tự nhiên và gần gũi.", phonetic: "/ˈʉːˌʂɛkːta veːt dʉː vɑːr ˈnɛrmastɛ ˈbɵsˌhɔlːplats ˈlɪɡːɛr/" },
  { id: 1042, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag behöver köpa frukt, grönsaker och bröd idag. Det är ett bra uttryck att kunna.", vi: "Hôm nay mình cần mua trái cây, rau củ và bánh mì. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ bɛˈhøːvɛr ˈɕøːpa frɵkt ˈɡrœnˌsɑːkɛr ɔ brøːd ɪˈdɑːɡ/" },
  { id: 1043, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hur mycket kostar det här totalt? Jag använder det gärna i samtal.", vi: "Món này tổng cộng giá bao nhiêu vậy? Mình thích dùng câu này khi trò chuyện.", phonetic: "/hʉːr ˈmʏkːɛt ˈkɔsːtar deːt hɛːr tʊˈtɑlt/" },
  { id: 1044, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag tar gärna en påse, tack så mycket. Det passar bra i många situationer.", vi: "Cho mình xin một túi nhé, cảm ơn bạn nhiều. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn ˈpoːsɛ tak soː ˈmʏkːɛt/" },
  { id: 1045, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Det är ganska svalt ute idag, så jag tar en tröja. Det hjälper mig att uttrycka mig klart.", vi: "Hôm nay ngoài trời khá mát nên mình mặc thêm áo len. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/deːt ɛːr ˈɡanːsa svɑlt ˈʉːtɛ ɪˈdɑːɡ soː jɑːɡ tɑːr ɛn ˈtrœjːa/" },
  { id: 1046, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Vi åker kollektivt eller går när det inte är så långt. Det känns avslappnat och vardagligt.", vi: "Tụi mình đi phương tiện công cộng hoặc đi bộ khi không quá xa. Nghe rất tự nhiên và gần gũi.", phonetic: "/viː ˈoːkɛr kʊlːɛkˈtiːvt ˈɛlːɛr ɡoːr nɛːr deː ˈɪnːtɛ ɛːr soː lɔŋt/" },
  { id: 1047, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag sparar undan lite varje månad för framtida planer. Det är ett bra uttryck att kunna.", vi: "Mình dành dụm một chút mỗi tháng cho các kế hoạch tương lai. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈspɑːrar ˈɵnːdan ˈliːtɛ ˈvarːjɛ ˈmoːnad fœr ˈfrɑːmˌtiːda ˈplɑːnɛr/" },
  { id: 1048, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Vädret växlar snabbt, så det är bra att ha paraply med. Jag använder det gärna i samtal.", vi: "Thời tiết đổi nhanh lắm nên mang theo ô là tốt nhất. Mình thích dùng câu này khi trò chuyện.", phonetic: "/ˈvɛːdrɛt ˈvɛkːslar snɑpt soː deːt ɛːr brɑː at hɑː pɑrɑˈplʏː meːd/" },
  { id: 1049, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag gillar tydliga och enkla rutiner i vardagen. Det passar bra i många situationer.", vi: "Mình thích những thói quen rõ ràng và đơn giản trong ngày. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ ˈjɪlːar ˈtʏːdliɡa ɔ ˈɛŋːkla rɵˈtiːnɛr ɪ ˈvɑːrˌdɑːɡɛn/" },
  { id: 1050, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Varje litet steg framåt räknas. Det hjälper mig att uttrycka mig klart.", vi: "Mỗi bước tiến nhỏ về phía trước đều đáng quý. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/ˈvarːjɛ ˈliːtɛt steːɡ ˈfrɑːmˌɔːt ˈrɛkːnas/" },
  { id: 1051, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "I vardagen säger jag: God morgon! Hur har du sovit?", vi: "Trong đời sống hằng ngày mình nói: Chào buổi sáng! Bạn ngủ có ngon không?", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr hɑːr dʉː ˈsʊːvɪt/" },
  { id: 1052, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag pratar med vänner säger jag: Jag vaknade tidigt idag och tog en lugn start.", vi: "Khi trò chuyện với bạn bè mình nói: Hôm nay mình dậy sớm và khởi đầu thật nhẹ nhàng.", phonetic: "/jɑːɡ ˈvɑːknadɛ ˈtiːdɪt ɪˈdɑːɡ ɔ tʊːɡ ɛn lɵŋn stɑʈ/" },
  { id: 1053, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Hemma och på fritiden säger jag: Vad ska vi äta till middag ikväll?", vi: "Ở nhà và lúc rảnh mình nói: Tối nay tụi mình sẽ ăn gì nhỉ?", phonetic: "/vɑːd skɑː viː ˈɛːta tɪl ˈmɪdːɑːɡ ɪˈkvɛlː/" },
  { id: 1054, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag tränar svenska säger jag: Jag håller på att laga mat i köket nu.", vi: "Khi luyện tiếng Thụy Điển mình nói: Bây giờ mình đang nấu ăn trong bếp.", phonetic: "/jɑːɡ ˈhɔlːɛr pɔː at ˈlɑːɡa mɑːt ɪ ˈɕøːkɛt nʉː/" },
  { id: 1055, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "På utflykt eller promenad säger jag: Kan du upprepa det lite långsammare, tack?", vi: "Khi đi chơi hoặc đi dạo mình nói: Bạn lặp lại chậm hơn một chút được không, cảm ơn bạn?", phonetic: "/kan dʉː ɵpːrɛˈpɑː deː ˈliːtɛ ˈlɔŋːsamːarɛ tak/" },
  { id: 1056, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "I vardagen säger jag: Jag förstår ungefär vad du menar, men jag övar fortfarande.", vi: "Trong đời sống hằng ngày mình nói: Mình hiểu đại khái ý bạn, nhưng mình vẫn đang luyện thêm.", phonetic: "/jɑːɡ fœrˈstoːr ɵnːfɛˈjɛːr vɑːd dʉː ˈmeːnar mɛn jɑːɡ ˈøːvar ˈfɔrtˌfarːandɛ/" },
  { id: 1057, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag pratar med vänner säger jag: Det här ordet är nytt för mig. Vad betyder det?", vi: "Khi trò chuyện với bạn bè mình nói: Từ này mới với mình. Nó có nghĩa là gì vậy?", phonetic: "/deːt hɛːr ˈuːɖɛt ɛːr nʏt fœr mej vɑːd bɛˈtʏːdɛr deː/" },
  { id: 1058, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Hemma och på fritiden säger jag: Jag övar på att prata svenska varje dag.", vi: "Ở nhà và lúc rảnh mình nói: Mình luyện nói tiếng Thụy Điển mỗi ngày.", phonetic: "/jɑːɡ ˈøːvar pɔː at ˈprɑːta ˈsvɛnːska ˈvarːjɛ dɑːɡ/" },
  { id: 1059, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag tränar svenska säger jag: Det blir lättare ju mer man pratar.", vi: "Khi luyện tiếng Thụy Điển mình nói: Càng nói nhiều thì sẽ càng dễ hơn.", phonetic: "/deːt bliːr ˈlɛtːarɛ jʉː meːr man ˈprɑːtar/" },
  { id: 1060, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "På utflykt eller promenad säger jag: Tack för hjälpen, det betydde mycket!", vi: "Khi đi chơi hoặc đi dạo mình nói: Cảm ơn vì đã giúp đỡ, điều đó có ý nghĩa lắm!", phonetic: "/tak fœr ˈjɛlːpɛn deː bɛˈtʏːdːɛ ˈmʏkːɛt/" },
  { id: 1061, topic: "Gia đình & người thân", sv: "I vardagen säger jag: Jag pratar med min man varje dag om framtiden.", vi: "Trong đời sống hằng ngày mình nói: Mình trò chuyện với chồng mỗi ngày về tương lai.", phonetic: "/jɑːɡ ˈprɑːtar meːd miːn man ˈvarːjɛ dɑːɡ ɔm ˈfrɑːmˌtiːdɛn/" },
  { id: 1062, topic: "Gia đình & người thân", sv: "När jag pratar med vänner säger jag: Vi planerar vårt nya liv tillsammans i lugn takt.", vi: "Khi trò chuyện với bạn bè mình nói: Tụi mình lên kế hoạch cho cuộc sống mới cùng nhau một cách chầm chậm.", phonetic: "/viː plɑˈneːrar voːʈ ˈnʏːa liːv tɪlˈsamːanːs ɪ lɵŋn tɑkt/" },
  { id: 1063, topic: "Gia đình & người thân", sv: "Hemma och på fritiden säger jag: Jag tänker ofta på min mormor hemma.", vi: "Ở nhà và lúc rảnh mình nói: Mình thường nhớ tới bà ngoại ở nhà.", phonetic: "/jɑːɡ ˈtɛŋːkɛr ˈɔfːta pɔː miːn ˈmʊːrmʊr ˈhɛmːa/" },
  { id: 1064, topic: "Gia đình & người thân", sv: "När jag tränar svenska säger jag: Familjen betyder allt när man är långt hemifrån.", vi: "Khi luyện tiếng Thụy Điển mình nói: Gia đình có ý nghĩa tất cả khi ở xa nhà.", phonetic: "/fɑˈmiːljɛn bɛˈtʏːdɛr alːt nɛːr man ɛːr lɔŋt ˈhɛmːɪˌfroːn/" },
  { id: 1065, topic: "Gia đình & người thân", sv: "På utflykt eller promenad säger jag: Vi ringer videosamtal på helgen när alla är lediga.", vi: "Khi đi chơi hoặc đi dạo mình nói: Tụi mình gọi video vào cuối tuần khi ai cũng rảnh.", phonetic: "/viː ˈrɪŋːɛr ˈviːdɛʊˌsamːtɑːl pɔː ˈhɛlːjɛn nɛːr ˈalːa ɛːr ˈleːdɪɡa/" },
  { id: 1066, topic: "Gia đình & người thân", sv: "I vardagen säger jag: Han lagar god mat och stöttar mig alltid.", vi: "Trong đời sống hằng ngày mình nói: Anh ấy nấu ăn ngon và luôn ủng hộ mình.", phonetic: "/han ˈlɑːɡar ɡuːd mɑːt ɔ ˈstœtːar mej ˈalːtiːd/" },
  { id: 1067, topic: "Gia đình & người thân", sv: "När jag pratar med vänner säger jag: Att hjälpa varandra gör vardagen enklare.", vi: "Khi trò chuyện với bạn bè mình nói: Giúp đỡ lẫn nhau khiến cuộc sống hằng ngày nhẹ nhàng hơn.", phonetic: "/at ˈjɛlːpa vɑˈranːdra jøːr ˈvɑːrˌdɑːɡɛn ˈɛŋːklarɛ/" },
  { id: 1068, topic: "Gia đình & người thân", sv: "Hemma och på fritiden säger jag: Jag vill gärna bjuda hem familjen på middag någon gång.", vi: "Ở nhà và lúc rảnh mình nói: Mình rất muốn mời gia đình đến nhà ăn tối một dịp nào đó.", phonetic: "/jɑːɡ vɪl ˈjɛːrna ˈbjʉːda hɛm fɑˈmiːljɛn pɔː ˈmɪdːɑːɡ ˈnoːɡɔn ɡɔŋ/" },
  { id: 1069, topic: "Gia đình & người thân", sv: "När jag tränar svenska säger jag: Det känns tryggt att ha någon som förstår en.", vi: "Khi luyện tiếng Thụy Điển mình nói: Thật vững tâm khi có người thấu hiểu mình.", phonetic: "/deːt ɕɛnːs trʏɡt at hɑː ˈnoːɡɔn sɔm fœrˈstoːr ɛn/" },
  { id: 1070, topic: "Gia đình & người thân", sv: "På utflykt eller promenad säger jag: Vi delar både glädje och små bekymmer.", vi: "Khi đi chơi hoặc đi dạo mình nói: Tụi mình chia sẻ cả niềm vui lẫn những nỗi lo nhỏ.", phonetic: "/viː ˈdeːlar ˈboːdɛ ˈɡlɛːdjɛ ɔ smoː bɛˈɕʏmːɛr/" },
  { id: 1071, topic: "Thiên nhiên, đi dạo & du lịch", sv: "I vardagen säger jag: Jag gillar att ta en promenad i parken efter jobbet.", vi: "Trong đời sống hằng ngày mình nói: Mình thích đi dạo trong công viên sau giờ làm.", phonetic: "/jɑːɡ ˈjɪlːar at tɑː ɛn prʊmɛˈnɑːd ɪ ˈparːkɛn ˈɛfːtɛr ˈjɔbːɛt/" },
  { id: 1072, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag pratar med vänner säger jag: Frisk luft och grönska hjälper mig att ladda om.", vi: "Khi trò chuyện với bạn bè mình nói: Không khí trong lành và cây xanh giúp mình nạp lại năng lượng.", phonetic: "/frɪsk lɵft ɔ ˈɡrœnːska ˈjɛlːpɛr mej at ˈladːa ɔm/" },
  { id: 1073, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Hemma och på fritiden säger jag: Vilken vacker utsikt över sjön och skogen!", vi: "Ở nhà và lúc rảnh mình nói: Khung cảnh nhìn ra hồ và rừng đẹp quá!", phonetic: "/ˈvɪlːkɛn ˈvakːɛr ˈʉːtˌsɪkːt ˈøːvɛr ɕøːn ɔ ˈskuːɡɛn/" },
  { id: 1074, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag tränar svenska säger jag: Jag brukar ta foton på naturen när vi reser.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình hay chụp ảnh thiên nhiên khi tụi mình đi du lịch.", phonetic: "/jɑːɡ ˈbrʉːkar tɑː ˈfuːtɔn pɔː nɑtʉːˈreːn nɛːr viː ˈreːsɛr/" },
  { id: 1075, topic: "Thiên nhiên, đi dạo & du lịch", sv: "På utflykt eller promenad säger jag: Vi åker gärna iväg på helgutflykter till nya platser.", vi: "Khi đi chơi hoặc đi dạo mình nói: Tụi mình thích đi chơi cuối tuần tới những vùng đất mới.", phonetic: "/viː ˈoːkɛr ˈjɛːrna ɪˈvɛːɡ pɔː ˈhɛljˌʉːtflʏkːtɛr tɪl ˈnʏːa ˈplatːsɛr/" },
  { id: 1076, topic: "Thiên nhiên, đi dạo & du lịch", sv: "I vardagen säger jag: Ljuset på morgonen och kvällen är så fint att fotografera.", vi: "Trong đời sống hằng ngày mình nói: Ánh sáng buổi sáng và buổi chiều tối chụp ảnh đẹp lắm.", phonetic: "/ˈjʉːsɛt pɔː ˈmɔrːɔnɛn ɔ ˈkvɛlːɛn ɛːr soː fiːnt at fʊtʊɡrɑˈfeːra/" },
  { id: 1077, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag pratar med vänner säger jag: Det är så tyst och rofyllt här borta vid vattnet.", vi: "Khi trò chuyện với bạn bè mình nói: Ở khu vực ven nước này thật yên tĩnh và thanh bình.", phonetic: "/deːt ɛːr soː tʏst ɔ ˈrʊːˌfʏlt hɛːr ˈbɔrːta viːd ˈvatːnɛt/" },
  { id: 1078, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Hemma och på fritiden säger jag: Vi tar det lugnt och njuter av resan i vårt eget tempo.", vi: "Ở nhà và lúc rảnh mình nói: Tụi mình đi thong thả và tận hưởng chuyến đi theo nhịp của riêng mình.", phonetic: "/viː tɑːr deː lɵŋt ɔ ˈnjʉːtɛr ɑːv ˈreːsan ɪ voːʈ ˈeːɡɛt ˈtɛmːpʊ/" },
  { id: 1079, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag tränar svenska säger jag: Jag älskar när solen tittar fram mellan molnen.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình thích khoảnh khắc mặt trời ló dạng giữa những đám mây.", phonetic: "/jɑːɡ ˈɛlːskar nɛːr ˈsuːlɛn ˈtɪtːar fram ˈmɛlːan ˈmuːlnɛn/" },
  { id: 1080, topic: "Thiên nhiên, đi dạo & du lịch", sv: "På utflykt eller promenad säger jag: Att komma ut i naturen rensar tankarna.", vi: "Khi đi chơi hoặc đi dạo mình nói: Ra ngoài thiên nhiên giúp đầu óc thư thái hẳn.", phonetic: "/at ˈkɔmːa ʉːt ɪ nɑtʉːˈreːn ˈrɛnːsar ˈtaŋːkarːa/" },
  { id: 1081, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "I vardagen säger jag: På kvällen gillar jag att varva ner hemma med en bra film.", vi: "Trong đời sống hằng ngày mình nói: Buổi tối mình thích thư giãn ở nhà với một bộ phim hay.", phonetic: "/pɔː ˈkvɛlːɛn ˈjɪlːar jɑːɡ at ˈvarːva neːr ˈhɛmːa meːd ɛn brɑː fɪlm/" },
  { id: 1082, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag pratar med vänner säger jag: Det är skönt att krypa upp i soffan efter en aktiv dag.", vi: "Khi trò chuyện với bạn bè mình nói: Thật dễ chịu khi cuộn mình trên ghế sofa sau một ngày năng động.", phonetic: "/deːt ɛːr ɕøːnt at ˈkrʏːpa ɵpː ɪ ˈsɔfːan ˈɛfːtɛr ɛn ˈakːtɪv dɑːɡ/" },
  { id: 1083, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Hemma och på fritiden säger jag: Vi spelar sällskapsspel och ordlekar när vi är många.", vi: "Ở nhà và lúc rảnh mình nói: Tụi mình chơi board game và trò nối chữ khi có đông người.", phonetic: "/viː ˈsɛlːskɑpsˌspeːl ɔ ˈuːɖˌleːkar nɛːr viː ɛːr ˈmɔŋːa/" },
  { id: 1084, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag tränar svenska säger jag: Det är så kul att skratta tillsammans över en spelomgång.", vi: "Khi luyện tiếng Thụy Điển mình nói: Cùng cười rôm rả qua một ván chơi vui thật đấy.", phonetic: "/deːt ɛːr soː kʉːl at ˈskratːa tɪlˈsamːanːs ˈøːvɛr ɛn ˈspeːlˌɔmːɡɔŋ/" },
  { id: 1085, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På utflykt eller promenad säger jag: Jag gillar att ha det städat och mysigt omkring mig.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình thích giữ không gian gọn gàng và ấm cúng quanh mình.", phonetic: "/jɑːɡ ˈjɪlːar at hɑː deː ˈstɛːdat ɔ ˈmʏːsɪt ɔmˈkrɪŋ mej/" },
  { id: 1086, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "I vardagen säger jag: En varm dusch och tystnad hjälper mig att somna gott.", vi: "Trong đời sống hằng ngày mình nói: Một trận tắm nước ấm và sự yên tĩnh giúp mình ngủ ngon.", phonetic: "/ɛn varm dɵʃ ɔ ˈtʏsːtnɑd ˈjɛlːpɛr mej at ˈsɔmːna ɡɔt/" },
  { id: 1087, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag pratar med vänner säger jag: Jag tar gärna en kort paus när jag behöver samla kraft.", vi: "Khi trò chuyện với bạn bè mình nói: Mình hay nghỉ giải lao ngắn khi cần lấy lại sức.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn kɔʈ paɵs nɛːr jɑːɡ bɛˈhøːvɛr ˈsamːla krɑft/" },
  { id: 1088, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Hemma och på fritiden säger jag: Vilken film eller serie tyckte du bäst om nyligen?", vi: "Ở nhà và lúc rảnh mình nói: Gần đây bạn thích phim điện ảnh hay phim bộ nào nhất?", phonetic: "/ˈvɪlːkɛn fɪlm ˈɛlːɛr ˈseːrɪɛ ˈtʏkːtɛ dʉː bɛst ɔm ˈnʏːˌliːɡɛn/" },
  { id: 1089, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag tränar svenska säger jag: Vi gör en enkel fika med kaffe och frukt idag.", vi: "Khi luyện tiếng Thụy Điển mình nói: Hôm nay tụi mình làm bữa fika nhẹ nhàng với cà phê và trái cây.", phonetic: "/viː jøːr ɛn ˈɛŋːkɛl ˈfiːka meːd ˈkafːɛ ɔ frɵkt ɪˈdɑːɡ/" },
  { id: 1090, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På utflykt eller promenad säger jag: Det känns skönt att bara vara sig själv i lugn och ro.", vi: "Khi đi chơi hoặc đi dạo mình nói: Thật thoải mái khi được là chính mình trong yên bình.", phonetic: "/deːt ɕɛnːs ɕøːnt at ˈbɑːra ˈvɑːra sej ɕɛlv ɪ lɵŋn ɔ rʊː/" },
  { id: 1091, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "I vardagen säger jag: Ursäkta, vet du var närmaste busshållplats ligger?", vi: "Trong đời sống hằng ngày mình nói: Xin lỗi, bạn có biết trạm xe buýt gần nhất ở đâu không?", phonetic: "/ˈʉːˌʂɛkːta veːt dʉː vɑːr ˈnɛrmastɛ ˈbɵsˌhɔlːplats ˈlɪɡːɛr/" },
  { id: 1092, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag pratar med vänner säger jag: Jag behöver köpa frukt, grönsaker och bröd idag.", vi: "Khi trò chuyện với bạn bè mình nói: Hôm nay mình cần mua trái cây, rau củ và bánh mì.", phonetic: "/jɑːɡ bɛˈhøːvɛr ˈɕøːpa frɵkt ˈɡrœnˌsɑːkɛr ɔ brøːd ɪˈdɑːɡ/" },
  { id: 1093, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hemma och på fritiden säger jag: Hur mycket kostar det här totalt?", vi: "Ở nhà và lúc rảnh mình nói: Món này tổng cộng giá bao nhiêu vậy?", phonetic: "/hʉːr ˈmʏkːɛt ˈkɔsːtar deːt hɛːr tʊˈtɑlt/" },
  { id: 1094, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag tränar svenska säger jag: Jag tar gärna en påse, tack så mycket.", vi: "Khi luyện tiếng Thụy Điển mình nói: Cho mình xin một túi nhé, cảm ơn bạn nhiều.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn ˈpoːsɛ tak soː ˈmʏkːɛt/" },
  { id: 1095, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "På utflykt eller promenad säger jag: Det är ganska svalt ute idag, så jag tar en tröja.", vi: "Khi đi chơi hoặc đi dạo mình nói: Hôm nay ngoài trời khá mát nên mình mặc thêm áo len.", phonetic: "/deːt ɛːr ˈɡanːsa svɑlt ˈʉːtɛ ɪˈdɑːɡ soː jɑːɡ tɑːr ɛn ˈtrœjːa/" },
  { id: 1096, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "I vardagen säger jag: Vi åker kollektivt eller går när det inte är så långt.", vi: "Trong đời sống hằng ngày mình nói: Tụi mình đi phương tiện công cộng hoặc đi bộ khi không quá xa.", phonetic: "/viː ˈoːkɛr kʊlːɛkˈtiːvt ˈɛlːɛr ɡoːr nɛːr deː ˈɪnːtɛ ɛːr soː lɔŋt/" },
  { id: 1097, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag pratar med vänner säger jag: Jag sparar undan lite varje månad för framtida planer.", vi: "Khi trò chuyện với bạn bè mình nói: Mình dành dụm một chút mỗi tháng cho các kế hoạch tương lai.", phonetic: "/jɑːɡ ˈspɑːrar ˈɵnːdan ˈliːtɛ ˈvarːjɛ ˈmoːnad fœr ˈfrɑːmˌtiːda ˈplɑːnɛr/" },
  { id: 1098, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hemma och på fritiden säger jag: Vädret växlar snabbt, så det är bra att ha paraply med.", vi: "Ở nhà và lúc rảnh mình nói: Thời tiết đổi nhanh lắm nên mang theo ô là tốt nhất.", phonetic: "/ˈvɛːdrɛt ˈvɛkːslar snɑpt soː deːt ɛːr brɑː at hɑː pɑrɑˈplʏː meːd/" },
  { id: 1099, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag tränar svenska säger jag: Jag gillar tydliga och enkla rutiner i vardagen.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình thích những thói quen rõ ràng và đơn giản trong ngày.", phonetic: "/jɑːɡ ˈjɪlːar ˈtʏːdliɡa ɔ ˈɛŋːkla rɵˈtiːnɛr ɪ ˈvɑːrˌdɑːɡɛn/" },
  { id: 1100, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "På utflykt eller promenad säger jag: Varje litet steg framåt räknas.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mỗi bước tiến nhỏ về phía trước đều đáng quý.", phonetic: "/ˈvarːjɛ ˈliːtɛt steːɡ ˈfrɑːmˌɔːt ˈrɛkːnas/" },
  { id: 1101, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "God morgon! Hur har du sovit? Jag använder det gärna i samtal.", vi: "Chào buổi sáng! Bạn ngủ có ngon không? Mình thích dùng câu này khi trò chuyện.", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr hɑːr dʉː ˈsʊːvɪt/" },
  { id: 1102, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag vaknade tidigt idag och tog en lugn start. Det passar bra i många situationer.", vi: "Hôm nay mình dậy sớm và khởi đầu thật nhẹ nhàng. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ ˈvɑːknadɛ ˈtiːdɪt ɪˈdɑːɡ ɔ tʊːɡ ɛn lɵŋn stɑʈ/" },
  { id: 1103, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Vad ska vi äta till middag ikväll? Det hjälper mig att uttrycka mig klart.", vi: "Tối nay tụi mình sẽ ăn gì nhỉ? Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/vɑːd skɑː viː ˈɛːta tɪl ˈmɪdːɑːɡ ɪˈkvɛlː/" },
  { id: 1104, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag håller på att laga mat i köket nu. Det känns avslappnat och vardagligt.", vi: "Bây giờ mình đang nấu ăn trong bếp. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ ˈhɔlːɛr pɔː at ˈlɑːɡa mɑːt ɪ ˈɕøːkɛt nʉː/" },
  { id: 1105, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Kan du upprepa det lite långsammare, tack? Det är ett bra uttryck att kunna.", vi: "Bạn lặp lại chậm hơn một chút được không, cảm ơn bạn? Đây là cách diễn đạt hay nên biết.", phonetic: "/kan dʉː ɵpːrɛˈpɑː deː ˈliːtɛ ˈlɔŋːsamːarɛ tak/" },
  { id: 1106, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag förstår ungefär vad du menar, men jag övar fortfarande. Jag använder det gärna i samtal.", vi: "Mình hiểu đại khái ý bạn, nhưng mình vẫn đang luyện thêm. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ fœrˈstoːr ɵnːfɛˈjɛːr vɑːd dʉː ˈmeːnar mɛn jɑːɡ ˈøːvar ˈfɔrtˌfarːandɛ/" },
  { id: 1107, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Det här ordet är nytt för mig. Vad betyder det? Det passar bra i många situationer.", vi: "Từ này mới với mình. Nó có nghĩa là gì vậy? Câu này dùng được trong nhiều tình huống.", phonetic: "/deːt hɛːr ˈuːɖɛt ɛːr nʏt fœr mej vɑːd bɛˈtʏːdɛr deː/" },
  { id: 1108, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag övar på att prata svenska varje dag. Det hjälper mig att uttrycka mig klart.", vi: "Mình luyện nói tiếng Thụy Điển mỗi ngày. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ ˈøːvar pɔː at ˈprɑːta ˈsvɛnːska ˈvarːjɛ dɑːɡ/" },
  { id: 1109, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Det blir lättare ju mer man pratar. Det känns avslappnat och vardagligt.", vi: "Càng nói nhiều thì sẽ càng dễ hơn. Nghe rất tự nhiên và gần gũi.", phonetic: "/deːt bliːr ˈlɛtːarɛ jʉː meːr man ˈprɑːtar/" },
  { id: 1110, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Tack för hjälpen, det betydde mycket! Det är ett bra uttryck att kunna.", vi: "Cảm ơn vì đã giúp đỡ, điều đó có ý nghĩa lắm! Đây là cách diễn đạt hay nên biết.", phonetic: "/tak fœr ˈjɛlːpɛn deː bɛˈtʏːdːɛ ˈmʏkːɛt/" },
  { id: 1111, topic: "Gia đình & người thân", sv: "Jag pratar med min man varje dag om framtiden. Jag använder det gärna i samtal.", vi: "Mình trò chuyện với chồng mỗi ngày về tương lai. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ ˈprɑːtar meːd miːn man ˈvarːjɛ dɑːɡ ɔm ˈfrɑːmˌtiːdɛn/" },
  { id: 1112, topic: "Gia đình & người thân", sv: "Vi planerar vårt nya liv tillsammans i lugn takt. Det passar bra i många situationer.", vi: "Tụi mình lên kế hoạch cho cuộc sống mới cùng nhau một cách chầm chậm. Câu này dùng được trong nhiều tình huống.", phonetic: "/viː plɑˈneːrar voːʈ ˈnʏːa liːv tɪlˈsamːanːs ɪ lɵŋn tɑkt/" },
  { id: 1113, topic: "Gia đình & người thân", sv: "Jag tänker ofta på min mormor hemma. Det hjälper mig att uttrycka mig klart.", vi: "Mình thường nhớ tới bà ngoại ở nhà. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ ˈtɛŋːkɛr ˈɔfːta pɔː miːn ˈmʊːrmʊr ˈhɛmːa/" },
  { id: 1114, topic: "Gia đình & người thân", sv: "Familjen betyder allt när man är långt hemifrån. Det känns avslappnat och vardagligt.", vi: "Gia đình có ý nghĩa tất cả khi ở xa nhà. Nghe rất tự nhiên và gần gũi.", phonetic: "/fɑˈmiːljɛn bɛˈtʏːdɛr alːt nɛːr man ɛːr lɔŋt ˈhɛmːɪˌfroːn/" },
  { id: 1115, topic: "Gia đình & người thân", sv: "Vi ringer videosamtal på helgen när alla är lediga. Det är ett bra uttryck att kunna.", vi: "Tụi mình gọi video vào cuối tuần khi ai cũng rảnh. Đây là cách diễn đạt hay nên biết.", phonetic: "/viː ˈrɪŋːɛr ˈviːdɛʊˌsamːtɑːl pɔː ˈhɛlːjɛn nɛːr ˈalːa ɛːr ˈleːdɪɡa/" },
  { id: 1116, topic: "Gia đình & người thân", sv: "Han lagar god mat och stöttar mig alltid. Jag använder det gärna i samtal.", vi: "Anh ấy nấu ăn ngon và luôn ủng hộ mình. Mình thích dùng câu này khi trò chuyện.", phonetic: "/han ˈlɑːɡar ɡuːd mɑːt ɔ ˈstœtːar mej ˈalːtiːd/" },
  { id: 1117, topic: "Gia đình & người thân", sv: "Att hjälpa varandra gör vardagen enklare. Det passar bra i många situationer.", vi: "Giúp đỡ lẫn nhau khiến cuộc sống hằng ngày nhẹ nhàng hơn. Câu này dùng được trong nhiều tình huống.", phonetic: "/at ˈjɛlːpa vɑˈranːdra jøːr ˈvɑːrˌdɑːɡɛn ˈɛŋːklarɛ/" },
  { id: 1118, topic: "Gia đình & người thân", sv: "Jag vill gärna bjuda hem familjen på middag någon gång. Det hjälper mig att uttrycka mig klart.", vi: "Mình rất muốn mời gia đình đến nhà ăn tối một dịp nào đó. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ vɪl ˈjɛːrna ˈbjʉːda hɛm fɑˈmiːljɛn pɔː ˈmɪdːɑːɡ ˈnoːɡɔn ɡɔŋ/" },
  { id: 1119, topic: "Gia đình & người thân", sv: "Det känns tryggt att ha någon som förstår en. Det känns avslappnat och vardagligt.", vi: "Thật vững tâm khi có người thấu hiểu mình. Nghe rất tự nhiên và gần gũi.", phonetic: "/deːt ɕɛnːs trʏɡt at hɑː ˈnoːɡɔn sɔm fœrˈstoːr ɛn/" },
  { id: 1120, topic: "Gia đình & người thân", sv: "Vi delar både glädje och små bekymmer. Det är ett bra uttryck att kunna.", vi: "Tụi mình chia sẻ cả niềm vui lẫn những nỗi lo nhỏ. Đây là cách diễn đạt hay nên biết.", phonetic: "/viː ˈdeːlar ˈboːdɛ ˈɡlɛːdjɛ ɔ smoː bɛˈɕʏmːɛr/" },
  { id: 1121, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag gillar att ta en promenad i parken efter jobbet. Jag använder det gärna i samtal.", vi: "Mình thích đi dạo trong công viên sau giờ làm. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ ˈjɪlːar at tɑː ɛn prʊmɛˈnɑːd ɪ ˈparːkɛn ˈɛfːtɛr ˈjɔbːɛt/" },
  { id: 1122, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Frisk luft och grönska hjälper mig att ladda om. Det passar bra i många situationer.", vi: "Không khí trong lành và cây xanh giúp mình nạp lại năng lượng. Câu này dùng được trong nhiều tình huống.", phonetic: "/frɪsk lɵft ɔ ˈɡrœnːska ˈjɛlːpɛr mej at ˈladːa ɔm/" },
  { id: 1123, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vilken vacker utsikt över sjön och skogen! Det hjälper mig att uttrycka mig klart.", vi: "Khung cảnh nhìn ra hồ và rừng đẹp quá! Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/ˈvɪlːkɛn ˈvakːɛr ˈʉːtˌsɪkːt ˈøːvɛr ɕøːn ɔ ˈskuːɡɛn/" },
  { id: 1124, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag brukar ta foton på naturen när vi reser. Det känns avslappnat och vardagligt.", vi: "Mình hay chụp ảnh thiên nhiên khi tụi mình đi du lịch. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ ˈbrʉːkar tɑː ˈfuːtɔn pɔː nɑtʉːˈreːn nɛːr viː ˈreːsɛr/" },
  { id: 1125, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vi åker gärna iväg på helgutflykter till nya platser. Det är ett bra uttryck att kunna.", vi: "Tụi mình thích đi chơi cuối tuần tới những vùng đất mới. Đây là cách diễn đạt hay nên biết.", phonetic: "/viː ˈoːkɛr ˈjɛːrna ɪˈvɛːɡ pɔː ˈhɛljˌʉːtflʏkːtɛr tɪl ˈnʏːa ˈplatːsɛr/" },
  { id: 1126, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Ljuset på morgonen och kvällen är så fint att fotografera. Jag använder det gärna i samtal.", vi: "Ánh sáng buổi sáng và buổi chiều tối chụp ảnh đẹp lắm. Mình thích dùng câu này khi trò chuyện.", phonetic: "/ˈjʉːsɛt pɔː ˈmɔrːɔnɛn ɔ ˈkvɛlːɛn ɛːr soː fiːnt at fʊtʊɡrɑˈfeːra/" },
  { id: 1127, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Det är så tyst och rofyllt här borta vid vattnet. Det passar bra i många situationer.", vi: "Ở khu vực ven nước này thật yên tĩnh và thanh bình. Câu này dùng được trong nhiều tình huống.", phonetic: "/deːt ɛːr soː tʏst ɔ ˈrʊːˌfʏlt hɛːr ˈbɔrːta viːd ˈvatːnɛt/" },
  { id: 1128, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vi tar det lugnt och njuter av resan i vårt eget tempo. Det hjälper mig att uttrycka mig klart.", vi: "Tụi mình đi thong thả và tận hưởng chuyến đi theo nhịp của riêng mình. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/viː tɑːr deː lɵŋt ɔ ˈnjʉːtɛr ɑːv ˈreːsan ɪ voːʈ ˈeːɡɛt ˈtɛmːpʊ/" },
  { id: 1129, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag älskar när solen tittar fram mellan molnen. Det känns avslappnat och vardagligt.", vi: "Mình thích khoảnh khắc mặt trời ló dạng giữa những đám mây. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ ˈɛlːskar nɛːr ˈsuːlɛn ˈtɪtːar fram ˈmɛlːan ˈmuːlnɛn/" },
  { id: 1130, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Att komma ut i naturen rensar tankarna. Det är ett bra uttryck att kunna.", vi: "Ra ngoài thiên nhiên giúp đầu óc thư thái hẳn. Đây là cách diễn đạt hay nên biết.", phonetic: "/at ˈkɔmːa ʉːt ɪ nɑtʉːˈreːn ˈrɛnːsar ˈtaŋːkarːa/" },
  { id: 1131, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På kvällen gillar jag att varva ner hemma med en bra film. Jag använder det gärna i samtal.", vi: "Buổi tối mình thích thư giãn ở nhà với một bộ phim hay. Mình thích dùng câu này khi trò chuyện.", phonetic: "/pɔː ˈkvɛlːɛn ˈjɪlːar jɑːɡ at ˈvarːva neːr ˈhɛmːa meːd ɛn brɑː fɪlm/" },
  { id: 1132, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det är skönt att krypa upp i soffan efter en aktiv dag. Det passar bra i många situationer.", vi: "Thật dễ chịu khi cuộn mình trên ghế sofa sau một ngày năng động. Câu này dùng được trong nhiều tình huống.", phonetic: "/deːt ɛːr ɕøːnt at ˈkrʏːpa ɵpː ɪ ˈsɔfːan ˈɛfːtɛr ɛn ˈakːtɪv dɑːɡ/" },
  { id: 1133, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vi spelar sällskapsspel och ordlekar när vi är många. Det hjälper mig att uttrycka mig klart.", vi: "Tụi mình chơi board game và trò nối chữ khi có đông người. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/viː ˈsɛlːskɑpsˌspeːl ɔ ˈuːɖˌleːkar nɛːr viː ɛːr ˈmɔŋːa/" },
  { id: 1134, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det är så kul att skratta tillsammans över en spelomgång. Det känns avslappnat och vardagligt.", vi: "Cùng cười rôm rả qua một ván chơi vui thật đấy. Nghe rất tự nhiên và gần gũi.", phonetic: "/deːt ɛːr soː kʉːl at ˈskratːa tɪlˈsamːanːs ˈøːvɛr ɛn ˈspeːlˌɔmːɡɔŋ/" },
  { id: 1135, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Jag gillar att ha det städat och mysigt omkring mig. Det är ett bra uttryck att kunna.", vi: "Mình thích giữ không gian gọn gàng và ấm cúng quanh mình. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈjɪlːar at hɑː deː ˈstɛːdat ɔ ˈmʏːsɪt ɔmˈkrɪŋ mej/" },
  { id: 1136, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "En varm dusch och tystnad hjälper mig att somna gott. Jag använder det gärna i samtal.", vi: "Một trận tắm nước ấm và sự yên tĩnh giúp mình ngủ ngon. Mình thích dùng câu này khi trò chuyện.", phonetic: "/ɛn varm dɵʃ ɔ ˈtʏsːtnɑd ˈjɛlːpɛr mej at ˈsɔmːna ɡɔt/" },
  { id: 1137, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Jag tar gärna en kort paus när jag behöver samla kraft. Det passar bra i många situationer.", vi: "Mình hay nghỉ giải lao ngắn khi cần lấy lại sức. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn kɔʈ paɵs nɛːr jɑːɡ bɛˈhøːvɛr ˈsamːla krɑft/" },
  { id: 1138, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vilken film eller serie tyckte du bäst om nyligen? Det hjälper mig att uttrycka mig klart.", vi: "Gần đây bạn thích phim điện ảnh hay phim bộ nào nhất? Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/ˈvɪlːkɛn fɪlm ˈɛlːɛr ˈseːrɪɛ ˈtʏkːtɛ dʉː bɛst ɔm ˈnʏːˌliːɡɛn/" },
  { id: 1139, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vi gör en enkel fika med kaffe och frukt idag. Det känns avslappnat och vardagligt.", vi: "Hôm nay tụi mình làm bữa fika nhẹ nhàng với cà phê và trái cây. Nghe rất tự nhiên và gần gũi.", phonetic: "/viː jøːr ɛn ˈɛŋːkɛl ˈfiːka meːd ˈkafːɛ ɔ frɵkt ɪˈdɑːɡ/" },
  { id: 1140, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det känns skönt att bara vara sig själv i lugn och ro. Det är ett bra uttryck att kunna.", vi: "Thật thoải mái khi được là chính mình trong yên bình. Đây là cách diễn đạt hay nên biết.", phonetic: "/deːt ɕɛnːs ɕøːnt at ˈbɑːra ˈvɑːra sej ɕɛlv ɪ lɵŋn ɔ rʊː/" },
  { id: 1141, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Ursäkta, vet du var närmaste busshållplats ligger? Jag använder det gärna i samtal.", vi: "Xin lỗi, bạn có biết trạm xe buýt gần nhất ở đâu không? Mình thích dùng câu này khi trò chuyện.", phonetic: "/ˈʉːˌʂɛkːta veːt dʉː vɑːr ˈnɛrmastɛ ˈbɵsˌhɔlːplats ˈlɪɡːɛr/" },
  { id: 1142, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag behöver köpa frukt, grönsaker och bröd idag. Det passar bra i många situationer.", vi: "Hôm nay mình cần mua trái cây, rau củ và bánh mì. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ bɛˈhøːvɛr ˈɕøːpa frɵkt ˈɡrœnˌsɑːkɛr ɔ brøːd ɪˈdɑːɡ/" },
  { id: 1143, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hur mycket kostar det här totalt? Det hjälper mig att uttrycka mig klart.", vi: "Món này tổng cộng giá bao nhiêu vậy? Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/hʉːr ˈmʏkːɛt ˈkɔsːtar deːt hɛːr tʊˈtɑlt/" },
  { id: 1144, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag tar gärna en påse, tack så mycket. Det känns avslappnat och vardagligt.", vi: "Cho mình xin một túi nhé, cảm ơn bạn nhiều. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn ˈpoːsɛ tak soː ˈmʏkːɛt/" },
  { id: 1145, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Det är ganska svalt ute idag, så jag tar en tröja. Det är ett bra uttryck att kunna.", vi: "Hôm nay ngoài trời khá mát nên mình mặc thêm áo len. Đây là cách diễn đạt hay nên biết.", phonetic: "/deːt ɛːr ˈɡanːsa svɑlt ˈʉːtɛ ɪˈdɑːɡ soː jɑːɡ tɑːr ɛn ˈtrœjːa/" },
  { id: 1146, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Vi åker kollektivt eller går när det inte är så långt. Jag använder det gärna i samtal.", vi: "Tụi mình đi phương tiện công cộng hoặc đi bộ khi không quá xa. Mình thích dùng câu này khi trò chuyện.", phonetic: "/viː ˈoːkɛr kʊlːɛkˈtiːvt ˈɛlːɛr ɡoːr nɛːr deː ˈɪnːtɛ ɛːr soː lɔŋt/" },
  { id: 1147, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag sparar undan lite varje månad för framtida planer. Det passar bra i många situationer.", vi: "Mình dành dụm một chút mỗi tháng cho các kế hoạch tương lai. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ ˈspɑːrar ˈɵnːdan ˈliːtɛ ˈvarːjɛ ˈmoːnad fœr ˈfrɑːmˌtiːda ˈplɑːnɛr/" },
  { id: 1148, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Vädret växlar snabbt, så det är bra att ha paraply med. Det hjälper mig att uttrycka mig klart.", vi: "Thời tiết đổi nhanh lắm nên mang theo ô là tốt nhất. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/ˈvɛːdrɛt ˈvɛkːslar snɑpt soː deːt ɛːr brɑː at hɑː pɑrɑˈplʏː meːd/" },
  { id: 1149, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag gillar tydliga och enkla rutiner i vardagen. Det känns avslappnat och vardagligt.", vi: "Mình thích những thói quen rõ ràng và đơn giản trong ngày. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ ˈjɪlːar ˈtʏːdliɡa ɔ ˈɛŋːkla rɵˈtiːnɛr ɪ ˈvɑːrˌdɑːɡɛn/" },
  { id: 1150, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Varje litet steg framåt räknas. Det är ett bra uttryck att kunna.", vi: "Mỗi bước tiến nhỏ về phía trước đều đáng quý. Đây là cách diễn đạt hay nên biết.", phonetic: "/ˈvarːjɛ ˈliːtɛt steːɡ ˈfrɑːmˌɔːt ˈrɛkːnas/" },
  { id: 1151, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Hemma och på fritiden säger jag: God morgon! Hur har du sovit?", vi: "Ở nhà và lúc rảnh mình nói: Chào buổi sáng! Bạn ngủ có ngon không?", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr hɑːr dʉː ˈsʊːvɪt/" },
  { id: 1152, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag tränar svenska säger jag: Jag vaknade tidigt idag och tog en lugn start.", vi: "Khi luyện tiếng Thụy Điển mình nói: Hôm nay mình dậy sớm và khởi đầu thật nhẹ nhàng.", phonetic: "/jɑːɡ ˈvɑːknadɛ ˈtiːdɪt ɪˈdɑːɡ ɔ tʊːɡ ɛn lɵŋn stɑʈ/" },
  { id: 1153, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "På utflykt eller promenad säger jag: Vad ska vi äta till middag ikväll?", vi: "Khi đi chơi hoặc đi dạo mình nói: Tối nay tụi mình sẽ ăn gì nhỉ?", phonetic: "/vɑːd skɑː viː ˈɛːta tɪl ˈmɪdːɑːɡ ɪˈkvɛlː/" },
  { id: 1154, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "I vardagen säger jag: Jag håller på att laga mat i köket nu.", vi: "Trong đời sống hằng ngày mình nói: Bây giờ mình đang nấu ăn trong bếp.", phonetic: "/jɑːɡ ˈhɔlːɛr pɔː at ˈlɑːɡa mɑːt ɪ ˈɕøːkɛt nʉː/" },
  { id: 1155, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag pratar med vänner säger jag: Kan du upprepa det lite långsammare, tack?", vi: "Khi trò chuyện với bạn bè mình nói: Bạn lặp lại chậm hơn một chút được không, cảm ơn bạn?", phonetic: "/kan dʉː ɵpːrɛˈpɑː deː ˈliːtɛ ˈlɔŋːsamːarɛ tak/" },
  { id: 1156, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Hemma och på fritiden säger jag: Jag förstår ungefär vad du menar, men jag övar fortfarande.", vi: "Ở nhà và lúc rảnh mình nói: Mình hiểu đại khái ý bạn, nhưng mình vẫn đang luyện thêm.", phonetic: "/jɑːɡ fœrˈstoːr ɵnːfɛˈjɛːr vɑːd dʉː ˈmeːnar mɛn jɑːɡ ˈøːvar ˈfɔrtˌfarːandɛ/" },
  { id: 1157, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag tränar svenska säger jag: Det här ordet är nytt för mig. Vad betyder det?", vi: "Khi luyện tiếng Thụy Điển mình nói: Từ này mới với mình. Nó có nghĩa là gì vậy?", phonetic: "/deːt hɛːr ˈuːɖɛt ɛːr nʏt fœr mej vɑːd bɛˈtʏːdɛr deː/" },
  { id: 1158, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "På utflykt eller promenad säger jag: Jag övar på att prata svenska varje dag.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình luyện nói tiếng Thụy Điển mỗi ngày.", phonetic: "/jɑːɡ ˈøːvar pɔː at ˈprɑːta ˈsvɛnːska ˈvarːjɛ dɑːɡ/" },
  { id: 1159, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "I vardagen säger jag: Det blir lättare ju mer man pratar.", vi: "Trong đời sống hằng ngày mình nói: Càng nói nhiều thì sẽ càng dễ hơn.", phonetic: "/deːt bliːr ˈlɛtːarɛ jʉː meːr man ˈprɑːtar/" },
  { id: 1160, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag pratar med vänner säger jag: Tack för hjälpen, det betydde mycket!", vi: "Khi trò chuyện với bạn bè mình nói: Cảm ơn vì đã giúp đỡ, điều đó có ý nghĩa lắm!", phonetic: "/tak fœr ˈjɛlːpɛn deː bɛˈtʏːdːɛ ˈmʏkːɛt/" },
  { id: 1161, topic: "Gia đình & người thân", sv: "Hemma och på fritiden säger jag: Jag pratar med min man varje dag om framtiden.", vi: "Ở nhà và lúc rảnh mình nói: Mình trò chuyện với chồng mỗi ngày về tương lai.", phonetic: "/jɑːɡ ˈprɑːtar meːd miːn man ˈvarːjɛ dɑːɡ ɔm ˈfrɑːmˌtiːdɛn/" },
  { id: 1162, topic: "Gia đình & người thân", sv: "När jag tränar svenska säger jag: Vi planerar vårt nya liv tillsammans i lugn takt.", vi: "Khi luyện tiếng Thụy Điển mình nói: Tụi mình lên kế hoạch cho cuộc sống mới cùng nhau một cách chầm chậm.", phonetic: "/viː plɑˈneːrar voːʈ ˈnʏːa liːv tɪlˈsamːanːs ɪ lɵŋn tɑkt/" },
  { id: 1163, topic: "Gia đình & người thân", sv: "På utflykt eller promenad säger jag: Jag tänker ofta på min mormor hemma.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình thường nhớ tới bà ngoại ở nhà.", phonetic: "/jɑːɡ ˈtɛŋːkɛr ˈɔfːta pɔː miːn ˈmʊːrmʊr ˈhɛmːa/" },
  { id: 1164, topic: "Gia đình & người thân", sv: "I vardagen säger jag: Familjen betyder allt när man är långt hemifrån.", vi: "Trong đời sống hằng ngày mình nói: Gia đình có ý nghĩa tất cả khi ở xa nhà.", phonetic: "/fɑˈmiːljɛn bɛˈtʏːdɛr alːt nɛːr man ɛːr lɔŋt ˈhɛmːɪˌfroːn/" },
  { id: 1165, topic: "Gia đình & người thân", sv: "När jag pratar med vänner säger jag: Vi ringer videosamtal på helgen när alla är lediga.", vi: "Khi trò chuyện với bạn bè mình nói: Tụi mình gọi video vào cuối tuần khi ai cũng rảnh.", phonetic: "/viː ˈrɪŋːɛr ˈviːdɛʊˌsamːtɑːl pɔː ˈhɛlːjɛn nɛːr ˈalːa ɛːr ˈleːdɪɡa/" },
  { id: 1166, topic: "Gia đình & người thân", sv: "Hemma och på fritiden säger jag: Han lagar god mat och stöttar mig alltid.", vi: "Ở nhà và lúc rảnh mình nói: Anh ấy nấu ăn ngon và luôn ủng hộ mình.", phonetic: "/han ˈlɑːɡar ɡuːd mɑːt ɔ ˈstœtːar mej ˈalːtiːd/" },
  { id: 1167, topic: "Gia đình & người thân", sv: "När jag tränar svenska säger jag: Att hjälpa varandra gör vardagen enklare.", vi: "Khi luyện tiếng Thụy Điển mình nói: Giúp đỡ lẫn nhau khiến cuộc sống hằng ngày nhẹ nhàng hơn.", phonetic: "/at ˈjɛlːpa vɑˈranːdra jøːr ˈvɑːrˌdɑːɡɛn ˈɛŋːklarɛ/" },
  { id: 1168, topic: "Gia đình & người thân", sv: "På utflykt eller promenad säger jag: Jag vill gärna bjuda hem familjen på middag någon gång.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình rất muốn mời gia đình đến nhà ăn tối một dịp nào đó.", phonetic: "/jɑːɡ vɪl ˈjɛːrna ˈbjʉːda hɛm fɑˈmiːljɛn pɔː ˈmɪdːɑːɡ ˈnoːɡɔn ɡɔŋ/" },
  { id: 1169, topic: "Gia đình & người thân", sv: "I vardagen säger jag: Det känns tryggt att ha någon som förstår en.", vi: "Trong đời sống hằng ngày mình nói: Thật vững tâm khi có người thấu hiểu mình.", phonetic: "/deːt ɕɛnːs trʏɡt at hɑː ˈnoːɡɔn sɔm fœrˈstoːr ɛn/" },
  { id: 1170, topic: "Gia đình & người thân", sv: "När jag pratar med vänner säger jag: Vi delar både glädje och små bekymmer.", vi: "Khi trò chuyện với bạn bè mình nói: Tụi mình chia sẻ cả niềm vui lẫn những nỗi lo nhỏ.", phonetic: "/viː ˈdeːlar ˈboːdɛ ˈɡlɛːdjɛ ɔ smoː bɛˈɕʏmːɛr/" },
  { id: 1171, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Hemma och på fritiden säger jag: Jag gillar att ta en promenad i parken efter jobbet.", vi: "Ở nhà và lúc rảnh mình nói: Mình thích đi dạo trong công viên sau giờ làm.", phonetic: "/jɑːɡ ˈjɪlːar at tɑː ɛn prʊmɛˈnɑːd ɪ ˈparːkɛn ˈɛfːtɛr ˈjɔbːɛt/" },
  { id: 1172, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag tränar svenska säger jag: Frisk luft och grönska hjälper mig att ladda om.", vi: "Khi luyện tiếng Thụy Điển mình nói: Không khí trong lành và cây xanh giúp mình nạp lại năng lượng.", phonetic: "/frɪsk lɵft ɔ ˈɡrœnːska ˈjɛlːpɛr mej at ˈladːa ɔm/" },
  { id: 1173, topic: "Thiên nhiên, đi dạo & du lịch", sv: "På utflykt eller promenad säger jag: Vilken vacker utsikt över sjön och skogen!", vi: "Khi đi chơi hoặc đi dạo mình nói: Khung cảnh nhìn ra hồ và rừng đẹp quá!", phonetic: "/ˈvɪlːkɛn ˈvakːɛr ˈʉːtˌsɪkːt ˈøːvɛr ɕøːn ɔ ˈskuːɡɛn/" },
  { id: 1174, topic: "Thiên nhiên, đi dạo & du lịch", sv: "I vardagen säger jag: Jag brukar ta foton på naturen när vi reser.", vi: "Trong đời sống hằng ngày mình nói: Mình hay chụp ảnh thiên nhiên khi tụi mình đi du lịch.", phonetic: "/jɑːɡ ˈbrʉːkar tɑː ˈfuːtɔn pɔː nɑtʉːˈreːn nɛːr viː ˈreːsɛr/" },
  { id: 1175, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag pratar med vänner säger jag: Vi åker gärna iväg på helgutflykter till nya platser.", vi: "Khi trò chuyện với bạn bè mình nói: Tụi mình thích đi chơi cuối tuần tới những vùng đất mới.", phonetic: "/viː ˈoːkɛr ˈjɛːrna ɪˈvɛːɡ pɔː ˈhɛljˌʉːtflʏkːtɛr tɪl ˈnʏːa ˈplatːsɛr/" },
  { id: 1176, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Hemma och på fritiden säger jag: Ljuset på morgonen och kvällen är så fint att fotografera.", vi: "Ở nhà và lúc rảnh mình nói: Ánh sáng buổi sáng và buổi chiều tối chụp ảnh đẹp lắm.", phonetic: "/ˈjʉːsɛt pɔː ˈmɔrːɔnɛn ɔ ˈkvɛlːɛn ɛːr soː fiːnt at fʊtʊɡrɑˈfeːra/" },
  { id: 1177, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag tränar svenska säger jag: Det är så tyst och rofyllt här borta vid vattnet.", vi: "Khi luyện tiếng Thụy Điển mình nói: Ở khu vực ven nước này thật yên tĩnh và thanh bình.", phonetic: "/deːt ɛːr soː tʏst ɔ ˈrʊːˌfʏlt hɛːr ˈbɔrːta viːd ˈvatːnɛt/" },
  { id: 1178, topic: "Thiên nhiên, đi dạo & du lịch", sv: "På utflykt eller promenad säger jag: Vi tar det lugnt och njuter av resan i vårt eget tempo.", vi: "Khi đi chơi hoặc đi dạo mình nói: Tụi mình đi thong thả và tận hưởng chuyến đi theo nhịp của riêng mình.", phonetic: "/viː tɑːr deː lɵŋt ɔ ˈnjʉːtɛr ɑːv ˈreːsan ɪ voːʈ ˈeːɡɛt ˈtɛmːpʊ/" },
  { id: 1179, topic: "Thiên nhiên, đi dạo & du lịch", sv: "I vardagen säger jag: Jag älskar när solen tittar fram mellan molnen.", vi: "Trong đời sống hằng ngày mình nói: Mình thích khoảnh khắc mặt trời ló dạng giữa những đám mây.", phonetic: "/jɑːɡ ˈɛlːskar nɛːr ˈsuːlɛn ˈtɪtːar fram ˈmɛlːan ˈmuːlnɛn/" },
  { id: 1180, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag pratar med vänner säger jag: Att komma ut i naturen rensar tankarna.", vi: "Khi trò chuyện với bạn bè mình nói: Ra ngoài thiên nhiên giúp đầu óc thư thái hẳn.", phonetic: "/at ˈkɔmːa ʉːt ɪ nɑtʉːˈreːn ˈrɛnːsar ˈtaŋːkarːa/" },
  { id: 1181, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Hemma och på fritiden säger jag: På kvällen gillar jag att varva ner hemma med en bra film.", vi: "Ở nhà và lúc rảnh mình nói: Buổi tối mình thích thư giãn ở nhà với một bộ phim hay.", phonetic: "/pɔː ˈkvɛlːɛn ˈjɪlːar jɑːɡ at ˈvarːva neːr ˈhɛmːa meːd ɛn brɑː fɪlm/" },
  { id: 1182, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag tränar svenska säger jag: Det är skönt att krypa upp i soffan efter en aktiv dag.", vi: "Khi luyện tiếng Thụy Điển mình nói: Thật dễ chịu khi cuộn mình trên ghế sofa sau một ngày năng động.", phonetic: "/deːt ɛːr ɕøːnt at ˈkrʏːpa ɵpː ɪ ˈsɔfːan ˈɛfːtɛr ɛn ˈakːtɪv dɑːɡ/" },
  { id: 1183, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På utflykt eller promenad säger jag: Vi spelar sällskapsspel och ordlekar när vi är många.", vi: "Khi đi chơi hoặc đi dạo mình nói: Tụi mình chơi board game và trò nối chữ khi có đông người.", phonetic: "/viː ˈsɛlːskɑpsˌspeːl ɔ ˈuːɖˌleːkar nɛːr viː ɛːr ˈmɔŋːa/" },
  { id: 1184, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "I vardagen säger jag: Det är så kul att skratta tillsammans över en spelomgång.", vi: "Trong đời sống hằng ngày mình nói: Cùng cười rôm rả qua một ván chơi vui thật đấy.", phonetic: "/deːt ɛːr soː kʉːl at ˈskratːa tɪlˈsamːanːs ˈøːvɛr ɛn ˈspeːlˌɔmːɡɔŋ/" },
  { id: 1185, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag pratar med vänner säger jag: Jag gillar att ha det städat och mysigt omkring mig.", vi: "Khi trò chuyện với bạn bè mình nói: Mình thích giữ không gian gọn gàng và ấm cúng quanh mình.", phonetic: "/jɑːɡ ˈjɪlːar at hɑː deː ˈstɛːdat ɔ ˈmʏːsɪt ɔmˈkrɪŋ mej/" },
  { id: 1186, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Hemma och på fritiden säger jag: En varm dusch och tystnad hjälper mig att somna gott.", vi: "Ở nhà và lúc rảnh mình nói: Một trận tắm nước ấm và sự yên tĩnh giúp mình ngủ ngon.", phonetic: "/ɛn varm dɵʃ ɔ ˈtʏsːtnɑd ˈjɛlːpɛr mej at ˈsɔmːna ɡɔt/" },
  { id: 1187, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag tränar svenska säger jag: Jag tar gärna en kort paus när jag behöver samla kraft.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình hay nghỉ giải lao ngắn khi cần lấy lại sức.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn kɔʈ paɵs nɛːr jɑːɡ bɛˈhøːvɛr ˈsamːla krɑft/" },
  { id: 1188, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På utflykt eller promenad säger jag: Vilken film eller serie tyckte du bäst om nyligen?", vi: "Khi đi chơi hoặc đi dạo mình nói: Gần đây bạn thích phim điện ảnh hay phim bộ nào nhất?", phonetic: "/ˈvɪlːkɛn fɪlm ˈɛlːɛr ˈseːrɪɛ ˈtʏkːtɛ dʉː bɛst ɔm ˈnʏːˌliːɡɛn/" },
  { id: 1189, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "I vardagen säger jag: Vi gör en enkel fika med kaffe och frukt idag.", vi: "Trong đời sống hằng ngày mình nói: Hôm nay tụi mình làm bữa fika nhẹ nhàng với cà phê và trái cây.", phonetic: "/viː jøːr ɛn ˈɛŋːkɛl ˈfiːka meːd ˈkafːɛ ɔ frɵkt ɪˈdɑːɡ/" },
  { id: 1190, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag pratar med vänner säger jag: Det känns skönt att bara vara sig själv i lugn och ro.", vi: "Khi trò chuyện với bạn bè mình nói: Thật thoải mái khi được là chính mình trong yên bình.", phonetic: "/deːt ɕɛnːs ɕøːnt at ˈbɑːra ˈvɑːra sej ɕɛlv ɪ lɵŋn ɔ rʊː/" },
  { id: 1191, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hemma och på fritiden säger jag: Ursäkta, vet du var närmaste busshållplats ligger?", vi: "Ở nhà và lúc rảnh mình nói: Xin lỗi, bạn có biết trạm xe buýt gần nhất ở đâu không?", phonetic: "/ˈʉːˌʂɛkːta veːt dʉː vɑːr ˈnɛrmastɛ ˈbɵsˌhɔlːplats ˈlɪɡːɛr/" },
  { id: 1192, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag tränar svenska säger jag: Jag behöver köpa frukt, grönsaker och bröd idag.", vi: "Khi luyện tiếng Thụy Điển mình nói: Hôm nay mình cần mua trái cây, rau củ và bánh mì.", phonetic: "/jɑːɡ bɛˈhøːvɛr ˈɕøːpa frɵkt ˈɡrœnˌsɑːkɛr ɔ brøːd ɪˈdɑːɡ/" },
  { id: 1193, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "På utflykt eller promenad säger jag: Hur mycket kostar det här totalt?", vi: "Khi đi chơi hoặc đi dạo mình nói: Món này tổng cộng giá bao nhiêu vậy?", phonetic: "/hʉːr ˈmʏkːɛt ˈkɔsːtar deːt hɛːr tʊˈtɑlt/" },
  { id: 1194, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "I vardagen säger jag: Jag tar gärna en påse, tack så mycket.", vi: "Trong đời sống hằng ngày mình nói: Cho mình xin một túi nhé, cảm ơn bạn nhiều.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn ˈpoːsɛ tak soː ˈmʏkːɛt/" },
  { id: 1195, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag pratar med vänner säger jag: Det är ganska svalt ute idag, så jag tar en tröja.", vi: "Khi trò chuyện với bạn bè mình nói: Hôm nay ngoài trời khá mát nên mình mặc thêm áo len.", phonetic: "/deːt ɛːr ˈɡanːsa svɑlt ˈʉːtɛ ɪˈdɑːɡ soː jɑːɡ tɑːr ɛn ˈtrœjːa/" },
  { id: 1196, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hemma och på fritiden säger jag: Vi åker kollektivt eller går när det inte är så långt.", vi: "Ở nhà và lúc rảnh mình nói: Tụi mình đi phương tiện công cộng hoặc đi bộ khi không quá xa.", phonetic: "/viː ˈoːkɛr kʊlːɛkˈtiːvt ˈɛlːɛr ɡoːr nɛːr deː ˈɪnːtɛ ɛːr soː lɔŋt/" },
  { id: 1197, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag tränar svenska säger jag: Jag sparar undan lite varje månad för framtida planer.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình dành dụm một chút mỗi tháng cho các kế hoạch tương lai.", phonetic: "/jɑːɡ ˈspɑːrar ˈɵnːdan ˈliːtɛ ˈvarːjɛ ˈmoːnad fœr ˈfrɑːmˌtiːda ˈplɑːnɛr/" },
  { id: 1198, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "På utflykt eller promenad säger jag: Vädret växlar snabbt, så det är bra att ha paraply med.", vi: "Khi đi chơi hoặc đi dạo mình nói: Thời tiết đổi nhanh lắm nên mang theo ô là tốt nhất.", phonetic: "/ˈvɛːdrɛt ˈvɛkːslar snɑpt soː deːt ɛːr brɑː at hɑː pɑrɑˈplʏː meːd/" },
  { id: 1199, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "I vardagen säger jag: Jag gillar tydliga och enkla rutiner i vardagen.", vi: "Trong đời sống hằng ngày mình nói: Mình thích những thói quen rõ ràng và đơn giản trong ngày.", phonetic: "/jɑːɡ ˈjɪlːar ˈtʏːdliɡa ɔ ˈɛŋːkla rɵˈtiːnɛr ɪ ˈvɑːrˌdɑːɡɛn/" },
  { id: 1200, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag pratar med vänner säger jag: Varje litet steg framåt räknas.", vi: "Khi trò chuyện với bạn bè mình nói: Mỗi bước tiến nhỏ về phía trước đều đáng quý.", phonetic: "/ˈvarːjɛ ˈliːtɛt steːɡ ˈfrɑːmˌɔːt ˈrɛkːnas/" },
  { id: 1201, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "God morgon! Hur har du sovit? Det hjälper mig att uttrycka mig klart.", vi: "Chào buổi sáng! Bạn ngủ có ngon không? Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr hɑːr dʉː ˈsʊːvɪt/" },
  { id: 1202, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag vaknade tidigt idag och tog en lugn start. Det känns avslappnat och vardagligt.", vi: "Hôm nay mình dậy sớm và khởi đầu thật nhẹ nhàng. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ ˈvɑːknadɛ ˈtiːdɪt ɪˈdɑːɡ ɔ tʊːɡ ɛn lɵŋn stɑʈ/" },
  { id: 1203, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Vad ska vi äta till middag ikväll? Det är ett bra uttryck att kunna.", vi: "Tối nay tụi mình sẽ ăn gì nhỉ? Đây là cách diễn đạt hay nên biết.", phonetic: "/vɑːd skɑː viː ˈɛːta tɪl ˈmɪdːɑːɡ ɪˈkvɛlː/" },
  { id: 1204, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag håller på att laga mat i köket nu. Jag använder det gärna i samtal.", vi: "Bây giờ mình đang nấu ăn trong bếp. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ ˈhɔlːɛr pɔː at ˈlɑːɡa mɑːt ɪ ˈɕøːkɛt nʉː/" },
  { id: 1205, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Kan du upprepa det lite långsammare, tack? Det passar bra i många situationer.", vi: "Bạn lặp lại chậm hơn một chút được không, cảm ơn bạn? Câu này dùng được trong nhiều tình huống.", phonetic: "/kan dʉː ɵpːrɛˈpɑː deː ˈliːtɛ ˈlɔŋːsamːarɛ tak/" },
  { id: 1206, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag förstår ungefär vad du menar, men jag övar fortfarande. Det hjälper mig att uttrycka mig klart.", vi: "Mình hiểu đại khái ý bạn, nhưng mình vẫn đang luyện thêm. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ fœrˈstoːr ɵnːfɛˈjɛːr vɑːd dʉː ˈmeːnar mɛn jɑːɡ ˈøːvar ˈfɔrtˌfarːandɛ/" },
  { id: 1207, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Det här ordet är nytt för mig. Vad betyder det? Det känns avslappnat och vardagligt.", vi: "Từ này mới với mình. Nó có nghĩa là gì vậy? Nghe rất tự nhiên và gần gũi.", phonetic: "/deːt hɛːr ˈuːɖɛt ɛːr nʏt fœr mej vɑːd bɛˈtʏːdɛr deː/" },
  { id: 1208, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag övar på att prata svenska varje dag. Det är ett bra uttryck att kunna.", vi: "Mình luyện nói tiếng Thụy Điển mỗi ngày. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈøːvar pɔː at ˈprɑːta ˈsvɛnːska ˈvarːjɛ dɑːɡ/" },
  { id: 1209, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Det blir lättare ju mer man pratar. Jag använder det gärna i samtal.", vi: "Càng nói nhiều thì sẽ càng dễ hơn. Mình thích dùng câu này khi trò chuyện.", phonetic: "/deːt bliːr ˈlɛtːarɛ jʉː meːr man ˈprɑːtar/" },
  { id: 1210, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Tack för hjälpen, det betydde mycket! Det passar bra i många situationer.", vi: "Cảm ơn vì đã giúp đỡ, điều đó có ý nghĩa lắm! Câu này dùng được trong nhiều tình huống.", phonetic: "/tak fœr ˈjɛlːpɛn deː bɛˈtʏːdːɛ ˈmʏkːɛt/" },
  { id: 1211, topic: "Gia đình & người thân", sv: "Jag pratar med min man varje dag om framtiden. Det hjälper mig att uttrycka mig klart.", vi: "Mình trò chuyện với chồng mỗi ngày về tương lai. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ ˈprɑːtar meːd miːn man ˈvarːjɛ dɑːɡ ɔm ˈfrɑːmˌtiːdɛn/" },
  { id: 1212, topic: "Gia đình & người thân", sv: "Vi planerar vårt nya liv tillsammans i lugn takt. Det känns avslappnat och vardagligt.", vi: "Tụi mình lên kế hoạch cho cuộc sống mới cùng nhau một cách chầm chậm. Nghe rất tự nhiên và gần gũi.", phonetic: "/viː plɑˈneːrar voːʈ ˈnʏːa liːv tɪlˈsamːanːs ɪ lɵŋn tɑkt/" },
  { id: 1213, topic: "Gia đình & người thân", sv: "Jag tänker ofta på min mormor hemma. Det är ett bra uttryck att kunna.", vi: "Mình thường nhớ tới bà ngoại ở nhà. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈtɛŋːkɛr ˈɔfːta pɔː miːn ˈmʊːrmʊr ˈhɛmːa/" },
  { id: 1214, topic: "Gia đình & người thân", sv: "Familjen betyder allt när man är långt hemifrån. Jag använder det gärna i samtal.", vi: "Gia đình có ý nghĩa tất cả khi ở xa nhà. Mình thích dùng câu này khi trò chuyện.", phonetic: "/fɑˈmiːljɛn bɛˈtʏːdɛr alːt nɛːr man ɛːr lɔŋt ˈhɛmːɪˌfroːn/" },
  { id: 1215, topic: "Gia đình & người thân", sv: "Vi ringer videosamtal på helgen när alla är lediga. Det passar bra i många situationer.", vi: "Tụi mình gọi video vào cuối tuần khi ai cũng rảnh. Câu này dùng được trong nhiều tình huống.", phonetic: "/viː ˈrɪŋːɛr ˈviːdɛʊˌsamːtɑːl pɔː ˈhɛlːjɛn nɛːr ˈalːa ɛːr ˈleːdɪɡa/" },
  { id: 1216, topic: "Gia đình & người thân", sv: "Han lagar god mat och stöttar mig alltid. Det hjälper mig att uttrycka mig klart.", vi: "Anh ấy nấu ăn ngon và luôn ủng hộ mình. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/han ˈlɑːɡar ɡuːd mɑːt ɔ ˈstœtːar mej ˈalːtiːd/" },
  { id: 1217, topic: "Gia đình & người thân", sv: "Att hjälpa varandra gör vardagen enklare. Det känns avslappnat och vardagligt.", vi: "Giúp đỡ lẫn nhau khiến cuộc sống hằng ngày nhẹ nhàng hơn. Nghe rất tự nhiên và gần gũi.", phonetic: "/at ˈjɛlːpa vɑˈranːdra jøːr ˈvɑːrˌdɑːɡɛn ˈɛŋːklarɛ/" },
  { id: 1218, topic: "Gia đình & người thân", sv: "Jag vill gärna bjuda hem familjen på middag någon gång. Det är ett bra uttryck att kunna.", vi: "Mình rất muốn mời gia đình đến nhà ăn tối một dịp nào đó. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ vɪl ˈjɛːrna ˈbjʉːda hɛm fɑˈmiːljɛn pɔː ˈmɪdːɑːɡ ˈnoːɡɔn ɡɔŋ/" },
  { id: 1219, topic: "Gia đình & người thân", sv: "Det känns tryggt att ha någon som förstår en. Jag använder det gärna i samtal.", vi: "Thật vững tâm khi có người thấu hiểu mình. Mình thích dùng câu này khi trò chuyện.", phonetic: "/deːt ɕɛnːs trʏɡt at hɑː ˈnoːɡɔn sɔm fœrˈstoːr ɛn/" },
  { id: 1220, topic: "Gia đình & người thân", sv: "Vi delar både glädje och små bekymmer. Det passar bra i många situationer.", vi: "Tụi mình chia sẻ cả niềm vui lẫn những nỗi lo nhỏ. Câu này dùng được trong nhiều tình huống.", phonetic: "/viː ˈdeːlar ˈboːdɛ ˈɡlɛːdjɛ ɔ smoː bɛˈɕʏmːɛr/" },
  { id: 1221, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag gillar att ta en promenad i parken efter jobbet. Det hjälper mig att uttrycka mig klart.", vi: "Mình thích đi dạo trong công viên sau giờ làm. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ ˈjɪlːar at tɑː ɛn prʊmɛˈnɑːd ɪ ˈparːkɛn ˈɛfːtɛr ˈjɔbːɛt/" },
  { id: 1222, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Frisk luft och grönska hjälper mig att ladda om. Det känns avslappnat och vardagligt.", vi: "Không khí trong lành và cây xanh giúp mình nạp lại năng lượng. Nghe rất tự nhiên và gần gũi.", phonetic: "/frɪsk lɵft ɔ ˈɡrœnːska ˈjɛlːpɛr mej at ˈladːa ɔm/" },
  { id: 1223, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vilken vacker utsikt över sjön och skogen! Det är ett bra uttryck att kunna.", vi: "Khung cảnh nhìn ra hồ và rừng đẹp quá! Đây là cách diễn đạt hay nên biết.", phonetic: "/ˈvɪlːkɛn ˈvakːɛr ˈʉːtˌsɪkːt ˈøːvɛr ɕøːn ɔ ˈskuːɡɛn/" },
  { id: 1224, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag brukar ta foton på naturen när vi reser. Jag använder det gärna i samtal.", vi: "Mình hay chụp ảnh thiên nhiên khi tụi mình đi du lịch. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ ˈbrʉːkar tɑː ˈfuːtɔn pɔː nɑtʉːˈreːn nɛːr viː ˈreːsɛr/" },
  { id: 1225, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vi åker gärna iväg på helgutflykter till nya platser. Det passar bra i många situationer.", vi: "Tụi mình thích đi chơi cuối tuần tới những vùng đất mới. Câu này dùng được trong nhiều tình huống.", phonetic: "/viː ˈoːkɛr ˈjɛːrna ɪˈvɛːɡ pɔː ˈhɛljˌʉːtflʏkːtɛr tɪl ˈnʏːa ˈplatːsɛr/" },
  { id: 1226, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Ljuset på morgonen och kvällen är så fint att fotografera. Det hjälper mig att uttrycka mig klart.", vi: "Ánh sáng buổi sáng và buổi chiều tối chụp ảnh đẹp lắm. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/ˈjʉːsɛt pɔː ˈmɔrːɔnɛn ɔ ˈkvɛlːɛn ɛːr soː fiːnt at fʊtʊɡrɑˈfeːra/" },
  { id: 1227, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Det är så tyst och rofyllt här borta vid vattnet. Det känns avslappnat och vardagligt.", vi: "Ở khu vực ven nước này thật yên tĩnh và thanh bình. Nghe rất tự nhiên và gần gũi.", phonetic: "/deːt ɛːr soː tʏst ɔ ˈrʊːˌfʏlt hɛːr ˈbɔrːta viːd ˈvatːnɛt/" },
  { id: 1228, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vi tar det lugnt och njuter av resan i vårt eget tempo. Det är ett bra uttryck att kunna.", vi: "Tụi mình đi thong thả và tận hưởng chuyến đi theo nhịp của riêng mình. Đây là cách diễn đạt hay nên biết.", phonetic: "/viː tɑːr deː lɵŋt ɔ ˈnjʉːtɛr ɑːv ˈreːsan ɪ voːʈ ˈeːɡɛt ˈtɛmːpʊ/" },
  { id: 1229, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag älskar när solen tittar fram mellan molnen. Jag använder det gärna i samtal.", vi: "Mình thích khoảnh khắc mặt trời ló dạng giữa những đám mây. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ ˈɛlːskar nɛːr ˈsuːlɛn ˈtɪtːar fram ˈmɛlːan ˈmuːlnɛn/" },
  { id: 1230, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Att komma ut i naturen rensar tankarna. Det passar bra i många situationer.", vi: "Ra ngoài thiên nhiên giúp đầu óc thư thái hẳn. Câu này dùng được trong nhiều tình huống.", phonetic: "/at ˈkɔmːa ʉːt ɪ nɑtʉːˈreːn ˈrɛnːsar ˈtaŋːkarːa/" },
  { id: 1231, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På kvällen gillar jag att varva ner hemma med en bra film. Det hjälper mig att uttrycka mig klart.", vi: "Buổi tối mình thích thư giãn ở nhà với một bộ phim hay. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/pɔː ˈkvɛlːɛn ˈjɪlːar jɑːɡ at ˈvarːva neːr ˈhɛmːa meːd ɛn brɑː fɪlm/" },
  { id: 1232, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det är skönt att krypa upp i soffan efter en aktiv dag. Det känns avslappnat och vardagligt.", vi: "Thật dễ chịu khi cuộn mình trên ghế sofa sau một ngày năng động. Nghe rất tự nhiên và gần gũi.", phonetic: "/deːt ɛːr ɕøːnt at ˈkrʏːpa ɵpː ɪ ˈsɔfːan ˈɛfːtɛr ɛn ˈakːtɪv dɑːɡ/" },
  { id: 1233, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vi spelar sällskapsspel och ordlekar när vi är många. Det är ett bra uttryck att kunna.", vi: "Tụi mình chơi board game và trò nối chữ khi có đông người. Đây là cách diễn đạt hay nên biết.", phonetic: "/viː ˈsɛlːskɑpsˌspeːl ɔ ˈuːɖˌleːkar nɛːr viː ɛːr ˈmɔŋːa/" },
  { id: 1234, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det är så kul att skratta tillsammans över en spelomgång. Jag använder det gärna i samtal.", vi: "Cùng cười rôm rả qua một ván chơi vui thật đấy. Mình thích dùng câu này khi trò chuyện.", phonetic: "/deːt ɛːr soː kʉːl at ˈskratːa tɪlˈsamːanːs ˈøːvɛr ɛn ˈspeːlˌɔmːɡɔŋ/" },
  { id: 1235, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Jag gillar att ha det städat och mysigt omkring mig. Det passar bra i många situationer.", vi: "Mình thích giữ không gian gọn gàng và ấm cúng quanh mình. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ ˈjɪlːar at hɑː deː ˈstɛːdat ɔ ˈmʏːsɪt ɔmˈkrɪŋ mej/" },
  { id: 1236, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "En varm dusch och tystnad hjälper mig att somna gott. Det hjälper mig att uttrycka mig klart.", vi: "Một trận tắm nước ấm và sự yên tĩnh giúp mình ngủ ngon. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/ɛn varm dɵʃ ɔ ˈtʏsːtnɑd ˈjɛlːpɛr mej at ˈsɔmːna ɡɔt/" },
  { id: 1237, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Jag tar gärna en kort paus när jag behöver samla kraft. Det känns avslappnat och vardagligt.", vi: "Mình hay nghỉ giải lao ngắn khi cần lấy lại sức. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn kɔʈ paɵs nɛːr jɑːɡ bɛˈhøːvɛr ˈsamːla krɑft/" },
  { id: 1238, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vilken film eller serie tyckte du bäst om nyligen? Det är ett bra uttryck att kunna.", vi: "Gần đây bạn thích phim điện ảnh hay phim bộ nào nhất? Đây là cách diễn đạt hay nên biết.", phonetic: "/ˈvɪlːkɛn fɪlm ˈɛlːɛr ˈseːrɪɛ ˈtʏkːtɛ dʉː bɛst ɔm ˈnʏːˌliːɡɛn/" },
  { id: 1239, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vi gör en enkel fika med kaffe och frukt idag. Jag använder det gärna i samtal.", vi: "Hôm nay tụi mình làm bữa fika nhẹ nhàng với cà phê và trái cây. Mình thích dùng câu này khi trò chuyện.", phonetic: "/viː jøːr ɛn ˈɛŋːkɛl ˈfiːka meːd ˈkafːɛ ɔ frɵkt ɪˈdɑːɡ/" },
  { id: 1240, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det känns skönt att bara vara sig själv i lugn och ro. Det passar bra i många situationer.", vi: "Thật thoải mái khi được là chính mình trong yên bình. Câu này dùng được trong nhiều tình huống.", phonetic: "/deːt ɕɛnːs ɕøːnt at ˈbɑːra ˈvɑːra sej ɕɛlv ɪ lɵŋn ɔ rʊː/" },
  { id: 1241, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Ursäkta, vet du var närmaste busshållplats ligger? Det hjälper mig att uttrycka mig klart.", vi: "Xin lỗi, bạn có biết trạm xe buýt gần nhất ở đâu không? Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/ˈʉːˌʂɛkːta veːt dʉː vɑːr ˈnɛrmastɛ ˈbɵsˌhɔlːplats ˈlɪɡːɛr/" },
  { id: 1242, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag behöver köpa frukt, grönsaker och bröd idag. Det känns avslappnat och vardagligt.", vi: "Hôm nay mình cần mua trái cây, rau củ và bánh mì. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ bɛˈhøːvɛr ˈɕøːpa frɵkt ˈɡrœnˌsɑːkɛr ɔ brøːd ɪˈdɑːɡ/" },
  { id: 1243, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hur mycket kostar det här totalt? Det är ett bra uttryck att kunna.", vi: "Món này tổng cộng giá bao nhiêu vậy? Đây là cách diễn đạt hay nên biết.", phonetic: "/hʉːr ˈmʏkːɛt ˈkɔsːtar deːt hɛːr tʊˈtɑlt/" },
  { id: 1244, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag tar gärna en påse, tack så mycket. Jag använder det gärna i samtal.", vi: "Cho mình xin một túi nhé, cảm ơn bạn nhiều. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn ˈpoːsɛ tak soː ˈmʏkːɛt/" },
  { id: 1245, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Det är ganska svalt ute idag, så jag tar en tröja. Det passar bra i många situationer.", vi: "Hôm nay ngoài trời khá mát nên mình mặc thêm áo len. Câu này dùng được trong nhiều tình huống.", phonetic: "/deːt ɛːr ˈɡanːsa svɑlt ˈʉːtɛ ɪˈdɑːɡ soː jɑːɡ tɑːr ɛn ˈtrœjːa/" },
  { id: 1246, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Vi åker kollektivt eller går när det inte är så långt. Det hjälper mig att uttrycka mig klart.", vi: "Tụi mình đi phương tiện công cộng hoặc đi bộ khi không quá xa. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/viː ˈoːkɛr kʊlːɛkˈtiːvt ˈɛlːɛr ɡoːr nɛːr deː ˈɪnːtɛ ɛːr soː lɔŋt/" },
  { id: 1247, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag sparar undan lite varje månad för framtida planer. Det känns avslappnat och vardagligt.", vi: "Mình dành dụm một chút mỗi tháng cho các kế hoạch tương lai. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ ˈspɑːrar ˈɵnːdan ˈliːtɛ ˈvarːjɛ ˈmoːnad fœr ˈfrɑːmˌtiːda ˈplɑːnɛr/" },
  { id: 1248, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Vädret växlar snabbt, så det är bra att ha paraply med. Det är ett bra uttryck att kunna.", vi: "Thời tiết đổi nhanh lắm nên mang theo ô là tốt nhất. Đây là cách diễn đạt hay nên biết.", phonetic: "/ˈvɛːdrɛt ˈvɛkːslar snɑpt soː deːt ɛːr brɑː at hɑː pɑrɑˈplʏː meːd/" },
  { id: 1249, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag gillar tydliga och enkla rutiner i vardagen. Jag använder det gärna i samtal.", vi: "Mình thích những thói quen rõ ràng và đơn giản trong ngày. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ ˈjɪlːar ˈtʏːdliɡa ɔ ˈɛŋːkla rɵˈtiːnɛr ɪ ˈvɑːrˌdɑːɡɛn/" },
  { id: 1250, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Varje litet steg framåt räknas. Det passar bra i många situationer.", vi: "Mỗi bước tiến nhỏ về phía trước đều đáng quý. Câu này dùng được trong nhiều tình huống.", phonetic: "/ˈvarːjɛ ˈliːtɛt steːɡ ˈfrɑːmˌɔːt ˈrɛkːnas/" },
  { id: 1251, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "På utflykt eller promenad säger jag: God morgon! Hur har du sovit?", vi: "Khi đi chơi hoặc đi dạo mình nói: Chào buổi sáng! Bạn ngủ có ngon không?", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr hɑːr dʉː ˈsʊːvɪt/" },
  { id: 1252, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "I vardagen säger jag: Jag vaknade tidigt idag och tog en lugn start.", vi: "Trong đời sống hằng ngày mình nói: Hôm nay mình dậy sớm và khởi đầu thật nhẹ nhàng.", phonetic: "/jɑːɡ ˈvɑːknadɛ ˈtiːdɪt ɪˈdɑːɡ ɔ tʊːɡ ɛn lɵŋn stɑʈ/" },
  { id: 1253, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag pratar med vänner säger jag: Vad ska vi äta till middag ikväll?", vi: "Khi trò chuyện với bạn bè mình nói: Tối nay tụi mình sẽ ăn gì nhỉ?", phonetic: "/vɑːd skɑː viː ˈɛːta tɪl ˈmɪdːɑːɡ ɪˈkvɛlː/" },
  { id: 1254, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Hemma och på fritiden säger jag: Jag håller på att laga mat i köket nu.", vi: "Ở nhà và lúc rảnh mình nói: Bây giờ mình đang nấu ăn trong bếp.", phonetic: "/jɑːɡ ˈhɔlːɛr pɔː at ˈlɑːɡa mɑːt ɪ ˈɕøːkɛt nʉː/" },
  { id: 1255, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag tränar svenska säger jag: Kan du upprepa det lite långsammare, tack?", vi: "Khi luyện tiếng Thụy Điển mình nói: Bạn lặp lại chậm hơn một chút được không, cảm ơn bạn?", phonetic: "/kan dʉː ɵpːrɛˈpɑː deː ˈliːtɛ ˈlɔŋːsamːarɛ tak/" },
  { id: 1256, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "På utflykt eller promenad säger jag: Jag förstår ungefär vad du menar, men jag övar fortfarande.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình hiểu đại khái ý bạn, nhưng mình vẫn đang luyện thêm.", phonetic: "/jɑːɡ fœrˈstoːr ɵnːfɛˈjɛːr vɑːd dʉː ˈmeːnar mɛn jɑːɡ ˈøːvar ˈfɔrtˌfarːandɛ/" },
  { id: 1257, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "I vardagen säger jag: Det här ordet är nytt för mig. Vad betyder det?", vi: "Trong đời sống hằng ngày mình nói: Từ này mới với mình. Nó có nghĩa là gì vậy?", phonetic: "/deːt hɛːr ˈuːɖɛt ɛːr nʏt fœr mej vɑːd bɛˈtʏːdɛr deː/" },
  { id: 1258, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag pratar med vänner säger jag: Jag övar på att prata svenska varje dag.", vi: "Khi trò chuyện với bạn bè mình nói: Mình luyện nói tiếng Thụy Điển mỗi ngày.", phonetic: "/jɑːɡ ˈøːvar pɔː at ˈprɑːta ˈsvɛnːska ˈvarːjɛ dɑːɡ/" },
  { id: 1259, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Hemma och på fritiden säger jag: Det blir lättare ju mer man pratar.", vi: "Ở nhà và lúc rảnh mình nói: Càng nói nhiều thì sẽ càng dễ hơn.", phonetic: "/deːt bliːr ˈlɛtːarɛ jʉː meːr man ˈprɑːtar/" },
  { id: 1260, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag tränar svenska säger jag: Tack för hjälpen, det betydde mycket!", vi: "Khi luyện tiếng Thụy Điển mình nói: Cảm ơn vì đã giúp đỡ, điều đó có ý nghĩa lắm!", phonetic: "/tak fœr ˈjɛlːpɛn deː bɛˈtʏːdːɛ ˈmʏkːɛt/" },
  { id: 1261, topic: "Gia đình & người thân", sv: "På utflykt eller promenad säger jag: Jag pratar med min man varje dag om framtiden.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình trò chuyện với chồng mỗi ngày về tương lai.", phonetic: "/jɑːɡ ˈprɑːtar meːd miːn man ˈvarːjɛ dɑːɡ ɔm ˈfrɑːmˌtiːdɛn/" },
  { id: 1262, topic: "Gia đình & người thân", sv: "I vardagen säger jag: Vi planerar vårt nya liv tillsammans i lugn takt.", vi: "Trong đời sống hằng ngày mình nói: Tụi mình lên kế hoạch cho cuộc sống mới cùng nhau một cách chầm chậm.", phonetic: "/viː plɑˈneːrar voːʈ ˈnʏːa liːv tɪlˈsamːanːs ɪ lɵŋn tɑkt/" },
  { id: 1263, topic: "Gia đình & người thân", sv: "När jag pratar med vänner säger jag: Jag tänker ofta på min mormor hemma.", vi: "Khi trò chuyện với bạn bè mình nói: Mình thường nhớ tới bà ngoại ở nhà.", phonetic: "/jɑːɡ ˈtɛŋːkɛr ˈɔfːta pɔː miːn ˈmʊːrmʊr ˈhɛmːa/" },
  { id: 1264, topic: "Gia đình & người thân", sv: "Hemma och på fritiden säger jag: Familjen betyder allt när man är långt hemifrån.", vi: "Ở nhà và lúc rảnh mình nói: Gia đình có ý nghĩa tất cả khi ở xa nhà.", phonetic: "/fɑˈmiːljɛn bɛˈtʏːdɛr alːt nɛːr man ɛːr lɔŋt ˈhɛmːɪˌfroːn/" },
  { id: 1265, topic: "Gia đình & người thân", sv: "När jag tränar svenska säger jag: Vi ringer videosamtal på helgen när alla är lediga.", vi: "Khi luyện tiếng Thụy Điển mình nói: Tụi mình gọi video vào cuối tuần khi ai cũng rảnh.", phonetic: "/viː ˈrɪŋːɛr ˈviːdɛʊˌsamːtɑːl pɔː ˈhɛlːjɛn nɛːr ˈalːa ɛːr ˈleːdɪɡa/" },
  { id: 1266, topic: "Gia đình & người thân", sv: "På utflykt eller promenad säger jag: Han lagar god mat och stöttar mig alltid.", vi: "Khi đi chơi hoặc đi dạo mình nói: Anh ấy nấu ăn ngon và luôn ủng hộ mình.", phonetic: "/han ˈlɑːɡar ɡuːd mɑːt ɔ ˈstœtːar mej ˈalːtiːd/" },
  { id: 1267, topic: "Gia đình & người thân", sv: "I vardagen säger jag: Att hjälpa varandra gör vardagen enklare.", vi: "Trong đời sống hằng ngày mình nói: Giúp đỡ lẫn nhau khiến cuộc sống hằng ngày nhẹ nhàng hơn.", phonetic: "/at ˈjɛlːpa vɑˈranːdra jøːr ˈvɑːrˌdɑːɡɛn ˈɛŋːklarɛ/" },
  { id: 1268, topic: "Gia đình & người thân", sv: "När jag pratar med vänner säger jag: Jag vill gärna bjuda hem familjen på middag någon gång.", vi: "Khi trò chuyện với bạn bè mình nói: Mình rất muốn mời gia đình đến nhà ăn tối một dịp nào đó.", phonetic: "/jɑːɡ vɪl ˈjɛːrna ˈbjʉːda hɛm fɑˈmiːljɛn pɔː ˈmɪdːɑːɡ ˈnoːɡɔn ɡɔŋ/" },
  { id: 1269, topic: "Gia đình & người thân", sv: "Hemma och på fritiden säger jag: Det känns tryggt att ha någon som förstår en.", vi: "Ở nhà và lúc rảnh mình nói: Thật vững tâm khi có người thấu hiểu mình.", phonetic: "/deːt ɕɛnːs trʏɡt at hɑː ˈnoːɡɔn sɔm fœrˈstoːr ɛn/" },
  { id: 1270, topic: "Gia đình & người thân", sv: "När jag tränar svenska säger jag: Vi delar både glädje och små bekymmer.", vi: "Khi luyện tiếng Thụy Điển mình nói: Tụi mình chia sẻ cả niềm vui lẫn những nỗi lo nhỏ.", phonetic: "/viː ˈdeːlar ˈboːdɛ ˈɡlɛːdjɛ ɔ smoː bɛˈɕʏmːɛr/" },
  { id: 1271, topic: "Thiên nhiên, đi dạo & du lịch", sv: "På utflykt eller promenad säger jag: Jag gillar att ta en promenad i parken efter jobbet.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình thích đi dạo trong công viên sau giờ làm.", phonetic: "/jɑːɡ ˈjɪlːar at tɑː ɛn prʊmɛˈnɑːd ɪ ˈparːkɛn ˈɛfːtɛr ˈjɔbːɛt/" },
  { id: 1272, topic: "Thiên nhiên, đi dạo & du lịch", sv: "I vardagen säger jag: Frisk luft och grönska hjälper mig att ladda om.", vi: "Trong đời sống hằng ngày mình nói: Không khí trong lành và cây xanh giúp mình nạp lại năng lượng.", phonetic: "/frɪsk lɵft ɔ ˈɡrœnːska ˈjɛlːpɛr mej at ˈladːa ɔm/" },
  { id: 1273, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag pratar med vänner säger jag: Vilken vacker utsikt över sjön och skogen!", vi: "Khi trò chuyện với bạn bè mình nói: Khung cảnh nhìn ra hồ và rừng đẹp quá!", phonetic: "/ˈvɪlːkɛn ˈvakːɛr ˈʉːtˌsɪkːt ˈøːvɛr ɕøːn ɔ ˈskuːɡɛn/" },
  { id: 1274, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Hemma och på fritiden säger jag: Jag brukar ta foton på naturen när vi reser.", vi: "Ở nhà và lúc rảnh mình nói: Mình hay chụp ảnh thiên nhiên khi tụi mình đi du lịch.", phonetic: "/jɑːɡ ˈbrʉːkar tɑː ˈfuːtɔn pɔː nɑtʉːˈreːn nɛːr viː ˈreːsɛr/" },
  { id: 1275, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag tränar svenska säger jag: Vi åker gärna iväg på helgutflykter till nya platser.", vi: "Khi luyện tiếng Thụy Điển mình nói: Tụi mình thích đi chơi cuối tuần tới những vùng đất mới.", phonetic: "/viː ˈoːkɛr ˈjɛːrna ɪˈvɛːɡ pɔː ˈhɛljˌʉːtflʏkːtɛr tɪl ˈnʏːa ˈplatːsɛr/" },
  { id: 1276, topic: "Thiên nhiên, đi dạo & du lịch", sv: "På utflykt eller promenad säger jag: Ljuset på morgonen och kvällen är så fint att fotografera.", vi: "Khi đi chơi hoặc đi dạo mình nói: Ánh sáng buổi sáng và buổi chiều tối chụp ảnh đẹp lắm.", phonetic: "/ˈjʉːsɛt pɔː ˈmɔrːɔnɛn ɔ ˈkvɛlːɛn ɛːr soː fiːnt at fʊtʊɡrɑˈfeːra/" },
  { id: 1277, topic: "Thiên nhiên, đi dạo & du lịch", sv: "I vardagen säger jag: Det är så tyst och rofyllt här borta vid vattnet.", vi: "Trong đời sống hằng ngày mình nói: Ở khu vực ven nước này thật yên tĩnh và thanh bình.", phonetic: "/deːt ɛːr soː tʏst ɔ ˈrʊːˌfʏlt hɛːr ˈbɔrːta viːd ˈvatːnɛt/" },
  { id: 1278, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag pratar med vänner säger jag: Vi tar det lugnt och njuter av resan i vårt eget tempo.", vi: "Khi trò chuyện với bạn bè mình nói: Tụi mình đi thong thả và tận hưởng chuyến đi theo nhịp của riêng mình.", phonetic: "/viː tɑːr deː lɵŋt ɔ ˈnjʉːtɛr ɑːv ˈreːsan ɪ voːʈ ˈeːɡɛt ˈtɛmːpʊ/" },
  { id: 1279, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Hemma och på fritiden säger jag: Jag älskar när solen tittar fram mellan molnen.", vi: "Ở nhà và lúc rảnh mình nói: Mình thích khoảnh khắc mặt trời ló dạng giữa những đám mây.", phonetic: "/jɑːɡ ˈɛlːskar nɛːr ˈsuːlɛn ˈtɪtːar fram ˈmɛlːan ˈmuːlnɛn/" },
  { id: 1280, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag tränar svenska säger jag: Att komma ut i naturen rensar tankarna.", vi: "Khi luyện tiếng Thụy Điển mình nói: Ra ngoài thiên nhiên giúp đầu óc thư thái hẳn.", phonetic: "/at ˈkɔmːa ʉːt ɪ nɑtʉːˈreːn ˈrɛnːsar ˈtaŋːkarːa/" },
  { id: 1281, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På utflykt eller promenad säger jag: På kvällen gillar jag att varva ner hemma med en bra film.", vi: "Khi đi chơi hoặc đi dạo mình nói: Buổi tối mình thích thư giãn ở nhà với một bộ phim hay.", phonetic: "/pɔː ˈkvɛlːɛn ˈjɪlːar jɑːɡ at ˈvarːva neːr ˈhɛmːa meːd ɛn brɑː fɪlm/" },
  { id: 1282, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "I vardagen säger jag: Det är skönt att krypa upp i soffan efter en aktiv dag.", vi: "Trong đời sống hằng ngày mình nói: Thật dễ chịu khi cuộn mình trên ghế sofa sau một ngày năng động.", phonetic: "/deːt ɛːr ɕøːnt at ˈkrʏːpa ɵpː ɪ ˈsɔfːan ˈɛfːtɛr ɛn ˈakːtɪv dɑːɡ/" },
  { id: 1283, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag pratar med vänner säger jag: Vi spelar sällskapsspel och ordlekar när vi är många.", vi: "Khi trò chuyện với bạn bè mình nói: Tụi mình chơi board game và trò nối chữ khi có đông người.", phonetic: "/viː ˈsɛlːskɑpsˌspeːl ɔ ˈuːɖˌleːkar nɛːr viː ɛːr ˈmɔŋːa/" },
  { id: 1284, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Hemma och på fritiden säger jag: Det är så kul att skratta tillsammans över en spelomgång.", vi: "Ở nhà và lúc rảnh mình nói: Cùng cười rôm rả qua một ván chơi vui thật đấy.", phonetic: "/deːt ɛːr soː kʉːl at ˈskratːa tɪlˈsamːanːs ˈøːvɛr ɛn ˈspeːlˌɔmːɡɔŋ/" },
  { id: 1285, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag tränar svenska säger jag: Jag gillar att ha det städat och mysigt omkring mig.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình thích giữ không gian gọn gàng và ấm cúng quanh mình.", phonetic: "/jɑːɡ ˈjɪlːar at hɑː deː ˈstɛːdat ɔ ˈmʏːsɪt ɔmˈkrɪŋ mej/" },
  { id: 1286, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På utflykt eller promenad säger jag: En varm dusch och tystnad hjälper mig att somna gott.", vi: "Khi đi chơi hoặc đi dạo mình nói: Một trận tắm nước ấm và sự yên tĩnh giúp mình ngủ ngon.", phonetic: "/ɛn varm dɵʃ ɔ ˈtʏsːtnɑd ˈjɛlːpɛr mej at ˈsɔmːna ɡɔt/" },
  { id: 1287, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "I vardagen säger jag: Jag tar gärna en kort paus när jag behöver samla kraft.", vi: "Trong đời sống hằng ngày mình nói: Mình hay nghỉ giải lao ngắn khi cần lấy lại sức.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn kɔʈ paɵs nɛːr jɑːɡ bɛˈhøːvɛr ˈsamːla krɑft/" },
  { id: 1288, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag pratar med vänner säger jag: Vilken film eller serie tyckte du bäst om nyligen?", vi: "Khi trò chuyện với bạn bè mình nói: Gần đây bạn thích phim điện ảnh hay phim bộ nào nhất?", phonetic: "/ˈvɪlːkɛn fɪlm ˈɛlːɛr ˈseːrɪɛ ˈtʏkːtɛ dʉː bɛst ɔm ˈnʏːˌliːɡɛn/" },
  { id: 1289, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Hemma och på fritiden säger jag: Vi gör en enkel fika med kaffe och frukt idag.", vi: "Ở nhà và lúc rảnh mình nói: Hôm nay tụi mình làm bữa fika nhẹ nhàng với cà phê và trái cây.", phonetic: "/viː jøːr ɛn ˈɛŋːkɛl ˈfiːka meːd ˈkafːɛ ɔ frɵkt ɪˈdɑːɡ/" },
  { id: 1290, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag tränar svenska säger jag: Det känns skönt att bara vara sig själv i lugn och ro.", vi: "Khi luyện tiếng Thụy Điển mình nói: Thật thoải mái khi được là chính mình trong yên bình.", phonetic: "/deːt ɕɛnːs ɕøːnt at ˈbɑːra ˈvɑːra sej ɕɛlv ɪ lɵŋn ɔ rʊː/" },
  { id: 1291, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "På utflykt eller promenad säger jag: Ursäkta, vet du var närmaste busshållplats ligger?", vi: "Khi đi chơi hoặc đi dạo mình nói: Xin lỗi, bạn có biết trạm xe buýt gần nhất ở đâu không?", phonetic: "/ˈʉːˌʂɛkːta veːt dʉː vɑːr ˈnɛrmastɛ ˈbɵsˌhɔlːplats ˈlɪɡːɛr/" },
  { id: 1292, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "I vardagen säger jag: Jag behöver köpa frukt, grönsaker och bröd idag.", vi: "Trong đời sống hằng ngày mình nói: Hôm nay mình cần mua trái cây, rau củ và bánh mì.", phonetic: "/jɑːɡ bɛˈhøːvɛr ˈɕøːpa frɵkt ˈɡrœnˌsɑːkɛr ɔ brøːd ɪˈdɑːɡ/" },
  { id: 1293, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag pratar med vänner säger jag: Hur mycket kostar det här totalt?", vi: "Khi trò chuyện với bạn bè mình nói: Món này tổng cộng giá bao nhiêu vậy?", phonetic: "/hʉːr ˈmʏkːɛt ˈkɔsːtar deːt hɛːr tʊˈtɑlt/" },
  { id: 1294, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hemma och på fritiden säger jag: Jag tar gärna en påse, tack så mycket.", vi: "Ở nhà và lúc rảnh mình nói: Cho mình xin một túi nhé, cảm ơn bạn nhiều.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn ˈpoːsɛ tak soː ˈmʏkːɛt/" },
  { id: 1295, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag tränar svenska säger jag: Det är ganska svalt ute idag, så jag tar en tröja.", vi: "Khi luyện tiếng Thụy Điển mình nói: Hôm nay ngoài trời khá mát nên mình mặc thêm áo len.", phonetic: "/deːt ɛːr ˈɡanːsa svɑlt ˈʉːtɛ ɪˈdɑːɡ soː jɑːɡ tɑːr ɛn ˈtrœjːa/" },
  { id: 1296, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "På utflykt eller promenad säger jag: Vi åker kollektivt eller går när det inte är så långt.", vi: "Khi đi chơi hoặc đi dạo mình nói: Tụi mình đi phương tiện công cộng hoặc đi bộ khi không quá xa.", phonetic: "/viː ˈoːkɛr kʊlːɛkˈtiːvt ˈɛlːɛr ɡoːr nɛːr deː ˈɪnːtɛ ɛːr soː lɔŋt/" },
  { id: 1297, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "I vardagen säger jag: Jag sparar undan lite varje månad för framtida planer.", vi: "Trong đời sống hằng ngày mình nói: Mình dành dụm một chút mỗi tháng cho các kế hoạch tương lai.", phonetic: "/jɑːɡ ˈspɑːrar ˈɵnːdan ˈliːtɛ ˈvarːjɛ ˈmoːnad fœr ˈfrɑːmˌtiːda ˈplɑːnɛr/" },
  { id: 1298, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag pratar med vänner säger jag: Vädret växlar snabbt, så det är bra att ha paraply med.", vi: "Khi trò chuyện với bạn bè mình nói: Thời tiết đổi nhanh lắm nên mang theo ô là tốt nhất.", phonetic: "/ˈvɛːdrɛt ˈvɛkːslar snɑpt soː deːt ɛːr brɑː at hɑː pɑrɑˈplʏː meːd/" },
  { id: 1299, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hemma och på fritiden säger jag: Jag gillar tydliga och enkla rutiner i vardagen.", vi: "Ở nhà và lúc rảnh mình nói: Mình thích những thói quen rõ ràng và đơn giản trong ngày.", phonetic: "/jɑːɡ ˈjɪlːar ˈtʏːdliɡa ɔ ˈɛŋːkla rɵˈtiːnɛr ɪ ˈvɑːrˌdɑːɡɛn/" },
  { id: 1300, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag tränar svenska säger jag: Varje litet steg framåt räknas.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mỗi bước tiến nhỏ về phía trước đều đáng quý.", phonetic: "/ˈvarːjɛ ˈliːtɛt steːɡ ˈfrɑːmˌɔːt ˈrɛkːnas/" },
  { id: 1301, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "God morgon! Hur har du sovit? Det är ett bra uttryck att kunna.", vi: "Chào buổi sáng! Bạn ngủ có ngon không? Đây là cách diễn đạt hay nên biết.", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr hɑːr dʉː ˈsʊːvɪt/" },
  { id: 1302, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag vaknade tidigt idag och tog en lugn start. Jag använder det gärna i samtal.", vi: "Hôm nay mình dậy sớm và khởi đầu thật nhẹ nhàng. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ ˈvɑːknadɛ ˈtiːdɪt ɪˈdɑːɡ ɔ tʊːɡ ɛn lɵŋn stɑʈ/" },
  { id: 1303, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Vad ska vi äta till middag ikväll? Det passar bra i många situationer.", vi: "Tối nay tụi mình sẽ ăn gì nhỉ? Câu này dùng được trong nhiều tình huống.", phonetic: "/vɑːd skɑː viː ˈɛːta tɪl ˈmɪdːɑːɡ ɪˈkvɛlː/" },
  { id: 1304, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag håller på att laga mat i köket nu. Det hjälper mig att uttrycka mig klart.", vi: "Bây giờ mình đang nấu ăn trong bếp. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ ˈhɔlːɛr pɔː at ˈlɑːɡa mɑːt ɪ ˈɕøːkɛt nʉː/" },
  { id: 1305, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Kan du upprepa det lite långsammare, tack? Det känns avslappnat och vardagligt.", vi: "Bạn lặp lại chậm hơn một chút được không, cảm ơn bạn? Nghe rất tự nhiên và gần gũi.", phonetic: "/kan dʉː ɵpːrɛˈpɑː deː ˈliːtɛ ˈlɔŋːsamːarɛ tak/" },
  { id: 1306, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag förstår ungefär vad du menar, men jag övar fortfarande. Det är ett bra uttryck att kunna.", vi: "Mình hiểu đại khái ý bạn, nhưng mình vẫn đang luyện thêm. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ fœrˈstoːr ɵnːfɛˈjɛːr vɑːd dʉː ˈmeːnar mɛn jɑːɡ ˈøːvar ˈfɔrtˌfarːandɛ/" },
  { id: 1307, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Det här ordet är nytt för mig. Vad betyder det? Jag använder det gärna i samtal.", vi: "Từ này mới với mình. Nó có nghĩa là gì vậy? Mình thích dùng câu này khi trò chuyện.", phonetic: "/deːt hɛːr ˈuːɖɛt ɛːr nʏt fœr mej vɑːd bɛˈtʏːdɛr deː/" },
  { id: 1308, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag övar på att prata svenska varje dag. Det passar bra i många situationer.", vi: "Mình luyện nói tiếng Thụy Điển mỗi ngày. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ ˈøːvar pɔː at ˈprɑːta ˈsvɛnːska ˈvarːjɛ dɑːɡ/" },
  { id: 1309, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Det blir lättare ju mer man pratar. Det hjälper mig att uttrycka mig klart.", vi: "Càng nói nhiều thì sẽ càng dễ hơn. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/deːt bliːr ˈlɛtːarɛ jʉː meːr man ˈprɑːtar/" },
  { id: 1310, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Tack för hjälpen, det betydde mycket! Det känns avslappnat och vardagligt.", vi: "Cảm ơn vì đã giúp đỡ, điều đó có ý nghĩa lắm! Nghe rất tự nhiên và gần gũi.", phonetic: "/tak fœr ˈjɛlːpɛn deː bɛˈtʏːdːɛ ˈmʏkːɛt/" },
  { id: 1311, topic: "Gia đình & người thân", sv: "Jag pratar med min man varje dag om framtiden. Det är ett bra uttryck att kunna.", vi: "Mình trò chuyện với chồng mỗi ngày về tương lai. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈprɑːtar meːd miːn man ˈvarːjɛ dɑːɡ ɔm ˈfrɑːmˌtiːdɛn/" },
  { id: 1312, topic: "Gia đình & người thân", sv: "Vi planerar vårt nya liv tillsammans i lugn takt. Jag använder det gärna i samtal.", vi: "Tụi mình lên kế hoạch cho cuộc sống mới cùng nhau một cách chầm chậm. Mình thích dùng câu này khi trò chuyện.", phonetic: "/viː plɑˈneːrar voːʈ ˈnʏːa liːv tɪlˈsamːanːs ɪ lɵŋn tɑkt/" },
  { id: 1313, topic: "Gia đình & người thân", sv: "Jag tänker ofta på min mormor hemma. Det passar bra i många situationer.", vi: "Mình thường nhớ tới bà ngoại ở nhà. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ ˈtɛŋːkɛr ˈɔfːta pɔː miːn ˈmʊːrmʊr ˈhɛmːa/" },
  { id: 1314, topic: "Gia đình & người thân", sv: "Familjen betyder allt när man är långt hemifrån. Det hjälper mig att uttrycka mig klart.", vi: "Gia đình có ý nghĩa tất cả khi ở xa nhà. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/fɑˈmiːljɛn bɛˈtʏːdɛr alːt nɛːr man ɛːr lɔŋt ˈhɛmːɪˌfroːn/" },
  { id: 1315, topic: "Gia đình & người thân", sv: "Vi ringer videosamtal på helgen när alla är lediga. Det känns avslappnat och vardagligt.", vi: "Tụi mình gọi video vào cuối tuần khi ai cũng rảnh. Nghe rất tự nhiên và gần gũi.", phonetic: "/viː ˈrɪŋːɛr ˈviːdɛʊˌsamːtɑːl pɔː ˈhɛlːjɛn nɛːr ˈalːa ɛːr ˈleːdɪɡa/" },
  { id: 1316, topic: "Gia đình & người thân", sv: "Han lagar god mat och stöttar mig alltid. Det är ett bra uttryck att kunna.", vi: "Anh ấy nấu ăn ngon và luôn ủng hộ mình. Đây là cách diễn đạt hay nên biết.", phonetic: "/han ˈlɑːɡar ɡuːd mɑːt ɔ ˈstœtːar mej ˈalːtiːd/" },
  { id: 1317, topic: "Gia đình & người thân", sv: "Att hjälpa varandra gör vardagen enklare. Jag använder det gärna i samtal.", vi: "Giúp đỡ lẫn nhau khiến cuộc sống hằng ngày nhẹ nhàng hơn. Mình thích dùng câu này khi trò chuyện.", phonetic: "/at ˈjɛlːpa vɑˈranːdra jøːr ˈvɑːrˌdɑːɡɛn ˈɛŋːklarɛ/" },
  { id: 1318, topic: "Gia đình & người thân", sv: "Jag vill gärna bjuda hem familjen på middag någon gång. Det passar bra i många situationer.", vi: "Mình rất muốn mời gia đình đến nhà ăn tối một dịp nào đó. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ vɪl ˈjɛːrna ˈbjʉːda hɛm fɑˈmiːljɛn pɔː ˈmɪdːɑːɡ ˈnoːɡɔn ɡɔŋ/" },
  { id: 1319, topic: "Gia đình & người thân", sv: "Det känns tryggt att ha någon som förstår en. Det hjälper mig att uttrycka mig klart.", vi: "Thật vững tâm khi có người thấu hiểu mình. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/deːt ɕɛnːs trʏɡt at hɑː ˈnoːɡɔn sɔm fœrˈstoːr ɛn/" },
  { id: 1320, topic: "Gia đình & người thân", sv: "Vi delar både glädje och små bekymmer. Det känns avslappnat och vardagligt.", vi: "Tụi mình chia sẻ cả niềm vui lẫn những nỗi lo nhỏ. Nghe rất tự nhiên và gần gũi.", phonetic: "/viː ˈdeːlar ˈboːdɛ ˈɡlɛːdjɛ ɔ smoː bɛˈɕʏmːɛr/" },
  { id: 1321, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag gillar att ta en promenad i parken efter jobbet. Det är ett bra uttryck att kunna.", vi: "Mình thích đi dạo trong công viên sau giờ làm. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈjɪlːar at tɑː ɛn prʊmɛˈnɑːd ɪ ˈparːkɛn ˈɛfːtɛr ˈjɔbːɛt/" },
  { id: 1322, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Frisk luft och grönska hjälper mig att ladda om. Jag använder det gärna i samtal.", vi: "Không khí trong lành và cây xanh giúp mình nạp lại năng lượng. Mình thích dùng câu này khi trò chuyện.", phonetic: "/frɪsk lɵft ɔ ˈɡrœnːska ˈjɛlːpɛr mej at ˈladːa ɔm/" },
  { id: 1323, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vilken vacker utsikt över sjön och skogen! Det passar bra i många situationer.", vi: "Khung cảnh nhìn ra hồ và rừng đẹp quá! Câu này dùng được trong nhiều tình huống.", phonetic: "/ˈvɪlːkɛn ˈvakːɛr ˈʉːtˌsɪkːt ˈøːvɛr ɕøːn ɔ ˈskuːɡɛn/" },
  { id: 1324, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag brukar ta foton på naturen när vi reser. Det hjälper mig att uttrycka mig klart.", vi: "Mình hay chụp ảnh thiên nhiên khi tụi mình đi du lịch. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ ˈbrʉːkar tɑː ˈfuːtɔn pɔː nɑtʉːˈreːn nɛːr viː ˈreːsɛr/" },
  { id: 1325, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vi åker gärna iväg på helgutflykter till nya platser. Det känns avslappnat och vardagligt.", vi: "Tụi mình thích đi chơi cuối tuần tới những vùng đất mới. Nghe rất tự nhiên và gần gũi.", phonetic: "/viː ˈoːkɛr ˈjɛːrna ɪˈvɛːɡ pɔː ˈhɛljˌʉːtflʏkːtɛr tɪl ˈnʏːa ˈplatːsɛr/" },
  { id: 1326, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Ljuset på morgonen och kvällen är så fint att fotografera. Det är ett bra uttryck att kunna.", vi: "Ánh sáng buổi sáng và buổi chiều tối chụp ảnh đẹp lắm. Đây là cách diễn đạt hay nên biết.", phonetic: "/ˈjʉːsɛt pɔː ˈmɔrːɔnɛn ɔ ˈkvɛlːɛn ɛːr soː fiːnt at fʊtʊɡrɑˈfeːra/" },
  { id: 1327, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Det är så tyst och rofyllt här borta vid vattnet. Jag använder det gärna i samtal.", vi: "Ở khu vực ven nước này thật yên tĩnh và thanh bình. Mình thích dùng câu này khi trò chuyện.", phonetic: "/deːt ɛːr soː tʏst ɔ ˈrʊːˌfʏlt hɛːr ˈbɔrːta viːd ˈvatːnɛt/" },
  { id: 1328, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vi tar det lugnt och njuter av resan i vårt eget tempo. Det passar bra i många situationer.", vi: "Tụi mình đi thong thả và tận hưởng chuyến đi theo nhịp của riêng mình. Câu này dùng được trong nhiều tình huống.", phonetic: "/viː tɑːr deː lɵŋt ɔ ˈnjʉːtɛr ɑːv ˈreːsan ɪ voːʈ ˈeːɡɛt ˈtɛmːpʊ/" },
  { id: 1329, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag älskar när solen tittar fram mellan molnen. Det hjälper mig att uttrycka mig klart.", vi: "Mình thích khoảnh khắc mặt trời ló dạng giữa những đám mây. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ ˈɛlːskar nɛːr ˈsuːlɛn ˈtɪtːar fram ˈmɛlːan ˈmuːlnɛn/" },
  { id: 1330, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Att komma ut i naturen rensar tankarna. Det känns avslappnat och vardagligt.", vi: "Ra ngoài thiên nhiên giúp đầu óc thư thái hẳn. Nghe rất tự nhiên và gần gũi.", phonetic: "/at ˈkɔmːa ʉːt ɪ nɑtʉːˈreːn ˈrɛnːsar ˈtaŋːkarːa/" },
  { id: 1331, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På kvällen gillar jag att varva ner hemma med en bra film. Det är ett bra uttryck att kunna.", vi: "Buổi tối mình thích thư giãn ở nhà với một bộ phim hay. Đây là cách diễn đạt hay nên biết.", phonetic: "/pɔː ˈkvɛlːɛn ˈjɪlːar jɑːɡ at ˈvarːva neːr ˈhɛmːa meːd ɛn brɑː fɪlm/" },
  { id: 1332, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det är skönt att krypa upp i soffan efter en aktiv dag. Jag använder det gärna i samtal.", vi: "Thật dễ chịu khi cuộn mình trên ghế sofa sau một ngày năng động. Mình thích dùng câu này khi trò chuyện.", phonetic: "/deːt ɛːr ɕøːnt at ˈkrʏːpa ɵpː ɪ ˈsɔfːan ˈɛfːtɛr ɛn ˈakːtɪv dɑːɡ/" },
  { id: 1333, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vi spelar sällskapsspel och ordlekar när vi är många. Det passar bra i många situationer.", vi: "Tụi mình chơi board game và trò nối chữ khi có đông người. Câu này dùng được trong nhiều tình huống.", phonetic: "/viː ˈsɛlːskɑpsˌspeːl ɔ ˈuːɖˌleːkar nɛːr viː ɛːr ˈmɔŋːa/" },
  { id: 1334, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det är så kul att skratta tillsammans över en spelomgång. Det hjälper mig att uttrycka mig klart.", vi: "Cùng cười rôm rả qua một ván chơi vui thật đấy. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/deːt ɛːr soː kʉːl at ˈskratːa tɪlˈsamːanːs ˈøːvɛr ɛn ˈspeːlˌɔmːɡɔŋ/" },
  { id: 1335, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Jag gillar att ha det städat och mysigt omkring mig. Det känns avslappnat och vardagligt.", vi: "Mình thích giữ không gian gọn gàng và ấm cúng quanh mình. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ ˈjɪlːar at hɑː deː ˈstɛːdat ɔ ˈmʏːsɪt ɔmˈkrɪŋ mej/" },
  { id: 1336, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "En varm dusch och tystnad hjälper mig att somna gott. Det är ett bra uttryck att kunna.", vi: "Một trận tắm nước ấm và sự yên tĩnh giúp mình ngủ ngon. Đây là cách diễn đạt hay nên biết.", phonetic: "/ɛn varm dɵʃ ɔ ˈtʏsːtnɑd ˈjɛlːpɛr mej at ˈsɔmːna ɡɔt/" },
  { id: 1337, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Jag tar gärna en kort paus när jag behöver samla kraft. Jag använder det gärna i samtal.", vi: "Mình hay nghỉ giải lao ngắn khi cần lấy lại sức. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn kɔʈ paɵs nɛːr jɑːɡ bɛˈhøːvɛr ˈsamːla krɑft/" },
  { id: 1338, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vilken film eller serie tyckte du bäst om nyligen? Det passar bra i många situationer.", vi: "Gần đây bạn thích phim điện ảnh hay phim bộ nào nhất? Câu này dùng được trong nhiều tình huống.", phonetic: "/ˈvɪlːkɛn fɪlm ˈɛlːɛr ˈseːrɪɛ ˈtʏkːtɛ dʉː bɛst ɔm ˈnʏːˌliːɡɛn/" },
  { id: 1339, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vi gör en enkel fika med kaffe och frukt idag. Det hjälper mig att uttrycka mig klart.", vi: "Hôm nay tụi mình làm bữa fika nhẹ nhàng với cà phê và trái cây. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/viː jøːr ɛn ˈɛŋːkɛl ˈfiːka meːd ˈkafːɛ ɔ frɵkt ɪˈdɑːɡ/" },
  { id: 1340, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det känns skönt att bara vara sig själv i lugn och ro. Det känns avslappnat och vardagligt.", vi: "Thật thoải mái khi được là chính mình trong yên bình. Nghe rất tự nhiên và gần gũi.", phonetic: "/deːt ɕɛnːs ɕøːnt at ˈbɑːra ˈvɑːra sej ɕɛlv ɪ lɵŋn ɔ rʊː/" },
  { id: 1341, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Ursäkta, vet du var närmaste busshållplats ligger? Det är ett bra uttryck att kunna.", vi: "Xin lỗi, bạn có biết trạm xe buýt gần nhất ở đâu không? Đây là cách diễn đạt hay nên biết.", phonetic: "/ˈʉːˌʂɛkːta veːt dʉː vɑːr ˈnɛrmastɛ ˈbɵsˌhɔlːplats ˈlɪɡːɛr/" },
  { id: 1342, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag behöver köpa frukt, grönsaker och bröd idag. Jag använder det gärna i samtal.", vi: "Hôm nay mình cần mua trái cây, rau củ và bánh mì. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ bɛˈhøːvɛr ˈɕøːpa frɵkt ˈɡrœnˌsɑːkɛr ɔ brøːd ɪˈdɑːɡ/" },
  { id: 1343, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hur mycket kostar det här totalt? Det passar bra i många situationer.", vi: "Món này tổng cộng giá bao nhiêu vậy? Câu này dùng được trong nhiều tình huống.", phonetic: "/hʉːr ˈmʏkːɛt ˈkɔsːtar deːt hɛːr tʊˈtɑlt/" },
  { id: 1344, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag tar gärna en påse, tack så mycket. Det hjälper mig att uttrycka mig klart.", vi: "Cho mình xin một túi nhé, cảm ơn bạn nhiều. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn ˈpoːsɛ tak soː ˈmʏkːɛt/" },
  { id: 1345, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Det är ganska svalt ute idag, så jag tar en tröja. Det känns avslappnat och vardagligt.", vi: "Hôm nay ngoài trời khá mát nên mình mặc thêm áo len. Nghe rất tự nhiên và gần gũi.", phonetic: "/deːt ɛːr ˈɡanːsa svɑlt ˈʉːtɛ ɪˈdɑːɡ soː jɑːɡ tɑːr ɛn ˈtrœjːa/" },
  { id: 1346, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Vi åker kollektivt eller går när det inte är så långt. Det är ett bra uttryck att kunna.", vi: "Tụi mình đi phương tiện công cộng hoặc đi bộ khi không quá xa. Đây là cách diễn đạt hay nên biết.", phonetic: "/viː ˈoːkɛr kʊlːɛkˈtiːvt ˈɛlːɛr ɡoːr nɛːr deː ˈɪnːtɛ ɛːr soː lɔŋt/" },
  { id: 1347, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag sparar undan lite varje månad för framtida planer. Jag använder det gärna i samtal.", vi: "Mình dành dụm một chút mỗi tháng cho các kế hoạch tương lai. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ ˈspɑːrar ˈɵnːdan ˈliːtɛ ˈvarːjɛ ˈmoːnad fœr ˈfrɑːmˌtiːda ˈplɑːnɛr/" },
  { id: 1348, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Vädret växlar snabbt, så det är bra att ha paraply med. Det passar bra i många situationer.", vi: "Thời tiết đổi nhanh lắm nên mang theo ô là tốt nhất. Câu này dùng được trong nhiều tình huống.", phonetic: "/ˈvɛːdrɛt ˈvɛkːslar snɑpt soː deːt ɛːr brɑː at hɑː pɑrɑˈplʏː meːd/" },
  { id: 1349, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag gillar tydliga och enkla rutiner i vardagen. Det hjälper mig att uttrycka mig klart.", vi: "Mình thích những thói quen rõ ràng và đơn giản trong ngày. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ ˈjɪlːar ˈtʏːdliɡa ɔ ˈɛŋːkla rɵˈtiːnɛr ɪ ˈvɑːrˌdɑːɡɛn/" },
  { id: 1350, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Varje litet steg framåt räknas. Det känns avslappnat och vardagligt.", vi: "Mỗi bước tiến nhỏ về phía trước đều đáng quý. Nghe rất tự nhiên và gần gũi.", phonetic: "/ˈvarːjɛ ˈliːtɛt steːɡ ˈfrɑːmˌɔːt ˈrɛkːnas/" },
  { id: 1351, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag pratar med vänner säger jag: God morgon! Hur har du sovit?", vi: "Khi trò chuyện với bạn bè mình nói: Chào buổi sáng! Bạn ngủ có ngon không?", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr hɑːr dʉː ˈsʊːvɪt/" },
  { id: 1352, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Hemma och på fritiden säger jag: Jag vaknade tidigt idag och tog en lugn start.", vi: "Ở nhà và lúc rảnh mình nói: Hôm nay mình dậy sớm và khởi đầu thật nhẹ nhàng.", phonetic: "/jɑːɡ ˈvɑːknadɛ ˈtiːdɪt ɪˈdɑːɡ ɔ tʊːɡ ɛn lɵŋn stɑʈ/" },
  { id: 1353, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag tränar svenska säger jag: Vad ska vi äta till middag ikväll?", vi: "Khi luyện tiếng Thụy Điển mình nói: Tối nay tụi mình sẽ ăn gì nhỉ?", phonetic: "/vɑːd skɑː viː ˈɛːta tɪl ˈmɪdːɑːɡ ɪˈkvɛlː/" },
  { id: 1354, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "På utflykt eller promenad säger jag: Jag håller på att laga mat i köket nu.", vi: "Khi đi chơi hoặc đi dạo mình nói: Bây giờ mình đang nấu ăn trong bếp.", phonetic: "/jɑːɡ ˈhɔlːɛr pɔː at ˈlɑːɡa mɑːt ɪ ˈɕøːkɛt nʉː/" },
  { id: 1355, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "I vardagen säger jag: Kan du upprepa det lite långsammare, tack?", vi: "Trong đời sống hằng ngày mình nói: Bạn lặp lại chậm hơn một chút được không, cảm ơn bạn?", phonetic: "/kan dʉː ɵpːrɛˈpɑː deː ˈliːtɛ ˈlɔŋːsamːarɛ tak/" },
  { id: 1356, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag pratar med vänner säger jag: Jag förstår ungefär vad du menar, men jag övar fortfarande.", vi: "Khi trò chuyện với bạn bè mình nói: Mình hiểu đại khái ý bạn, nhưng mình vẫn đang luyện thêm.", phonetic: "/jɑːɡ fœrˈstoːr ɵnːfɛˈjɛːr vɑːd dʉː ˈmeːnar mɛn jɑːɡ ˈøːvar ˈfɔrtˌfarːandɛ/" },
  { id: 1357, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Hemma och på fritiden säger jag: Det här ordet är nytt för mig. Vad betyder det?", vi: "Ở nhà và lúc rảnh mình nói: Từ này mới với mình. Nó có nghĩa là gì vậy?", phonetic: "/deːt hɛːr ˈuːɖɛt ɛːr nʏt fœr mej vɑːd bɛˈtʏːdɛr deː/" },
  { id: 1358, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag tränar svenska säger jag: Jag övar på att prata svenska varje dag.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình luyện nói tiếng Thụy Điển mỗi ngày.", phonetic: "/jɑːɡ ˈøːvar pɔː at ˈprɑːta ˈsvɛnːska ˈvarːjɛ dɑːɡ/" },
  { id: 1359, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "På utflykt eller promenad säger jag: Det blir lättare ju mer man pratar.", vi: "Khi đi chơi hoặc đi dạo mình nói: Càng nói nhiều thì sẽ càng dễ hơn.", phonetic: "/deːt bliːr ˈlɛtːarɛ jʉː meːr man ˈprɑːtar/" },
  { id: 1360, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "I vardagen säger jag: Tack för hjälpen, det betydde mycket!", vi: "Trong đời sống hằng ngày mình nói: Cảm ơn vì đã giúp đỡ, điều đó có ý nghĩa lắm!", phonetic: "/tak fœr ˈjɛlːpɛn deː bɛˈtʏːdːɛ ˈmʏkːɛt/" },
  { id: 1361, topic: "Gia đình & người thân", sv: "När jag pratar med vänner säger jag: Jag pratar med min man varje dag om framtiden.", vi: "Khi trò chuyện với bạn bè mình nói: Mình trò chuyện với chồng mỗi ngày về tương lai.", phonetic: "/jɑːɡ ˈprɑːtar meːd miːn man ˈvarːjɛ dɑːɡ ɔm ˈfrɑːmˌtiːdɛn/" },
  { id: 1362, topic: "Gia đình & người thân", sv: "Hemma och på fritiden säger jag: Vi planerar vårt nya liv tillsammans i lugn takt.", vi: "Ở nhà và lúc rảnh mình nói: Tụi mình lên kế hoạch cho cuộc sống mới cùng nhau một cách chầm chậm.", phonetic: "/viː plɑˈneːrar voːʈ ˈnʏːa liːv tɪlˈsamːanːs ɪ lɵŋn tɑkt/" },
  { id: 1363, topic: "Gia đình & người thân", sv: "När jag tränar svenska säger jag: Jag tänker ofta på min mormor hemma.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình thường nhớ tới bà ngoại ở nhà.", phonetic: "/jɑːɡ ˈtɛŋːkɛr ˈɔfːta pɔː miːn ˈmʊːrmʊr ˈhɛmːa/" },
  { id: 1364, topic: "Gia đình & người thân", sv: "På utflykt eller promenad säger jag: Familjen betyder allt när man är långt hemifrån.", vi: "Khi đi chơi hoặc đi dạo mình nói: Gia đình có ý nghĩa tất cả khi ở xa nhà.", phonetic: "/fɑˈmiːljɛn bɛˈtʏːdɛr alːt nɛːr man ɛːr lɔŋt ˈhɛmːɪˌfroːn/" },
  { id: 1365, topic: "Gia đình & người thân", sv: "I vardagen säger jag: Vi ringer videosamtal på helgen när alla är lediga.", vi: "Trong đời sống hằng ngày mình nói: Tụi mình gọi video vào cuối tuần khi ai cũng rảnh.", phonetic: "/viː ˈrɪŋːɛr ˈviːdɛʊˌsamːtɑːl pɔː ˈhɛlːjɛn nɛːr ˈalːa ɛːr ˈleːdɪɡa/" },
  { id: 1366, topic: "Gia đình & người thân", sv: "När jag pratar med vänner säger jag: Han lagar god mat och stöttar mig alltid.", vi: "Khi trò chuyện với bạn bè mình nói: Anh ấy nấu ăn ngon và luôn ủng hộ mình.", phonetic: "/han ˈlɑːɡar ɡuːd mɑːt ɔ ˈstœtːar mej ˈalːtiːd/" },
  { id: 1367, topic: "Gia đình & người thân", sv: "Hemma och på fritiden säger jag: Att hjälpa varandra gör vardagen enklare.", vi: "Ở nhà và lúc rảnh mình nói: Giúp đỡ lẫn nhau khiến cuộc sống hằng ngày nhẹ nhàng hơn.", phonetic: "/at ˈjɛlːpa vɑˈranːdra jøːr ˈvɑːrˌdɑːɡɛn ˈɛŋːklarɛ/" },
  { id: 1368, topic: "Gia đình & người thân", sv: "När jag tränar svenska säger jag: Jag vill gärna bjuda hem familjen på middag någon gång.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình rất muốn mời gia đình đến nhà ăn tối một dịp nào đó.", phonetic: "/jɑːɡ vɪl ˈjɛːrna ˈbjʉːda hɛm fɑˈmiːljɛn pɔː ˈmɪdːɑːɡ ˈnoːɡɔn ɡɔŋ/" },
  { id: 1369, topic: "Gia đình & người thân", sv: "På utflykt eller promenad säger jag: Det känns tryggt att ha någon som förstår en.", vi: "Khi đi chơi hoặc đi dạo mình nói: Thật vững tâm khi có người thấu hiểu mình.", phonetic: "/deːt ɕɛnːs trʏɡt at hɑː ˈnoːɡɔn sɔm fœrˈstoːr ɛn/" },
  { id: 1370, topic: "Gia đình & người thân", sv: "I vardagen säger jag: Vi delar både glädje och små bekymmer.", vi: "Trong đời sống hằng ngày mình nói: Tụi mình chia sẻ cả niềm vui lẫn những nỗi lo nhỏ.", phonetic: "/viː ˈdeːlar ˈboːdɛ ˈɡlɛːdjɛ ɔ smoː bɛˈɕʏmːɛr/" },
  { id: 1371, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag pratar med vänner säger jag: Jag gillar att ta en promenad i parken efter jobbet.", vi: "Khi trò chuyện với bạn bè mình nói: Mình thích đi dạo trong công viên sau giờ làm.", phonetic: "/jɑːɡ ˈjɪlːar at tɑː ɛn prʊmɛˈnɑːd ɪ ˈparːkɛn ˈɛfːtɛr ˈjɔbːɛt/" },
  { id: 1372, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Hemma och på fritiden säger jag: Frisk luft och grönska hjälper mig att ladda om.", vi: "Ở nhà và lúc rảnh mình nói: Không khí trong lành và cây xanh giúp mình nạp lại năng lượng.", phonetic: "/frɪsk lɵft ɔ ˈɡrœnːska ˈjɛlːpɛr mej at ˈladːa ɔm/" },
  { id: 1373, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag tränar svenska säger jag: Vilken vacker utsikt över sjön och skogen!", vi: "Khi luyện tiếng Thụy Điển mình nói: Khung cảnh nhìn ra hồ và rừng đẹp quá!", phonetic: "/ˈvɪlːkɛn ˈvakːɛr ˈʉːtˌsɪkːt ˈøːvɛr ɕøːn ɔ ˈskuːɡɛn/" },
  { id: 1374, topic: "Thiên nhiên, đi dạo & du lịch", sv: "På utflykt eller promenad säger jag: Jag brukar ta foton på naturen när vi reser.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình hay chụp ảnh thiên nhiên khi tụi mình đi du lịch.", phonetic: "/jɑːɡ ˈbrʉːkar tɑː ˈfuːtɔn pɔː nɑtʉːˈreːn nɛːr viː ˈreːsɛr/" },
  { id: 1375, topic: "Thiên nhiên, đi dạo & du lịch", sv: "I vardagen säger jag: Vi åker gärna iväg på helgutflykter till nya platser.", vi: "Trong đời sống hằng ngày mình nói: Tụi mình thích đi chơi cuối tuần tới những vùng đất mới.", phonetic: "/viː ˈoːkɛr ˈjɛːrna ɪˈvɛːɡ pɔː ˈhɛljˌʉːtflʏkːtɛr tɪl ˈnʏːa ˈplatːsɛr/" },
  { id: 1376, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag pratar med vänner säger jag: Ljuset på morgonen och kvällen är så fint att fotografera.", vi: "Khi trò chuyện với bạn bè mình nói: Ánh sáng buổi sáng và buổi chiều tối chụp ảnh đẹp lắm.", phonetic: "/ˈjʉːsɛt pɔː ˈmɔrːɔnɛn ɔ ˈkvɛlːɛn ɛːr soː fiːnt at fʊtʊɡrɑˈfeːra/" },
  { id: 1377, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Hemma och på fritiden säger jag: Det är så tyst och rofyllt här borta vid vattnet.", vi: "Ở nhà và lúc rảnh mình nói: Ở khu vực ven nước này thật yên tĩnh và thanh bình.", phonetic: "/deːt ɛːr soː tʏst ɔ ˈrʊːˌfʏlt hɛːr ˈbɔrːta viːd ˈvatːnɛt/" },
  { id: 1378, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag tränar svenska säger jag: Vi tar det lugnt och njuter av resan i vårt eget tempo.", vi: "Khi luyện tiếng Thụy Điển mình nói: Tụi mình đi thong thả và tận hưởng chuyến đi theo nhịp của riêng mình.", phonetic: "/viː tɑːr deː lɵŋt ɔ ˈnjʉːtɛr ɑːv ˈreːsan ɪ voːʈ ˈeːɡɛt ˈtɛmːpʊ/" },
  { id: 1379, topic: "Thiên nhiên, đi dạo & du lịch", sv: "På utflykt eller promenad säger jag: Jag älskar när solen tittar fram mellan molnen.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình thích khoảnh khắc mặt trời ló dạng giữa những đám mây.", phonetic: "/jɑːɡ ˈɛlːskar nɛːr ˈsuːlɛn ˈtɪtːar fram ˈmɛlːan ˈmuːlnɛn/" },
  { id: 1380, topic: "Thiên nhiên, đi dạo & du lịch", sv: "I vardagen säger jag: Att komma ut i naturen rensar tankarna.", vi: "Trong đời sống hằng ngày mình nói: Ra ngoài thiên nhiên giúp đầu óc thư thái hẳn.", phonetic: "/at ˈkɔmːa ʉːt ɪ nɑtʉːˈreːn ˈrɛnːsar ˈtaŋːkarːa/" },
  { id: 1381, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag pratar med vänner säger jag: På kvällen gillar jag att varva ner hemma med en bra film.", vi: "Khi trò chuyện với bạn bè mình nói: Buổi tối mình thích thư giãn ở nhà với một bộ phim hay.", phonetic: "/pɔː ˈkvɛlːɛn ˈjɪlːar jɑːɡ at ˈvarːva neːr ˈhɛmːa meːd ɛn brɑː fɪlm/" },
  { id: 1382, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Hemma och på fritiden säger jag: Det är skönt att krypa upp i soffan efter en aktiv dag.", vi: "Ở nhà và lúc rảnh mình nói: Thật dễ chịu khi cuộn mình trên ghế sofa sau một ngày năng động.", phonetic: "/deːt ɛːr ɕøːnt at ˈkrʏːpa ɵpː ɪ ˈsɔfːan ˈɛfːtɛr ɛn ˈakːtɪv dɑːɡ/" },
  { id: 1383, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag tränar svenska säger jag: Vi spelar sällskapsspel och ordlekar när vi är många.", vi: "Khi luyện tiếng Thụy Điển mình nói: Tụi mình chơi board game và trò nối chữ khi có đông người.", phonetic: "/viː ˈsɛlːskɑpsˌspeːl ɔ ˈuːɖˌleːkar nɛːr viː ɛːr ˈmɔŋːa/" },
  { id: 1384, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På utflykt eller promenad säger jag: Det är så kul att skratta tillsammans över en spelomgång.", vi: "Khi đi chơi hoặc đi dạo mình nói: Cùng cười rôm rả qua một ván chơi vui thật đấy.", phonetic: "/deːt ɛːr soː kʉːl at ˈskratːa tɪlˈsamːanːs ˈøːvɛr ɛn ˈspeːlˌɔmːɡɔŋ/" },
  { id: 1385, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "I vardagen säger jag: Jag gillar att ha det städat och mysigt omkring mig.", vi: "Trong đời sống hằng ngày mình nói: Mình thích giữ không gian gọn gàng và ấm cúng quanh mình.", phonetic: "/jɑːɡ ˈjɪlːar at hɑː deː ˈstɛːdat ɔ ˈmʏːsɪt ɔmˈkrɪŋ mej/" },
  { id: 1386, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag pratar med vänner säger jag: En varm dusch och tystnad hjälper mig att somna gott.", vi: "Khi trò chuyện với bạn bè mình nói: Một trận tắm nước ấm và sự yên tĩnh giúp mình ngủ ngon.", phonetic: "/ɛn varm dɵʃ ɔ ˈtʏsːtnɑd ˈjɛlːpɛr mej at ˈsɔmːna ɡɔt/" },
  { id: 1387, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Hemma och på fritiden säger jag: Jag tar gärna en kort paus när jag behöver samla kraft.", vi: "Ở nhà và lúc rảnh mình nói: Mình hay nghỉ giải lao ngắn khi cần lấy lại sức.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn kɔʈ paɵs nɛːr jɑːɡ bɛˈhøːvɛr ˈsamːla krɑft/" },
  { id: 1388, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag tränar svenska säger jag: Vilken film eller serie tyckte du bäst om nyligen?", vi: "Khi luyện tiếng Thụy Điển mình nói: Gần đây bạn thích phim điện ảnh hay phim bộ nào nhất?", phonetic: "/ˈvɪlːkɛn fɪlm ˈɛlːɛr ˈseːrɪɛ ˈtʏkːtɛ dʉː bɛst ɔm ˈnʏːˌliːɡɛn/" },
  { id: 1389, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På utflykt eller promenad säger jag: Vi gör en enkel fika med kaffe och frukt idag.", vi: "Khi đi chơi hoặc đi dạo mình nói: Hôm nay tụi mình làm bữa fika nhẹ nhàng với cà phê và trái cây.", phonetic: "/viː jøːr ɛn ˈɛŋːkɛl ˈfiːka meːd ˈkafːɛ ɔ frɵkt ɪˈdɑːɡ/" },
  { id: 1390, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "I vardagen säger jag: Det känns skönt att bara vara sig själv i lugn och ro.", vi: "Trong đời sống hằng ngày mình nói: Thật thoải mái khi được là chính mình trong yên bình.", phonetic: "/deːt ɕɛnːs ɕøːnt at ˈbɑːra ˈvɑːra sej ɕɛlv ɪ lɵŋn ɔ rʊː/" },
  { id: 1391, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag pratar med vänner säger jag: Ursäkta, vet du var närmaste busshållplats ligger?", vi: "Khi trò chuyện với bạn bè mình nói: Xin lỗi, bạn có biết trạm xe buýt gần nhất ở đâu không?", phonetic: "/ˈʉːˌʂɛkːta veːt dʉː vɑːr ˈnɛrmastɛ ˈbɵsˌhɔlːplats ˈlɪɡːɛr/" },
  { id: 1392, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hemma och på fritiden säger jag: Jag behöver köpa frukt, grönsaker och bröd idag.", vi: "Ở nhà và lúc rảnh mình nói: Hôm nay mình cần mua trái cây, rau củ và bánh mì.", phonetic: "/jɑːɡ bɛˈhøːvɛr ˈɕøːpa frɵkt ˈɡrœnˌsɑːkɛr ɔ brøːd ɪˈdɑːɡ/" },
  { id: 1393, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag tränar svenska säger jag: Hur mycket kostar det här totalt?", vi: "Khi luyện tiếng Thụy Điển mình nói: Món này tổng cộng giá bao nhiêu vậy?", phonetic: "/hʉːr ˈmʏkːɛt ˈkɔsːtar deːt hɛːr tʊˈtɑlt/" },
  { id: 1394, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "På utflykt eller promenad säger jag: Jag tar gärna en påse, tack så mycket.", vi: "Khi đi chơi hoặc đi dạo mình nói: Cho mình xin một túi nhé, cảm ơn bạn nhiều.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn ˈpoːsɛ tak soː ˈmʏkːɛt/" },
  { id: 1395, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "I vardagen säger jag: Det är ganska svalt ute idag, så jag tar en tröja.", vi: "Trong đời sống hằng ngày mình nói: Hôm nay ngoài trời khá mát nên mình mặc thêm áo len.", phonetic: "/deːt ɛːr ˈɡanːsa svɑlt ˈʉːtɛ ɪˈdɑːɡ soː jɑːɡ tɑːr ɛn ˈtrœjːa/" },
  { id: 1396, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag pratar med vänner säger jag: Vi åker kollektivt eller går när det inte är så långt.", vi: "Khi trò chuyện với bạn bè mình nói: Tụi mình đi phương tiện công cộng hoặc đi bộ khi không quá xa.", phonetic: "/viː ˈoːkɛr kʊlːɛkˈtiːvt ˈɛlːɛr ɡoːr nɛːr deː ˈɪnːtɛ ɛːr soː lɔŋt/" },
  { id: 1397, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hemma och på fritiden säger jag: Jag sparar undan lite varje månad för framtida planer.", vi: "Ở nhà và lúc rảnh mình nói: Mình dành dụm một chút mỗi tháng cho các kế hoạch tương lai.", phonetic: "/jɑːɡ ˈspɑːrar ˈɵnːdan ˈliːtɛ ˈvarːjɛ ˈmoːnad fœr ˈfrɑːmˌtiːda ˈplɑːnɛr/" },
  { id: 1398, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag tränar svenska säger jag: Vädret växlar snabbt, så det är bra att ha paraply med.", vi: "Khi luyện tiếng Thụy Điển mình nói: Thời tiết đổi nhanh lắm nên mang theo ô là tốt nhất.", phonetic: "/ˈvɛːdrɛt ˈvɛkːslar snɑpt soː deːt ɛːr brɑː at hɑː pɑrɑˈplʏː meːd/" },
  { id: 1399, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "På utflykt eller promenad säger jag: Jag gillar tydliga och enkla rutiner i vardagen.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình thích những thói quen rõ ràng và đơn giản trong ngày.", phonetic: "/jɑːɡ ˈjɪlːar ˈtʏːdliɡa ɔ ˈɛŋːkla rɵˈtiːnɛr ɪ ˈvɑːrˌdɑːɡɛn/" },
  { id: 1400, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "I vardagen säger jag: Varje litet steg framåt räknas.", vi: "Trong đời sống hằng ngày mình nói: Mỗi bước tiến nhỏ về phía trước đều đáng quý.", phonetic: "/ˈvarːjɛ ˈliːtɛt steːɡ ˈfrɑːmˌɔːt ˈrɛkːnas/" },
  { id: 1401, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "God morgon! Hur har du sovit? Det passar bra i många situationer.", vi: "Chào buổi sáng! Bạn ngủ có ngon không? Câu này dùng được trong nhiều tình huống.", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr hɑːr dʉː ˈsʊːvɪt/" },
  { id: 1402, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag vaknade tidigt idag och tog en lugn start. Det hjälper mig att uttrycka mig klart.", vi: "Hôm nay mình dậy sớm và khởi đầu thật nhẹ nhàng. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ ˈvɑːknadɛ ˈtiːdɪt ɪˈdɑːɡ ɔ tʊːɡ ɛn lɵŋn stɑʈ/" },
  { id: 1403, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Vad ska vi äta till middag ikväll? Det känns avslappnat och vardagligt.", vi: "Tối nay tụi mình sẽ ăn gì nhỉ? Nghe rất tự nhiên và gần gũi.", phonetic: "/vɑːd skɑː viː ˈɛːta tɪl ˈmɪdːɑːɡ ɪˈkvɛlː/" },
  { id: 1404, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag håller på att laga mat i köket nu. Det är ett bra uttryck att kunna.", vi: "Bây giờ mình đang nấu ăn trong bếp. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈhɔlːɛr pɔː at ˈlɑːɡa mɑːt ɪ ˈɕøːkɛt nʉː/" },
  { id: 1405, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Kan du upprepa det lite långsammare, tack? Jag använder det gärna i samtal.", vi: "Bạn lặp lại chậm hơn một chút được không, cảm ơn bạn? Mình thích dùng câu này khi trò chuyện.", phonetic: "/kan dʉː ɵpːrɛˈpɑː deː ˈliːtɛ ˈlɔŋːsamːarɛ tak/" },
  { id: 1406, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag förstår ungefär vad du menar, men jag övar fortfarande. Det passar bra i många situationer.", vi: "Mình hiểu đại khái ý bạn, nhưng mình vẫn đang luyện thêm. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ fœrˈstoːr ɵnːfɛˈjɛːr vɑːd dʉː ˈmeːnar mɛn jɑːɡ ˈøːvar ˈfɔrtˌfarːandɛ/" },
  { id: 1407, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Det här ordet är nytt för mig. Vad betyder det? Det hjälper mig att uttrycka mig klart.", vi: "Từ này mới với mình. Nó có nghĩa là gì vậy? Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/deːt hɛːr ˈuːɖɛt ɛːr nʏt fœr mej vɑːd bɛˈtʏːdɛr deː/" },
  { id: 1408, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag övar på att prata svenska varje dag. Det känns avslappnat och vardagligt.", vi: "Mình luyện nói tiếng Thụy Điển mỗi ngày. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ ˈøːvar pɔː at ˈprɑːta ˈsvɛnːska ˈvarːjɛ dɑːɡ/" },
  { id: 1409, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Det blir lättare ju mer man pratar. Det är ett bra uttryck att kunna.", vi: "Càng nói nhiều thì sẽ càng dễ hơn. Đây là cách diễn đạt hay nên biết.", phonetic: "/deːt bliːr ˈlɛtːarɛ jʉː meːr man ˈprɑːtar/" },
  { id: 1410, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Tack för hjälpen, det betydde mycket! Jag använder det gärna i samtal.", vi: "Cảm ơn vì đã giúp đỡ, điều đó có ý nghĩa lắm! Mình thích dùng câu này khi trò chuyện.", phonetic: "/tak fœr ˈjɛlːpɛn deː bɛˈtʏːdːɛ ˈmʏkːɛt/" },
  { id: 1411, topic: "Gia đình & người thân", sv: "Jag pratar med min man varje dag om framtiden. Det passar bra i många situationer.", vi: "Mình trò chuyện với chồng mỗi ngày về tương lai. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ ˈprɑːtar meːd miːn man ˈvarːjɛ dɑːɡ ɔm ˈfrɑːmˌtiːdɛn/" },
  { id: 1412, topic: "Gia đình & người thân", sv: "Vi planerar vårt nya liv tillsammans i lugn takt. Det hjälper mig att uttrycka mig klart.", vi: "Tụi mình lên kế hoạch cho cuộc sống mới cùng nhau một cách chầm chậm. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/viː plɑˈneːrar voːʈ ˈnʏːa liːv tɪlˈsamːanːs ɪ lɵŋn tɑkt/" },
  { id: 1413, topic: "Gia đình & người thân", sv: "Jag tänker ofta på min mormor hemma. Det känns avslappnat och vardagligt.", vi: "Mình thường nhớ tới bà ngoại ở nhà. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ ˈtɛŋːkɛr ˈɔfːta pɔː miːn ˈmʊːrmʊr ˈhɛmːa/" },
  { id: 1414, topic: "Gia đình & người thân", sv: "Familjen betyder allt när man är långt hemifrån. Det är ett bra uttryck att kunna.", vi: "Gia đình có ý nghĩa tất cả khi ở xa nhà. Đây là cách diễn đạt hay nên biết.", phonetic: "/fɑˈmiːljɛn bɛˈtʏːdɛr alːt nɛːr man ɛːr lɔŋt ˈhɛmːɪˌfroːn/" },
  { id: 1415, topic: "Gia đình & người thân", sv: "Vi ringer videosamtal på helgen när alla är lediga. Jag använder det gärna i samtal.", vi: "Tụi mình gọi video vào cuối tuần khi ai cũng rảnh. Mình thích dùng câu này khi trò chuyện.", phonetic: "/viː ˈrɪŋːɛr ˈviːdɛʊˌsamːtɑːl pɔː ˈhɛlːjɛn nɛːr ˈalːa ɛːr ˈleːdɪɡa/" },
  { id: 1416, topic: "Gia đình & người thân", sv: "Han lagar god mat och stöttar mig alltid. Det passar bra i många situationer.", vi: "Anh ấy nấu ăn ngon và luôn ủng hộ mình. Câu này dùng được trong nhiều tình huống.", phonetic: "/han ˈlɑːɡar ɡuːd mɑːt ɔ ˈstœtːar mej ˈalːtiːd/" },
  { id: 1417, topic: "Gia đình & người thân", sv: "Att hjälpa varandra gör vardagen enklare. Det hjälper mig att uttrycka mig klart.", vi: "Giúp đỡ lẫn nhau khiến cuộc sống hằng ngày nhẹ nhàng hơn. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/at ˈjɛlːpa vɑˈranːdra jøːr ˈvɑːrˌdɑːɡɛn ˈɛŋːklarɛ/" },
  { id: 1418, topic: "Gia đình & người thân", sv: "Jag vill gärna bjuda hem familjen på middag någon gång. Det känns avslappnat och vardagligt.", vi: "Mình rất muốn mời gia đình đến nhà ăn tối một dịp nào đó. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ vɪl ˈjɛːrna ˈbjʉːda hɛm fɑˈmiːljɛn pɔː ˈmɪdːɑːɡ ˈnoːɡɔn ɡɔŋ/" },
  { id: 1419, topic: "Gia đình & người thân", sv: "Det känns tryggt att ha någon som förstår en. Det är ett bra uttryck att kunna.", vi: "Thật vững tâm khi có người thấu hiểu mình. Đây là cách diễn đạt hay nên biết.", phonetic: "/deːt ɕɛnːs trʏɡt at hɑː ˈnoːɡɔn sɔm fœrˈstoːr ɛn/" },
  { id: 1420, topic: "Gia đình & người thân", sv: "Vi delar både glädje och små bekymmer. Jag använder det gärna i samtal.", vi: "Tụi mình chia sẻ cả niềm vui lẫn những nỗi lo nhỏ. Mình thích dùng câu này khi trò chuyện.", phonetic: "/viː ˈdeːlar ˈboːdɛ ˈɡlɛːdjɛ ɔ smoː bɛˈɕʏmːɛr/" },
  { id: 1421, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag gillar att ta en promenad i parken efter jobbet. Det passar bra i många situationer.", vi: "Mình thích đi dạo trong công viên sau giờ làm. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ ˈjɪlːar at tɑː ɛn prʊmɛˈnɑːd ɪ ˈparːkɛn ˈɛfːtɛr ˈjɔbːɛt/" },
  { id: 1422, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Frisk luft och grönska hjälper mig att ladda om. Det hjälper mig att uttrycka mig klart.", vi: "Không khí trong lành và cây xanh giúp mình nạp lại năng lượng. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/frɪsk lɵft ɔ ˈɡrœnːska ˈjɛlːpɛr mej at ˈladːa ɔm/" },
  { id: 1423, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vilken vacker utsikt över sjön och skogen! Det känns avslappnat och vardagligt.", vi: "Khung cảnh nhìn ra hồ và rừng đẹp quá! Nghe rất tự nhiên và gần gũi.", phonetic: "/ˈvɪlːkɛn ˈvakːɛr ˈʉːtˌsɪkːt ˈøːvɛr ɕøːn ɔ ˈskuːɡɛn/" },
  { id: 1424, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag brukar ta foton på naturen när vi reser. Det är ett bra uttryck att kunna.", vi: "Mình hay chụp ảnh thiên nhiên khi tụi mình đi du lịch. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈbrʉːkar tɑː ˈfuːtɔn pɔː nɑtʉːˈreːn nɛːr viː ˈreːsɛr/" },
  { id: 1425, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vi åker gärna iväg på helgutflykter till nya platser. Jag använder det gärna i samtal.", vi: "Tụi mình thích đi chơi cuối tuần tới những vùng đất mới. Mình thích dùng câu này khi trò chuyện.", phonetic: "/viː ˈoːkɛr ˈjɛːrna ɪˈvɛːɡ pɔː ˈhɛljˌʉːtflʏkːtɛr tɪl ˈnʏːa ˈplatːsɛr/" },
  { id: 1426, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Ljuset på morgonen och kvällen är så fint att fotografera. Det passar bra i många situationer.", vi: "Ánh sáng buổi sáng và buổi chiều tối chụp ảnh đẹp lắm. Câu này dùng được trong nhiều tình huống.", phonetic: "/ˈjʉːsɛt pɔː ˈmɔrːɔnɛn ɔ ˈkvɛlːɛn ɛːr soː fiːnt at fʊtʊɡrɑˈfeːra/" },
  { id: 1427, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Det är så tyst och rofyllt här borta vid vattnet. Det hjälper mig att uttrycka mig klart.", vi: "Ở khu vực ven nước này thật yên tĩnh và thanh bình. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/deːt ɛːr soː tʏst ɔ ˈrʊːˌfʏlt hɛːr ˈbɔrːta viːd ˈvatːnɛt/" },
  { id: 1428, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vi tar det lugnt och njuter av resan i vårt eget tempo. Det känns avslappnat och vardagligt.", vi: "Tụi mình đi thong thả và tận hưởng chuyến đi theo nhịp của riêng mình. Nghe rất tự nhiên và gần gũi.", phonetic: "/viː tɑːr deː lɵŋt ɔ ˈnjʉːtɛr ɑːv ˈreːsan ɪ voːʈ ˈeːɡɛt ˈtɛmːpʊ/" },
  { id: 1429, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag älskar när solen tittar fram mellan molnen. Det är ett bra uttryck att kunna.", vi: "Mình thích khoảnh khắc mặt trời ló dạng giữa những đám mây. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈɛlːskar nɛːr ˈsuːlɛn ˈtɪtːar fram ˈmɛlːan ˈmuːlnɛn/" },
  { id: 1430, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Att komma ut i naturen rensar tankarna. Jag använder det gärna i samtal.", vi: "Ra ngoài thiên nhiên giúp đầu óc thư thái hẳn. Mình thích dùng câu này khi trò chuyện.", phonetic: "/at ˈkɔmːa ʉːt ɪ nɑtʉːˈreːn ˈrɛnːsar ˈtaŋːkarːa/" },
  { id: 1431, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På kvällen gillar jag att varva ner hemma med en bra film. Det passar bra i många situationer.", vi: "Buổi tối mình thích thư giãn ở nhà với một bộ phim hay. Câu này dùng được trong nhiều tình huống.", phonetic: "/pɔː ˈkvɛlːɛn ˈjɪlːar jɑːɡ at ˈvarːva neːr ˈhɛmːa meːd ɛn brɑː fɪlm/" },
  { id: 1432, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det är skönt att krypa upp i soffan efter en aktiv dag. Det hjälper mig att uttrycka mig klart.", vi: "Thật dễ chịu khi cuộn mình trên ghế sofa sau một ngày năng động. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/deːt ɛːr ɕøːnt at ˈkrʏːpa ɵpː ɪ ˈsɔfːan ˈɛfːtɛr ɛn ˈakːtɪv dɑːɡ/" },
  { id: 1433, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vi spelar sällskapsspel och ordlekar när vi är många. Det känns avslappnat och vardagligt.", vi: "Tụi mình chơi board game và trò nối chữ khi có đông người. Nghe rất tự nhiên và gần gũi.", phonetic: "/viː ˈsɛlːskɑpsˌspeːl ɔ ˈuːɖˌleːkar nɛːr viː ɛːr ˈmɔŋːa/" },
  { id: 1434, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det är så kul att skratta tillsammans över en spelomgång. Det är ett bra uttryck att kunna.", vi: "Cùng cười rôm rả qua một ván chơi vui thật đấy. Đây là cách diễn đạt hay nên biết.", phonetic: "/deːt ɛːr soː kʉːl at ˈskratːa tɪlˈsamːanːs ˈøːvɛr ɛn ˈspeːlˌɔmːɡɔŋ/" },
  { id: 1435, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Jag gillar att ha det städat och mysigt omkring mig. Jag använder det gärna i samtal.", vi: "Mình thích giữ không gian gọn gàng và ấm cúng quanh mình. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ ˈjɪlːar at hɑː deː ˈstɛːdat ɔ ˈmʏːsɪt ɔmˈkrɪŋ mej/" },
  { id: 1436, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "En varm dusch och tystnad hjälper mig att somna gott. Det passar bra i många situationer.", vi: "Một trận tắm nước ấm và sự yên tĩnh giúp mình ngủ ngon. Câu này dùng được trong nhiều tình huống.", phonetic: "/ɛn varm dɵʃ ɔ ˈtʏsːtnɑd ˈjɛlːpɛr mej at ˈsɔmːna ɡɔt/" },
  { id: 1437, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Jag tar gärna en kort paus när jag behöver samla kraft. Det hjälper mig att uttrycka mig klart.", vi: "Mình hay nghỉ giải lao ngắn khi cần lấy lại sức. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn kɔʈ paɵs nɛːr jɑːɡ bɛˈhøːvɛr ˈsamːla krɑft/" },
  { id: 1438, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vilken film eller serie tyckte du bäst om nyligen? Det känns avslappnat och vardagligt.", vi: "Gần đây bạn thích phim điện ảnh hay phim bộ nào nhất? Nghe rất tự nhiên và gần gũi.", phonetic: "/ˈvɪlːkɛn fɪlm ˈɛlːɛr ˈseːrɪɛ ˈtʏkːtɛ dʉː bɛst ɔm ˈnʏːˌliːɡɛn/" },
  { id: 1439, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vi gör en enkel fika med kaffe och frukt idag. Det är ett bra uttryck att kunna.", vi: "Hôm nay tụi mình làm bữa fika nhẹ nhàng với cà phê và trái cây. Đây là cách diễn đạt hay nên biết.", phonetic: "/viː jøːr ɛn ˈɛŋːkɛl ˈfiːka meːd ˈkafːɛ ɔ frɵkt ɪˈdɑːɡ/" },
  { id: 1440, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det känns skönt att bara vara sig själv i lugn och ro. Jag använder det gärna i samtal.", vi: "Thật thoải mái khi được là chính mình trong yên bình. Mình thích dùng câu này khi trò chuyện.", phonetic: "/deːt ɕɛnːs ɕøːnt at ˈbɑːra ˈvɑːra sej ɕɛlv ɪ lɵŋn ɔ rʊː/" },
  { id: 1441, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Ursäkta, vet du var närmaste busshållplats ligger? Det passar bra i många situationer.", vi: "Xin lỗi, bạn có biết trạm xe buýt gần nhất ở đâu không? Câu này dùng được trong nhiều tình huống.", phonetic: "/ˈʉːˌʂɛkːta veːt dʉː vɑːr ˈnɛrmastɛ ˈbɵsˌhɔlːplats ˈlɪɡːɛr/" },
  { id: 1442, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag behöver köpa frukt, grönsaker och bröd idag. Det hjälper mig att uttrycka mig klart.", vi: "Hôm nay mình cần mua trái cây, rau củ và bánh mì. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ bɛˈhøːvɛr ˈɕøːpa frɵkt ˈɡrœnˌsɑːkɛr ɔ brøːd ɪˈdɑːɡ/" },
  { id: 1443, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hur mycket kostar det här totalt? Det känns avslappnat och vardagligt.", vi: "Món này tổng cộng giá bao nhiêu vậy? Nghe rất tự nhiên và gần gũi.", phonetic: "/hʉːr ˈmʏkːɛt ˈkɔsːtar deːt hɛːr tʊˈtɑlt/" },
  { id: 1444, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag tar gärna en påse, tack så mycket. Det är ett bra uttryck att kunna.", vi: "Cho mình xin một túi nhé, cảm ơn bạn nhiều. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn ˈpoːsɛ tak soː ˈmʏkːɛt/" },
  { id: 1445, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Det är ganska svalt ute idag, så jag tar en tröja. Jag använder det gärna i samtal.", vi: "Hôm nay ngoài trời khá mát nên mình mặc thêm áo len. Mình thích dùng câu này khi trò chuyện.", phonetic: "/deːt ɛːr ˈɡanːsa svɑlt ˈʉːtɛ ɪˈdɑːɡ soː jɑːɡ tɑːr ɛn ˈtrœjːa/" },
  { id: 1446, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Vi åker kollektivt eller går när det inte är så långt. Det passar bra i många situationer.", vi: "Tụi mình đi phương tiện công cộng hoặc đi bộ khi không quá xa. Câu này dùng được trong nhiều tình huống.", phonetic: "/viː ˈoːkɛr kʊlːɛkˈtiːvt ˈɛlːɛr ɡoːr nɛːr deː ˈɪnːtɛ ɛːr soː lɔŋt/" },
  { id: 1447, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag sparar undan lite varje månad för framtida planer. Det hjälper mig att uttrycka mig klart.", vi: "Mình dành dụm một chút mỗi tháng cho các kế hoạch tương lai. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ ˈspɑːrar ˈɵnːdan ˈliːtɛ ˈvarːjɛ ˈmoːnad fœr ˈfrɑːmˌtiːda ˈplɑːnɛr/" },
  { id: 1448, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Vädret växlar snabbt, så det är bra att ha paraply med. Det känns avslappnat och vardagligt.", vi: "Thời tiết đổi nhanh lắm nên mang theo ô là tốt nhất. Nghe rất tự nhiên và gần gũi.", phonetic: "/ˈvɛːdrɛt ˈvɛkːslar snɑpt soː deːt ɛːr brɑː at hɑː pɑrɑˈplʏː meːd/" },
  { id: 1449, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag gillar tydliga och enkla rutiner i vardagen. Det är ett bra uttryck att kunna.", vi: "Mình thích những thói quen rõ ràng và đơn giản trong ngày. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈjɪlːar ˈtʏːdliɡa ɔ ˈɛŋːkla rɵˈtiːnɛr ɪ ˈvɑːrˌdɑːɡɛn/" },
  { id: 1450, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Varje litet steg framåt räknas. Jag använder det gärna i samtal.", vi: "Mỗi bước tiến nhỏ về phía trước đều đáng quý. Mình thích dùng câu này khi trò chuyện.", phonetic: "/ˈvarːjɛ ˈliːtɛt steːɡ ˈfrɑːmˌɔːt ˈrɛkːnas/" },
  { id: 1451, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag tränar svenska säger jag: God morgon! Hur har du sovit?", vi: "Khi luyện tiếng Thụy Điển mình nói: Chào buổi sáng! Bạn ngủ có ngon không?", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr hɑːr dʉː ˈsʊːvɪt/" },
  { id: 1452, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "På utflykt eller promenad säger jag: Jag vaknade tidigt idag och tog en lugn start.", vi: "Khi đi chơi hoặc đi dạo mình nói: Hôm nay mình dậy sớm và khởi đầu thật nhẹ nhàng.", phonetic: "/jɑːɡ ˈvɑːknadɛ ˈtiːdɪt ɪˈdɑːɡ ɔ tʊːɡ ɛn lɵŋn stɑʈ/" },
  { id: 1453, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "I vardagen säger jag: Vad ska vi äta till middag ikväll?", vi: "Trong đời sống hằng ngày mình nói: Tối nay tụi mình sẽ ăn gì nhỉ?", phonetic: "/vɑːd skɑː viː ˈɛːta tɪl ˈmɪdːɑːɡ ɪˈkvɛlː/" },
  { id: 1454, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag pratar med vänner säger jag: Jag håller på att laga mat i köket nu.", vi: "Khi trò chuyện với bạn bè mình nói: Bây giờ mình đang nấu ăn trong bếp.", phonetic: "/jɑːɡ ˈhɔlːɛr pɔː at ˈlɑːɡa mɑːt ɪ ˈɕøːkɛt nʉː/" },
  { id: 1455, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Hemma och på fritiden säger jag: Kan du upprepa det lite långsammare, tack?", vi: "Ở nhà và lúc rảnh mình nói: Bạn lặp lại chậm hơn một chút được không, cảm ơn bạn?", phonetic: "/kan dʉː ɵpːrɛˈpɑː deː ˈliːtɛ ˈlɔŋːsamːarɛ tak/" },
  { id: 1456, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag tränar svenska säger jag: Jag förstår ungefär vad du menar, men jag övar fortfarande.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình hiểu đại khái ý bạn, nhưng mình vẫn đang luyện thêm.", phonetic: "/jɑːɡ fœrˈstoːr ɵnːfɛˈjɛːr vɑːd dʉː ˈmeːnar mɛn jɑːɡ ˈøːvar ˈfɔrtˌfarːandɛ/" },
  { id: 1457, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "På utflykt eller promenad säger jag: Det här ordet är nytt för mig. Vad betyder det?", vi: "Khi đi chơi hoặc đi dạo mình nói: Từ này mới với mình. Nó có nghĩa là gì vậy?", phonetic: "/deːt hɛːr ˈuːɖɛt ɛːr nʏt fœr mej vɑːd bɛˈtʏːdɛr deː/" },
  { id: 1458, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "I vardagen säger jag: Jag övar på att prata svenska varje dag.", vi: "Trong đời sống hằng ngày mình nói: Mình luyện nói tiếng Thụy Điển mỗi ngày.", phonetic: "/jɑːɡ ˈøːvar pɔː at ˈprɑːta ˈsvɛnːska ˈvarːjɛ dɑːɡ/" },
  { id: 1459, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag pratar med vänner säger jag: Det blir lättare ju mer man pratar.", vi: "Khi trò chuyện với bạn bè mình nói: Càng nói nhiều thì sẽ càng dễ hơn.", phonetic: "/deːt bliːr ˈlɛtːarɛ jʉː meːr man ˈprɑːtar/" },
  { id: 1460, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Hemma och på fritiden säger jag: Tack för hjälpen, det betydde mycket!", vi: "Ở nhà và lúc rảnh mình nói: Cảm ơn vì đã giúp đỡ, điều đó có ý nghĩa lắm!", phonetic: "/tak fœr ˈjɛlːpɛn deː bɛˈtʏːdːɛ ˈmʏkːɛt/" },
  { id: 1461, topic: "Gia đình & người thân", sv: "När jag tränar svenska säger jag: Jag pratar med min man varje dag om framtiden.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình trò chuyện với chồng mỗi ngày về tương lai.", phonetic: "/jɑːɡ ˈprɑːtar meːd miːn man ˈvarːjɛ dɑːɡ ɔm ˈfrɑːmˌtiːdɛn/" },
  { id: 1462, topic: "Gia đình & người thân", sv: "På utflykt eller promenad säger jag: Vi planerar vårt nya liv tillsammans i lugn takt.", vi: "Khi đi chơi hoặc đi dạo mình nói: Tụi mình lên kế hoạch cho cuộc sống mới cùng nhau một cách chầm chậm.", phonetic: "/viː plɑˈneːrar voːʈ ˈnʏːa liːv tɪlˈsamːanːs ɪ lɵŋn tɑkt/" },
  { id: 1463, topic: "Gia đình & người thân", sv: "I vardagen säger jag: Jag tänker ofta på min mormor hemma.", vi: "Trong đời sống hằng ngày mình nói: Mình thường nhớ tới bà ngoại ở nhà.", phonetic: "/jɑːɡ ˈtɛŋːkɛr ˈɔfːta pɔː miːn ˈmʊːrmʊr ˈhɛmːa/" },
  { id: 1464, topic: "Gia đình & người thân", sv: "När jag pratar med vänner säger jag: Familjen betyder allt när man är långt hemifrån.", vi: "Khi trò chuyện với bạn bè mình nói: Gia đình có ý nghĩa tất cả khi ở xa nhà.", phonetic: "/fɑˈmiːljɛn bɛˈtʏːdɛr alːt nɛːr man ɛːr lɔŋt ˈhɛmːɪˌfroːn/" },
  { id: 1465, topic: "Gia đình & người thân", sv: "Hemma och på fritiden säger jag: Vi ringer videosamtal på helgen när alla är lediga.", vi: "Ở nhà và lúc rảnh mình nói: Tụi mình gọi video vào cuối tuần khi ai cũng rảnh.", phonetic: "/viː ˈrɪŋːɛr ˈviːdɛʊˌsamːtɑːl pɔː ˈhɛlːjɛn nɛːr ˈalːa ɛːr ˈleːdɪɡa/" },
  { id: 1466, topic: "Gia đình & người thân", sv: "När jag tränar svenska säger jag: Han lagar god mat och stöttar mig alltid.", vi: "Khi luyện tiếng Thụy Điển mình nói: Anh ấy nấu ăn ngon và luôn ủng hộ mình.", phonetic: "/han ˈlɑːɡar ɡuːd mɑːt ɔ ˈstœtːar mej ˈalːtiːd/" },
  { id: 1467, topic: "Gia đình & người thân", sv: "På utflykt eller promenad säger jag: Att hjälpa varandra gör vardagen enklare.", vi: "Khi đi chơi hoặc đi dạo mình nói: Giúp đỡ lẫn nhau khiến cuộc sống hằng ngày nhẹ nhàng hơn.", phonetic: "/at ˈjɛlːpa vɑˈranːdra jøːr ˈvɑːrˌdɑːɡɛn ˈɛŋːklarɛ/" },
  { id: 1468, topic: "Gia đình & người thân", sv: "I vardagen säger jag: Jag vill gärna bjuda hem familjen på middag någon gång.", vi: "Trong đời sống hằng ngày mình nói: Mình rất muốn mời gia đình đến nhà ăn tối một dịp nào đó.", phonetic: "/jɑːɡ vɪl ˈjɛːrna ˈbjʉːda hɛm fɑˈmiːljɛn pɔː ˈmɪdːɑːɡ ˈnoːɡɔn ɡɔŋ/" },
  { id: 1469, topic: "Gia đình & người thân", sv: "När jag pratar med vänner säger jag: Det känns tryggt att ha någon som förstår en.", vi: "Khi trò chuyện với bạn bè mình nói: Thật vững tâm khi có người thấu hiểu mình.", phonetic: "/deːt ɕɛnːs trʏɡt at hɑː ˈnoːɡɔn sɔm fœrˈstoːr ɛn/" },
  { id: 1470, topic: "Gia đình & người thân", sv: "Hemma och på fritiden säger jag: Vi delar både glädje och små bekymmer.", vi: "Ở nhà và lúc rảnh mình nói: Tụi mình chia sẻ cả niềm vui lẫn những nỗi lo nhỏ.", phonetic: "/viː ˈdeːlar ˈboːdɛ ˈɡlɛːdjɛ ɔ smoː bɛˈɕʏmːɛr/" },
  { id: 1471, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag tränar svenska säger jag: Jag gillar att ta en promenad i parken efter jobbet.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình thích đi dạo trong công viên sau giờ làm.", phonetic: "/jɑːɡ ˈjɪlːar at tɑː ɛn prʊmɛˈnɑːd ɪ ˈparːkɛn ˈɛfːtɛr ˈjɔbːɛt/" },
  { id: 1472, topic: "Thiên nhiên, đi dạo & du lịch", sv: "På utflykt eller promenad säger jag: Frisk luft och grönska hjälper mig att ladda om.", vi: "Khi đi chơi hoặc đi dạo mình nói: Không khí trong lành và cây xanh giúp mình nạp lại năng lượng.", phonetic: "/frɪsk lɵft ɔ ˈɡrœnːska ˈjɛlːpɛr mej at ˈladːa ɔm/" },
  { id: 1473, topic: "Thiên nhiên, đi dạo & du lịch", sv: "I vardagen säger jag: Vilken vacker utsikt över sjön och skogen!", vi: "Trong đời sống hằng ngày mình nói: Khung cảnh nhìn ra hồ và rừng đẹp quá!", phonetic: "/ˈvɪlːkɛn ˈvakːɛr ˈʉːtˌsɪkːt ˈøːvɛr ɕøːn ɔ ˈskuːɡɛn/" },
  { id: 1474, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag pratar med vänner säger jag: Jag brukar ta foton på naturen när vi reser.", vi: "Khi trò chuyện với bạn bè mình nói: Mình hay chụp ảnh thiên nhiên khi tụi mình đi du lịch.", phonetic: "/jɑːɡ ˈbrʉːkar tɑː ˈfuːtɔn pɔː nɑtʉːˈreːn nɛːr viː ˈreːsɛr/" },
  { id: 1475, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Hemma och på fritiden säger jag: Vi åker gärna iväg på helgutflykter till nya platser.", vi: "Ở nhà và lúc rảnh mình nói: Tụi mình thích đi chơi cuối tuần tới những vùng đất mới.", phonetic: "/viː ˈoːkɛr ˈjɛːrna ɪˈvɛːɡ pɔː ˈhɛljˌʉːtflʏkːtɛr tɪl ˈnʏːa ˈplatːsɛr/" },
  { id: 1476, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag tränar svenska säger jag: Ljuset på morgonen och kvällen är så fint att fotografera.", vi: "Khi luyện tiếng Thụy Điển mình nói: Ánh sáng buổi sáng và buổi chiều tối chụp ảnh đẹp lắm.", phonetic: "/ˈjʉːsɛt pɔː ˈmɔrːɔnɛn ɔ ˈkvɛlːɛn ɛːr soː fiːnt at fʊtʊɡrɑˈfeːra/" },
  { id: 1477, topic: "Thiên nhiên, đi dạo & du lịch", sv: "På utflykt eller promenad säger jag: Det är så tyst och rofyllt här borta vid vattnet.", vi: "Khi đi chơi hoặc đi dạo mình nói: Ở khu vực ven nước này thật yên tĩnh và thanh bình.", phonetic: "/deːt ɛːr soː tʏst ɔ ˈrʊːˌfʏlt hɛːr ˈbɔrːta viːd ˈvatːnɛt/" },
  { id: 1478, topic: "Thiên nhiên, đi dạo & du lịch", sv: "I vardagen säger jag: Vi tar det lugnt och njuter av resan i vårt eget tempo.", vi: "Trong đời sống hằng ngày mình nói: Tụi mình đi thong thả và tận hưởng chuyến đi theo nhịp của riêng mình.", phonetic: "/viː tɑːr deː lɵŋt ɔ ˈnjʉːtɛr ɑːv ˈreːsan ɪ voːʈ ˈeːɡɛt ˈtɛmːpʊ/" },
  { id: 1479, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag pratar med vänner säger jag: Jag älskar när solen tittar fram mellan molnen.", vi: "Khi trò chuyện với bạn bè mình nói: Mình thích khoảnh khắc mặt trời ló dạng giữa những đám mây.", phonetic: "/jɑːɡ ˈɛlːskar nɛːr ˈsuːlɛn ˈtɪtːar fram ˈmɛlːan ˈmuːlnɛn/" },
  { id: 1480, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Hemma och på fritiden säger jag: Att komma ut i naturen rensar tankarna.", vi: "Ở nhà và lúc rảnh mình nói: Ra ngoài thiên nhiên giúp đầu óc thư thái hẳn.", phonetic: "/at ˈkɔmːa ʉːt ɪ nɑtʉːˈreːn ˈrɛnːsar ˈtaŋːkarːa/" },
  { id: 1481, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag tränar svenska säger jag: På kvällen gillar jag att varva ner hemma med en bra film.", vi: "Khi luyện tiếng Thụy Điển mình nói: Buổi tối mình thích thư giãn ở nhà với một bộ phim hay.", phonetic: "/pɔː ˈkvɛlːɛn ˈjɪlːar jɑːɡ at ˈvarːva neːr ˈhɛmːa meːd ɛn brɑː fɪlm/" },
  { id: 1482, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På utflykt eller promenad säger jag: Det är skönt att krypa upp i soffan efter en aktiv dag.", vi: "Khi đi chơi hoặc đi dạo mình nói: Thật dễ chịu khi cuộn mình trên ghế sofa sau một ngày năng động.", phonetic: "/deːt ɛːr ɕøːnt at ˈkrʏːpa ɵpː ɪ ˈsɔfːan ˈɛfːtɛr ɛn ˈakːtɪv dɑːɡ/" },
  { id: 1483, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "I vardagen säger jag: Vi spelar sällskapsspel och ordlekar när vi är många.", vi: "Trong đời sống hằng ngày mình nói: Tụi mình chơi board game và trò nối chữ khi có đông người.", phonetic: "/viː ˈsɛlːskɑpsˌspeːl ɔ ˈuːɖˌleːkar nɛːr viː ɛːr ˈmɔŋːa/" },
  { id: 1484, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag pratar med vänner säger jag: Det är så kul att skratta tillsammans över en spelomgång.", vi: "Khi trò chuyện với bạn bè mình nói: Cùng cười rôm rả qua một ván chơi vui thật đấy.", phonetic: "/deːt ɛːr soː kʉːl at ˈskratːa tɪlˈsamːanːs ˈøːvɛr ɛn ˈspeːlˌɔmːɡɔŋ/" },
  { id: 1485, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Hemma och på fritiden säger jag: Jag gillar att ha det städat och mysigt omkring mig.", vi: "Ở nhà và lúc rảnh mình nói: Mình thích giữ không gian gọn gàng và ấm cúng quanh mình.", phonetic: "/jɑːɡ ˈjɪlːar at hɑː deː ˈstɛːdat ɔ ˈmʏːsɪt ɔmˈkrɪŋ mej/" },
  { id: 1486, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag tränar svenska säger jag: En varm dusch och tystnad hjälper mig att somna gott.", vi: "Khi luyện tiếng Thụy Điển mình nói: Một trận tắm nước ấm và sự yên tĩnh giúp mình ngủ ngon.", phonetic: "/ɛn varm dɵʃ ɔ ˈtʏsːtnɑd ˈjɛlːpɛr mej at ˈsɔmːna ɡɔt/" },
  { id: 1487, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På utflykt eller promenad säger jag: Jag tar gärna en kort paus när jag behöver samla kraft.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình hay nghỉ giải lao ngắn khi cần lấy lại sức.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn kɔʈ paɵs nɛːr jɑːɡ bɛˈhøːvɛr ˈsamːla krɑft/" },
  { id: 1488, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "I vardagen säger jag: Vilken film eller serie tyckte du bäst om nyligen?", vi: "Trong đời sống hằng ngày mình nói: Gần đây bạn thích phim điện ảnh hay phim bộ nào nhất?", phonetic: "/ˈvɪlːkɛn fɪlm ˈɛlːɛr ˈseːrɪɛ ˈtʏkːtɛ dʉː bɛst ɔm ˈnʏːˌliːɡɛn/" },
  { id: 1489, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag pratar med vänner säger jag: Vi gör en enkel fika med kaffe och frukt idag.", vi: "Khi trò chuyện với bạn bè mình nói: Hôm nay tụi mình làm bữa fika nhẹ nhàng với cà phê và trái cây.", phonetic: "/viː jøːr ɛn ˈɛŋːkɛl ˈfiːka meːd ˈkafːɛ ɔ frɵkt ɪˈdɑːɡ/" },
  { id: 1490, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Hemma och på fritiden säger jag: Det känns skönt att bara vara sig själv i lugn och ro.", vi: "Ở nhà và lúc rảnh mình nói: Thật thoải mái khi được là chính mình trong yên bình.", phonetic: "/deːt ɕɛnːs ɕøːnt at ˈbɑːra ˈvɑːra sej ɕɛlv ɪ lɵŋn ɔ rʊː/" },
  { id: 1491, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag tränar svenska säger jag: Ursäkta, vet du var närmaste busshållplats ligger?", vi: "Khi luyện tiếng Thụy Điển mình nói: Xin lỗi, bạn có biết trạm xe buýt gần nhất ở đâu không?", phonetic: "/ˈʉːˌʂɛkːta veːt dʉː vɑːr ˈnɛrmastɛ ˈbɵsˌhɔlːplats ˈlɪɡːɛr/" },
  { id: 1492, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "På utflykt eller promenad säger jag: Jag behöver köpa frukt, grönsaker och bröd idag.", vi: "Khi đi chơi hoặc đi dạo mình nói: Hôm nay mình cần mua trái cây, rau củ và bánh mì.", phonetic: "/jɑːɡ bɛˈhøːvɛr ˈɕøːpa frɵkt ˈɡrœnˌsɑːkɛr ɔ brøːd ɪˈdɑːɡ/" },
  { id: 1493, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "I vardagen säger jag: Hur mycket kostar det här totalt?", vi: "Trong đời sống hằng ngày mình nói: Món này tổng cộng giá bao nhiêu vậy?", phonetic: "/hʉːr ˈmʏkːɛt ˈkɔsːtar deːt hɛːr tʊˈtɑlt/" },
  { id: 1494, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag pratar med vänner säger jag: Jag tar gärna en påse, tack så mycket.", vi: "Khi trò chuyện với bạn bè mình nói: Cho mình xin một túi nhé, cảm ơn bạn nhiều.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn ˈpoːsɛ tak soː ˈmʏkːɛt/" },
  { id: 1495, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hemma och på fritiden säger jag: Det är ganska svalt ute idag, så jag tar en tröja.", vi: "Ở nhà và lúc rảnh mình nói: Hôm nay ngoài trời khá mát nên mình mặc thêm áo len.", phonetic: "/deːt ɛːr ˈɡanːsa svɑlt ˈʉːtɛ ɪˈdɑːɡ soː jɑːɡ tɑːr ɛn ˈtrœjːa/" },
  { id: 1496, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag tränar svenska säger jag: Vi åker kollektivt eller går när det inte är så långt.", vi: "Khi luyện tiếng Thụy Điển mình nói: Tụi mình đi phương tiện công cộng hoặc đi bộ khi không quá xa.", phonetic: "/viː ˈoːkɛr kʊlːɛkˈtiːvt ˈɛlːɛr ɡoːr nɛːr deː ˈɪnːtɛ ɛːr soː lɔŋt/" },
  { id: 1497, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "På utflykt eller promenad säger jag: Jag sparar undan lite varje månad för framtida planer.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình dành dụm một chút mỗi tháng cho các kế hoạch tương lai.", phonetic: "/jɑːɡ ˈspɑːrar ˈɵnːdan ˈliːtɛ ˈvarːjɛ ˈmoːnad fœr ˈfrɑːmˌtiːda ˈplɑːnɛr/" },
  { id: 1498, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "I vardagen säger jag: Vädret växlar snabbt, så det är bra att ha paraply med.", vi: "Trong đời sống hằng ngày mình nói: Thời tiết đổi nhanh lắm nên mang theo ô là tốt nhất.", phonetic: "/ˈvɛːdrɛt ˈvɛkːslar snɑpt soː deːt ɛːr brɑː at hɑː pɑrɑˈplʏː meːd/" },
  { id: 1499, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag pratar med vänner säger jag: Jag gillar tydliga och enkla rutiner i vardagen.", vi: "Khi trò chuyện với bạn bè mình nói: Mình thích những thói quen rõ ràng và đơn giản trong ngày.", phonetic: "/jɑːɡ ˈjɪlːar ˈtʏːdliɡa ɔ ˈɛŋːkla rɵˈtiːnɛr ɪ ˈvɑːrˌdɑːɡɛn/" },
  { id: 1500, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hemma och på fritiden säger jag: Varje litet steg framåt räknas.", vi: "Ở nhà và lúc rảnh mình nói: Mỗi bước tiến nhỏ về phía trước đều đáng quý.", phonetic: "/ˈvarːjɛ ˈliːtɛt steːɡ ˈfrɑːmˌɔːt ˈrɛkːnas/" },
  { id: 1501, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "God morgon! Hur har du sovit? Det känns avslappnat och vardagligt.", vi: "Chào buổi sáng! Bạn ngủ có ngon không? Nghe rất tự nhiên và gần gũi.", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr hɑːr dʉː ˈsʊːvɪt/" },
  { id: 1502, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag vaknade tidigt idag och tog en lugn start. Det är ett bra uttryck att kunna.", vi: "Hôm nay mình dậy sớm và khởi đầu thật nhẹ nhàng. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈvɑːknadɛ ˈtiːdɪt ɪˈdɑːɡ ɔ tʊːɡ ɛn lɵŋn stɑʈ/" },
  { id: 1503, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Vad ska vi äta till middag ikväll? Jag använder det gärna i samtal.", vi: "Tối nay tụi mình sẽ ăn gì nhỉ? Mình thích dùng câu này khi trò chuyện.", phonetic: "/vɑːd skɑː viː ˈɛːta tɪl ˈmɪdːɑːɡ ɪˈkvɛlː/" },
  { id: 1504, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag håller på att laga mat i köket nu. Det passar bra i många situationer.", vi: "Bây giờ mình đang nấu ăn trong bếp. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ ˈhɔlːɛr pɔː at ˈlɑːɡa mɑːt ɪ ˈɕøːkɛt nʉː/" },
  { id: 1505, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Kan du upprepa det lite långsammare, tack? Det hjälper mig att uttrycka mig klart.", vi: "Bạn lặp lại chậm hơn một chút được không, cảm ơn bạn? Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/kan dʉː ɵpːrɛˈpɑː deː ˈliːtɛ ˈlɔŋːsamːarɛ tak/" },
  { id: 1506, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag förstår ungefär vad du menar, men jag övar fortfarande. Det känns avslappnat och vardagligt.", vi: "Mình hiểu đại khái ý bạn, nhưng mình vẫn đang luyện thêm. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ fœrˈstoːr ɵnːfɛˈjɛːr vɑːd dʉː ˈmeːnar mɛn jɑːɡ ˈøːvar ˈfɔrtˌfarːandɛ/" },
  { id: 1507, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Det här ordet är nytt för mig. Vad betyder det? Det är ett bra uttryck att kunna.", vi: "Từ này mới với mình. Nó có nghĩa là gì vậy? Đây là cách diễn đạt hay nên biết.", phonetic: "/deːt hɛːr ˈuːɖɛt ɛːr nʏt fœr mej vɑːd bɛˈtʏːdɛr deː/" },
  { id: 1508, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag övar på att prata svenska varje dag. Jag använder det gärna i samtal.", vi: "Mình luyện nói tiếng Thụy Điển mỗi ngày. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ ˈøːvar pɔː at ˈprɑːta ˈsvɛnːska ˈvarːjɛ dɑːɡ/" },
  { id: 1509, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Det blir lättare ju mer man pratar. Det passar bra i många situationer.", vi: "Càng nói nhiều thì sẽ càng dễ hơn. Câu này dùng được trong nhiều tình huống.", phonetic: "/deːt bliːr ˈlɛtːarɛ jʉː meːr man ˈprɑːtar/" },
  { id: 1510, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Tack för hjälpen, det betydde mycket! Det hjälper mig att uttrycka mig klart.", vi: "Cảm ơn vì đã giúp đỡ, điều đó có ý nghĩa lắm! Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/tak fœr ˈjɛlːpɛn deː bɛˈtʏːdːɛ ˈmʏkːɛt/" },
  { id: 1511, topic: "Gia đình & người thân", sv: "Jag pratar med min man varje dag om framtiden. Det känns avslappnat och vardagligt.", vi: "Mình trò chuyện với chồng mỗi ngày về tương lai. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ ˈprɑːtar meːd miːn man ˈvarːjɛ dɑːɡ ɔm ˈfrɑːmˌtiːdɛn/" },
  { id: 1512, topic: "Gia đình & người thân", sv: "Vi planerar vårt nya liv tillsammans i lugn takt. Det är ett bra uttryck att kunna.", vi: "Tụi mình lên kế hoạch cho cuộc sống mới cùng nhau một cách chầm chậm. Đây là cách diễn đạt hay nên biết.", phonetic: "/viː plɑˈneːrar voːʈ ˈnʏːa liːv tɪlˈsamːanːs ɪ lɵŋn tɑkt/" },
  { id: 1513, topic: "Gia đình & người thân", sv: "Jag tänker ofta på min mormor hemma. Jag använder det gärna i samtal.", vi: "Mình thường nhớ tới bà ngoại ở nhà. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ ˈtɛŋːkɛr ˈɔfːta pɔː miːn ˈmʊːrmʊr ˈhɛmːa/" },
  { id: 1514, topic: "Gia đình & người thân", sv: "Familjen betyder allt när man är långt hemifrån. Det passar bra i många situationer.", vi: "Gia đình có ý nghĩa tất cả khi ở xa nhà. Câu này dùng được trong nhiều tình huống.", phonetic: "/fɑˈmiːljɛn bɛˈtʏːdɛr alːt nɛːr man ɛːr lɔŋt ˈhɛmːɪˌfroːn/" },
  { id: 1515, topic: "Gia đình & người thân", sv: "Vi ringer videosamtal på helgen när alla är lediga. Det hjälper mig att uttrycka mig klart.", vi: "Tụi mình gọi video vào cuối tuần khi ai cũng rảnh. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/viː ˈrɪŋːɛr ˈviːdɛʊˌsamːtɑːl pɔː ˈhɛlːjɛn nɛːr ˈalːa ɛːr ˈleːdɪɡa/" },
  { id: 1516, topic: "Gia đình & người thân", sv: "Han lagar god mat och stöttar mig alltid. Det känns avslappnat och vardagligt.", vi: "Anh ấy nấu ăn ngon và luôn ủng hộ mình. Nghe rất tự nhiên và gần gũi.", phonetic: "/han ˈlɑːɡar ɡuːd mɑːt ɔ ˈstœtːar mej ˈalːtiːd/" },
  { id: 1517, topic: "Gia đình & người thân", sv: "Att hjälpa varandra gör vardagen enklare. Det är ett bra uttryck att kunna.", vi: "Giúp đỡ lẫn nhau khiến cuộc sống hằng ngày nhẹ nhàng hơn. Đây là cách diễn đạt hay nên biết.", phonetic: "/at ˈjɛlːpa vɑˈranːdra jøːr ˈvɑːrˌdɑːɡɛn ˈɛŋːklarɛ/" },
  { id: 1518, topic: "Gia đình & người thân", sv: "Jag vill gärna bjuda hem familjen på middag någon gång. Jag använder det gärna i samtal.", vi: "Mình rất muốn mời gia đình đến nhà ăn tối một dịp nào đó. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ vɪl ˈjɛːrna ˈbjʉːda hɛm fɑˈmiːljɛn pɔː ˈmɪdːɑːɡ ˈnoːɡɔn ɡɔŋ/" },
  { id: 1519, topic: "Gia đình & người thân", sv: "Det känns tryggt att ha någon som förstår en. Det passar bra i många situationer.", vi: "Thật vững tâm khi có người thấu hiểu mình. Câu này dùng được trong nhiều tình huống.", phonetic: "/deːt ɕɛnːs trʏɡt at hɑː ˈnoːɡɔn sɔm fœrˈstoːr ɛn/" },
  { id: 1520, topic: "Gia đình & người thân", sv: "Vi delar både glädje och små bekymmer. Det hjälper mig att uttrycka mig klart.", vi: "Tụi mình chia sẻ cả niềm vui lẫn những nỗi lo nhỏ. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/viː ˈdeːlar ˈboːdɛ ˈɡlɛːdjɛ ɔ smoː bɛˈɕʏmːɛr/" },
  { id: 1521, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag gillar att ta en promenad i parken efter jobbet. Det känns avslappnat och vardagligt.", vi: "Mình thích đi dạo trong công viên sau giờ làm. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ ˈjɪlːar at tɑː ɛn prʊmɛˈnɑːd ɪ ˈparːkɛn ˈɛfːtɛr ˈjɔbːɛt/" },
  { id: 1522, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Frisk luft och grönska hjälper mig att ladda om. Det är ett bra uttryck att kunna.", vi: "Không khí trong lành và cây xanh giúp mình nạp lại năng lượng. Đây là cách diễn đạt hay nên biết.", phonetic: "/frɪsk lɵft ɔ ˈɡrœnːska ˈjɛlːpɛr mej at ˈladːa ɔm/" },
  { id: 1523, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vilken vacker utsikt över sjön och skogen! Jag använder det gärna i samtal.", vi: "Khung cảnh nhìn ra hồ và rừng đẹp quá! Mình thích dùng câu này khi trò chuyện.", phonetic: "/ˈvɪlːkɛn ˈvakːɛr ˈʉːtˌsɪkːt ˈøːvɛr ɕøːn ɔ ˈskuːɡɛn/" },
  { id: 1524, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag brukar ta foton på naturen när vi reser. Det passar bra i många situationer.", vi: "Mình hay chụp ảnh thiên nhiên khi tụi mình đi du lịch. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ ˈbrʉːkar tɑː ˈfuːtɔn pɔː nɑtʉːˈreːn nɛːr viː ˈreːsɛr/" },
  { id: 1525, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vi åker gärna iväg på helgutflykter till nya platser. Det hjälper mig att uttrycka mig klart.", vi: "Tụi mình thích đi chơi cuối tuần tới những vùng đất mới. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/viː ˈoːkɛr ˈjɛːrna ɪˈvɛːɡ pɔː ˈhɛljˌʉːtflʏkːtɛr tɪl ˈnʏːa ˈplatːsɛr/" },
  { id: 1526, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Ljuset på morgonen och kvällen är så fint att fotografera. Det känns avslappnat och vardagligt.", vi: "Ánh sáng buổi sáng và buổi chiều tối chụp ảnh đẹp lắm. Nghe rất tự nhiên và gần gũi.", phonetic: "/ˈjʉːsɛt pɔː ˈmɔrːɔnɛn ɔ ˈkvɛlːɛn ɛːr soː fiːnt at fʊtʊɡrɑˈfeːra/" },
  { id: 1527, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Det är så tyst och rofyllt här borta vid vattnet. Det är ett bra uttryck att kunna.", vi: "Ở khu vực ven nước này thật yên tĩnh và thanh bình. Đây là cách diễn đạt hay nên biết.", phonetic: "/deːt ɛːr soː tʏst ɔ ˈrʊːˌfʏlt hɛːr ˈbɔrːta viːd ˈvatːnɛt/" },
  { id: 1528, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vi tar det lugnt och njuter av resan i vårt eget tempo. Jag använder det gärna i samtal.", vi: "Tụi mình đi thong thả và tận hưởng chuyến đi theo nhịp của riêng mình. Mình thích dùng câu này khi trò chuyện.", phonetic: "/viː tɑːr deː lɵŋt ɔ ˈnjʉːtɛr ɑːv ˈreːsan ɪ voːʈ ˈeːɡɛt ˈtɛmːpʊ/" },
  { id: 1529, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag älskar när solen tittar fram mellan molnen. Det passar bra i många situationer.", vi: "Mình thích khoảnh khắc mặt trời ló dạng giữa những đám mây. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ ˈɛlːskar nɛːr ˈsuːlɛn ˈtɪtːar fram ˈmɛlːan ˈmuːlnɛn/" },
  { id: 1530, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Att komma ut i naturen rensar tankarna. Det hjälper mig att uttrycka mig klart.", vi: "Ra ngoài thiên nhiên giúp đầu óc thư thái hẳn. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/at ˈkɔmːa ʉːt ɪ nɑtʉːˈreːn ˈrɛnːsar ˈtaŋːkarːa/" },
  { id: 1531, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På kvällen gillar jag att varva ner hemma med en bra film. Det känns avslappnat och vardagligt.", vi: "Buổi tối mình thích thư giãn ở nhà với một bộ phim hay. Nghe rất tự nhiên và gần gũi.", phonetic: "/pɔː ˈkvɛlːɛn ˈjɪlːar jɑːɡ at ˈvarːva neːr ˈhɛmːa meːd ɛn brɑː fɪlm/" },
  { id: 1532, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det är skönt att krypa upp i soffan efter en aktiv dag. Det är ett bra uttryck att kunna.", vi: "Thật dễ chịu khi cuộn mình trên ghế sofa sau một ngày năng động. Đây là cách diễn đạt hay nên biết.", phonetic: "/deːt ɛːr ɕøːnt at ˈkrʏːpa ɵpː ɪ ˈsɔfːan ˈɛfːtɛr ɛn ˈakːtɪv dɑːɡ/" },
  { id: 1533, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vi spelar sällskapsspel och ordlekar när vi är många. Jag använder det gärna i samtal.", vi: "Tụi mình chơi board game và trò nối chữ khi có đông người. Mình thích dùng câu này khi trò chuyện.", phonetic: "/viː ˈsɛlːskɑpsˌspeːl ɔ ˈuːɖˌleːkar nɛːr viː ɛːr ˈmɔŋːa/" },
  { id: 1534, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det är så kul att skratta tillsammans över en spelomgång. Det passar bra i många situationer.", vi: "Cùng cười rôm rả qua một ván chơi vui thật đấy. Câu này dùng được trong nhiều tình huống.", phonetic: "/deːt ɛːr soː kʉːl at ˈskratːa tɪlˈsamːanːs ˈøːvɛr ɛn ˈspeːlˌɔmːɡɔŋ/" },
  { id: 1535, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Jag gillar att ha det städat och mysigt omkring mig. Det hjälper mig att uttrycka mig klart.", vi: "Mình thích giữ không gian gọn gàng và ấm cúng quanh mình. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ ˈjɪlːar at hɑː deː ˈstɛːdat ɔ ˈmʏːsɪt ɔmˈkrɪŋ mej/" },
  { id: 1536, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "En varm dusch och tystnad hjälper mig att somna gott. Det känns avslappnat och vardagligt.", vi: "Một trận tắm nước ấm và sự yên tĩnh giúp mình ngủ ngon. Nghe rất tự nhiên và gần gũi.", phonetic: "/ɛn varm dɵʃ ɔ ˈtʏsːtnɑd ˈjɛlːpɛr mej at ˈsɔmːna ɡɔt/" },
  { id: 1537, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Jag tar gärna en kort paus när jag behöver samla kraft. Det är ett bra uttryck att kunna.", vi: "Mình hay nghỉ giải lao ngắn khi cần lấy lại sức. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn kɔʈ paɵs nɛːr jɑːɡ bɛˈhøːvɛr ˈsamːla krɑft/" },
  { id: 1538, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vilken film eller serie tyckte du bäst om nyligen? Jag använder det gärna i samtal.", vi: "Gần đây bạn thích phim điện ảnh hay phim bộ nào nhất? Mình thích dùng câu này khi trò chuyện.", phonetic: "/ˈvɪlːkɛn fɪlm ˈɛlːɛr ˈseːrɪɛ ˈtʏkːtɛ dʉː bɛst ɔm ˈnʏːˌliːɡɛn/" },
  { id: 1539, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vi gör en enkel fika med kaffe och frukt idag. Det passar bra i många situationer.", vi: "Hôm nay tụi mình làm bữa fika nhẹ nhàng với cà phê và trái cây. Câu này dùng được trong nhiều tình huống.", phonetic: "/viː jøːr ɛn ˈɛŋːkɛl ˈfiːka meːd ˈkafːɛ ɔ frɵkt ɪˈdɑːɡ/" },
  { id: 1540, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det känns skönt att bara vara sig själv i lugn och ro. Det hjälper mig att uttrycka mig klart.", vi: "Thật thoải mái khi được là chính mình trong yên bình. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/deːt ɕɛnːs ɕøːnt at ˈbɑːra ˈvɑːra sej ɕɛlv ɪ lɵŋn ɔ rʊː/" },
  { id: 1541, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Ursäkta, vet du var närmaste busshållplats ligger? Det känns avslappnat och vardagligt.", vi: "Xin lỗi, bạn có biết trạm xe buýt gần nhất ở đâu không? Nghe rất tự nhiên và gần gũi.", phonetic: "/ˈʉːˌʂɛkːta veːt dʉː vɑːr ˈnɛrmastɛ ˈbɵsˌhɔlːplats ˈlɪɡːɛr/" },
  { id: 1542, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag behöver köpa frukt, grönsaker och bröd idag. Det är ett bra uttryck att kunna.", vi: "Hôm nay mình cần mua trái cây, rau củ và bánh mì. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ bɛˈhøːvɛr ˈɕøːpa frɵkt ˈɡrœnˌsɑːkɛr ɔ brøːd ɪˈdɑːɡ/" },
  { id: 1543, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hur mycket kostar det här totalt? Jag använder det gärna i samtal.", vi: "Món này tổng cộng giá bao nhiêu vậy? Mình thích dùng câu này khi trò chuyện.", phonetic: "/hʉːr ˈmʏkːɛt ˈkɔsːtar deːt hɛːr tʊˈtɑlt/" },
  { id: 1544, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag tar gärna en påse, tack så mycket. Det passar bra i många situationer.", vi: "Cho mình xin một túi nhé, cảm ơn bạn nhiều. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn ˈpoːsɛ tak soː ˈmʏkːɛt/" },
  { id: 1545, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Det är ganska svalt ute idag, så jag tar en tröja. Det hjälper mig att uttrycka mig klart.", vi: "Hôm nay ngoài trời khá mát nên mình mặc thêm áo len. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/deːt ɛːr ˈɡanːsa svɑlt ˈʉːtɛ ɪˈdɑːɡ soː jɑːɡ tɑːr ɛn ˈtrœjːa/" },
  { id: 1546, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Vi åker kollektivt eller går när det inte är så långt. Det känns avslappnat och vardagligt.", vi: "Tụi mình đi phương tiện công cộng hoặc đi bộ khi không quá xa. Nghe rất tự nhiên và gần gũi.", phonetic: "/viː ˈoːkɛr kʊlːɛkˈtiːvt ˈɛlːɛr ɡoːr nɛːr deː ˈɪnːtɛ ɛːr soː lɔŋt/" },
  { id: 1547, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag sparar undan lite varje månad för framtida planer. Det är ett bra uttryck att kunna.", vi: "Mình dành dụm một chút mỗi tháng cho các kế hoạch tương lai. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈspɑːrar ˈɵnːdan ˈliːtɛ ˈvarːjɛ ˈmoːnad fœr ˈfrɑːmˌtiːda ˈplɑːnɛr/" },
  { id: 1548, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Vädret växlar snabbt, så det är bra att ha paraply med. Jag använder det gärna i samtal.", vi: "Thời tiết đổi nhanh lắm nên mang theo ô là tốt nhất. Mình thích dùng câu này khi trò chuyện.", phonetic: "/ˈvɛːdrɛt ˈvɛkːslar snɑpt soː deːt ɛːr brɑː at hɑː pɑrɑˈplʏː meːd/" },
  { id: 1549, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag gillar tydliga och enkla rutiner i vardagen. Det passar bra i många situationer.", vi: "Mình thích những thói quen rõ ràng và đơn giản trong ngày. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ ˈjɪlːar ˈtʏːdliɡa ɔ ˈɛŋːkla rɵˈtiːnɛr ɪ ˈvɑːrˌdɑːɡɛn/" },
  { id: 1550, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Varje litet steg framåt räknas. Det hjälper mig att uttrycka mig klart.", vi: "Mỗi bước tiến nhỏ về phía trước đều đáng quý. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/ˈvarːjɛ ˈliːtɛt steːɡ ˈfrɑːmˌɔːt ˈrɛkːnas/" },
  { id: 1551, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "I vardagen säger jag: God morgon! Hur har du sovit?", vi: "Trong đời sống hằng ngày mình nói: Chào buổi sáng! Bạn ngủ có ngon không?", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr hɑːr dʉː ˈsʊːvɪt/" },
  { id: 1552, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag pratar med vänner säger jag: Jag vaknade tidigt idag och tog en lugn start.", vi: "Khi trò chuyện với bạn bè mình nói: Hôm nay mình dậy sớm và khởi đầu thật nhẹ nhàng.", phonetic: "/jɑːɡ ˈvɑːknadɛ ˈtiːdɪt ɪˈdɑːɡ ɔ tʊːɡ ɛn lɵŋn stɑʈ/" },
  { id: 1553, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Hemma och på fritiden säger jag: Vad ska vi äta till middag ikväll?", vi: "Ở nhà và lúc rảnh mình nói: Tối nay tụi mình sẽ ăn gì nhỉ?", phonetic: "/vɑːd skɑː viː ˈɛːta tɪl ˈmɪdːɑːɡ ɪˈkvɛlː/" },
  { id: 1554, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag tränar svenska säger jag: Jag håller på att laga mat i köket nu.", vi: "Khi luyện tiếng Thụy Điển mình nói: Bây giờ mình đang nấu ăn trong bếp.", phonetic: "/jɑːɡ ˈhɔlːɛr pɔː at ˈlɑːɡa mɑːt ɪ ˈɕøːkɛt nʉː/" },
  { id: 1555, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "På utflykt eller promenad säger jag: Kan du upprepa det lite långsammare, tack?", vi: "Khi đi chơi hoặc đi dạo mình nói: Bạn lặp lại chậm hơn một chút được không, cảm ơn bạn?", phonetic: "/kan dʉː ɵpːrɛˈpɑː deː ˈliːtɛ ˈlɔŋːsamːarɛ tak/" },
  { id: 1556, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "I vardagen säger jag: Jag förstår ungefär vad du menar, men jag övar fortfarande.", vi: "Trong đời sống hằng ngày mình nói: Mình hiểu đại khái ý bạn, nhưng mình vẫn đang luyện thêm.", phonetic: "/jɑːɡ fœrˈstoːr ɵnːfɛˈjɛːr vɑːd dʉː ˈmeːnar mɛn jɑːɡ ˈøːvar ˈfɔrtˌfarːandɛ/" },
  { id: 1557, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag pratar med vänner säger jag: Det här ordet är nytt för mig. Vad betyder det?", vi: "Khi trò chuyện với bạn bè mình nói: Từ này mới với mình. Nó có nghĩa là gì vậy?", phonetic: "/deːt hɛːr ˈuːɖɛt ɛːr nʏt fœr mej vɑːd bɛˈtʏːdɛr deː/" },
  { id: 1558, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Hemma och på fritiden säger jag: Jag övar på att prata svenska varje dag.", vi: "Ở nhà và lúc rảnh mình nói: Mình luyện nói tiếng Thụy Điển mỗi ngày.", phonetic: "/jɑːɡ ˈøːvar pɔː at ˈprɑːta ˈsvɛnːska ˈvarːjɛ dɑːɡ/" },
  { id: 1559, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag tränar svenska säger jag: Det blir lättare ju mer man pratar.", vi: "Khi luyện tiếng Thụy Điển mình nói: Càng nói nhiều thì sẽ càng dễ hơn.", phonetic: "/deːt bliːr ˈlɛtːarɛ jʉː meːr man ˈprɑːtar/" },
  { id: 1560, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "På utflykt eller promenad säger jag: Tack för hjälpen, det betydde mycket!", vi: "Khi đi chơi hoặc đi dạo mình nói: Cảm ơn vì đã giúp đỡ, điều đó có ý nghĩa lắm!", phonetic: "/tak fœr ˈjɛlːpɛn deː bɛˈtʏːdːɛ ˈmʏkːɛt/" },
  { id: 1561, topic: "Gia đình & người thân", sv: "I vardagen säger jag: Jag pratar med min man varje dag om framtiden.", vi: "Trong đời sống hằng ngày mình nói: Mình trò chuyện với chồng mỗi ngày về tương lai.", phonetic: "/jɑːɡ ˈprɑːtar meːd miːn man ˈvarːjɛ dɑːɡ ɔm ˈfrɑːmˌtiːdɛn/" },
  { id: 1562, topic: "Gia đình & người thân", sv: "När jag pratar med vänner säger jag: Vi planerar vårt nya liv tillsammans i lugn takt.", vi: "Khi trò chuyện với bạn bè mình nói: Tụi mình lên kế hoạch cho cuộc sống mới cùng nhau một cách chầm chậm.", phonetic: "/viː plɑˈneːrar voːʈ ˈnʏːa liːv tɪlˈsamːanːs ɪ lɵŋn tɑkt/" },
  { id: 1563, topic: "Gia đình & người thân", sv: "Hemma och på fritiden säger jag: Jag tänker ofta på min mormor hemma.", vi: "Ở nhà và lúc rảnh mình nói: Mình thường nhớ tới bà ngoại ở nhà.", phonetic: "/jɑːɡ ˈtɛŋːkɛr ˈɔfːta pɔː miːn ˈmʊːrmʊr ˈhɛmːa/" },
  { id: 1564, topic: "Gia đình & người thân", sv: "När jag tränar svenska säger jag: Familjen betyder allt när man är långt hemifrån.", vi: "Khi luyện tiếng Thụy Điển mình nói: Gia đình có ý nghĩa tất cả khi ở xa nhà.", phonetic: "/fɑˈmiːljɛn bɛˈtʏːdɛr alːt nɛːr man ɛːr lɔŋt ˈhɛmːɪˌfroːn/" },
  { id: 1565, topic: "Gia đình & người thân", sv: "På utflykt eller promenad säger jag: Vi ringer videosamtal på helgen när alla är lediga.", vi: "Khi đi chơi hoặc đi dạo mình nói: Tụi mình gọi video vào cuối tuần khi ai cũng rảnh.", phonetic: "/viː ˈrɪŋːɛr ˈviːdɛʊˌsamːtɑːl pɔː ˈhɛlːjɛn nɛːr ˈalːa ɛːr ˈleːdɪɡa/" },
  { id: 1566, topic: "Gia đình & người thân", sv: "I vardagen säger jag: Han lagar god mat och stöttar mig alltid.", vi: "Trong đời sống hằng ngày mình nói: Anh ấy nấu ăn ngon và luôn ủng hộ mình.", phonetic: "/han ˈlɑːɡar ɡuːd mɑːt ɔ ˈstœtːar mej ˈalːtiːd/" },
  { id: 1567, topic: "Gia đình & người thân", sv: "När jag pratar med vänner säger jag: Att hjälpa varandra gör vardagen enklare.", vi: "Khi trò chuyện với bạn bè mình nói: Giúp đỡ lẫn nhau khiến cuộc sống hằng ngày nhẹ nhàng hơn.", phonetic: "/at ˈjɛlːpa vɑˈranːdra jøːr ˈvɑːrˌdɑːɡɛn ˈɛŋːklarɛ/" },
  { id: 1568, topic: "Gia đình & người thân", sv: "Hemma och på fritiden säger jag: Jag vill gärna bjuda hem familjen på middag någon gång.", vi: "Ở nhà và lúc rảnh mình nói: Mình rất muốn mời gia đình đến nhà ăn tối một dịp nào đó.", phonetic: "/jɑːɡ vɪl ˈjɛːrna ˈbjʉːda hɛm fɑˈmiːljɛn pɔː ˈmɪdːɑːɡ ˈnoːɡɔn ɡɔŋ/" },
  { id: 1569, topic: "Gia đình & người thân", sv: "När jag tränar svenska säger jag: Det känns tryggt att ha någon som förstår en.", vi: "Khi luyện tiếng Thụy Điển mình nói: Thật vững tâm khi có người thấu hiểu mình.", phonetic: "/deːt ɕɛnːs trʏɡt at hɑː ˈnoːɡɔn sɔm fœrˈstoːr ɛn/" },
  { id: 1570, topic: "Gia đình & người thân", sv: "På utflykt eller promenad säger jag: Vi delar både glädje och små bekymmer.", vi: "Khi đi chơi hoặc đi dạo mình nói: Tụi mình chia sẻ cả niềm vui lẫn những nỗi lo nhỏ.", phonetic: "/viː ˈdeːlar ˈboːdɛ ˈɡlɛːdjɛ ɔ smoː bɛˈɕʏmːɛr/" },
  { id: 1571, topic: "Thiên nhiên, đi dạo & du lịch", sv: "I vardagen säger jag: Jag gillar att ta en promenad i parken efter jobbet.", vi: "Trong đời sống hằng ngày mình nói: Mình thích đi dạo trong công viên sau giờ làm.", phonetic: "/jɑːɡ ˈjɪlːar at tɑː ɛn prʊmɛˈnɑːd ɪ ˈparːkɛn ˈɛfːtɛr ˈjɔbːɛt/" },
  { id: 1572, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag pratar med vänner säger jag: Frisk luft och grönska hjälper mig att ladda om.", vi: "Khi trò chuyện với bạn bè mình nói: Không khí trong lành và cây xanh giúp mình nạp lại năng lượng.", phonetic: "/frɪsk lɵft ɔ ˈɡrœnːska ˈjɛlːpɛr mej at ˈladːa ɔm/" },
  { id: 1573, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Hemma och på fritiden säger jag: Vilken vacker utsikt över sjön och skogen!", vi: "Ở nhà và lúc rảnh mình nói: Khung cảnh nhìn ra hồ và rừng đẹp quá!", phonetic: "/ˈvɪlːkɛn ˈvakːɛr ˈʉːtˌsɪkːt ˈøːvɛr ɕøːn ɔ ˈskuːɡɛn/" },
  { id: 1574, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag tränar svenska säger jag: Jag brukar ta foton på naturen när vi reser.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình hay chụp ảnh thiên nhiên khi tụi mình đi du lịch.", phonetic: "/jɑːɡ ˈbrʉːkar tɑː ˈfuːtɔn pɔː nɑtʉːˈreːn nɛːr viː ˈreːsɛr/" },
  { id: 1575, topic: "Thiên nhiên, đi dạo & du lịch", sv: "På utflykt eller promenad säger jag: Vi åker gärna iväg på helgutflykter till nya platser.", vi: "Khi đi chơi hoặc đi dạo mình nói: Tụi mình thích đi chơi cuối tuần tới những vùng đất mới.", phonetic: "/viː ˈoːkɛr ˈjɛːrna ɪˈvɛːɡ pɔː ˈhɛljˌʉːtflʏkːtɛr tɪl ˈnʏːa ˈplatːsɛr/" },
  { id: 1576, topic: "Thiên nhiên, đi dạo & du lịch", sv: "I vardagen säger jag: Ljuset på morgonen och kvällen är så fint att fotografera.", vi: "Trong đời sống hằng ngày mình nói: Ánh sáng buổi sáng và buổi chiều tối chụp ảnh đẹp lắm.", phonetic: "/ˈjʉːsɛt pɔː ˈmɔrːɔnɛn ɔ ˈkvɛlːɛn ɛːr soː fiːnt at fʊtʊɡrɑˈfeːra/" },
  { id: 1577, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag pratar med vänner säger jag: Det är så tyst och rofyllt här borta vid vattnet.", vi: "Khi trò chuyện với bạn bè mình nói: Ở khu vực ven nước này thật yên tĩnh và thanh bình.", phonetic: "/deːt ɛːr soː tʏst ɔ ˈrʊːˌfʏlt hɛːr ˈbɔrːta viːd ˈvatːnɛt/" },
  { id: 1578, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Hemma och på fritiden säger jag: Vi tar det lugnt och njuter av resan i vårt eget tempo.", vi: "Ở nhà và lúc rảnh mình nói: Tụi mình đi thong thả và tận hưởng chuyến đi theo nhịp của riêng mình.", phonetic: "/viː tɑːr deː lɵŋt ɔ ˈnjʉːtɛr ɑːv ˈreːsan ɪ voːʈ ˈeːɡɛt ˈtɛmːpʊ/" },
  { id: 1579, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag tränar svenska säger jag: Jag älskar när solen tittar fram mellan molnen.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình thích khoảnh khắc mặt trời ló dạng giữa những đám mây.", phonetic: "/jɑːɡ ˈɛlːskar nɛːr ˈsuːlɛn ˈtɪtːar fram ˈmɛlːan ˈmuːlnɛn/" },
  { id: 1580, topic: "Thiên nhiên, đi dạo & du lịch", sv: "På utflykt eller promenad säger jag: Att komma ut i naturen rensar tankarna.", vi: "Khi đi chơi hoặc đi dạo mình nói: Ra ngoài thiên nhiên giúp đầu óc thư thái hẳn.", phonetic: "/at ˈkɔmːa ʉːt ɪ nɑtʉːˈreːn ˈrɛnːsar ˈtaŋːkarːa/" },
  { id: 1581, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "I vardagen säger jag: På kvällen gillar jag att varva ner hemma med en bra film.", vi: "Trong đời sống hằng ngày mình nói: Buổi tối mình thích thư giãn ở nhà với một bộ phim hay.", phonetic: "/pɔː ˈkvɛlːɛn ˈjɪlːar jɑːɡ at ˈvarːva neːr ˈhɛmːa meːd ɛn brɑː fɪlm/" },
  { id: 1582, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag pratar med vänner säger jag: Det är skönt att krypa upp i soffan efter en aktiv dag.", vi: "Khi trò chuyện với bạn bè mình nói: Thật dễ chịu khi cuộn mình trên ghế sofa sau một ngày năng động.", phonetic: "/deːt ɛːr ɕøːnt at ˈkrʏːpa ɵpː ɪ ˈsɔfːan ˈɛfːtɛr ɛn ˈakːtɪv dɑːɡ/" },
  { id: 1583, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Hemma och på fritiden säger jag: Vi spelar sällskapsspel och ordlekar när vi är många.", vi: "Ở nhà và lúc rảnh mình nói: Tụi mình chơi board game và trò nối chữ khi có đông người.", phonetic: "/viː ˈsɛlːskɑpsˌspeːl ɔ ˈuːɖˌleːkar nɛːr viː ɛːr ˈmɔŋːa/" },
  { id: 1584, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag tränar svenska säger jag: Det är så kul att skratta tillsammans över en spelomgång.", vi: "Khi luyện tiếng Thụy Điển mình nói: Cùng cười rôm rả qua một ván chơi vui thật đấy.", phonetic: "/deːt ɛːr soː kʉːl at ˈskratːa tɪlˈsamːanːs ˈøːvɛr ɛn ˈspeːlˌɔmːɡɔŋ/" },
  { id: 1585, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På utflykt eller promenad säger jag: Jag gillar att ha det städat och mysigt omkring mig.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình thích giữ không gian gọn gàng và ấm cúng quanh mình.", phonetic: "/jɑːɡ ˈjɪlːar at hɑː deː ˈstɛːdat ɔ ˈmʏːsɪt ɔmˈkrɪŋ mej/" },
  { id: 1586, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "I vardagen säger jag: En varm dusch och tystnad hjälper mig att somna gott.", vi: "Trong đời sống hằng ngày mình nói: Một trận tắm nước ấm và sự yên tĩnh giúp mình ngủ ngon.", phonetic: "/ɛn varm dɵʃ ɔ ˈtʏsːtnɑd ˈjɛlːpɛr mej at ˈsɔmːna ɡɔt/" },
  { id: 1587, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag pratar med vänner säger jag: Jag tar gärna en kort paus när jag behöver samla kraft.", vi: "Khi trò chuyện với bạn bè mình nói: Mình hay nghỉ giải lao ngắn khi cần lấy lại sức.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn kɔʈ paɵs nɛːr jɑːɡ bɛˈhøːvɛr ˈsamːla krɑft/" },
  { id: 1588, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Hemma och på fritiden säger jag: Vilken film eller serie tyckte du bäst om nyligen?", vi: "Ở nhà và lúc rảnh mình nói: Gần đây bạn thích phim điện ảnh hay phim bộ nào nhất?", phonetic: "/ˈvɪlːkɛn fɪlm ˈɛlːɛr ˈseːrɪɛ ˈtʏkːtɛ dʉː bɛst ɔm ˈnʏːˌliːɡɛn/" },
  { id: 1589, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag tränar svenska säger jag: Vi gör en enkel fika med kaffe och frukt idag.", vi: "Khi luyện tiếng Thụy Điển mình nói: Hôm nay tụi mình làm bữa fika nhẹ nhàng với cà phê và trái cây.", phonetic: "/viː jøːr ɛn ˈɛŋːkɛl ˈfiːka meːd ˈkafːɛ ɔ frɵkt ɪˈdɑːɡ/" },
  { id: 1590, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På utflykt eller promenad säger jag: Det känns skönt att bara vara sig själv i lugn och ro.", vi: "Khi đi chơi hoặc đi dạo mình nói: Thật thoải mái khi được là chính mình trong yên bình.", phonetic: "/deːt ɕɛnːs ɕøːnt at ˈbɑːra ˈvɑːra sej ɕɛlv ɪ lɵŋn ɔ rʊː/" },
  { id: 1591, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "I vardagen säger jag: Ursäkta, vet du var närmaste busshållplats ligger?", vi: "Trong đời sống hằng ngày mình nói: Xin lỗi, bạn có biết trạm xe buýt gần nhất ở đâu không?", phonetic: "/ˈʉːˌʂɛkːta veːt dʉː vɑːr ˈnɛrmastɛ ˈbɵsˌhɔlːplats ˈlɪɡːɛr/" },
  { id: 1592, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag pratar med vänner säger jag: Jag behöver köpa frukt, grönsaker och bröd idag.", vi: "Khi trò chuyện với bạn bè mình nói: Hôm nay mình cần mua trái cây, rau củ và bánh mì.", phonetic: "/jɑːɡ bɛˈhøːvɛr ˈɕøːpa frɵkt ˈɡrœnˌsɑːkɛr ɔ brøːd ɪˈdɑːɡ/" },
  { id: 1593, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hemma och på fritiden säger jag: Hur mycket kostar det här totalt?", vi: "Ở nhà và lúc rảnh mình nói: Món này tổng cộng giá bao nhiêu vậy?", phonetic: "/hʉːr ˈmʏkːɛt ˈkɔsːtar deːt hɛːr tʊˈtɑlt/" },
  { id: 1594, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag tränar svenska säger jag: Jag tar gärna en påse, tack så mycket.", vi: "Khi luyện tiếng Thụy Điển mình nói: Cho mình xin một túi nhé, cảm ơn bạn nhiều.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn ˈpoːsɛ tak soː ˈmʏkːɛt/" },
  { id: 1595, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "På utflykt eller promenad säger jag: Det är ganska svalt ute idag, så jag tar en tröja.", vi: "Khi đi chơi hoặc đi dạo mình nói: Hôm nay ngoài trời khá mát nên mình mặc thêm áo len.", phonetic: "/deːt ɛːr ˈɡanːsa svɑlt ˈʉːtɛ ɪˈdɑːɡ soː jɑːɡ tɑːr ɛn ˈtrœjːa/" },
  { id: 1596, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "I vardagen säger jag: Vi åker kollektivt eller går när det inte är så långt.", vi: "Trong đời sống hằng ngày mình nói: Tụi mình đi phương tiện công cộng hoặc đi bộ khi không quá xa.", phonetic: "/viː ˈoːkɛr kʊlːɛkˈtiːvt ˈɛlːɛr ɡoːr nɛːr deː ˈɪnːtɛ ɛːr soː lɔŋt/" },
  { id: 1597, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag pratar med vänner säger jag: Jag sparar undan lite varje månad för framtida planer.", vi: "Khi trò chuyện với bạn bè mình nói: Mình dành dụm một chút mỗi tháng cho các kế hoạch tương lai.", phonetic: "/jɑːɡ ˈspɑːrar ˈɵnːdan ˈliːtɛ ˈvarːjɛ ˈmoːnad fœr ˈfrɑːmˌtiːda ˈplɑːnɛr/" },
  { id: 1598, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hemma och på fritiden säger jag: Vädret växlar snabbt, så det är bra att ha paraply med.", vi: "Ở nhà và lúc rảnh mình nói: Thời tiết đổi nhanh lắm nên mang theo ô là tốt nhất.", phonetic: "/ˈvɛːdrɛt ˈvɛkːslar snɑpt soː deːt ɛːr brɑː at hɑː pɑrɑˈplʏː meːd/" },
  { id: 1599, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag tränar svenska säger jag: Jag gillar tydliga och enkla rutiner i vardagen.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình thích những thói quen rõ ràng và đơn giản trong ngày.", phonetic: "/jɑːɡ ˈjɪlːar ˈtʏːdliɡa ɔ ˈɛŋːkla rɵˈtiːnɛr ɪ ˈvɑːrˌdɑːɡɛn/" },
  { id: 1600, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "På utflykt eller promenad säger jag: Varje litet steg framåt räknas.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mỗi bước tiến nhỏ về phía trước đều đáng quý.", phonetic: "/ˈvarːjɛ ˈliːtɛt steːɡ ˈfrɑːmˌɔːt ˈrɛkːnas/" },
  { id: 1601, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "God morgon! Hur har du sovit? Jag använder det gärna i samtal.", vi: "Chào buổi sáng! Bạn ngủ có ngon không? Mình thích dùng câu này khi trò chuyện.", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr hɑːr dʉː ˈsʊːvɪt/" },
  { id: 1602, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag vaknade tidigt idag och tog en lugn start. Det passar bra i många situationer.", vi: "Hôm nay mình dậy sớm và khởi đầu thật nhẹ nhàng. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ ˈvɑːknadɛ ˈtiːdɪt ɪˈdɑːɡ ɔ tʊːɡ ɛn lɵŋn stɑʈ/" },
  { id: 1603, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Vad ska vi äta till middag ikväll? Det hjälper mig att uttrycka mig klart.", vi: "Tối nay tụi mình sẽ ăn gì nhỉ? Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/vɑːd skɑː viː ˈɛːta tɪl ˈmɪdːɑːɡ ɪˈkvɛlː/" },
  { id: 1604, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag håller på att laga mat i köket nu. Det känns avslappnat och vardagligt.", vi: "Bây giờ mình đang nấu ăn trong bếp. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ ˈhɔlːɛr pɔː at ˈlɑːɡa mɑːt ɪ ˈɕøːkɛt nʉː/" },
  { id: 1605, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Kan du upprepa det lite långsammare, tack? Det är ett bra uttryck att kunna.", vi: "Bạn lặp lại chậm hơn một chút được không, cảm ơn bạn? Đây là cách diễn đạt hay nên biết.", phonetic: "/kan dʉː ɵpːrɛˈpɑː deː ˈliːtɛ ˈlɔŋːsamːarɛ tak/" },
  { id: 1606, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag förstår ungefär vad du menar, men jag övar fortfarande. Jag använder det gärna i samtal.", vi: "Mình hiểu đại khái ý bạn, nhưng mình vẫn đang luyện thêm. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ fœrˈstoːr ɵnːfɛˈjɛːr vɑːd dʉː ˈmeːnar mɛn jɑːɡ ˈøːvar ˈfɔrtˌfarːandɛ/" },
  { id: 1607, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Det här ordet är nytt för mig. Vad betyder det? Det passar bra i många situationer.", vi: "Từ này mới với mình. Nó có nghĩa là gì vậy? Câu này dùng được trong nhiều tình huống.", phonetic: "/deːt hɛːr ˈuːɖɛt ɛːr nʏt fœr mej vɑːd bɛˈtʏːdɛr deː/" },
  { id: 1608, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag övar på att prata svenska varje dag. Det hjälper mig att uttrycka mig klart.", vi: "Mình luyện nói tiếng Thụy Điển mỗi ngày. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ ˈøːvar pɔː at ˈprɑːta ˈsvɛnːska ˈvarːjɛ dɑːɡ/" },
  { id: 1609, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Det blir lättare ju mer man pratar. Det känns avslappnat och vardagligt.", vi: "Càng nói nhiều thì sẽ càng dễ hơn. Nghe rất tự nhiên và gần gũi.", phonetic: "/deːt bliːr ˈlɛtːarɛ jʉː meːr man ˈprɑːtar/" },
  { id: 1610, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Tack för hjälpen, det betydde mycket! Det är ett bra uttryck att kunna.", vi: "Cảm ơn vì đã giúp đỡ, điều đó có ý nghĩa lắm! Đây là cách diễn đạt hay nên biết.", phonetic: "/tak fœr ˈjɛlːpɛn deː bɛˈtʏːdːɛ ˈmʏkːɛt/" },
  { id: 1611, topic: "Gia đình & người thân", sv: "Jag pratar med min man varje dag om framtiden. Jag använder det gärna i samtal.", vi: "Mình trò chuyện với chồng mỗi ngày về tương lai. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ ˈprɑːtar meːd miːn man ˈvarːjɛ dɑːɡ ɔm ˈfrɑːmˌtiːdɛn/" },
  { id: 1612, topic: "Gia đình & người thân", sv: "Vi planerar vårt nya liv tillsammans i lugn takt. Det passar bra i många situationer.", vi: "Tụi mình lên kế hoạch cho cuộc sống mới cùng nhau một cách chầm chậm. Câu này dùng được trong nhiều tình huống.", phonetic: "/viː plɑˈneːrar voːʈ ˈnʏːa liːv tɪlˈsamːanːs ɪ lɵŋn tɑkt/" },
  { id: 1613, topic: "Gia đình & người thân", sv: "Jag tänker ofta på min mormor hemma. Det hjälper mig att uttrycka mig klart.", vi: "Mình thường nhớ tới bà ngoại ở nhà. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ ˈtɛŋːkɛr ˈɔfːta pɔː miːn ˈmʊːrmʊr ˈhɛmːa/" },
  { id: 1614, topic: "Gia đình & người thân", sv: "Familjen betyder allt när man är långt hemifrån. Det känns avslappnat och vardagligt.", vi: "Gia đình có ý nghĩa tất cả khi ở xa nhà. Nghe rất tự nhiên và gần gũi.", phonetic: "/fɑˈmiːljɛn bɛˈtʏːdɛr alːt nɛːr man ɛːr lɔŋt ˈhɛmːɪˌfroːn/" },
  { id: 1615, topic: "Gia đình & người thân", sv: "Vi ringer videosamtal på helgen när alla är lediga. Det är ett bra uttryck att kunna.", vi: "Tụi mình gọi video vào cuối tuần khi ai cũng rảnh. Đây là cách diễn đạt hay nên biết.", phonetic: "/viː ˈrɪŋːɛr ˈviːdɛʊˌsamːtɑːl pɔː ˈhɛlːjɛn nɛːr ˈalːa ɛːr ˈleːdɪɡa/" },
  { id: 1616, topic: "Gia đình & người thân", sv: "Han lagar god mat och stöttar mig alltid. Jag använder det gärna i samtal.", vi: "Anh ấy nấu ăn ngon và luôn ủng hộ mình. Mình thích dùng câu này khi trò chuyện.", phonetic: "/han ˈlɑːɡar ɡuːd mɑːt ɔ ˈstœtːar mej ˈalːtiːd/" },
  { id: 1617, topic: "Gia đình & người thân", sv: "Att hjälpa varandra gör vardagen enklare. Det passar bra i många situationer.", vi: "Giúp đỡ lẫn nhau khiến cuộc sống hằng ngày nhẹ nhàng hơn. Câu này dùng được trong nhiều tình huống.", phonetic: "/at ˈjɛlːpa vɑˈranːdra jøːr ˈvɑːrˌdɑːɡɛn ˈɛŋːklarɛ/" },
  { id: 1618, topic: "Gia đình & người thân", sv: "Jag vill gärna bjuda hem familjen på middag någon gång. Det hjälper mig att uttrycka mig klart.", vi: "Mình rất muốn mời gia đình đến nhà ăn tối một dịp nào đó. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ vɪl ˈjɛːrna ˈbjʉːda hɛm fɑˈmiːljɛn pɔː ˈmɪdːɑːɡ ˈnoːɡɔn ɡɔŋ/" },
  { id: 1619, topic: "Gia đình & người thân", sv: "Det känns tryggt att ha någon som förstår en. Det känns avslappnat och vardagligt.", vi: "Thật vững tâm khi có người thấu hiểu mình. Nghe rất tự nhiên và gần gũi.", phonetic: "/deːt ɕɛnːs trʏɡt at hɑː ˈnoːɡɔn sɔm fœrˈstoːr ɛn/" },
  { id: 1620, topic: "Gia đình & người thân", sv: "Vi delar både glädje och små bekymmer. Det är ett bra uttryck att kunna.", vi: "Tụi mình chia sẻ cả niềm vui lẫn những nỗi lo nhỏ. Đây là cách diễn đạt hay nên biết.", phonetic: "/viː ˈdeːlar ˈboːdɛ ˈɡlɛːdjɛ ɔ smoː bɛˈɕʏmːɛr/" },
  { id: 1621, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag gillar att ta en promenad i parken efter jobbet. Jag använder det gärna i samtal.", vi: "Mình thích đi dạo trong công viên sau giờ làm. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ ˈjɪlːar at tɑː ɛn prʊmɛˈnɑːd ɪ ˈparːkɛn ˈɛfːtɛr ˈjɔbːɛt/" },
  { id: 1622, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Frisk luft och grönska hjälper mig att ladda om. Det passar bra i många situationer.", vi: "Không khí trong lành và cây xanh giúp mình nạp lại năng lượng. Câu này dùng được trong nhiều tình huống.", phonetic: "/frɪsk lɵft ɔ ˈɡrœnːska ˈjɛlːpɛr mej at ˈladːa ɔm/" },
  { id: 1623, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vilken vacker utsikt över sjön och skogen! Det hjälper mig att uttrycka mig klart.", vi: "Khung cảnh nhìn ra hồ và rừng đẹp quá! Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/ˈvɪlːkɛn ˈvakːɛr ˈʉːtˌsɪkːt ˈøːvɛr ɕøːn ɔ ˈskuːɡɛn/" },
  { id: 1624, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag brukar ta foton på naturen när vi reser. Det känns avslappnat och vardagligt.", vi: "Mình hay chụp ảnh thiên nhiên khi tụi mình đi du lịch. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ ˈbrʉːkar tɑː ˈfuːtɔn pɔː nɑtʉːˈreːn nɛːr viː ˈreːsɛr/" },
  { id: 1625, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vi åker gärna iväg på helgutflykter till nya platser. Det är ett bra uttryck att kunna.", vi: "Tụi mình thích đi chơi cuối tuần tới những vùng đất mới. Đây là cách diễn đạt hay nên biết.", phonetic: "/viː ˈoːkɛr ˈjɛːrna ɪˈvɛːɡ pɔː ˈhɛljˌʉːtflʏkːtɛr tɪl ˈnʏːa ˈplatːsɛr/" },
  { id: 1626, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Ljuset på morgonen och kvällen är så fint att fotografera. Jag använder det gärna i samtal.", vi: "Ánh sáng buổi sáng và buổi chiều tối chụp ảnh đẹp lắm. Mình thích dùng câu này khi trò chuyện.", phonetic: "/ˈjʉːsɛt pɔː ˈmɔrːɔnɛn ɔ ˈkvɛlːɛn ɛːr soː fiːnt at fʊtʊɡrɑˈfeːra/" },
  { id: 1627, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Det är så tyst och rofyllt här borta vid vattnet. Det passar bra i många situationer.", vi: "Ở khu vực ven nước này thật yên tĩnh và thanh bình. Câu này dùng được trong nhiều tình huống.", phonetic: "/deːt ɛːr soː tʏst ɔ ˈrʊːˌfʏlt hɛːr ˈbɔrːta viːd ˈvatːnɛt/" },
  { id: 1628, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vi tar det lugnt och njuter av resan i vårt eget tempo. Det hjälper mig att uttrycka mig klart.", vi: "Tụi mình đi thong thả và tận hưởng chuyến đi theo nhịp của riêng mình. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/viː tɑːr deː lɵŋt ɔ ˈnjʉːtɛr ɑːv ˈreːsan ɪ voːʈ ˈeːɡɛt ˈtɛmːpʊ/" },
  { id: 1629, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag älskar när solen tittar fram mellan molnen. Det känns avslappnat och vardagligt.", vi: "Mình thích khoảnh khắc mặt trời ló dạng giữa những đám mây. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ ˈɛlːskar nɛːr ˈsuːlɛn ˈtɪtːar fram ˈmɛlːan ˈmuːlnɛn/" },
  { id: 1630, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Att komma ut i naturen rensar tankarna. Det är ett bra uttryck att kunna.", vi: "Ra ngoài thiên nhiên giúp đầu óc thư thái hẳn. Đây là cách diễn đạt hay nên biết.", phonetic: "/at ˈkɔmːa ʉːt ɪ nɑtʉːˈreːn ˈrɛnːsar ˈtaŋːkarːa/" },
  { id: 1631, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På kvällen gillar jag att varva ner hemma med en bra film. Jag använder det gärna i samtal.", vi: "Buổi tối mình thích thư giãn ở nhà với một bộ phim hay. Mình thích dùng câu này khi trò chuyện.", phonetic: "/pɔː ˈkvɛlːɛn ˈjɪlːar jɑːɡ at ˈvarːva neːr ˈhɛmːa meːd ɛn brɑː fɪlm/" },
  { id: 1632, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det är skönt att krypa upp i soffan efter en aktiv dag. Det passar bra i många situationer.", vi: "Thật dễ chịu khi cuộn mình trên ghế sofa sau một ngày năng động. Câu này dùng được trong nhiều tình huống.", phonetic: "/deːt ɛːr ɕøːnt at ˈkrʏːpa ɵpː ɪ ˈsɔfːan ˈɛfːtɛr ɛn ˈakːtɪv dɑːɡ/" },
  { id: 1633, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vi spelar sällskapsspel och ordlekar när vi är många. Det hjälper mig att uttrycka mig klart.", vi: "Tụi mình chơi board game và trò nối chữ khi có đông người. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/viː ˈsɛlːskɑpsˌspeːl ɔ ˈuːɖˌleːkar nɛːr viː ɛːr ˈmɔŋːa/" },
  { id: 1634, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det är så kul att skratta tillsammans över en spelomgång. Det känns avslappnat och vardagligt.", vi: "Cùng cười rôm rả qua một ván chơi vui thật đấy. Nghe rất tự nhiên và gần gũi.", phonetic: "/deːt ɛːr soː kʉːl at ˈskratːa tɪlˈsamːanːs ˈøːvɛr ɛn ˈspeːlˌɔmːɡɔŋ/" },
  { id: 1635, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Jag gillar att ha det städat och mysigt omkring mig. Det är ett bra uttryck att kunna.", vi: "Mình thích giữ không gian gọn gàng và ấm cúng quanh mình. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈjɪlːar at hɑː deː ˈstɛːdat ɔ ˈmʏːsɪt ɔmˈkrɪŋ mej/" },
  { id: 1636, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "En varm dusch och tystnad hjälper mig att somna gott. Jag använder det gärna i samtal.", vi: "Một trận tắm nước ấm và sự yên tĩnh giúp mình ngủ ngon. Mình thích dùng câu này khi trò chuyện.", phonetic: "/ɛn varm dɵʃ ɔ ˈtʏsːtnɑd ˈjɛlːpɛr mej at ˈsɔmːna ɡɔt/" },
  { id: 1637, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Jag tar gärna en kort paus när jag behöver samla kraft. Det passar bra i många situationer.", vi: "Mình hay nghỉ giải lao ngắn khi cần lấy lại sức. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn kɔʈ paɵs nɛːr jɑːɡ bɛˈhøːvɛr ˈsamːla krɑft/" },
  { id: 1638, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vilken film eller serie tyckte du bäst om nyligen? Det hjälper mig att uttrycka mig klart.", vi: "Gần đây bạn thích phim điện ảnh hay phim bộ nào nhất? Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/ˈvɪlːkɛn fɪlm ˈɛlːɛr ˈseːrɪɛ ˈtʏkːtɛ dʉː bɛst ɔm ˈnʏːˌliːɡɛn/" },
  { id: 1639, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vi gör en enkel fika med kaffe och frukt idag. Det känns avslappnat och vardagligt.", vi: "Hôm nay tụi mình làm bữa fika nhẹ nhàng với cà phê và trái cây. Nghe rất tự nhiên và gần gũi.", phonetic: "/viː jøːr ɛn ˈɛŋːkɛl ˈfiːka meːd ˈkafːɛ ɔ frɵkt ɪˈdɑːɡ/" },
  { id: 1640, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det känns skönt att bara vara sig själv i lugn och ro. Det är ett bra uttryck att kunna.", vi: "Thật thoải mái khi được là chính mình trong yên bình. Đây là cách diễn đạt hay nên biết.", phonetic: "/deːt ɕɛnːs ɕøːnt at ˈbɑːra ˈvɑːra sej ɕɛlv ɪ lɵŋn ɔ rʊː/" },
  { id: 1641, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Ursäkta, vet du var närmaste busshållplats ligger? Jag använder det gärna i samtal.", vi: "Xin lỗi, bạn có biết trạm xe buýt gần nhất ở đâu không? Mình thích dùng câu này khi trò chuyện.", phonetic: "/ˈʉːˌʂɛkːta veːt dʉː vɑːr ˈnɛrmastɛ ˈbɵsˌhɔlːplats ˈlɪɡːɛr/" },
  { id: 1642, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag behöver köpa frukt, grönsaker och bröd idag. Det passar bra i många situationer.", vi: "Hôm nay mình cần mua trái cây, rau củ và bánh mì. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ bɛˈhøːvɛr ˈɕøːpa frɵkt ˈɡrœnˌsɑːkɛr ɔ brøːd ɪˈdɑːɡ/" },
  { id: 1643, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hur mycket kostar det här totalt? Det hjälper mig att uttrycka mig klart.", vi: "Món này tổng cộng giá bao nhiêu vậy? Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/hʉːr ˈmʏkːɛt ˈkɔsːtar deːt hɛːr tʊˈtɑlt/" },
  { id: 1644, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag tar gärna en påse, tack så mycket. Det känns avslappnat och vardagligt.", vi: "Cho mình xin một túi nhé, cảm ơn bạn nhiều. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn ˈpoːsɛ tak soː ˈmʏkːɛt/" },
  { id: 1645, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Det är ganska svalt ute idag, så jag tar en tröja. Det är ett bra uttryck att kunna.", vi: "Hôm nay ngoài trời khá mát nên mình mặc thêm áo len. Đây là cách diễn đạt hay nên biết.", phonetic: "/deːt ɛːr ˈɡanːsa svɑlt ˈʉːtɛ ɪˈdɑːɡ soː jɑːɡ tɑːr ɛn ˈtrœjːa/" },
  { id: 1646, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Vi åker kollektivt eller går när det inte är så långt. Jag använder det gärna i samtal.", vi: "Tụi mình đi phương tiện công cộng hoặc đi bộ khi không quá xa. Mình thích dùng câu này khi trò chuyện.", phonetic: "/viː ˈoːkɛr kʊlːɛkˈtiːvt ˈɛlːɛr ɡoːr nɛːr deː ˈɪnːtɛ ɛːr soː lɔŋt/" },
  { id: 1647, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag sparar undan lite varje månad för framtida planer. Det passar bra i många situationer.", vi: "Mình dành dụm một chút mỗi tháng cho các kế hoạch tương lai. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ ˈspɑːrar ˈɵnːdan ˈliːtɛ ˈvarːjɛ ˈmoːnad fœr ˈfrɑːmˌtiːda ˈplɑːnɛr/" },
  { id: 1648, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Vädret växlar snabbt, så det är bra att ha paraply med. Det hjälper mig att uttrycka mig klart.", vi: "Thời tiết đổi nhanh lắm nên mang theo ô là tốt nhất. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/ˈvɛːdrɛt ˈvɛkːslar snɑpt soː deːt ɛːr brɑː at hɑː pɑrɑˈplʏː meːd/" },
  { id: 1649, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag gillar tydliga och enkla rutiner i vardagen. Det känns avslappnat och vardagligt.", vi: "Mình thích những thói quen rõ ràng và đơn giản trong ngày. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ ˈjɪlːar ˈtʏːdliɡa ɔ ˈɛŋːkla rɵˈtiːnɛr ɪ ˈvɑːrˌdɑːɡɛn/" },
  { id: 1650, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Varje litet steg framåt räknas. Det är ett bra uttryck att kunna.", vi: "Mỗi bước tiến nhỏ về phía trước đều đáng quý. Đây là cách diễn đạt hay nên biết.", phonetic: "/ˈvarːjɛ ˈliːtɛt steːɡ ˈfrɑːmˌɔːt ˈrɛkːnas/" },
  { id: 1651, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Hemma och på fritiden säger jag: God morgon! Hur har du sovit?", vi: "Ở nhà và lúc rảnh mình nói: Chào buổi sáng! Bạn ngủ có ngon không?", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr hɑːr dʉː ˈsʊːvɪt/" },
  { id: 1652, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag tränar svenska säger jag: Jag vaknade tidigt idag och tog en lugn start.", vi: "Khi luyện tiếng Thụy Điển mình nói: Hôm nay mình dậy sớm và khởi đầu thật nhẹ nhàng.", phonetic: "/jɑːɡ ˈvɑːknadɛ ˈtiːdɪt ɪˈdɑːɡ ɔ tʊːɡ ɛn lɵŋn stɑʈ/" },
  { id: 1653, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "På utflykt eller promenad säger jag: Vad ska vi äta till middag ikväll?", vi: "Khi đi chơi hoặc đi dạo mình nói: Tối nay tụi mình sẽ ăn gì nhỉ?", phonetic: "/vɑːd skɑː viː ˈɛːta tɪl ˈmɪdːɑːɡ ɪˈkvɛlː/" },
  { id: 1654, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "I vardagen säger jag: Jag håller på att laga mat i köket nu.", vi: "Trong đời sống hằng ngày mình nói: Bây giờ mình đang nấu ăn trong bếp.", phonetic: "/jɑːɡ ˈhɔlːɛr pɔː at ˈlɑːɡa mɑːt ɪ ˈɕøːkɛt nʉː/" },
  { id: 1655, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag pratar med vänner säger jag: Kan du upprepa det lite långsammare, tack?", vi: "Khi trò chuyện với bạn bè mình nói: Bạn lặp lại chậm hơn một chút được không, cảm ơn bạn?", phonetic: "/kan dʉː ɵpːrɛˈpɑː deː ˈliːtɛ ˈlɔŋːsamːarɛ tak/" },
  { id: 1656, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Hemma och på fritiden säger jag: Jag förstår ungefär vad du menar, men jag övar fortfarande.", vi: "Ở nhà và lúc rảnh mình nói: Mình hiểu đại khái ý bạn, nhưng mình vẫn đang luyện thêm.", phonetic: "/jɑːɡ fœrˈstoːr ɵnːfɛˈjɛːr vɑːd dʉː ˈmeːnar mɛn jɑːɡ ˈøːvar ˈfɔrtˌfarːandɛ/" },
  { id: 1657, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag tränar svenska säger jag: Det här ordet är nytt för mig. Vad betyder det?", vi: "Khi luyện tiếng Thụy Điển mình nói: Từ này mới với mình. Nó có nghĩa là gì vậy?", phonetic: "/deːt hɛːr ˈuːɖɛt ɛːr nʏt fœr mej vɑːd bɛˈtʏːdɛr deː/" },
  { id: 1658, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "På utflykt eller promenad säger jag: Jag övar på att prata svenska varje dag.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình luyện nói tiếng Thụy Điển mỗi ngày.", phonetic: "/jɑːɡ ˈøːvar pɔː at ˈprɑːta ˈsvɛnːska ˈvarːjɛ dɑːɡ/" },
  { id: 1659, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "I vardagen säger jag: Det blir lättare ju mer man pratar.", vi: "Trong đời sống hằng ngày mình nói: Càng nói nhiều thì sẽ càng dễ hơn.", phonetic: "/deːt bliːr ˈlɛtːarɛ jʉː meːr man ˈprɑːtar/" },
  { id: 1660, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag pratar med vänner säger jag: Tack för hjälpen, det betydde mycket!", vi: "Khi trò chuyện với bạn bè mình nói: Cảm ơn vì đã giúp đỡ, điều đó có ý nghĩa lắm!", phonetic: "/tak fœr ˈjɛlːpɛn deː bɛˈtʏːdːɛ ˈmʏkːɛt/" },
  { id: 1661, topic: "Gia đình & người thân", sv: "Hemma och på fritiden säger jag: Jag pratar med min man varje dag om framtiden.", vi: "Ở nhà và lúc rảnh mình nói: Mình trò chuyện với chồng mỗi ngày về tương lai.", phonetic: "/jɑːɡ ˈprɑːtar meːd miːn man ˈvarːjɛ dɑːɡ ɔm ˈfrɑːmˌtiːdɛn/" },
  { id: 1662, topic: "Gia đình & người thân", sv: "När jag tränar svenska säger jag: Vi planerar vårt nya liv tillsammans i lugn takt.", vi: "Khi luyện tiếng Thụy Điển mình nói: Tụi mình lên kế hoạch cho cuộc sống mới cùng nhau một cách chầm chậm.", phonetic: "/viː plɑˈneːrar voːʈ ˈnʏːa liːv tɪlˈsamːanːs ɪ lɵŋn tɑkt/" },
  { id: 1663, topic: "Gia đình & người thân", sv: "På utflykt eller promenad säger jag: Jag tänker ofta på min mormor hemma.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình thường nhớ tới bà ngoại ở nhà.", phonetic: "/jɑːɡ ˈtɛŋːkɛr ˈɔfːta pɔː miːn ˈmʊːrmʊr ˈhɛmːa/" },
  { id: 1664, topic: "Gia đình & người thân", sv: "I vardagen säger jag: Familjen betyder allt när man är långt hemifrån.", vi: "Trong đời sống hằng ngày mình nói: Gia đình có ý nghĩa tất cả khi ở xa nhà.", phonetic: "/fɑˈmiːljɛn bɛˈtʏːdɛr alːt nɛːr man ɛːr lɔŋt ˈhɛmːɪˌfroːn/" },
  { id: 1665, topic: "Gia đình & người thân", sv: "När jag pratar med vänner säger jag: Vi ringer videosamtal på helgen när alla är lediga.", vi: "Khi trò chuyện với bạn bè mình nói: Tụi mình gọi video vào cuối tuần khi ai cũng rảnh.", phonetic: "/viː ˈrɪŋːɛr ˈviːdɛʊˌsamːtɑːl pɔː ˈhɛlːjɛn nɛːr ˈalːa ɛːr ˈleːdɪɡa/" },
  { id: 1666, topic: "Gia đình & người thân", sv: "Hemma och på fritiden säger jag: Han lagar god mat och stöttar mig alltid.", vi: "Ở nhà và lúc rảnh mình nói: Anh ấy nấu ăn ngon và luôn ủng hộ mình.", phonetic: "/han ˈlɑːɡar ɡuːd mɑːt ɔ ˈstœtːar mej ˈalːtiːd/" },
  { id: 1667, topic: "Gia đình & người thân", sv: "När jag tränar svenska säger jag: Att hjälpa varandra gör vardagen enklare.", vi: "Khi luyện tiếng Thụy Điển mình nói: Giúp đỡ lẫn nhau khiến cuộc sống hằng ngày nhẹ nhàng hơn.", phonetic: "/at ˈjɛlːpa vɑˈranːdra jøːr ˈvɑːrˌdɑːɡɛn ˈɛŋːklarɛ/" },
  { id: 1668, topic: "Gia đình & người thân", sv: "På utflykt eller promenad säger jag: Jag vill gärna bjuda hem familjen på middag någon gång.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình rất muốn mời gia đình đến nhà ăn tối một dịp nào đó.", phonetic: "/jɑːɡ vɪl ˈjɛːrna ˈbjʉːda hɛm fɑˈmiːljɛn pɔː ˈmɪdːɑːɡ ˈnoːɡɔn ɡɔŋ/" },
  { id: 1669, topic: "Gia đình & người thân", sv: "I vardagen säger jag: Det känns tryggt att ha någon som förstår en.", vi: "Trong đời sống hằng ngày mình nói: Thật vững tâm khi có người thấu hiểu mình.", phonetic: "/deːt ɕɛnːs trʏɡt at hɑː ˈnoːɡɔn sɔm fœrˈstoːr ɛn/" },
  { id: 1670, topic: "Gia đình & người thân", sv: "När jag pratar med vänner säger jag: Vi delar både glädje och små bekymmer.", vi: "Khi trò chuyện với bạn bè mình nói: Tụi mình chia sẻ cả niềm vui lẫn những nỗi lo nhỏ.", phonetic: "/viː ˈdeːlar ˈboːdɛ ˈɡlɛːdjɛ ɔ smoː bɛˈɕʏmːɛr/" },
  { id: 1671, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Hemma och på fritiden säger jag: Jag gillar att ta en promenad i parken efter jobbet.", vi: "Ở nhà và lúc rảnh mình nói: Mình thích đi dạo trong công viên sau giờ làm.", phonetic: "/jɑːɡ ˈjɪlːar at tɑː ɛn prʊmɛˈnɑːd ɪ ˈparːkɛn ˈɛfːtɛr ˈjɔbːɛt/" },
  { id: 1672, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag tränar svenska säger jag: Frisk luft och grönska hjälper mig att ladda om.", vi: "Khi luyện tiếng Thụy Điển mình nói: Không khí trong lành và cây xanh giúp mình nạp lại năng lượng.", phonetic: "/frɪsk lɵft ɔ ˈɡrœnːska ˈjɛlːpɛr mej at ˈladːa ɔm/" },
  { id: 1673, topic: "Thiên nhiên, đi dạo & du lịch", sv: "På utflykt eller promenad säger jag: Vilken vacker utsikt över sjön och skogen!", vi: "Khi đi chơi hoặc đi dạo mình nói: Khung cảnh nhìn ra hồ và rừng đẹp quá!", phonetic: "/ˈvɪlːkɛn ˈvakːɛr ˈʉːtˌsɪkːt ˈøːvɛr ɕøːn ɔ ˈskuːɡɛn/" },
  { id: 1674, topic: "Thiên nhiên, đi dạo & du lịch", sv: "I vardagen säger jag: Jag brukar ta foton på naturen när vi reser.", vi: "Trong đời sống hằng ngày mình nói: Mình hay chụp ảnh thiên nhiên khi tụi mình đi du lịch.", phonetic: "/jɑːɡ ˈbrʉːkar tɑː ˈfuːtɔn pɔː nɑtʉːˈreːn nɛːr viː ˈreːsɛr/" },
  { id: 1675, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag pratar med vänner säger jag: Vi åker gärna iväg på helgutflykter till nya platser.", vi: "Khi trò chuyện với bạn bè mình nói: Tụi mình thích đi chơi cuối tuần tới những vùng đất mới.", phonetic: "/viː ˈoːkɛr ˈjɛːrna ɪˈvɛːɡ pɔː ˈhɛljˌʉːtflʏkːtɛr tɪl ˈnʏːa ˈplatːsɛr/" },
  { id: 1676, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Hemma och på fritiden säger jag: Ljuset på morgonen och kvällen är så fint att fotografera.", vi: "Ở nhà và lúc rảnh mình nói: Ánh sáng buổi sáng và buổi chiều tối chụp ảnh đẹp lắm.", phonetic: "/ˈjʉːsɛt pɔː ˈmɔrːɔnɛn ɔ ˈkvɛlːɛn ɛːr soː fiːnt at fʊtʊɡrɑˈfeːra/" },
  { id: 1677, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag tränar svenska säger jag: Det är så tyst och rofyllt här borta vid vattnet.", vi: "Khi luyện tiếng Thụy Điển mình nói: Ở khu vực ven nước này thật yên tĩnh và thanh bình.", phonetic: "/deːt ɛːr soː tʏst ɔ ˈrʊːˌfʏlt hɛːr ˈbɔrːta viːd ˈvatːnɛt/" },
  { id: 1678, topic: "Thiên nhiên, đi dạo & du lịch", sv: "På utflykt eller promenad säger jag: Vi tar det lugnt och njuter av resan i vårt eget tempo.", vi: "Khi đi chơi hoặc đi dạo mình nói: Tụi mình đi thong thả và tận hưởng chuyến đi theo nhịp của riêng mình.", phonetic: "/viː tɑːr deː lɵŋt ɔ ˈnjʉːtɛr ɑːv ˈreːsan ɪ voːʈ ˈeːɡɛt ˈtɛmːpʊ/" },
  { id: 1679, topic: "Thiên nhiên, đi dạo & du lịch", sv: "I vardagen säger jag: Jag älskar när solen tittar fram mellan molnen.", vi: "Trong đời sống hằng ngày mình nói: Mình thích khoảnh khắc mặt trời ló dạng giữa những đám mây.", phonetic: "/jɑːɡ ˈɛlːskar nɛːr ˈsuːlɛn ˈtɪtːar fram ˈmɛlːan ˈmuːlnɛn/" },
  { id: 1680, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag pratar med vänner säger jag: Att komma ut i naturen rensar tankarna.", vi: "Khi trò chuyện với bạn bè mình nói: Ra ngoài thiên nhiên giúp đầu óc thư thái hẳn.", phonetic: "/at ˈkɔmːa ʉːt ɪ nɑtʉːˈreːn ˈrɛnːsar ˈtaŋːkarːa/" },
  { id: 1681, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Hemma och på fritiden säger jag: På kvällen gillar jag att varva ner hemma med en bra film.", vi: "Ở nhà và lúc rảnh mình nói: Buổi tối mình thích thư giãn ở nhà với một bộ phim hay.", phonetic: "/pɔː ˈkvɛlːɛn ˈjɪlːar jɑːɡ at ˈvarːva neːr ˈhɛmːa meːd ɛn brɑː fɪlm/" },
  { id: 1682, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag tränar svenska säger jag: Det är skönt att krypa upp i soffan efter en aktiv dag.", vi: "Khi luyện tiếng Thụy Điển mình nói: Thật dễ chịu khi cuộn mình trên ghế sofa sau một ngày năng động.", phonetic: "/deːt ɛːr ɕøːnt at ˈkrʏːpa ɵpː ɪ ˈsɔfːan ˈɛfːtɛr ɛn ˈakːtɪv dɑːɡ/" },
  { id: 1683, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På utflykt eller promenad säger jag: Vi spelar sällskapsspel och ordlekar när vi är många.", vi: "Khi đi chơi hoặc đi dạo mình nói: Tụi mình chơi board game và trò nối chữ khi có đông người.", phonetic: "/viː ˈsɛlːskɑpsˌspeːl ɔ ˈuːɖˌleːkar nɛːr viː ɛːr ˈmɔŋːa/" },
  { id: 1684, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "I vardagen säger jag: Det är så kul att skratta tillsammans över en spelomgång.", vi: "Trong đời sống hằng ngày mình nói: Cùng cười rôm rả qua một ván chơi vui thật đấy.", phonetic: "/deːt ɛːr soː kʉːl at ˈskratːa tɪlˈsamːanːs ˈøːvɛr ɛn ˈspeːlˌɔmːɡɔŋ/" },
  { id: 1685, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag pratar med vänner säger jag: Jag gillar att ha det städat och mysigt omkring mig.", vi: "Khi trò chuyện với bạn bè mình nói: Mình thích giữ không gian gọn gàng và ấm cúng quanh mình.", phonetic: "/jɑːɡ ˈjɪlːar at hɑː deː ˈstɛːdat ɔ ˈmʏːsɪt ɔmˈkrɪŋ mej/" },
  { id: 1686, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Hemma och på fritiden säger jag: En varm dusch och tystnad hjälper mig att somna gott.", vi: "Ở nhà và lúc rảnh mình nói: Một trận tắm nước ấm và sự yên tĩnh giúp mình ngủ ngon.", phonetic: "/ɛn varm dɵʃ ɔ ˈtʏsːtnɑd ˈjɛlːpɛr mej at ˈsɔmːna ɡɔt/" },
  { id: 1687, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag tränar svenska säger jag: Jag tar gärna en kort paus när jag behöver samla kraft.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình hay nghỉ giải lao ngắn khi cần lấy lại sức.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn kɔʈ paɵs nɛːr jɑːɡ bɛˈhøːvɛr ˈsamːla krɑft/" },
  { id: 1688, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På utflykt eller promenad säger jag: Vilken film eller serie tyckte du bäst om nyligen?", vi: "Khi đi chơi hoặc đi dạo mình nói: Gần đây bạn thích phim điện ảnh hay phim bộ nào nhất?", phonetic: "/ˈvɪlːkɛn fɪlm ˈɛlːɛr ˈseːrɪɛ ˈtʏkːtɛ dʉː bɛst ɔm ˈnʏːˌliːɡɛn/" },
  { id: 1689, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "I vardagen säger jag: Vi gör en enkel fika med kaffe och frukt idag.", vi: "Trong đời sống hằng ngày mình nói: Hôm nay tụi mình làm bữa fika nhẹ nhàng với cà phê và trái cây.", phonetic: "/viː jøːr ɛn ˈɛŋːkɛl ˈfiːka meːd ˈkafːɛ ɔ frɵkt ɪˈdɑːɡ/" },
  { id: 1690, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag pratar med vänner säger jag: Det känns skönt att bara vara sig själv i lugn och ro.", vi: "Khi trò chuyện với bạn bè mình nói: Thật thoải mái khi được là chính mình trong yên bình.", phonetic: "/deːt ɕɛnːs ɕøːnt at ˈbɑːra ˈvɑːra sej ɕɛlv ɪ lɵŋn ɔ rʊː/" },
  { id: 1691, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hemma och på fritiden säger jag: Ursäkta, vet du var närmaste busshållplats ligger?", vi: "Ở nhà và lúc rảnh mình nói: Xin lỗi, bạn có biết trạm xe buýt gần nhất ở đâu không?", phonetic: "/ˈʉːˌʂɛkːta veːt dʉː vɑːr ˈnɛrmastɛ ˈbɵsˌhɔlːplats ˈlɪɡːɛr/" },
  { id: 1692, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag tränar svenska säger jag: Jag behöver köpa frukt, grönsaker och bröd idag.", vi: "Khi luyện tiếng Thụy Điển mình nói: Hôm nay mình cần mua trái cây, rau củ và bánh mì.", phonetic: "/jɑːɡ bɛˈhøːvɛr ˈɕøːpa frɵkt ˈɡrœnˌsɑːkɛr ɔ brøːd ɪˈdɑːɡ/" },
  { id: 1693, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "På utflykt eller promenad säger jag: Hur mycket kostar det här totalt?", vi: "Khi đi chơi hoặc đi dạo mình nói: Món này tổng cộng giá bao nhiêu vậy?", phonetic: "/hʉːr ˈmʏkːɛt ˈkɔsːtar deːt hɛːr tʊˈtɑlt/" },
  { id: 1694, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "I vardagen säger jag: Jag tar gärna en påse, tack så mycket.", vi: "Trong đời sống hằng ngày mình nói: Cho mình xin một túi nhé, cảm ơn bạn nhiều.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn ˈpoːsɛ tak soː ˈmʏkːɛt/" },
  { id: 1695, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag pratar med vänner säger jag: Det är ganska svalt ute idag, så jag tar en tröja.", vi: "Khi trò chuyện với bạn bè mình nói: Hôm nay ngoài trời khá mát nên mình mặc thêm áo len.", phonetic: "/deːt ɛːr ˈɡanːsa svɑlt ˈʉːtɛ ɪˈdɑːɡ soː jɑːɡ tɑːr ɛn ˈtrœjːa/" },
  { id: 1696, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hemma och på fritiden säger jag: Vi åker kollektivt eller går när det inte är så långt.", vi: "Ở nhà và lúc rảnh mình nói: Tụi mình đi phương tiện công cộng hoặc đi bộ khi không quá xa.", phonetic: "/viː ˈoːkɛr kʊlːɛkˈtiːvt ˈɛlːɛr ɡoːr nɛːr deː ˈɪnːtɛ ɛːr soː lɔŋt/" },
  { id: 1697, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag tränar svenska säger jag: Jag sparar undan lite varje månad för framtida planer.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình dành dụm một chút mỗi tháng cho các kế hoạch tương lai.", phonetic: "/jɑːɡ ˈspɑːrar ˈɵnːdan ˈliːtɛ ˈvarːjɛ ˈmoːnad fœr ˈfrɑːmˌtiːda ˈplɑːnɛr/" },
  { id: 1698, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "På utflykt eller promenad säger jag: Vädret växlar snabbt, så det är bra att ha paraply med.", vi: "Khi đi chơi hoặc đi dạo mình nói: Thời tiết đổi nhanh lắm nên mang theo ô là tốt nhất.", phonetic: "/ˈvɛːdrɛt ˈvɛkːslar snɑpt soː deːt ɛːr brɑː at hɑː pɑrɑˈplʏː meːd/" },
  { id: 1699, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "I vardagen säger jag: Jag gillar tydliga och enkla rutiner i vardagen.", vi: "Trong đời sống hằng ngày mình nói: Mình thích những thói quen rõ ràng và đơn giản trong ngày.", phonetic: "/jɑːɡ ˈjɪlːar ˈtʏːdliɡa ɔ ˈɛŋːkla rɵˈtiːnɛr ɪ ˈvɑːrˌdɑːɡɛn/" },
  { id: 1700, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag pratar med vänner säger jag: Varje litet steg framåt räknas.", vi: "Khi trò chuyện với bạn bè mình nói: Mỗi bước tiến nhỏ về phía trước đều đáng quý.", phonetic: "/ˈvarːjɛ ˈliːtɛt steːɡ ˈfrɑːmˌɔːt ˈrɛkːnas/" },
  { id: 1701, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "God morgon! Hur har du sovit? Det hjälper mig att uttrycka mig klart.", vi: "Chào buổi sáng! Bạn ngủ có ngon không? Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr hɑːr dʉː ˈsʊːvɪt/" },
  { id: 1702, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag vaknade tidigt idag och tog en lugn start. Det känns avslappnat och vardagligt.", vi: "Hôm nay mình dậy sớm và khởi đầu thật nhẹ nhàng. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ ˈvɑːknadɛ ˈtiːdɪt ɪˈdɑːɡ ɔ tʊːɡ ɛn lɵŋn stɑʈ/" },
  { id: 1703, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Vad ska vi äta till middag ikväll? Det är ett bra uttryck att kunna.", vi: "Tối nay tụi mình sẽ ăn gì nhỉ? Đây là cách diễn đạt hay nên biết.", phonetic: "/vɑːd skɑː viː ˈɛːta tɪl ˈmɪdːɑːɡ ɪˈkvɛlː/" },
  { id: 1704, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag håller på att laga mat i köket nu. Jag använder det gärna i samtal.", vi: "Bây giờ mình đang nấu ăn trong bếp. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ ˈhɔlːɛr pɔː at ˈlɑːɡa mɑːt ɪ ˈɕøːkɛt nʉː/" },
  { id: 1705, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Kan du upprepa det lite långsammare, tack? Det passar bra i många situationer.", vi: "Bạn lặp lại chậm hơn một chút được không, cảm ơn bạn? Câu này dùng được trong nhiều tình huống.", phonetic: "/kan dʉː ɵpːrɛˈpɑː deː ˈliːtɛ ˈlɔŋːsamːarɛ tak/" },
  { id: 1706, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag förstår ungefär vad du menar, men jag övar fortfarande. Det hjälper mig att uttrycka mig klart.", vi: "Mình hiểu đại khái ý bạn, nhưng mình vẫn đang luyện thêm. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ fœrˈstoːr ɵnːfɛˈjɛːr vɑːd dʉː ˈmeːnar mɛn jɑːɡ ˈøːvar ˈfɔrtˌfarːandɛ/" },
  { id: 1707, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Det här ordet är nytt för mig. Vad betyder det? Det känns avslappnat och vardagligt.", vi: "Từ này mới với mình. Nó có nghĩa là gì vậy? Nghe rất tự nhiên và gần gũi.", phonetic: "/deːt hɛːr ˈuːɖɛt ɛːr nʏt fœr mej vɑːd bɛˈtʏːdɛr deː/" },
  { id: 1708, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag övar på att prata svenska varje dag. Det är ett bra uttryck att kunna.", vi: "Mình luyện nói tiếng Thụy Điển mỗi ngày. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈøːvar pɔː at ˈprɑːta ˈsvɛnːska ˈvarːjɛ dɑːɡ/" },
  { id: 1709, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Det blir lättare ju mer man pratar. Jag använder det gärna i samtal.", vi: "Càng nói nhiều thì sẽ càng dễ hơn. Mình thích dùng câu này khi trò chuyện.", phonetic: "/deːt bliːr ˈlɛtːarɛ jʉː meːr man ˈprɑːtar/" },
  { id: 1710, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Tack för hjälpen, det betydde mycket! Det passar bra i många situationer.", vi: "Cảm ơn vì đã giúp đỡ, điều đó có ý nghĩa lắm! Câu này dùng được trong nhiều tình huống.", phonetic: "/tak fœr ˈjɛlːpɛn deː bɛˈtʏːdːɛ ˈmʏkːɛt/" },
  { id: 1711, topic: "Gia đình & người thân", sv: "Jag pratar med min man varje dag om framtiden. Det hjälper mig att uttrycka mig klart.", vi: "Mình trò chuyện với chồng mỗi ngày về tương lai. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ ˈprɑːtar meːd miːn man ˈvarːjɛ dɑːɡ ɔm ˈfrɑːmˌtiːdɛn/" },
  { id: 1712, topic: "Gia đình & người thân", sv: "Vi planerar vårt nya liv tillsammans i lugn takt. Det känns avslappnat och vardagligt.", vi: "Tụi mình lên kế hoạch cho cuộc sống mới cùng nhau một cách chầm chậm. Nghe rất tự nhiên và gần gũi.", phonetic: "/viː plɑˈneːrar voːʈ ˈnʏːa liːv tɪlˈsamːanːs ɪ lɵŋn tɑkt/" },
  { id: 1713, topic: "Gia đình & người thân", sv: "Jag tänker ofta på min mormor hemma. Det är ett bra uttryck att kunna.", vi: "Mình thường nhớ tới bà ngoại ở nhà. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈtɛŋːkɛr ˈɔfːta pɔː miːn ˈmʊːrmʊr ˈhɛmːa/" },
  { id: 1714, topic: "Gia đình & người thân", sv: "Familjen betyder allt när man är långt hemifrån. Jag använder det gärna i samtal.", vi: "Gia đình có ý nghĩa tất cả khi ở xa nhà. Mình thích dùng câu này khi trò chuyện.", phonetic: "/fɑˈmiːljɛn bɛˈtʏːdɛr alːt nɛːr man ɛːr lɔŋt ˈhɛmːɪˌfroːn/" },
  { id: 1715, topic: "Gia đình & người thân", sv: "Vi ringer videosamtal på helgen när alla är lediga. Det passar bra i många situationer.", vi: "Tụi mình gọi video vào cuối tuần khi ai cũng rảnh. Câu này dùng được trong nhiều tình huống.", phonetic: "/viː ˈrɪŋːɛr ˈviːdɛʊˌsamːtɑːl pɔː ˈhɛlːjɛn nɛːr ˈalːa ɛːr ˈleːdɪɡa/" },
  { id: 1716, topic: "Gia đình & người thân", sv: "Han lagar god mat och stöttar mig alltid. Det hjälper mig att uttrycka mig klart.", vi: "Anh ấy nấu ăn ngon và luôn ủng hộ mình. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/han ˈlɑːɡar ɡuːd mɑːt ɔ ˈstœtːar mej ˈalːtiːd/" },
  { id: 1717, topic: "Gia đình & người thân", sv: "Att hjälpa varandra gör vardagen enklare. Det känns avslappnat och vardagligt.", vi: "Giúp đỡ lẫn nhau khiến cuộc sống hằng ngày nhẹ nhàng hơn. Nghe rất tự nhiên và gần gũi.", phonetic: "/at ˈjɛlːpa vɑˈranːdra jøːr ˈvɑːrˌdɑːɡɛn ˈɛŋːklarɛ/" },
  { id: 1718, topic: "Gia đình & người thân", sv: "Jag vill gärna bjuda hem familjen på middag någon gång. Det är ett bra uttryck att kunna.", vi: "Mình rất muốn mời gia đình đến nhà ăn tối một dịp nào đó. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ vɪl ˈjɛːrna ˈbjʉːda hɛm fɑˈmiːljɛn pɔː ˈmɪdːɑːɡ ˈnoːɡɔn ɡɔŋ/" },
  { id: 1719, topic: "Gia đình & người thân", sv: "Det känns tryggt att ha någon som förstår en. Jag använder det gärna i samtal.", vi: "Thật vững tâm khi có người thấu hiểu mình. Mình thích dùng câu này khi trò chuyện.", phonetic: "/deːt ɕɛnːs trʏɡt at hɑː ˈnoːɡɔn sɔm fœrˈstoːr ɛn/" },
  { id: 1720, topic: "Gia đình & người thân", sv: "Vi delar både glädje och små bekymmer. Det passar bra i många situationer.", vi: "Tụi mình chia sẻ cả niềm vui lẫn những nỗi lo nhỏ. Câu này dùng được trong nhiều tình huống.", phonetic: "/viː ˈdeːlar ˈboːdɛ ˈɡlɛːdjɛ ɔ smoː bɛˈɕʏmːɛr/" },
  { id: 1721, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag gillar att ta en promenad i parken efter jobbet. Det hjälper mig att uttrycka mig klart.", vi: "Mình thích đi dạo trong công viên sau giờ làm. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ ˈjɪlːar at tɑː ɛn prʊmɛˈnɑːd ɪ ˈparːkɛn ˈɛfːtɛr ˈjɔbːɛt/" },
  { id: 1722, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Frisk luft och grönska hjälper mig att ladda om. Det känns avslappnat och vardagligt.", vi: "Không khí trong lành và cây xanh giúp mình nạp lại năng lượng. Nghe rất tự nhiên và gần gũi.", phonetic: "/frɪsk lɵft ɔ ˈɡrœnːska ˈjɛlːpɛr mej at ˈladːa ɔm/" },
  { id: 1723, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vilken vacker utsikt över sjön och skogen! Det är ett bra uttryck att kunna.", vi: "Khung cảnh nhìn ra hồ và rừng đẹp quá! Đây là cách diễn đạt hay nên biết.", phonetic: "/ˈvɪlːkɛn ˈvakːɛr ˈʉːtˌsɪkːt ˈøːvɛr ɕøːn ɔ ˈskuːɡɛn/" },
  { id: 1724, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag brukar ta foton på naturen när vi reser. Jag använder det gärna i samtal.", vi: "Mình hay chụp ảnh thiên nhiên khi tụi mình đi du lịch. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ ˈbrʉːkar tɑː ˈfuːtɔn pɔː nɑtʉːˈreːn nɛːr viː ˈreːsɛr/" },
  { id: 1725, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vi åker gärna iväg på helgutflykter till nya platser. Det passar bra i många situationer.", vi: "Tụi mình thích đi chơi cuối tuần tới những vùng đất mới. Câu này dùng được trong nhiều tình huống.", phonetic: "/viː ˈoːkɛr ˈjɛːrna ɪˈvɛːɡ pɔː ˈhɛljˌʉːtflʏkːtɛr tɪl ˈnʏːa ˈplatːsɛr/" },
  { id: 1726, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Ljuset på morgonen och kvällen är så fint att fotografera. Det hjälper mig att uttrycka mig klart.", vi: "Ánh sáng buổi sáng và buổi chiều tối chụp ảnh đẹp lắm. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/ˈjʉːsɛt pɔː ˈmɔrːɔnɛn ɔ ˈkvɛlːɛn ɛːr soː fiːnt at fʊtʊɡrɑˈfeːra/" },
  { id: 1727, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Det är så tyst och rofyllt här borta vid vattnet. Det känns avslappnat och vardagligt.", vi: "Ở khu vực ven nước này thật yên tĩnh và thanh bình. Nghe rất tự nhiên và gần gũi.", phonetic: "/deːt ɛːr soː tʏst ɔ ˈrʊːˌfʏlt hɛːr ˈbɔrːta viːd ˈvatːnɛt/" },
  { id: 1728, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vi tar det lugnt och njuter av resan i vårt eget tempo. Det är ett bra uttryck att kunna.", vi: "Tụi mình đi thong thả và tận hưởng chuyến đi theo nhịp của riêng mình. Đây là cách diễn đạt hay nên biết.", phonetic: "/viː tɑːr deː lɵŋt ɔ ˈnjʉːtɛr ɑːv ˈreːsan ɪ voːʈ ˈeːɡɛt ˈtɛmːpʊ/" },
  { id: 1729, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag älskar när solen tittar fram mellan molnen. Jag använder det gärna i samtal.", vi: "Mình thích khoảnh khắc mặt trời ló dạng giữa những đám mây. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ ˈɛlːskar nɛːr ˈsuːlɛn ˈtɪtːar fram ˈmɛlːan ˈmuːlnɛn/" },
  { id: 1730, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Att komma ut i naturen rensar tankarna. Det passar bra i många situationer.", vi: "Ra ngoài thiên nhiên giúp đầu óc thư thái hẳn. Câu này dùng được trong nhiều tình huống.", phonetic: "/at ˈkɔmːa ʉːt ɪ nɑtʉːˈreːn ˈrɛnːsar ˈtaŋːkarːa/" },
  { id: 1731, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På kvällen gillar jag att varva ner hemma med en bra film. Det hjälper mig att uttrycka mig klart.", vi: "Buổi tối mình thích thư giãn ở nhà với một bộ phim hay. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/pɔː ˈkvɛlːɛn ˈjɪlːar jɑːɡ at ˈvarːva neːr ˈhɛmːa meːd ɛn brɑː fɪlm/" },
  { id: 1732, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det är skönt att krypa upp i soffan efter en aktiv dag. Det känns avslappnat och vardagligt.", vi: "Thật dễ chịu khi cuộn mình trên ghế sofa sau một ngày năng động. Nghe rất tự nhiên và gần gũi.", phonetic: "/deːt ɛːr ɕøːnt at ˈkrʏːpa ɵpː ɪ ˈsɔfːan ˈɛfːtɛr ɛn ˈakːtɪv dɑːɡ/" },
  { id: 1733, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vi spelar sällskapsspel och ordlekar när vi är många. Det är ett bra uttryck att kunna.", vi: "Tụi mình chơi board game và trò nối chữ khi có đông người. Đây là cách diễn đạt hay nên biết.", phonetic: "/viː ˈsɛlːskɑpsˌspeːl ɔ ˈuːɖˌleːkar nɛːr viː ɛːr ˈmɔŋːa/" },
  { id: 1734, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det är så kul att skratta tillsammans över en spelomgång. Jag använder det gärna i samtal.", vi: "Cùng cười rôm rả qua một ván chơi vui thật đấy. Mình thích dùng câu này khi trò chuyện.", phonetic: "/deːt ɛːr soː kʉːl at ˈskratːa tɪlˈsamːanːs ˈøːvɛr ɛn ˈspeːlˌɔmːɡɔŋ/" },
  { id: 1735, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Jag gillar att ha det städat och mysigt omkring mig. Det passar bra i många situationer.", vi: "Mình thích giữ không gian gọn gàng và ấm cúng quanh mình. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ ˈjɪlːar at hɑː deː ˈstɛːdat ɔ ˈmʏːsɪt ɔmˈkrɪŋ mej/" },
  { id: 1736, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "En varm dusch och tystnad hjälper mig att somna gott. Det hjälper mig att uttrycka mig klart.", vi: "Một trận tắm nước ấm và sự yên tĩnh giúp mình ngủ ngon. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/ɛn varm dɵʃ ɔ ˈtʏsːtnɑd ˈjɛlːpɛr mej at ˈsɔmːna ɡɔt/" },
  { id: 1737, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Jag tar gärna en kort paus när jag behöver samla kraft. Det känns avslappnat och vardagligt.", vi: "Mình hay nghỉ giải lao ngắn khi cần lấy lại sức. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn kɔʈ paɵs nɛːr jɑːɡ bɛˈhøːvɛr ˈsamːla krɑft/" },
  { id: 1738, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vilken film eller serie tyckte du bäst om nyligen? Det är ett bra uttryck att kunna.", vi: "Gần đây bạn thích phim điện ảnh hay phim bộ nào nhất? Đây là cách diễn đạt hay nên biết.", phonetic: "/ˈvɪlːkɛn fɪlm ˈɛlːɛr ˈseːrɪɛ ˈtʏkːtɛ dʉː bɛst ɔm ˈnʏːˌliːɡɛn/" },
  { id: 1739, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vi gör en enkel fika med kaffe och frukt idag. Jag använder det gärna i samtal.", vi: "Hôm nay tụi mình làm bữa fika nhẹ nhàng với cà phê và trái cây. Mình thích dùng câu này khi trò chuyện.", phonetic: "/viː jøːr ɛn ˈɛŋːkɛl ˈfiːka meːd ˈkafːɛ ɔ frɵkt ɪˈdɑːɡ/" },
  { id: 1740, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det känns skönt att bara vara sig själv i lugn och ro. Det passar bra i många situationer.", vi: "Thật thoải mái khi được là chính mình trong yên bình. Câu này dùng được trong nhiều tình huống.", phonetic: "/deːt ɕɛnːs ɕøːnt at ˈbɑːra ˈvɑːra sej ɕɛlv ɪ lɵŋn ɔ rʊː/" },
  { id: 1741, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Ursäkta, vet du var närmaste busshållplats ligger? Det hjälper mig att uttrycka mig klart.", vi: "Xin lỗi, bạn có biết trạm xe buýt gần nhất ở đâu không? Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/ˈʉːˌʂɛkːta veːt dʉː vɑːr ˈnɛrmastɛ ˈbɵsˌhɔlːplats ˈlɪɡːɛr/" },
  { id: 1742, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag behöver köpa frukt, grönsaker och bröd idag. Det känns avslappnat och vardagligt.", vi: "Hôm nay mình cần mua trái cây, rau củ và bánh mì. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ bɛˈhøːvɛr ˈɕøːpa frɵkt ˈɡrœnˌsɑːkɛr ɔ brøːd ɪˈdɑːɡ/" },
  { id: 1743, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hur mycket kostar det här totalt? Det är ett bra uttryck att kunna.", vi: "Món này tổng cộng giá bao nhiêu vậy? Đây là cách diễn đạt hay nên biết.", phonetic: "/hʉːr ˈmʏkːɛt ˈkɔsːtar deːt hɛːr tʊˈtɑlt/" },
  { id: 1744, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag tar gärna en påse, tack så mycket. Jag använder det gärna i samtal.", vi: "Cho mình xin một túi nhé, cảm ơn bạn nhiều. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn ˈpoːsɛ tak soː ˈmʏkːɛt/" },
  { id: 1745, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Det är ganska svalt ute idag, så jag tar en tröja. Det passar bra i många situationer.", vi: "Hôm nay ngoài trời khá mát nên mình mặc thêm áo len. Câu này dùng được trong nhiều tình huống.", phonetic: "/deːt ɛːr ˈɡanːsa svɑlt ˈʉːtɛ ɪˈdɑːɡ soː jɑːɡ tɑːr ɛn ˈtrœjːa/" },
  { id: 1746, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Vi åker kollektivt eller går när det inte är så långt. Det hjälper mig att uttrycka mig klart.", vi: "Tụi mình đi phương tiện công cộng hoặc đi bộ khi không quá xa. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/viː ˈoːkɛr kʊlːɛkˈtiːvt ˈɛlːɛr ɡoːr nɛːr deː ˈɪnːtɛ ɛːr soː lɔŋt/" },
  { id: 1747, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag sparar undan lite varje månad för framtida planer. Det känns avslappnat och vardagligt.", vi: "Mình dành dụm một chút mỗi tháng cho các kế hoạch tương lai. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ ˈspɑːrar ˈɵnːdan ˈliːtɛ ˈvarːjɛ ˈmoːnad fœr ˈfrɑːmˌtiːda ˈplɑːnɛr/" },
  { id: 1748, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Vädret växlar snabbt, så det är bra att ha paraply med. Det är ett bra uttryck att kunna.", vi: "Thời tiết đổi nhanh lắm nên mang theo ô là tốt nhất. Đây là cách diễn đạt hay nên biết.", phonetic: "/ˈvɛːdrɛt ˈvɛkːslar snɑpt soː deːt ɛːr brɑː at hɑː pɑrɑˈplʏː meːd/" },
  { id: 1749, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag gillar tydliga och enkla rutiner i vardagen. Jag använder det gärna i samtal.", vi: "Mình thích những thói quen rõ ràng và đơn giản trong ngày. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ ˈjɪlːar ˈtʏːdliɡa ɔ ˈɛŋːkla rɵˈtiːnɛr ɪ ˈvɑːrˌdɑːɡɛn/" },
  { id: 1750, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Varje litet steg framåt räknas. Det passar bra i många situationer.", vi: "Mỗi bước tiến nhỏ về phía trước đều đáng quý. Câu này dùng được trong nhiều tình huống.", phonetic: "/ˈvarːjɛ ˈliːtɛt steːɡ ˈfrɑːmˌɔːt ˈrɛkːnas/" },
  { id: 1751, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "På utflykt eller promenad säger jag: God morgon! Hur har du sovit?", vi: "Khi đi chơi hoặc đi dạo mình nói: Chào buổi sáng! Bạn ngủ có ngon không?", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr hɑːr dʉː ˈsʊːvɪt/" },
  { id: 1752, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "I vardagen säger jag: Jag vaknade tidigt idag och tog en lugn start.", vi: "Trong đời sống hằng ngày mình nói: Hôm nay mình dậy sớm và khởi đầu thật nhẹ nhàng.", phonetic: "/jɑːɡ ˈvɑːknadɛ ˈtiːdɪt ɪˈdɑːɡ ɔ tʊːɡ ɛn lɵŋn stɑʈ/" },
  { id: 1753, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag pratar med vänner säger jag: Vad ska vi äta till middag ikväll?", vi: "Khi trò chuyện với bạn bè mình nói: Tối nay tụi mình sẽ ăn gì nhỉ?", phonetic: "/vɑːd skɑː viː ˈɛːta tɪl ˈmɪdːɑːɡ ɪˈkvɛlː/" },
  { id: 1754, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Hemma och på fritiden säger jag: Jag håller på att laga mat i köket nu.", vi: "Ở nhà và lúc rảnh mình nói: Bây giờ mình đang nấu ăn trong bếp.", phonetic: "/jɑːɡ ˈhɔlːɛr pɔː at ˈlɑːɡa mɑːt ɪ ˈɕøːkɛt nʉː/" },
  { id: 1755, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag tränar svenska säger jag: Kan du upprepa det lite långsammare, tack?", vi: "Khi luyện tiếng Thụy Điển mình nói: Bạn lặp lại chậm hơn một chút được không, cảm ơn bạn?", phonetic: "/kan dʉː ɵpːrɛˈpɑː deː ˈliːtɛ ˈlɔŋːsamːarɛ tak/" },
  { id: 1756, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "På utflykt eller promenad säger jag: Jag förstår ungefär vad du menar, men jag övar fortfarande.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình hiểu đại khái ý bạn, nhưng mình vẫn đang luyện thêm.", phonetic: "/jɑːɡ fœrˈstoːr ɵnːfɛˈjɛːr vɑːd dʉː ˈmeːnar mɛn jɑːɡ ˈøːvar ˈfɔrtˌfarːandɛ/" },
  { id: 1757, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "I vardagen säger jag: Det här ordet är nytt för mig. Vad betyder det?", vi: "Trong đời sống hằng ngày mình nói: Từ này mới với mình. Nó có nghĩa là gì vậy?", phonetic: "/deːt hɛːr ˈuːɖɛt ɛːr nʏt fœr mej vɑːd bɛˈtʏːdɛr deː/" },
  { id: 1758, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag pratar med vänner säger jag: Jag övar på att prata svenska varje dag.", vi: "Khi trò chuyện với bạn bè mình nói: Mình luyện nói tiếng Thụy Điển mỗi ngày.", phonetic: "/jɑːɡ ˈøːvar pɔː at ˈprɑːta ˈsvɛnːska ˈvarːjɛ dɑːɡ/" },
  { id: 1759, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Hemma och på fritiden säger jag: Det blir lättare ju mer man pratar.", vi: "Ở nhà và lúc rảnh mình nói: Càng nói nhiều thì sẽ càng dễ hơn.", phonetic: "/deːt bliːr ˈlɛtːarɛ jʉː meːr man ˈprɑːtar/" },
  { id: 1760, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag tränar svenska säger jag: Tack för hjälpen, det betydde mycket!", vi: "Khi luyện tiếng Thụy Điển mình nói: Cảm ơn vì đã giúp đỡ, điều đó có ý nghĩa lắm!", phonetic: "/tak fœr ˈjɛlːpɛn deː bɛˈtʏːdːɛ ˈmʏkːɛt/" },
  { id: 1761, topic: "Gia đình & người thân", sv: "På utflykt eller promenad säger jag: Jag pratar med min man varje dag om framtiden.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình trò chuyện với chồng mỗi ngày về tương lai.", phonetic: "/jɑːɡ ˈprɑːtar meːd miːn man ˈvarːjɛ dɑːɡ ɔm ˈfrɑːmˌtiːdɛn/" },
  { id: 1762, topic: "Gia đình & người thân", sv: "I vardagen säger jag: Vi planerar vårt nya liv tillsammans i lugn takt.", vi: "Trong đời sống hằng ngày mình nói: Tụi mình lên kế hoạch cho cuộc sống mới cùng nhau một cách chầm chậm.", phonetic: "/viː plɑˈneːrar voːʈ ˈnʏːa liːv tɪlˈsamːanːs ɪ lɵŋn tɑkt/" },
  { id: 1763, topic: "Gia đình & người thân", sv: "När jag pratar med vänner säger jag: Jag tänker ofta på min mormor hemma.", vi: "Khi trò chuyện với bạn bè mình nói: Mình thường nhớ tới bà ngoại ở nhà.", phonetic: "/jɑːɡ ˈtɛŋːkɛr ˈɔfːta pɔː miːn ˈmʊːrmʊr ˈhɛmːa/" },
  { id: 1764, topic: "Gia đình & người thân", sv: "Hemma och på fritiden säger jag: Familjen betyder allt när man är långt hemifrån.", vi: "Ở nhà và lúc rảnh mình nói: Gia đình có ý nghĩa tất cả khi ở xa nhà.", phonetic: "/fɑˈmiːljɛn bɛˈtʏːdɛr alːt nɛːr man ɛːr lɔŋt ˈhɛmːɪˌfroːn/" },
  { id: 1765, topic: "Gia đình & người thân", sv: "När jag tränar svenska säger jag: Vi ringer videosamtal på helgen när alla är lediga.", vi: "Khi luyện tiếng Thụy Điển mình nói: Tụi mình gọi video vào cuối tuần khi ai cũng rảnh.", phonetic: "/viː ˈrɪŋːɛr ˈviːdɛʊˌsamːtɑːl pɔː ˈhɛlːjɛn nɛːr ˈalːa ɛːr ˈleːdɪɡa/" },
  { id: 1766, topic: "Gia đình & người thân", sv: "På utflykt eller promenad säger jag: Han lagar god mat och stöttar mig alltid.", vi: "Khi đi chơi hoặc đi dạo mình nói: Anh ấy nấu ăn ngon và luôn ủng hộ mình.", phonetic: "/han ˈlɑːɡar ɡuːd mɑːt ɔ ˈstœtːar mej ˈalːtiːd/" },
  { id: 1767, topic: "Gia đình & người thân", sv: "I vardagen säger jag: Att hjälpa varandra gör vardagen enklare.", vi: "Trong đời sống hằng ngày mình nói: Giúp đỡ lẫn nhau khiến cuộc sống hằng ngày nhẹ nhàng hơn.", phonetic: "/at ˈjɛlːpa vɑˈranːdra jøːr ˈvɑːrˌdɑːɡɛn ˈɛŋːklarɛ/" },
  { id: 1768, topic: "Gia đình & người thân", sv: "När jag pratar med vänner säger jag: Jag vill gärna bjuda hem familjen på middag någon gång.", vi: "Khi trò chuyện với bạn bè mình nói: Mình rất muốn mời gia đình đến nhà ăn tối một dịp nào đó.", phonetic: "/jɑːɡ vɪl ˈjɛːrna ˈbjʉːda hɛm fɑˈmiːljɛn pɔː ˈmɪdːɑːɡ ˈnoːɡɔn ɡɔŋ/" },
  { id: 1769, topic: "Gia đình & người thân", sv: "Hemma och på fritiden säger jag: Det känns tryggt att ha någon som förstår en.", vi: "Ở nhà và lúc rảnh mình nói: Thật vững tâm khi có người thấu hiểu mình.", phonetic: "/deːt ɕɛnːs trʏɡt at hɑː ˈnoːɡɔn sɔm fœrˈstoːr ɛn/" },
  { id: 1770, topic: "Gia đình & người thân", sv: "När jag tränar svenska säger jag: Vi delar både glädje och små bekymmer.", vi: "Khi luyện tiếng Thụy Điển mình nói: Tụi mình chia sẻ cả niềm vui lẫn những nỗi lo nhỏ.", phonetic: "/viː ˈdeːlar ˈboːdɛ ˈɡlɛːdjɛ ɔ smoː bɛˈɕʏmːɛr/" },
  { id: 1771, topic: "Thiên nhiên, đi dạo & du lịch", sv: "På utflykt eller promenad säger jag: Jag gillar att ta en promenad i parken efter jobbet.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình thích đi dạo trong công viên sau giờ làm.", phonetic: "/jɑːɡ ˈjɪlːar at tɑː ɛn prʊmɛˈnɑːd ɪ ˈparːkɛn ˈɛfːtɛr ˈjɔbːɛt/" },
  { id: 1772, topic: "Thiên nhiên, đi dạo & du lịch", sv: "I vardagen säger jag: Frisk luft och grönska hjälper mig att ladda om.", vi: "Trong đời sống hằng ngày mình nói: Không khí trong lành và cây xanh giúp mình nạp lại năng lượng.", phonetic: "/frɪsk lɵft ɔ ˈɡrœnːska ˈjɛlːpɛr mej at ˈladːa ɔm/" },
  { id: 1773, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag pratar med vänner säger jag: Vilken vacker utsikt över sjön och skogen!", vi: "Khi trò chuyện với bạn bè mình nói: Khung cảnh nhìn ra hồ và rừng đẹp quá!", phonetic: "/ˈvɪlːkɛn ˈvakːɛr ˈʉːtˌsɪkːt ˈøːvɛr ɕøːn ɔ ˈskuːɡɛn/" },
  { id: 1774, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Hemma och på fritiden säger jag: Jag brukar ta foton på naturen när vi reser.", vi: "Ở nhà và lúc rảnh mình nói: Mình hay chụp ảnh thiên nhiên khi tụi mình đi du lịch.", phonetic: "/jɑːɡ ˈbrʉːkar tɑː ˈfuːtɔn pɔː nɑtʉːˈreːn nɛːr viː ˈreːsɛr/" },
  { id: 1775, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag tränar svenska säger jag: Vi åker gärna iväg på helgutflykter till nya platser.", vi: "Khi luyện tiếng Thụy Điển mình nói: Tụi mình thích đi chơi cuối tuần tới những vùng đất mới.", phonetic: "/viː ˈoːkɛr ˈjɛːrna ɪˈvɛːɡ pɔː ˈhɛljˌʉːtflʏkːtɛr tɪl ˈnʏːa ˈplatːsɛr/" },
  { id: 1776, topic: "Thiên nhiên, đi dạo & du lịch", sv: "På utflykt eller promenad säger jag: Ljuset på morgonen och kvällen är så fint att fotografera.", vi: "Khi đi chơi hoặc đi dạo mình nói: Ánh sáng buổi sáng và buổi chiều tối chụp ảnh đẹp lắm.", phonetic: "/ˈjʉːsɛt pɔː ˈmɔrːɔnɛn ɔ ˈkvɛlːɛn ɛːr soː fiːnt at fʊtʊɡrɑˈfeːra/" },
  { id: 1777, topic: "Thiên nhiên, đi dạo & du lịch", sv: "I vardagen säger jag: Det är så tyst och rofyllt här borta vid vattnet.", vi: "Trong đời sống hằng ngày mình nói: Ở khu vực ven nước này thật yên tĩnh và thanh bình.", phonetic: "/deːt ɛːr soː tʏst ɔ ˈrʊːˌfʏlt hɛːr ˈbɔrːta viːd ˈvatːnɛt/" },
  { id: 1778, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag pratar med vänner säger jag: Vi tar det lugnt och njuter av resan i vårt eget tempo.", vi: "Khi trò chuyện với bạn bè mình nói: Tụi mình đi thong thả và tận hưởng chuyến đi theo nhịp của riêng mình.", phonetic: "/viː tɑːr deː lɵŋt ɔ ˈnjʉːtɛr ɑːv ˈreːsan ɪ voːʈ ˈeːɡɛt ˈtɛmːpʊ/" },
  { id: 1779, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Hemma och på fritiden säger jag: Jag älskar när solen tittar fram mellan molnen.", vi: "Ở nhà và lúc rảnh mình nói: Mình thích khoảnh khắc mặt trời ló dạng giữa những đám mây.", phonetic: "/jɑːɡ ˈɛlːskar nɛːr ˈsuːlɛn ˈtɪtːar fram ˈmɛlːan ˈmuːlnɛn/" },
  { id: 1780, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag tränar svenska säger jag: Att komma ut i naturen rensar tankarna.", vi: "Khi luyện tiếng Thụy Điển mình nói: Ra ngoài thiên nhiên giúp đầu óc thư thái hẳn.", phonetic: "/at ˈkɔmːa ʉːt ɪ nɑtʉːˈreːn ˈrɛnːsar ˈtaŋːkarːa/" },
  { id: 1781, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På utflykt eller promenad säger jag: På kvällen gillar jag att varva ner hemma med en bra film.", vi: "Khi đi chơi hoặc đi dạo mình nói: Buổi tối mình thích thư giãn ở nhà với một bộ phim hay.", phonetic: "/pɔː ˈkvɛlːɛn ˈjɪlːar jɑːɡ at ˈvarːva neːr ˈhɛmːa meːd ɛn brɑː fɪlm/" },
  { id: 1782, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "I vardagen säger jag: Det är skönt att krypa upp i soffan efter en aktiv dag.", vi: "Trong đời sống hằng ngày mình nói: Thật dễ chịu khi cuộn mình trên ghế sofa sau một ngày năng động.", phonetic: "/deːt ɛːr ɕøːnt at ˈkrʏːpa ɵpː ɪ ˈsɔfːan ˈɛfːtɛr ɛn ˈakːtɪv dɑːɡ/" },
  { id: 1783, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag pratar med vänner säger jag: Vi spelar sällskapsspel och ordlekar när vi är många.", vi: "Khi trò chuyện với bạn bè mình nói: Tụi mình chơi board game và trò nối chữ khi có đông người.", phonetic: "/viː ˈsɛlːskɑpsˌspeːl ɔ ˈuːɖˌleːkar nɛːr viː ɛːr ˈmɔŋːa/" },
  { id: 1784, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Hemma och på fritiden säger jag: Det är så kul att skratta tillsammans över en spelomgång.", vi: "Ở nhà và lúc rảnh mình nói: Cùng cười rôm rả qua một ván chơi vui thật đấy.", phonetic: "/deːt ɛːr soː kʉːl at ˈskratːa tɪlˈsamːanːs ˈøːvɛr ɛn ˈspeːlˌɔmːɡɔŋ/" },
  { id: 1785, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag tränar svenska säger jag: Jag gillar att ha det städat och mysigt omkring mig.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình thích giữ không gian gọn gàng và ấm cúng quanh mình.", phonetic: "/jɑːɡ ˈjɪlːar at hɑː deː ˈstɛːdat ɔ ˈmʏːsɪt ɔmˈkrɪŋ mej/" },
  { id: 1786, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På utflykt eller promenad säger jag: En varm dusch och tystnad hjälper mig att somna gott.", vi: "Khi đi chơi hoặc đi dạo mình nói: Một trận tắm nước ấm và sự yên tĩnh giúp mình ngủ ngon.", phonetic: "/ɛn varm dɵʃ ɔ ˈtʏsːtnɑd ˈjɛlːpɛr mej at ˈsɔmːna ɡɔt/" },
  { id: 1787, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "I vardagen säger jag: Jag tar gärna en kort paus när jag behöver samla kraft.", vi: "Trong đời sống hằng ngày mình nói: Mình hay nghỉ giải lao ngắn khi cần lấy lại sức.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn kɔʈ paɵs nɛːr jɑːɡ bɛˈhøːvɛr ˈsamːla krɑft/" },
  { id: 1788, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag pratar med vänner säger jag: Vilken film eller serie tyckte du bäst om nyligen?", vi: "Khi trò chuyện với bạn bè mình nói: Gần đây bạn thích phim điện ảnh hay phim bộ nào nhất?", phonetic: "/ˈvɪlːkɛn fɪlm ˈɛlːɛr ˈseːrɪɛ ˈtʏkːtɛ dʉː bɛst ɔm ˈnʏːˌliːɡɛn/" },
  { id: 1789, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Hemma och på fritiden säger jag: Vi gör en enkel fika med kaffe och frukt idag.", vi: "Ở nhà và lúc rảnh mình nói: Hôm nay tụi mình làm bữa fika nhẹ nhàng với cà phê và trái cây.", phonetic: "/viː jøːr ɛn ˈɛŋːkɛl ˈfiːka meːd ˈkafːɛ ɔ frɵkt ɪˈdɑːɡ/" },
  { id: 1790, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag tränar svenska säger jag: Det känns skönt att bara vara sig själv i lugn och ro.", vi: "Khi luyện tiếng Thụy Điển mình nói: Thật thoải mái khi được là chính mình trong yên bình.", phonetic: "/deːt ɕɛnːs ɕøːnt at ˈbɑːra ˈvɑːra sej ɕɛlv ɪ lɵŋn ɔ rʊː/" },
  { id: 1791, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "På utflykt eller promenad säger jag: Ursäkta, vet du var närmaste busshållplats ligger?", vi: "Khi đi chơi hoặc đi dạo mình nói: Xin lỗi, bạn có biết trạm xe buýt gần nhất ở đâu không?", phonetic: "/ˈʉːˌʂɛkːta veːt dʉː vɑːr ˈnɛrmastɛ ˈbɵsˌhɔlːplats ˈlɪɡːɛr/" },
  { id: 1792, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "I vardagen säger jag: Jag behöver köpa frukt, grönsaker och bröd idag.", vi: "Trong đời sống hằng ngày mình nói: Hôm nay mình cần mua trái cây, rau củ và bánh mì.", phonetic: "/jɑːɡ bɛˈhøːvɛr ˈɕøːpa frɵkt ˈɡrœnˌsɑːkɛr ɔ brøːd ɪˈdɑːɡ/" },
  { id: 1793, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag pratar med vänner säger jag: Hur mycket kostar det här totalt?", vi: "Khi trò chuyện với bạn bè mình nói: Món này tổng cộng giá bao nhiêu vậy?", phonetic: "/hʉːr ˈmʏkːɛt ˈkɔsːtar deːt hɛːr tʊˈtɑlt/" },
  { id: 1794, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hemma och på fritiden säger jag: Jag tar gärna en påse, tack så mycket.", vi: "Ở nhà và lúc rảnh mình nói: Cho mình xin một túi nhé, cảm ơn bạn nhiều.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn ˈpoːsɛ tak soː ˈmʏkːɛt/" },
  { id: 1795, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag tränar svenska säger jag: Det är ganska svalt ute idag, så jag tar en tröja.", vi: "Khi luyện tiếng Thụy Điển mình nói: Hôm nay ngoài trời khá mát nên mình mặc thêm áo len.", phonetic: "/deːt ɛːr ˈɡanːsa svɑlt ˈʉːtɛ ɪˈdɑːɡ soː jɑːɡ tɑːr ɛn ˈtrœjːa/" },
  { id: 1796, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "På utflykt eller promenad säger jag: Vi åker kollektivt eller går när det inte är så långt.", vi: "Khi đi chơi hoặc đi dạo mình nói: Tụi mình đi phương tiện công cộng hoặc đi bộ khi không quá xa.", phonetic: "/viː ˈoːkɛr kʊlːɛkˈtiːvt ˈɛlːɛr ɡoːr nɛːr deː ˈɪnːtɛ ɛːr soː lɔŋt/" },
  { id: 1797, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "I vardagen säger jag: Jag sparar undan lite varje månad för framtida planer.", vi: "Trong đời sống hằng ngày mình nói: Mình dành dụm một chút mỗi tháng cho các kế hoạch tương lai.", phonetic: "/jɑːɡ ˈspɑːrar ˈɵnːdan ˈliːtɛ ˈvarːjɛ ˈmoːnad fœr ˈfrɑːmˌtiːda ˈplɑːnɛr/" },
  { id: 1798, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag pratar med vänner säger jag: Vädret växlar snabbt, så det är bra att ha paraply med.", vi: "Khi trò chuyện với bạn bè mình nói: Thời tiết đổi nhanh lắm nên mang theo ô là tốt nhất.", phonetic: "/ˈvɛːdrɛt ˈvɛkːslar snɑpt soː deːt ɛːr brɑː at hɑː pɑrɑˈplʏː meːd/" },
  { id: 1799, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hemma och på fritiden säger jag: Jag gillar tydliga och enkla rutiner i vardagen.", vi: "Ở nhà và lúc rảnh mình nói: Mình thích những thói quen rõ ràng và đơn giản trong ngày.", phonetic: "/jɑːɡ ˈjɪlːar ˈtʏːdliɡa ɔ ˈɛŋːkla rɵˈtiːnɛr ɪ ˈvɑːrˌdɑːɡɛn/" },
  { id: 1800, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag tränar svenska säger jag: Varje litet steg framåt räknas.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mỗi bước tiến nhỏ về phía trước đều đáng quý.", phonetic: "/ˈvarːjɛ ˈliːtɛt steːɡ ˈfrɑːmˌɔːt ˈrɛkːnas/" },
  { id: 1801, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "God morgon! Hur har du sovit? Det är ett bra uttryck att kunna.", vi: "Chào buổi sáng! Bạn ngủ có ngon không? Đây là cách diễn đạt hay nên biết.", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr hɑːr dʉː ˈsʊːvɪt/" },
  { id: 1802, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag vaknade tidigt idag och tog en lugn start. Jag använder det gärna i samtal.", vi: "Hôm nay mình dậy sớm và khởi đầu thật nhẹ nhàng. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ ˈvɑːknadɛ ˈtiːdɪt ɪˈdɑːɡ ɔ tʊːɡ ɛn lɵŋn stɑʈ/" },
  { id: 1803, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Vad ska vi äta till middag ikväll? Det passar bra i många situationer.", vi: "Tối nay tụi mình sẽ ăn gì nhỉ? Câu này dùng được trong nhiều tình huống.", phonetic: "/vɑːd skɑː viː ˈɛːta tɪl ˈmɪdːɑːɡ ɪˈkvɛlː/" },
  { id: 1804, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag håller på att laga mat i köket nu. Det hjälper mig att uttrycka mig klart.", vi: "Bây giờ mình đang nấu ăn trong bếp. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ ˈhɔlːɛr pɔː at ˈlɑːɡa mɑːt ɪ ˈɕøːkɛt nʉː/" },
  { id: 1805, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Kan du upprepa det lite långsammare, tack? Det känns avslappnat och vardagligt.", vi: "Bạn lặp lại chậm hơn một chút được không, cảm ơn bạn? Nghe rất tự nhiên và gần gũi.", phonetic: "/kan dʉː ɵpːrɛˈpɑː deː ˈliːtɛ ˈlɔŋːsamːarɛ tak/" },
  { id: 1806, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag förstår ungefär vad du menar, men jag övar fortfarande. Det är ett bra uttryck att kunna.", vi: "Mình hiểu đại khái ý bạn, nhưng mình vẫn đang luyện thêm. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ fœrˈstoːr ɵnːfɛˈjɛːr vɑːd dʉː ˈmeːnar mɛn jɑːɡ ˈøːvar ˈfɔrtˌfarːandɛ/" },
  { id: 1807, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Det här ordet är nytt för mig. Vad betyder det? Jag använder det gärna i samtal.", vi: "Từ này mới với mình. Nó có nghĩa là gì vậy? Mình thích dùng câu này khi trò chuyện.", phonetic: "/deːt hɛːr ˈuːɖɛt ɛːr nʏt fœr mej vɑːd bɛˈtʏːdɛr deː/" },
  { id: 1808, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag övar på att prata svenska varje dag. Det passar bra i många situationer.", vi: "Mình luyện nói tiếng Thụy Điển mỗi ngày. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ ˈøːvar pɔː at ˈprɑːta ˈsvɛnːska ˈvarːjɛ dɑːɡ/" },
  { id: 1809, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Det blir lättare ju mer man pratar. Det hjälper mig att uttrycka mig klart.", vi: "Càng nói nhiều thì sẽ càng dễ hơn. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/deːt bliːr ˈlɛtːarɛ jʉː meːr man ˈprɑːtar/" },
  { id: 1810, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Tack för hjälpen, det betydde mycket! Det känns avslappnat och vardagligt.", vi: "Cảm ơn vì đã giúp đỡ, điều đó có ý nghĩa lắm! Nghe rất tự nhiên và gần gũi.", phonetic: "/tak fœr ˈjɛlːpɛn deː bɛˈtʏːdːɛ ˈmʏkːɛt/" },
  { id: 1811, topic: "Gia đình & người thân", sv: "Jag pratar med min man varje dag om framtiden. Det är ett bra uttryck att kunna.", vi: "Mình trò chuyện với chồng mỗi ngày về tương lai. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈprɑːtar meːd miːn man ˈvarːjɛ dɑːɡ ɔm ˈfrɑːmˌtiːdɛn/" },
  { id: 1812, topic: "Gia đình & người thân", sv: "Vi planerar vårt nya liv tillsammans i lugn takt. Jag använder det gärna i samtal.", vi: "Tụi mình lên kế hoạch cho cuộc sống mới cùng nhau một cách chầm chậm. Mình thích dùng câu này khi trò chuyện.", phonetic: "/viː plɑˈneːrar voːʈ ˈnʏːa liːv tɪlˈsamːanːs ɪ lɵŋn tɑkt/" },
  { id: 1813, topic: "Gia đình & người thân", sv: "Jag tänker ofta på min mormor hemma. Det passar bra i många situationer.", vi: "Mình thường nhớ tới bà ngoại ở nhà. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ ˈtɛŋːkɛr ˈɔfːta pɔː miːn ˈmʊːrmʊr ˈhɛmːa/" },
  { id: 1814, topic: "Gia đình & người thân", sv: "Familjen betyder allt när man är långt hemifrån. Det hjälper mig att uttrycka mig klart.", vi: "Gia đình có ý nghĩa tất cả khi ở xa nhà. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/fɑˈmiːljɛn bɛˈtʏːdɛr alːt nɛːr man ɛːr lɔŋt ˈhɛmːɪˌfroːn/" },
  { id: 1815, topic: "Gia đình & người thân", sv: "Vi ringer videosamtal på helgen när alla är lediga. Det känns avslappnat och vardagligt.", vi: "Tụi mình gọi video vào cuối tuần khi ai cũng rảnh. Nghe rất tự nhiên và gần gũi.", phonetic: "/viː ˈrɪŋːɛr ˈviːdɛʊˌsamːtɑːl pɔː ˈhɛlːjɛn nɛːr ˈalːa ɛːr ˈleːdɪɡa/" },
  { id: 1816, topic: "Gia đình & người thân", sv: "Han lagar god mat och stöttar mig alltid. Det är ett bra uttryck att kunna.", vi: "Anh ấy nấu ăn ngon và luôn ủng hộ mình. Đây là cách diễn đạt hay nên biết.", phonetic: "/han ˈlɑːɡar ɡuːd mɑːt ɔ ˈstœtːar mej ˈalːtiːd/" },
  { id: 1817, topic: "Gia đình & người thân", sv: "Att hjälpa varandra gör vardagen enklare. Jag använder det gärna i samtal.", vi: "Giúp đỡ lẫn nhau khiến cuộc sống hằng ngày nhẹ nhàng hơn. Mình thích dùng câu này khi trò chuyện.", phonetic: "/at ˈjɛlːpa vɑˈranːdra jøːr ˈvɑːrˌdɑːɡɛn ˈɛŋːklarɛ/" },
  { id: 1818, topic: "Gia đình & người thân", sv: "Jag vill gärna bjuda hem familjen på middag någon gång. Det passar bra i många situationer.", vi: "Mình rất muốn mời gia đình đến nhà ăn tối một dịp nào đó. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ vɪl ˈjɛːrna ˈbjʉːda hɛm fɑˈmiːljɛn pɔː ˈmɪdːɑːɡ ˈnoːɡɔn ɡɔŋ/" },
  { id: 1819, topic: "Gia đình & người thân", sv: "Det känns tryggt att ha någon som förstår en. Det hjälper mig att uttrycka mig klart.", vi: "Thật vững tâm khi có người thấu hiểu mình. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/deːt ɕɛnːs trʏɡt at hɑː ˈnoːɡɔn sɔm fœrˈstoːr ɛn/" },
  { id: 1820, topic: "Gia đình & người thân", sv: "Vi delar både glädje och små bekymmer. Det känns avslappnat och vardagligt.", vi: "Tụi mình chia sẻ cả niềm vui lẫn những nỗi lo nhỏ. Nghe rất tự nhiên và gần gũi.", phonetic: "/viː ˈdeːlar ˈboːdɛ ˈɡlɛːdjɛ ɔ smoː bɛˈɕʏmːɛr/" },
  { id: 1821, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag gillar att ta en promenad i parken efter jobbet. Det är ett bra uttryck att kunna.", vi: "Mình thích đi dạo trong công viên sau giờ làm. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈjɪlːar at tɑː ɛn prʊmɛˈnɑːd ɪ ˈparːkɛn ˈɛfːtɛr ˈjɔbːɛt/" },
  { id: 1822, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Frisk luft och grönska hjälper mig att ladda om. Jag använder det gärna i samtal.", vi: "Không khí trong lành và cây xanh giúp mình nạp lại năng lượng. Mình thích dùng câu này khi trò chuyện.", phonetic: "/frɪsk lɵft ɔ ˈɡrœnːska ˈjɛlːpɛr mej at ˈladːa ɔm/" },
  { id: 1823, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vilken vacker utsikt över sjön och skogen! Det passar bra i många situationer.", vi: "Khung cảnh nhìn ra hồ và rừng đẹp quá! Câu này dùng được trong nhiều tình huống.", phonetic: "/ˈvɪlːkɛn ˈvakːɛr ˈʉːtˌsɪkːt ˈøːvɛr ɕøːn ɔ ˈskuːɡɛn/" },
  { id: 1824, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag brukar ta foton på naturen när vi reser. Det hjälper mig att uttrycka mig klart.", vi: "Mình hay chụp ảnh thiên nhiên khi tụi mình đi du lịch. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ ˈbrʉːkar tɑː ˈfuːtɔn pɔː nɑtʉːˈreːn nɛːr viː ˈreːsɛr/" },
  { id: 1825, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vi åker gärna iväg på helgutflykter till nya platser. Det känns avslappnat och vardagligt.", vi: "Tụi mình thích đi chơi cuối tuần tới những vùng đất mới. Nghe rất tự nhiên và gần gũi.", phonetic: "/viː ˈoːkɛr ˈjɛːrna ɪˈvɛːɡ pɔː ˈhɛljˌʉːtflʏkːtɛr tɪl ˈnʏːa ˈplatːsɛr/" },
  { id: 1826, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Ljuset på morgonen och kvällen är så fint att fotografera. Det är ett bra uttryck att kunna.", vi: "Ánh sáng buổi sáng và buổi chiều tối chụp ảnh đẹp lắm. Đây là cách diễn đạt hay nên biết.", phonetic: "/ˈjʉːsɛt pɔː ˈmɔrːɔnɛn ɔ ˈkvɛlːɛn ɛːr soː fiːnt at fʊtʊɡrɑˈfeːra/" },
  { id: 1827, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Det är så tyst och rofyllt här borta vid vattnet. Jag använder det gärna i samtal.", vi: "Ở khu vực ven nước này thật yên tĩnh và thanh bình. Mình thích dùng câu này khi trò chuyện.", phonetic: "/deːt ɛːr soː tʏst ɔ ˈrʊːˌfʏlt hɛːr ˈbɔrːta viːd ˈvatːnɛt/" },
  { id: 1828, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vi tar det lugnt och njuter av resan i vårt eget tempo. Det passar bra i många situationer.", vi: "Tụi mình đi thong thả và tận hưởng chuyến đi theo nhịp của riêng mình. Câu này dùng được trong nhiều tình huống.", phonetic: "/viː tɑːr deː lɵŋt ɔ ˈnjʉːtɛr ɑːv ˈreːsan ɪ voːʈ ˈeːɡɛt ˈtɛmːpʊ/" },
  { id: 1829, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag älskar när solen tittar fram mellan molnen. Det hjälper mig att uttrycka mig klart.", vi: "Mình thích khoảnh khắc mặt trời ló dạng giữa những đám mây. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ ˈɛlːskar nɛːr ˈsuːlɛn ˈtɪtːar fram ˈmɛlːan ˈmuːlnɛn/" },
  { id: 1830, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Att komma ut i naturen rensar tankarna. Det känns avslappnat och vardagligt.", vi: "Ra ngoài thiên nhiên giúp đầu óc thư thái hẳn. Nghe rất tự nhiên và gần gũi.", phonetic: "/at ˈkɔmːa ʉːt ɪ nɑtʉːˈreːn ˈrɛnːsar ˈtaŋːkarːa/" },
  { id: 1831, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På kvällen gillar jag att varva ner hemma med en bra film. Det är ett bra uttryck att kunna.", vi: "Buổi tối mình thích thư giãn ở nhà với một bộ phim hay. Đây là cách diễn đạt hay nên biết.", phonetic: "/pɔː ˈkvɛlːɛn ˈjɪlːar jɑːɡ at ˈvarːva neːr ˈhɛmːa meːd ɛn brɑː fɪlm/" },
  { id: 1832, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det är skönt att krypa upp i soffan efter en aktiv dag. Jag använder det gärna i samtal.", vi: "Thật dễ chịu khi cuộn mình trên ghế sofa sau một ngày năng động. Mình thích dùng câu này khi trò chuyện.", phonetic: "/deːt ɛːr ɕøːnt at ˈkrʏːpa ɵpː ɪ ˈsɔfːan ˈɛfːtɛr ɛn ˈakːtɪv dɑːɡ/" },
  { id: 1833, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vi spelar sällskapsspel och ordlekar när vi är många. Det passar bra i många situationer.", vi: "Tụi mình chơi board game và trò nối chữ khi có đông người. Câu này dùng được trong nhiều tình huống.", phonetic: "/viː ˈsɛlːskɑpsˌspeːl ɔ ˈuːɖˌleːkar nɛːr viː ɛːr ˈmɔŋːa/" },
  { id: 1834, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det är så kul att skratta tillsammans över en spelomgång. Det hjälper mig att uttrycka mig klart.", vi: "Cùng cười rôm rả qua một ván chơi vui thật đấy. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/deːt ɛːr soː kʉːl at ˈskratːa tɪlˈsamːanːs ˈøːvɛr ɛn ˈspeːlˌɔmːɡɔŋ/" },
  { id: 1835, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Jag gillar att ha det städat och mysigt omkring mig. Det känns avslappnat och vardagligt.", vi: "Mình thích giữ không gian gọn gàng và ấm cúng quanh mình. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ ˈjɪlːar at hɑː deː ˈstɛːdat ɔ ˈmʏːsɪt ɔmˈkrɪŋ mej/" },
  { id: 1836, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "En varm dusch och tystnad hjälper mig att somna gott. Det är ett bra uttryck att kunna.", vi: "Một trận tắm nước ấm và sự yên tĩnh giúp mình ngủ ngon. Đây là cách diễn đạt hay nên biết.", phonetic: "/ɛn varm dɵʃ ɔ ˈtʏsːtnɑd ˈjɛlːpɛr mej at ˈsɔmːna ɡɔt/" },
  { id: 1837, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Jag tar gärna en kort paus när jag behöver samla kraft. Jag använder det gärna i samtal.", vi: "Mình hay nghỉ giải lao ngắn khi cần lấy lại sức. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn kɔʈ paɵs nɛːr jɑːɡ bɛˈhøːvɛr ˈsamːla krɑft/" },
  { id: 1838, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vilken film eller serie tyckte du bäst om nyligen? Det passar bra i många situationer.", vi: "Gần đây bạn thích phim điện ảnh hay phim bộ nào nhất? Câu này dùng được trong nhiều tình huống.", phonetic: "/ˈvɪlːkɛn fɪlm ˈɛlːɛr ˈseːrɪɛ ˈtʏkːtɛ dʉː bɛst ɔm ˈnʏːˌliːɡɛn/" },
  { id: 1839, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vi gör en enkel fika med kaffe och frukt idag. Det hjälper mig att uttrycka mig klart.", vi: "Hôm nay tụi mình làm bữa fika nhẹ nhàng với cà phê và trái cây. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/viː jøːr ɛn ˈɛŋːkɛl ˈfiːka meːd ˈkafːɛ ɔ frɵkt ɪˈdɑːɡ/" },
  { id: 1840, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det känns skönt att bara vara sig själv i lugn och ro. Det känns avslappnat och vardagligt.", vi: "Thật thoải mái khi được là chính mình trong yên bình. Nghe rất tự nhiên và gần gũi.", phonetic: "/deːt ɕɛnːs ɕøːnt at ˈbɑːra ˈvɑːra sej ɕɛlv ɪ lɵŋn ɔ rʊː/" },
  { id: 1841, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Ursäkta, vet du var närmaste busshållplats ligger? Det är ett bra uttryck att kunna.", vi: "Xin lỗi, bạn có biết trạm xe buýt gần nhất ở đâu không? Đây là cách diễn đạt hay nên biết.", phonetic: "/ˈʉːˌʂɛkːta veːt dʉː vɑːr ˈnɛrmastɛ ˈbɵsˌhɔlːplats ˈlɪɡːɛr/" },
  { id: 1842, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag behöver köpa frukt, grönsaker och bröd idag. Jag använder det gärna i samtal.", vi: "Hôm nay mình cần mua trái cây, rau củ và bánh mì. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ bɛˈhøːvɛr ˈɕøːpa frɵkt ˈɡrœnˌsɑːkɛr ɔ brøːd ɪˈdɑːɡ/" },
  { id: 1843, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hur mycket kostar det här totalt? Det passar bra i många situationer.", vi: "Món này tổng cộng giá bao nhiêu vậy? Câu này dùng được trong nhiều tình huống.", phonetic: "/hʉːr ˈmʏkːɛt ˈkɔsːtar deːt hɛːr tʊˈtɑlt/" },
  { id: 1844, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag tar gärna en påse, tack så mycket. Det hjälper mig att uttrycka mig klart.", vi: "Cho mình xin một túi nhé, cảm ơn bạn nhiều. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn ˈpoːsɛ tak soː ˈmʏkːɛt/" },
  { id: 1845, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Det är ganska svalt ute idag, så jag tar en tröja. Det känns avslappnat och vardagligt.", vi: "Hôm nay ngoài trời khá mát nên mình mặc thêm áo len. Nghe rất tự nhiên và gần gũi.", phonetic: "/deːt ɛːr ˈɡanːsa svɑlt ˈʉːtɛ ɪˈdɑːɡ soː jɑːɡ tɑːr ɛn ˈtrœjːa/" },
  { id: 1846, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Vi åker kollektivt eller går när det inte är så långt. Det är ett bra uttryck att kunna.", vi: "Tụi mình đi phương tiện công cộng hoặc đi bộ khi không quá xa. Đây là cách diễn đạt hay nên biết.", phonetic: "/viː ˈoːkɛr kʊlːɛkˈtiːvt ˈɛlːɛr ɡoːr nɛːr deː ˈɪnːtɛ ɛːr soː lɔŋt/" },
  { id: 1847, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag sparar undan lite varje månad för framtida planer. Jag använder det gärna i samtal.", vi: "Mình dành dụm một chút mỗi tháng cho các kế hoạch tương lai. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ ˈspɑːrar ˈɵnːdan ˈliːtɛ ˈvarːjɛ ˈmoːnad fœr ˈfrɑːmˌtiːda ˈplɑːnɛr/" },
  { id: 1848, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Vädret växlar snabbt, så det är bra att ha paraply med. Det passar bra i många situationer.", vi: "Thời tiết đổi nhanh lắm nên mang theo ô là tốt nhất. Câu này dùng được trong nhiều tình huống.", phonetic: "/ˈvɛːdrɛt ˈvɛkːslar snɑpt soː deːt ɛːr brɑː at hɑː pɑrɑˈplʏː meːd/" },
  { id: 1849, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag gillar tydliga och enkla rutiner i vardagen. Det hjälper mig att uttrycka mig klart.", vi: "Mình thích những thói quen rõ ràng và đơn giản trong ngày. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ ˈjɪlːar ˈtʏːdliɡa ɔ ˈɛŋːkla rɵˈtiːnɛr ɪ ˈvɑːrˌdɑːɡɛn/" },
  { id: 1850, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Varje litet steg framåt räknas. Det känns avslappnat och vardagligt.", vi: "Mỗi bước tiến nhỏ về phía trước đều đáng quý. Nghe rất tự nhiên và gần gũi.", phonetic: "/ˈvarːjɛ ˈliːtɛt steːɡ ˈfrɑːmˌɔːt ˈrɛkːnas/" },
  { id: 1851, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag pratar med vänner säger jag: God morgon! Hur har du sovit?", vi: "Khi trò chuyện với bạn bè mình nói: Chào buổi sáng! Bạn ngủ có ngon không?", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr hɑːr dʉː ˈsʊːvɪt/" },
  { id: 1852, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Hemma och på fritiden säger jag: Jag vaknade tidigt idag och tog en lugn start.", vi: "Ở nhà và lúc rảnh mình nói: Hôm nay mình dậy sớm và khởi đầu thật nhẹ nhàng.", phonetic: "/jɑːɡ ˈvɑːknadɛ ˈtiːdɪt ɪˈdɑːɡ ɔ tʊːɡ ɛn lɵŋn stɑʈ/" },
  { id: 1853, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag tränar svenska säger jag: Vad ska vi äta till middag ikväll?", vi: "Khi luyện tiếng Thụy Điển mình nói: Tối nay tụi mình sẽ ăn gì nhỉ?", phonetic: "/vɑːd skɑː viː ˈɛːta tɪl ˈmɪdːɑːɡ ɪˈkvɛlː/" },
  { id: 1854, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "På utflykt eller promenad säger jag: Jag håller på att laga mat i köket nu.", vi: "Khi đi chơi hoặc đi dạo mình nói: Bây giờ mình đang nấu ăn trong bếp.", phonetic: "/jɑːɡ ˈhɔlːɛr pɔː at ˈlɑːɡa mɑːt ɪ ˈɕøːkɛt nʉː/" },
  { id: 1855, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "I vardagen säger jag: Kan du upprepa det lite långsammare, tack?", vi: "Trong đời sống hằng ngày mình nói: Bạn lặp lại chậm hơn một chút được không, cảm ơn bạn?", phonetic: "/kan dʉː ɵpːrɛˈpɑː deː ˈliːtɛ ˈlɔŋːsamːarɛ tak/" },
  { id: 1856, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag pratar med vänner säger jag: Jag förstår ungefär vad du menar, men jag övar fortfarande.", vi: "Khi trò chuyện với bạn bè mình nói: Mình hiểu đại khái ý bạn, nhưng mình vẫn đang luyện thêm.", phonetic: "/jɑːɡ fœrˈstoːr ɵnːfɛˈjɛːr vɑːd dʉː ˈmeːnar mɛn jɑːɡ ˈøːvar ˈfɔrtˌfarːandɛ/" },
  { id: 1857, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Hemma och på fritiden säger jag: Det här ordet är nytt för mig. Vad betyder det?", vi: "Ở nhà và lúc rảnh mình nói: Từ này mới với mình. Nó có nghĩa là gì vậy?", phonetic: "/deːt hɛːr ˈuːɖɛt ɛːr nʏt fœr mej vɑːd bɛˈtʏːdɛr deː/" },
  { id: 1858, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag tränar svenska säger jag: Jag övar på att prata svenska varje dag.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình luyện nói tiếng Thụy Điển mỗi ngày.", phonetic: "/jɑːɡ ˈøːvar pɔː at ˈprɑːta ˈsvɛnːska ˈvarːjɛ dɑːɡ/" },
  { id: 1859, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "På utflykt eller promenad säger jag: Det blir lättare ju mer man pratar.", vi: "Khi đi chơi hoặc đi dạo mình nói: Càng nói nhiều thì sẽ càng dễ hơn.", phonetic: "/deːt bliːr ˈlɛtːarɛ jʉː meːr man ˈprɑːtar/" },
  { id: 1860, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "I vardagen säger jag: Tack för hjälpen, det betydde mycket!", vi: "Trong đời sống hằng ngày mình nói: Cảm ơn vì đã giúp đỡ, điều đó có ý nghĩa lắm!", phonetic: "/tak fœr ˈjɛlːpɛn deː bɛˈtʏːdːɛ ˈmʏkːɛt/" },
  { id: 1861, topic: "Gia đình & người thân", sv: "När jag pratar med vänner säger jag: Jag pratar med min man varje dag om framtiden.", vi: "Khi trò chuyện với bạn bè mình nói: Mình trò chuyện với chồng mỗi ngày về tương lai.", phonetic: "/jɑːɡ ˈprɑːtar meːd miːn man ˈvarːjɛ dɑːɡ ɔm ˈfrɑːmˌtiːdɛn/" },
  { id: 1862, topic: "Gia đình & người thân", sv: "Hemma och på fritiden säger jag: Vi planerar vårt nya liv tillsammans i lugn takt.", vi: "Ở nhà và lúc rảnh mình nói: Tụi mình lên kế hoạch cho cuộc sống mới cùng nhau một cách chầm chậm.", phonetic: "/viː plɑˈneːrar voːʈ ˈnʏːa liːv tɪlˈsamːanːs ɪ lɵŋn tɑkt/" },
  { id: 1863, topic: "Gia đình & người thân", sv: "När jag tränar svenska säger jag: Jag tänker ofta på min mormor hemma.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình thường nhớ tới bà ngoại ở nhà.", phonetic: "/jɑːɡ ˈtɛŋːkɛr ˈɔfːta pɔː miːn ˈmʊːrmʊr ˈhɛmːa/" },
  { id: 1864, topic: "Gia đình & người thân", sv: "På utflykt eller promenad säger jag: Familjen betyder allt när man är långt hemifrån.", vi: "Khi đi chơi hoặc đi dạo mình nói: Gia đình có ý nghĩa tất cả khi ở xa nhà.", phonetic: "/fɑˈmiːljɛn bɛˈtʏːdɛr alːt nɛːr man ɛːr lɔŋt ˈhɛmːɪˌfroːn/" },
  { id: 1865, topic: "Gia đình & người thân", sv: "I vardagen säger jag: Vi ringer videosamtal på helgen när alla är lediga.", vi: "Trong đời sống hằng ngày mình nói: Tụi mình gọi video vào cuối tuần khi ai cũng rảnh.", phonetic: "/viː ˈrɪŋːɛr ˈviːdɛʊˌsamːtɑːl pɔː ˈhɛlːjɛn nɛːr ˈalːa ɛːr ˈleːdɪɡa/" },
  { id: 1866, topic: "Gia đình & người thân", sv: "När jag pratar med vänner säger jag: Han lagar god mat och stöttar mig alltid.", vi: "Khi trò chuyện với bạn bè mình nói: Anh ấy nấu ăn ngon và luôn ủng hộ mình.", phonetic: "/han ˈlɑːɡar ɡuːd mɑːt ɔ ˈstœtːar mej ˈalːtiːd/" },
  { id: 1867, topic: "Gia đình & người thân", sv: "Hemma och på fritiden säger jag: Att hjälpa varandra gör vardagen enklare.", vi: "Ở nhà và lúc rảnh mình nói: Giúp đỡ lẫn nhau khiến cuộc sống hằng ngày nhẹ nhàng hơn.", phonetic: "/at ˈjɛlːpa vɑˈranːdra jøːr ˈvɑːrˌdɑːɡɛn ˈɛŋːklarɛ/" },
  { id: 1868, topic: "Gia đình & người thân", sv: "När jag tränar svenska säger jag: Jag vill gärna bjuda hem familjen på middag någon gång.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình rất muốn mời gia đình đến nhà ăn tối một dịp nào đó.", phonetic: "/jɑːɡ vɪl ˈjɛːrna ˈbjʉːda hɛm fɑˈmiːljɛn pɔː ˈmɪdːɑːɡ ˈnoːɡɔn ɡɔŋ/" },
  { id: 1869, topic: "Gia đình & người thân", sv: "På utflykt eller promenad säger jag: Det känns tryggt att ha någon som förstår en.", vi: "Khi đi chơi hoặc đi dạo mình nói: Thật vững tâm khi có người thấu hiểu mình.", phonetic: "/deːt ɕɛnːs trʏɡt at hɑː ˈnoːɡɔn sɔm fœrˈstoːr ɛn/" },
  { id: 1870, topic: "Gia đình & người thân", sv: "I vardagen säger jag: Vi delar både glädje och små bekymmer.", vi: "Trong đời sống hằng ngày mình nói: Tụi mình chia sẻ cả niềm vui lẫn những nỗi lo nhỏ.", phonetic: "/viː ˈdeːlar ˈboːdɛ ˈɡlɛːdjɛ ɔ smoː bɛˈɕʏmːɛr/" },
  { id: 1871, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag pratar med vänner säger jag: Jag gillar att ta en promenad i parken efter jobbet.", vi: "Khi trò chuyện với bạn bè mình nói: Mình thích đi dạo trong công viên sau giờ làm.", phonetic: "/jɑːɡ ˈjɪlːar at tɑː ɛn prʊmɛˈnɑːd ɪ ˈparːkɛn ˈɛfːtɛr ˈjɔbːɛt/" },
  { id: 1872, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Hemma och på fritiden säger jag: Frisk luft och grönska hjälper mig att ladda om.", vi: "Ở nhà và lúc rảnh mình nói: Không khí trong lành và cây xanh giúp mình nạp lại năng lượng.", phonetic: "/frɪsk lɵft ɔ ˈɡrœnːska ˈjɛlːpɛr mej at ˈladːa ɔm/" },
  { id: 1873, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag tränar svenska säger jag: Vilken vacker utsikt över sjön och skogen!", vi: "Khi luyện tiếng Thụy Điển mình nói: Khung cảnh nhìn ra hồ và rừng đẹp quá!", phonetic: "/ˈvɪlːkɛn ˈvakːɛr ˈʉːtˌsɪkːt ˈøːvɛr ɕøːn ɔ ˈskuːɡɛn/" },
  { id: 1874, topic: "Thiên nhiên, đi dạo & du lịch", sv: "På utflykt eller promenad säger jag: Jag brukar ta foton på naturen när vi reser.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình hay chụp ảnh thiên nhiên khi tụi mình đi du lịch.", phonetic: "/jɑːɡ ˈbrʉːkar tɑː ˈfuːtɔn pɔː nɑtʉːˈreːn nɛːr viː ˈreːsɛr/" },
  { id: 1875, topic: "Thiên nhiên, đi dạo & du lịch", sv: "I vardagen säger jag: Vi åker gärna iväg på helgutflykter till nya platser.", vi: "Trong đời sống hằng ngày mình nói: Tụi mình thích đi chơi cuối tuần tới những vùng đất mới.", phonetic: "/viː ˈoːkɛr ˈjɛːrna ɪˈvɛːɡ pɔː ˈhɛljˌʉːtflʏkːtɛr tɪl ˈnʏːa ˈplatːsɛr/" },
  { id: 1876, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag pratar med vänner säger jag: Ljuset på morgonen och kvällen är så fint att fotografera.", vi: "Khi trò chuyện với bạn bè mình nói: Ánh sáng buổi sáng và buổi chiều tối chụp ảnh đẹp lắm.", phonetic: "/ˈjʉːsɛt pɔː ˈmɔrːɔnɛn ɔ ˈkvɛlːɛn ɛːr soː fiːnt at fʊtʊɡrɑˈfeːra/" },
  { id: 1877, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Hemma och på fritiden säger jag: Det är så tyst och rofyllt här borta vid vattnet.", vi: "Ở nhà và lúc rảnh mình nói: Ở khu vực ven nước này thật yên tĩnh và thanh bình.", phonetic: "/deːt ɛːr soː tʏst ɔ ˈrʊːˌfʏlt hɛːr ˈbɔrːta viːd ˈvatːnɛt/" },
  { id: 1878, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag tränar svenska säger jag: Vi tar det lugnt och njuter av resan i vårt eget tempo.", vi: "Khi luyện tiếng Thụy Điển mình nói: Tụi mình đi thong thả và tận hưởng chuyến đi theo nhịp của riêng mình.", phonetic: "/viː tɑːr deː lɵŋt ɔ ˈnjʉːtɛr ɑːv ˈreːsan ɪ voːʈ ˈeːɡɛt ˈtɛmːpʊ/" },
  { id: 1879, topic: "Thiên nhiên, đi dạo & du lịch", sv: "På utflykt eller promenad säger jag: Jag älskar när solen tittar fram mellan molnen.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình thích khoảnh khắc mặt trời ló dạng giữa những đám mây.", phonetic: "/jɑːɡ ˈɛlːskar nɛːr ˈsuːlɛn ˈtɪtːar fram ˈmɛlːan ˈmuːlnɛn/" },
  { id: 1880, topic: "Thiên nhiên, đi dạo & du lịch", sv: "I vardagen säger jag: Att komma ut i naturen rensar tankarna.", vi: "Trong đời sống hằng ngày mình nói: Ra ngoài thiên nhiên giúp đầu óc thư thái hẳn.", phonetic: "/at ˈkɔmːa ʉːt ɪ nɑtʉːˈreːn ˈrɛnːsar ˈtaŋːkarːa/" },
  { id: 1881, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag pratar med vänner säger jag: På kvällen gillar jag att varva ner hemma med en bra film.", vi: "Khi trò chuyện với bạn bè mình nói: Buổi tối mình thích thư giãn ở nhà với một bộ phim hay.", phonetic: "/pɔː ˈkvɛlːɛn ˈjɪlːar jɑːɡ at ˈvarːva neːr ˈhɛmːa meːd ɛn brɑː fɪlm/" },
  { id: 1882, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Hemma och på fritiden säger jag: Det är skönt att krypa upp i soffan efter en aktiv dag.", vi: "Ở nhà và lúc rảnh mình nói: Thật dễ chịu khi cuộn mình trên ghế sofa sau một ngày năng động.", phonetic: "/deːt ɛːr ɕøːnt at ˈkrʏːpa ɵpː ɪ ˈsɔfːan ˈɛfːtɛr ɛn ˈakːtɪv dɑːɡ/" },
  { id: 1883, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag tränar svenska säger jag: Vi spelar sällskapsspel och ordlekar när vi är många.", vi: "Khi luyện tiếng Thụy Điển mình nói: Tụi mình chơi board game và trò nối chữ khi có đông người.", phonetic: "/viː ˈsɛlːskɑpsˌspeːl ɔ ˈuːɖˌleːkar nɛːr viː ɛːr ˈmɔŋːa/" },
  { id: 1884, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På utflykt eller promenad säger jag: Det är så kul att skratta tillsammans över en spelomgång.", vi: "Khi đi chơi hoặc đi dạo mình nói: Cùng cười rôm rả qua một ván chơi vui thật đấy.", phonetic: "/deːt ɛːr soː kʉːl at ˈskratːa tɪlˈsamːanːs ˈøːvɛr ɛn ˈspeːlˌɔmːɡɔŋ/" },
  { id: 1885, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "I vardagen säger jag: Jag gillar att ha det städat och mysigt omkring mig.", vi: "Trong đời sống hằng ngày mình nói: Mình thích giữ không gian gọn gàng và ấm cúng quanh mình.", phonetic: "/jɑːɡ ˈjɪlːar at hɑː deː ˈstɛːdat ɔ ˈmʏːsɪt ɔmˈkrɪŋ mej/" },
  { id: 1886, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag pratar med vänner säger jag: En varm dusch och tystnad hjälper mig att somna gott.", vi: "Khi trò chuyện với bạn bè mình nói: Một trận tắm nước ấm và sự yên tĩnh giúp mình ngủ ngon.", phonetic: "/ɛn varm dɵʃ ɔ ˈtʏsːtnɑd ˈjɛlːpɛr mej at ˈsɔmːna ɡɔt/" },
  { id: 1887, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Hemma och på fritiden säger jag: Jag tar gärna en kort paus när jag behöver samla kraft.", vi: "Ở nhà và lúc rảnh mình nói: Mình hay nghỉ giải lao ngắn khi cần lấy lại sức.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn kɔʈ paɵs nɛːr jɑːɡ bɛˈhøːvɛr ˈsamːla krɑft/" },
  { id: 1888, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag tränar svenska säger jag: Vilken film eller serie tyckte du bäst om nyligen?", vi: "Khi luyện tiếng Thụy Điển mình nói: Gần đây bạn thích phim điện ảnh hay phim bộ nào nhất?", phonetic: "/ˈvɪlːkɛn fɪlm ˈɛlːɛr ˈseːrɪɛ ˈtʏkːtɛ dʉː bɛst ɔm ˈnʏːˌliːɡɛn/" },
  { id: 1889, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På utflykt eller promenad säger jag: Vi gör en enkel fika med kaffe och frukt idag.", vi: "Khi đi chơi hoặc đi dạo mình nói: Hôm nay tụi mình làm bữa fika nhẹ nhàng với cà phê và trái cây.", phonetic: "/viː jøːr ɛn ˈɛŋːkɛl ˈfiːka meːd ˈkafːɛ ɔ frɵkt ɪˈdɑːɡ/" },
  { id: 1890, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "I vardagen säger jag: Det känns skönt att bara vara sig själv i lugn och ro.", vi: "Trong đời sống hằng ngày mình nói: Thật thoải mái khi được là chính mình trong yên bình.", phonetic: "/deːt ɕɛnːs ɕøːnt at ˈbɑːra ˈvɑːra sej ɕɛlv ɪ lɵŋn ɔ rʊː/" },
  { id: 1891, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag pratar med vänner säger jag: Ursäkta, vet du var närmaste busshållplats ligger?", vi: "Khi trò chuyện với bạn bè mình nói: Xin lỗi, bạn có biết trạm xe buýt gần nhất ở đâu không?", phonetic: "/ˈʉːˌʂɛkːta veːt dʉː vɑːr ˈnɛrmastɛ ˈbɵsˌhɔlːplats ˈlɪɡːɛr/" },
  { id: 1892, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hemma och på fritiden säger jag: Jag behöver köpa frukt, grönsaker och bröd idag.", vi: "Ở nhà và lúc rảnh mình nói: Hôm nay mình cần mua trái cây, rau củ và bánh mì.", phonetic: "/jɑːɡ bɛˈhøːvɛr ˈɕøːpa frɵkt ˈɡrœnˌsɑːkɛr ɔ brøːd ɪˈdɑːɡ/" },
  { id: 1893, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag tränar svenska säger jag: Hur mycket kostar det här totalt?", vi: "Khi luyện tiếng Thụy Điển mình nói: Món này tổng cộng giá bao nhiêu vậy?", phonetic: "/hʉːr ˈmʏkːɛt ˈkɔsːtar deːt hɛːr tʊˈtɑlt/" },
  { id: 1894, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "På utflykt eller promenad säger jag: Jag tar gärna en påse, tack så mycket.", vi: "Khi đi chơi hoặc đi dạo mình nói: Cho mình xin một túi nhé, cảm ơn bạn nhiều.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn ˈpoːsɛ tak soː ˈmʏkːɛt/" },
  { id: 1895, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "I vardagen säger jag: Det är ganska svalt ute idag, så jag tar en tröja.", vi: "Trong đời sống hằng ngày mình nói: Hôm nay ngoài trời khá mát nên mình mặc thêm áo len.", phonetic: "/deːt ɛːr ˈɡanːsa svɑlt ˈʉːtɛ ɪˈdɑːɡ soː jɑːɡ tɑːr ɛn ˈtrœjːa/" },
  { id: 1896, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag pratar med vänner säger jag: Vi åker kollektivt eller går när det inte är så långt.", vi: "Khi trò chuyện với bạn bè mình nói: Tụi mình đi phương tiện công cộng hoặc đi bộ khi không quá xa.", phonetic: "/viː ˈoːkɛr kʊlːɛkˈtiːvt ˈɛlːɛr ɡoːr nɛːr deː ˈɪnːtɛ ɛːr soː lɔŋt/" },
  { id: 1897, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hemma och på fritiden säger jag: Jag sparar undan lite varje månad för framtida planer.", vi: "Ở nhà và lúc rảnh mình nói: Mình dành dụm một chút mỗi tháng cho các kế hoạch tương lai.", phonetic: "/jɑːɡ ˈspɑːrar ˈɵnːdan ˈliːtɛ ˈvarːjɛ ˈmoːnad fœr ˈfrɑːmˌtiːda ˈplɑːnɛr/" },
  { id: 1898, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag tränar svenska säger jag: Vädret växlar snabbt, så det är bra att ha paraply med.", vi: "Khi luyện tiếng Thụy Điển mình nói: Thời tiết đổi nhanh lắm nên mang theo ô là tốt nhất.", phonetic: "/ˈvɛːdrɛt ˈvɛkːslar snɑpt soː deːt ɛːr brɑː at hɑː pɑrɑˈplʏː meːd/" },
  { id: 1899, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "På utflykt eller promenad säger jag: Jag gillar tydliga och enkla rutiner i vardagen.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình thích những thói quen rõ ràng và đơn giản trong ngày.", phonetic: "/jɑːɡ ˈjɪlːar ˈtʏːdliɡa ɔ ˈɛŋːkla rɵˈtiːnɛr ɪ ˈvɑːrˌdɑːɡɛn/" },
  { id: 1900, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "I vardagen säger jag: Varje litet steg framåt räknas.", vi: "Trong đời sống hằng ngày mình nói: Mỗi bước tiến nhỏ về phía trước đều đáng quý.", phonetic: "/ˈvarːjɛ ˈliːtɛt steːɡ ˈfrɑːmˌɔːt ˈrɛkːnas/" },
  { id: 1901, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "God morgon! Hur har du sovit? Det passar bra i många situationer.", vi: "Chào buổi sáng! Bạn ngủ có ngon không? Câu này dùng được trong nhiều tình huống.", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr hɑːr dʉː ˈsʊːvɪt/" },
  { id: 1902, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag vaknade tidigt idag och tog en lugn start. Det hjälper mig att uttrycka mig klart.", vi: "Hôm nay mình dậy sớm và khởi đầu thật nhẹ nhàng. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ ˈvɑːknadɛ ˈtiːdɪt ɪˈdɑːɡ ɔ tʊːɡ ɛn lɵŋn stɑʈ/" },
  { id: 1903, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Vad ska vi äta till middag ikväll? Det känns avslappnat och vardagligt.", vi: "Tối nay tụi mình sẽ ăn gì nhỉ? Nghe rất tự nhiên và gần gũi.", phonetic: "/vɑːd skɑː viː ˈɛːta tɪl ˈmɪdːɑːɡ ɪˈkvɛlː/" },
  { id: 1904, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag håller på att laga mat i köket nu. Det är ett bra uttryck att kunna.", vi: "Bây giờ mình đang nấu ăn trong bếp. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈhɔlːɛr pɔː at ˈlɑːɡa mɑːt ɪ ˈɕøːkɛt nʉː/" },
  { id: 1905, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Kan du upprepa det lite långsammare, tack? Jag använder det gärna i samtal.", vi: "Bạn lặp lại chậm hơn một chút được không, cảm ơn bạn? Mình thích dùng câu này khi trò chuyện.", phonetic: "/kan dʉː ɵpːrɛˈpɑː deː ˈliːtɛ ˈlɔŋːsamːarɛ tak/" },
  { id: 1906, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag förstår ungefär vad du menar, men jag övar fortfarande. Det passar bra i många situationer.", vi: "Mình hiểu đại khái ý bạn, nhưng mình vẫn đang luyện thêm. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ fœrˈstoːr ɵnːfɛˈjɛːr vɑːd dʉː ˈmeːnar mɛn jɑːɡ ˈøːvar ˈfɔrtˌfarːandɛ/" },
  { id: 1907, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Det här ordet är nytt för mig. Vad betyder det? Det hjälper mig att uttrycka mig klart.", vi: "Từ này mới với mình. Nó có nghĩa là gì vậy? Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/deːt hɛːr ˈuːɖɛt ɛːr nʏt fœr mej vɑːd bɛˈtʏːdɛr deː/" },
  { id: 1908, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Jag övar på att prata svenska varje dag. Det känns avslappnat och vardagligt.", vi: "Mình luyện nói tiếng Thụy Điển mỗi ngày. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ ˈøːvar pɔː at ˈprɑːta ˈsvɛnːska ˈvarːjɛ dɑːɡ/" },
  { id: 1909, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Det blir lättare ju mer man pratar. Det är ett bra uttryck att kunna.", vi: "Càng nói nhiều thì sẽ càng dễ hơn. Đây là cách diễn đạt hay nên biết.", phonetic: "/deːt bliːr ˈlɛtːarɛ jʉː meːr man ˈprɑːtar/" },
  { id: 1910, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Tack för hjälpen, det betydde mycket! Jag använder det gärna i samtal.", vi: "Cảm ơn vì đã giúp đỡ, điều đó có ý nghĩa lắm! Mình thích dùng câu này khi trò chuyện.", phonetic: "/tak fœr ˈjɛlːpɛn deː bɛˈtʏːdːɛ ˈmʏkːɛt/" },
  { id: 1911, topic: "Gia đình & người thân", sv: "Jag pratar med min man varje dag om framtiden. Det passar bra i många situationer.", vi: "Mình trò chuyện với chồng mỗi ngày về tương lai. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ ˈprɑːtar meːd miːn man ˈvarːjɛ dɑːɡ ɔm ˈfrɑːmˌtiːdɛn/" },
  { id: 1912, topic: "Gia đình & người thân", sv: "Vi planerar vårt nya liv tillsammans i lugn takt. Det hjälper mig att uttrycka mig klart.", vi: "Tụi mình lên kế hoạch cho cuộc sống mới cùng nhau một cách chầm chậm. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/viː plɑˈneːrar voːʈ ˈnʏːa liːv tɪlˈsamːanːs ɪ lɵŋn tɑkt/" },
  { id: 1913, topic: "Gia đình & người thân", sv: "Jag tänker ofta på min mormor hemma. Det känns avslappnat och vardagligt.", vi: "Mình thường nhớ tới bà ngoại ở nhà. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ ˈtɛŋːkɛr ˈɔfːta pɔː miːn ˈmʊːrmʊr ˈhɛmːa/" },
  { id: 1914, topic: "Gia đình & người thân", sv: "Familjen betyder allt när man är långt hemifrån. Det är ett bra uttryck att kunna.", vi: "Gia đình có ý nghĩa tất cả khi ở xa nhà. Đây là cách diễn đạt hay nên biết.", phonetic: "/fɑˈmiːljɛn bɛˈtʏːdɛr alːt nɛːr man ɛːr lɔŋt ˈhɛmːɪˌfroːn/" },
  { id: 1915, topic: "Gia đình & người thân", sv: "Vi ringer videosamtal på helgen när alla är lediga. Jag använder det gärna i samtal.", vi: "Tụi mình gọi video vào cuối tuần khi ai cũng rảnh. Mình thích dùng câu này khi trò chuyện.", phonetic: "/viː ˈrɪŋːɛr ˈviːdɛʊˌsamːtɑːl pɔː ˈhɛlːjɛn nɛːr ˈalːa ɛːr ˈleːdɪɡa/" },
  { id: 1916, topic: "Gia đình & người thân", sv: "Han lagar god mat och stöttar mig alltid. Det passar bra i många situationer.", vi: "Anh ấy nấu ăn ngon và luôn ủng hộ mình. Câu này dùng được trong nhiều tình huống.", phonetic: "/han ˈlɑːɡar ɡuːd mɑːt ɔ ˈstœtːar mej ˈalːtiːd/" },
  { id: 1917, topic: "Gia đình & người thân", sv: "Att hjälpa varandra gör vardagen enklare. Det hjälper mig att uttrycka mig klart.", vi: "Giúp đỡ lẫn nhau khiến cuộc sống hằng ngày nhẹ nhàng hơn. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/at ˈjɛlːpa vɑˈranːdra jøːr ˈvɑːrˌdɑːɡɛn ˈɛŋːklarɛ/" },
  { id: 1918, topic: "Gia đình & người thân", sv: "Jag vill gärna bjuda hem familjen på middag någon gång. Det känns avslappnat och vardagligt.", vi: "Mình rất muốn mời gia đình đến nhà ăn tối một dịp nào đó. Nghe rất tự nhiên và gần gũi.", phonetic: "/jɑːɡ vɪl ˈjɛːrna ˈbjʉːda hɛm fɑˈmiːljɛn pɔː ˈmɪdːɑːɡ ˈnoːɡɔn ɡɔŋ/" },
  { id: 1919, topic: "Gia đình & người thân", sv: "Det känns tryggt att ha någon som förstår en. Det är ett bra uttryck att kunna.", vi: "Thật vững tâm khi có người thấu hiểu mình. Đây là cách diễn đạt hay nên biết.", phonetic: "/deːt ɕɛnːs trʏɡt at hɑː ˈnoːɡɔn sɔm fœrˈstoːr ɛn/" },
  { id: 1920, topic: "Gia đình & người thân", sv: "Vi delar både glädje och små bekymmer. Jag använder det gärna i samtal.", vi: "Tụi mình chia sẻ cả niềm vui lẫn những nỗi lo nhỏ. Mình thích dùng câu này khi trò chuyện.", phonetic: "/viː ˈdeːlar ˈboːdɛ ˈɡlɛːdjɛ ɔ smoː bɛˈɕʏmːɛr/" },
  { id: 1921, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag gillar att ta en promenad i parken efter jobbet. Det passar bra i många situationer.", vi: "Mình thích đi dạo trong công viên sau giờ làm. Câu này dùng được trong nhiều tình huống.", phonetic: "/jɑːɡ ˈjɪlːar at tɑː ɛn prʊmɛˈnɑːd ɪ ˈparːkɛn ˈɛfːtɛr ˈjɔbːɛt/" },
  { id: 1922, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Frisk luft och grönska hjälper mig att ladda om. Det hjälper mig att uttrycka mig klart.", vi: "Không khí trong lành và cây xanh giúp mình nạp lại năng lượng. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/frɪsk lɵft ɔ ˈɡrœnːska ˈjɛlːpɛr mej at ˈladːa ɔm/" },
  { id: 1923, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vilken vacker utsikt över sjön och skogen! Det känns avslappnat och vardagligt.", vi: "Khung cảnh nhìn ra hồ và rừng đẹp quá! Nghe rất tự nhiên và gần gũi.", phonetic: "/ˈvɪlːkɛn ˈvakːɛr ˈʉːtˌsɪkːt ˈøːvɛr ɕøːn ɔ ˈskuːɡɛn/" },
  { id: 1924, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag brukar ta foton på naturen när vi reser. Det är ett bra uttryck att kunna.", vi: "Mình hay chụp ảnh thiên nhiên khi tụi mình đi du lịch. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈbrʉːkar tɑː ˈfuːtɔn pɔː nɑtʉːˈreːn nɛːr viː ˈreːsɛr/" },
  { id: 1925, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vi åker gärna iväg på helgutflykter till nya platser. Jag använder det gärna i samtal.", vi: "Tụi mình thích đi chơi cuối tuần tới những vùng đất mới. Mình thích dùng câu này khi trò chuyện.", phonetic: "/viː ˈoːkɛr ˈjɛːrna ɪˈvɛːɡ pɔː ˈhɛljˌʉːtflʏkːtɛr tɪl ˈnʏːa ˈplatːsɛr/" },
  { id: 1926, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Ljuset på morgonen och kvällen är så fint att fotografera. Det passar bra i många situationer.", vi: "Ánh sáng buổi sáng và buổi chiều tối chụp ảnh đẹp lắm. Câu này dùng được trong nhiều tình huống.", phonetic: "/ˈjʉːsɛt pɔː ˈmɔrːɔnɛn ɔ ˈkvɛlːɛn ɛːr soː fiːnt at fʊtʊɡrɑˈfeːra/" },
  { id: 1927, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Det är så tyst och rofyllt här borta vid vattnet. Det hjälper mig att uttrycka mig klart.", vi: "Ở khu vực ven nước này thật yên tĩnh và thanh bình. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/deːt ɛːr soː tʏst ɔ ˈrʊːˌfʏlt hɛːr ˈbɔrːta viːd ˈvatːnɛt/" },
  { id: 1928, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Vi tar det lugnt och njuter av resan i vårt eget tempo. Det känns avslappnat och vardagligt.", vi: "Tụi mình đi thong thả và tận hưởng chuyến đi theo nhịp của riêng mình. Nghe rất tự nhiên và gần gũi.", phonetic: "/viː tɑːr deː lɵŋt ɔ ˈnjʉːtɛr ɑːv ˈreːsan ɪ voːʈ ˈeːɡɛt ˈtɛmːpʊ/" },
  { id: 1929, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Jag älskar när solen tittar fram mellan molnen. Det är ett bra uttryck att kunna.", vi: "Mình thích khoảnh khắc mặt trời ló dạng giữa những đám mây. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈɛlːskar nɛːr ˈsuːlɛn ˈtɪtːar fram ˈmɛlːan ˈmuːlnɛn/" },
  { id: 1930, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Att komma ut i naturen rensar tankarna. Jag använder det gärna i samtal.", vi: "Ra ngoài thiên nhiên giúp đầu óc thư thái hẳn. Mình thích dùng câu này khi trò chuyện.", phonetic: "/at ˈkɔmːa ʉːt ɪ nɑtʉːˈreːn ˈrɛnːsar ˈtaŋːkarːa/" },
  { id: 1931, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På kvällen gillar jag att varva ner hemma med en bra film. Det passar bra i många situationer.", vi: "Buổi tối mình thích thư giãn ở nhà với một bộ phim hay. Câu này dùng được trong nhiều tình huống.", phonetic: "/pɔː ˈkvɛlːɛn ˈjɪlːar jɑːɡ at ˈvarːva neːr ˈhɛmːa meːd ɛn brɑː fɪlm/" },
  { id: 1932, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det är skönt att krypa upp i soffan efter en aktiv dag. Det hjälper mig att uttrycka mig klart.", vi: "Thật dễ chịu khi cuộn mình trên ghế sofa sau một ngày năng động. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/deːt ɛːr ɕøːnt at ˈkrʏːpa ɵpː ɪ ˈsɔfːan ˈɛfːtɛr ɛn ˈakːtɪv dɑːɡ/" },
  { id: 1933, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vi spelar sällskapsspel och ordlekar när vi är många. Det känns avslappnat och vardagligt.", vi: "Tụi mình chơi board game và trò nối chữ khi có đông người. Nghe rất tự nhiên và gần gũi.", phonetic: "/viː ˈsɛlːskɑpsˌspeːl ɔ ˈuːɖˌleːkar nɛːr viː ɛːr ˈmɔŋːa/" },
  { id: 1934, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det är så kul att skratta tillsammans över en spelomgång. Det är ett bra uttryck att kunna.", vi: "Cùng cười rôm rả qua một ván chơi vui thật đấy. Đây là cách diễn đạt hay nên biết.", phonetic: "/deːt ɛːr soː kʉːl at ˈskratːa tɪlˈsamːanːs ˈøːvɛr ɛn ˈspeːlˌɔmːɡɔŋ/" },
  { id: 1935, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Jag gillar att ha det städat och mysigt omkring mig. Jag använder det gärna i samtal.", vi: "Mình thích giữ không gian gọn gàng và ấm cúng quanh mình. Mình thích dùng câu này khi trò chuyện.", phonetic: "/jɑːɡ ˈjɪlːar at hɑː deː ˈstɛːdat ɔ ˈmʏːsɪt ɔmˈkrɪŋ mej/" },
  { id: 1936, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "En varm dusch och tystnad hjälper mig att somna gott. Det passar bra i många situationer.", vi: "Một trận tắm nước ấm và sự yên tĩnh giúp mình ngủ ngon. Câu này dùng được trong nhiều tình huống.", phonetic: "/ɛn varm dɵʃ ɔ ˈtʏsːtnɑd ˈjɛlːpɛr mej at ˈsɔmːna ɡɔt/" },
  { id: 1937, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Jag tar gärna en kort paus när jag behöver samla kraft. Det hjälper mig att uttrycka mig klart.", vi: "Mình hay nghỉ giải lao ngắn khi cần lấy lại sức. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn kɔʈ paɵs nɛːr jɑːɡ bɛˈhøːvɛr ˈsamːla krɑft/" },
  { id: 1938, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vilken film eller serie tyckte du bäst om nyligen? Det känns avslappnat och vardagligt.", vi: "Gần đây bạn thích phim điện ảnh hay phim bộ nào nhất? Nghe rất tự nhiên và gần gũi.", phonetic: "/ˈvɪlːkɛn fɪlm ˈɛlːɛr ˈseːrɪɛ ˈtʏkːtɛ dʉː bɛst ɔm ˈnʏːˌliːɡɛn/" },
  { id: 1939, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Vi gör en enkel fika med kaffe och frukt idag. Det är ett bra uttryck att kunna.", vi: "Hôm nay tụi mình làm bữa fika nhẹ nhàng với cà phê và trái cây. Đây là cách diễn đạt hay nên biết.", phonetic: "/viː jøːr ɛn ˈɛŋːkɛl ˈfiːka meːd ˈkafːɛ ɔ frɵkt ɪˈdɑːɡ/" },
  { id: 1940, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Det känns skönt att bara vara sig själv i lugn och ro. Jag använder det gärna i samtal.", vi: "Thật thoải mái khi được là chính mình trong yên bình. Mình thích dùng câu này khi trò chuyện.", phonetic: "/deːt ɕɛnːs ɕøːnt at ˈbɑːra ˈvɑːra sej ɕɛlv ɪ lɵŋn ɔ rʊː/" },
  { id: 1941, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Ursäkta, vet du var närmaste busshållplats ligger? Det passar bra i många situationer.", vi: "Xin lỗi, bạn có biết trạm xe buýt gần nhất ở đâu không? Câu này dùng được trong nhiều tình huống.", phonetic: "/ˈʉːˌʂɛkːta veːt dʉː vɑːr ˈnɛrmastɛ ˈbɵsˌhɔlːplats ˈlɪɡːɛr/" },
  { id: 1942, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag behöver köpa frukt, grönsaker och bröd idag. Det hjälper mig att uttrycka mig klart.", vi: "Hôm nay mình cần mua trái cây, rau củ và bánh mì. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ bɛˈhøːvɛr ˈɕøːpa frɵkt ˈɡrœnˌsɑːkɛr ɔ brøːd ɪˈdɑːɡ/" },
  { id: 1943, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hur mycket kostar det här totalt? Det känns avslappnat och vardagligt.", vi: "Món này tổng cộng giá bao nhiêu vậy? Nghe rất tự nhiên và gần gũi.", phonetic: "/hʉːr ˈmʏkːɛt ˈkɔsːtar deːt hɛːr tʊˈtɑlt/" },
  { id: 1944, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag tar gärna en påse, tack så mycket. Det är ett bra uttryck att kunna.", vi: "Cho mình xin một túi nhé, cảm ơn bạn nhiều. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn ˈpoːsɛ tak soː ˈmʏkːɛt/" },
  { id: 1945, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Det är ganska svalt ute idag, så jag tar en tröja. Jag använder det gärna i samtal.", vi: "Hôm nay ngoài trời khá mát nên mình mặc thêm áo len. Mình thích dùng câu này khi trò chuyện.", phonetic: "/deːt ɛːr ˈɡanːsa svɑlt ˈʉːtɛ ɪˈdɑːɡ soː jɑːɡ tɑːr ɛn ˈtrœjːa/" },
  { id: 1946, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Vi åker kollektivt eller går när det inte är så långt. Det passar bra i många situationer.", vi: "Tụi mình đi phương tiện công cộng hoặc đi bộ khi không quá xa. Câu này dùng được trong nhiều tình huống.", phonetic: "/viː ˈoːkɛr kʊlːɛkˈtiːvt ˈɛlːɛr ɡoːr nɛːr deː ˈɪnːtɛ ɛːr soː lɔŋt/" },
  { id: 1947, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag sparar undan lite varje månad för framtida planer. Det hjälper mig att uttrycka mig klart.", vi: "Mình dành dụm một chút mỗi tháng cho các kế hoạch tương lai. Nó giúp mình diễn đạt rõ ý hơn.", phonetic: "/jɑːɡ ˈspɑːrar ˈɵnːdan ˈliːtɛ ˈvarːjɛ ˈmoːnad fœr ˈfrɑːmˌtiːda ˈplɑːnɛr/" },
  { id: 1948, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Vädret växlar snabbt, så det är bra att ha paraply med. Det känns avslappnat och vardagligt.", vi: "Thời tiết đổi nhanh lắm nên mang theo ô là tốt nhất. Nghe rất tự nhiên và gần gũi.", phonetic: "/ˈvɛːdrɛt ˈvɛkːslar snɑpt soː deːt ɛːr brɑː at hɑː pɑrɑˈplʏː meːd/" },
  { id: 1949, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Jag gillar tydliga och enkla rutiner i vardagen. Det är ett bra uttryck att kunna.", vi: "Mình thích những thói quen rõ ràng và đơn giản trong ngày. Đây là cách diễn đạt hay nên biết.", phonetic: "/jɑːɡ ˈjɪlːar ˈtʏːdliɡa ɔ ˈɛŋːkla rɵˈtiːnɛr ɪ ˈvɑːrˌdɑːɡɛn/" },
  { id: 1950, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Varje litet steg framåt räknas. Jag använder det gärna i samtal.", vi: "Mỗi bước tiến nhỏ về phía trước đều đáng quý. Mình thích dùng câu này khi trò chuyện.", phonetic: "/ˈvarːjɛ ˈliːtɛt steːɡ ˈfrɑːmˌɔːt ˈrɛkːnas/" },
  { id: 1951, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag tränar svenska säger jag: God morgon! Hur har du sovit?", vi: "Khi luyện tiếng Thụy Điển mình nói: Chào buổi sáng! Bạn ngủ có ngon không?", phonetic: "/ɡuːd ˈmɔrːɔn hʉːr hɑːr dʉː ˈsʊːvɪt/" },
  { id: 1952, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "På utflykt eller promenad säger jag: Jag vaknade tidigt idag och tog en lugn start.", vi: "Khi đi chơi hoặc đi dạo mình nói: Hôm nay mình dậy sớm và khởi đầu thật nhẹ nhàng.", phonetic: "/jɑːɡ ˈvɑːknadɛ ˈtiːdɪt ɪˈdɑːɡ ɔ tʊːɡ ɛn lɵŋn stɑʈ/" },
  { id: 1953, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "I vardagen säger jag: Vad ska vi äta till middag ikväll?", vi: "Trong đời sống hằng ngày mình nói: Tối nay tụi mình sẽ ăn gì nhỉ?", phonetic: "/vɑːd skɑː viː ˈɛːta tɪl ˈmɪdːɑːɡ ɪˈkvɛlː/" },
  { id: 1954, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag pratar med vänner säger jag: Jag håller på att laga mat i köket nu.", vi: "Khi trò chuyện với bạn bè mình nói: Bây giờ mình đang nấu ăn trong bếp.", phonetic: "/jɑːɡ ˈhɔlːɛr pɔː at ˈlɑːɡa mɑːt ɪ ˈɕøːkɛt nʉː/" },
  { id: 1955, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Hemma och på fritiden säger jag: Kan du upprepa det lite långsammare, tack?", vi: "Ở nhà và lúc rảnh mình nói: Bạn lặp lại chậm hơn một chút được không, cảm ơn bạn?", phonetic: "/kan dʉː ɵpːrɛˈpɑː deː ˈliːtɛ ˈlɔŋːsamːarɛ tak/" },
  { id: 1956, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag tränar svenska säger jag: Jag förstår ungefär vad du menar, men jag övar fortfarande.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình hiểu đại khái ý bạn, nhưng mình vẫn đang luyện thêm.", phonetic: "/jɑːɡ fœrˈstoːr ɵnːfɛˈjɛːr vɑːd dʉː ˈmeːnar mɛn jɑːɡ ˈøːvar ˈfɔrtˌfarːandɛ/" },
  { id: 1957, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "På utflykt eller promenad säger jag: Det här ordet är nytt för mig. Vad betyder det?", vi: "Khi đi chơi hoặc đi dạo mình nói: Từ này mới với mình. Nó có nghĩa là gì vậy?", phonetic: "/deːt hɛːr ˈuːɖɛt ɛːr nʏt fœr mej vɑːd bɛˈtʏːdɛr deː/" },
  { id: 1958, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "I vardagen säger jag: Jag övar på att prata svenska varje dag.", vi: "Trong đời sống hằng ngày mình nói: Mình luyện nói tiếng Thụy Điển mỗi ngày.", phonetic: "/jɑːɡ ˈøːvar pɔː at ˈprɑːta ˈsvɛnːska ˈvarːjɛ dɑːɡ/" },
  { id: 1959, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "När jag pratar med vänner säger jag: Det blir lättare ju mer man pratar.", vi: "Khi trò chuyện với bạn bè mình nói: Càng nói nhiều thì sẽ càng dễ hơn.", phonetic: "/deːt bliːr ˈlɛtːarɛ jʉː meːr man ˈprɑːtar/" },
  { id: 1960, topic: "Sinh hoạt & giao tiếp hằng ngày", sv: "Hemma och på fritiden säger jag: Tack för hjälpen, det betydde mycket!", vi: "Ở nhà và lúc rảnh mình nói: Cảm ơn vì đã giúp đỡ, điều đó có ý nghĩa lắm!", phonetic: "/tak fœr ˈjɛlːpɛn deː bɛˈtʏːdːɛ ˈmʏkːɛt/" },
  { id: 1961, topic: "Gia đình & người thân", sv: "När jag tränar svenska säger jag: Jag pratar med min man varje dag om framtiden.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình trò chuyện với chồng mỗi ngày về tương lai.", phonetic: "/jɑːɡ ˈprɑːtar meːd miːn man ˈvarːjɛ dɑːɡ ɔm ˈfrɑːmˌtiːdɛn/" },
  { id: 1962, topic: "Gia đình & người thân", sv: "På utflykt eller promenad säger jag: Vi planerar vårt nya liv tillsammans i lugn takt.", vi: "Khi đi chơi hoặc đi dạo mình nói: Tụi mình lên kế hoạch cho cuộc sống mới cùng nhau một cách chầm chậm.", phonetic: "/viː plɑˈneːrar voːʈ ˈnʏːa liːv tɪlˈsamːanːs ɪ lɵŋn tɑkt/" },
  { id: 1963, topic: "Gia đình & người thân", sv: "I vardagen säger jag: Jag tänker ofta på min mormor hemma.", vi: "Trong đời sống hằng ngày mình nói: Mình thường nhớ tới bà ngoại ở nhà.", phonetic: "/jɑːɡ ˈtɛŋːkɛr ˈɔfːta pɔː miːn ˈmʊːrmʊr ˈhɛmːa/" },
  { id: 1964, topic: "Gia đình & người thân", sv: "När jag pratar med vänner säger jag: Familjen betyder allt när man är långt hemifrån.", vi: "Khi trò chuyện với bạn bè mình nói: Gia đình có ý nghĩa tất cả khi ở xa nhà.", phonetic: "/fɑˈmiːljɛn bɛˈtʏːdɛr alːt nɛːr man ɛːr lɔŋt ˈhɛmːɪˌfroːn/" },
  { id: 1965, topic: "Gia đình & người thân", sv: "Hemma och på fritiden säger jag: Vi ringer videosamtal på helgen när alla är lediga.", vi: "Ở nhà và lúc rảnh mình nói: Tụi mình gọi video vào cuối tuần khi ai cũng rảnh.", phonetic: "/viː ˈrɪŋːɛr ˈviːdɛʊˌsamːtɑːl pɔː ˈhɛlːjɛn nɛːr ˈalːa ɛːr ˈleːdɪɡa/" },
  { id: 1966, topic: "Gia đình & người thân", sv: "När jag tränar svenska säger jag: Han lagar god mat och stöttar mig alltid.", vi: "Khi luyện tiếng Thụy Điển mình nói: Anh ấy nấu ăn ngon và luôn ủng hộ mình.", phonetic: "/han ˈlɑːɡar ɡuːd mɑːt ɔ ˈstœtːar mej ˈalːtiːd/" },
  { id: 1967, topic: "Gia đình & người thân", sv: "På utflykt eller promenad säger jag: Att hjälpa varandra gör vardagen enklare.", vi: "Khi đi chơi hoặc đi dạo mình nói: Giúp đỡ lẫn nhau khiến cuộc sống hằng ngày nhẹ nhàng hơn.", phonetic: "/at ˈjɛlːpa vɑˈranːdra jøːr ˈvɑːrˌdɑːɡɛn ˈɛŋːklarɛ/" },
  { id: 1968, topic: "Gia đình & người thân", sv: "I vardagen säger jag: Jag vill gärna bjuda hem familjen på middag någon gång.", vi: "Trong đời sống hằng ngày mình nói: Mình rất muốn mời gia đình đến nhà ăn tối một dịp nào đó.", phonetic: "/jɑːɡ vɪl ˈjɛːrna ˈbjʉːda hɛm fɑˈmiːljɛn pɔː ˈmɪdːɑːɡ ˈnoːɡɔn ɡɔŋ/" },
  { id: 1969, topic: "Gia đình & người thân", sv: "När jag pratar med vänner säger jag: Det känns tryggt att ha någon som förstår en.", vi: "Khi trò chuyện với bạn bè mình nói: Thật vững tâm khi có người thấu hiểu mình.", phonetic: "/deːt ɕɛnːs trʏɡt at hɑː ˈnoːɡɔn sɔm fœrˈstoːr ɛn/" },
  { id: 1970, topic: "Gia đình & người thân", sv: "Hemma och på fritiden säger jag: Vi delar både glädje och små bekymmer.", vi: "Ở nhà và lúc rảnh mình nói: Tụi mình chia sẻ cả niềm vui lẫn những nỗi lo nhỏ.", phonetic: "/viː ˈdeːlar ˈboːdɛ ˈɡlɛːdjɛ ɔ smoː bɛˈɕʏmːɛr/" },
  { id: 1971, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag tränar svenska säger jag: Jag gillar att ta en promenad i parken efter jobbet.", vi: "Khi luyện tiếng Thụy Điển mình nói: Mình thích đi dạo trong công viên sau giờ làm.", phonetic: "/jɑːɡ ˈjɪlːar at tɑː ɛn prʊmɛˈnɑːd ɪ ˈparːkɛn ˈɛfːtɛr ˈjɔbːɛt/" },
  { id: 1972, topic: "Thiên nhiên, đi dạo & du lịch", sv: "På utflykt eller promenad säger jag: Frisk luft och grönska hjälper mig att ladda om.", vi: "Khi đi chơi hoặc đi dạo mình nói: Không khí trong lành và cây xanh giúp mình nạp lại năng lượng.", phonetic: "/frɪsk lɵft ɔ ˈɡrœnːska ˈjɛlːpɛr mej at ˈladːa ɔm/" },
  { id: 1973, topic: "Thiên nhiên, đi dạo & du lịch", sv: "I vardagen säger jag: Vilken vacker utsikt över sjön och skogen!", vi: "Trong đời sống hằng ngày mình nói: Khung cảnh nhìn ra hồ và rừng đẹp quá!", phonetic: "/ˈvɪlːkɛn ˈvakːɛr ˈʉːtˌsɪkːt ˈøːvɛr ɕøːn ɔ ˈskuːɡɛn/" },
  { id: 1974, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag pratar med vänner säger jag: Jag brukar ta foton på naturen när vi reser.", vi: "Khi trò chuyện với bạn bè mình nói: Mình hay chụp ảnh thiên nhiên khi tụi mình đi du lịch.", phonetic: "/jɑːɡ ˈbrʉːkar tɑː ˈfuːtɔn pɔː nɑtʉːˈreːn nɛːr viː ˈreːsɛr/" },
  { id: 1975, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Hemma och på fritiden säger jag: Vi åker gärna iväg på helgutflykter till nya platser.", vi: "Ở nhà và lúc rảnh mình nói: Tụi mình thích đi chơi cuối tuần tới những vùng đất mới.", phonetic: "/viː ˈoːkɛr ˈjɛːrna ɪˈvɛːɡ pɔː ˈhɛljˌʉːtflʏkːtɛr tɪl ˈnʏːa ˈplatːsɛr/" },
  { id: 1976, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag tränar svenska säger jag: Ljuset på morgonen och kvällen är så fint att fotografera.", vi: "Khi luyện tiếng Thụy Điển mình nói: Ánh sáng buổi sáng và buổi chiều tối chụp ảnh đẹp lắm.", phonetic: "/ˈjʉːsɛt pɔː ˈmɔrːɔnɛn ɔ ˈkvɛlːɛn ɛːr soː fiːnt at fʊtʊɡrɑˈfeːra/" },
  { id: 1977, topic: "Thiên nhiên, đi dạo & du lịch", sv: "På utflykt eller promenad säger jag: Det är så tyst och rofyllt här borta vid vattnet.", vi: "Khi đi chơi hoặc đi dạo mình nói: Ở khu vực ven nước này thật yên tĩnh và thanh bình.", phonetic: "/deːt ɛːr soː tʏst ɔ ˈrʊːˌfʏlt hɛːr ˈbɔrːta viːd ˈvatːnɛt/" },
  { id: 1978, topic: "Thiên nhiên, đi dạo & du lịch", sv: "I vardagen säger jag: Vi tar det lugnt och njuter av resan i vårt eget tempo.", vi: "Trong đời sống hằng ngày mình nói: Tụi mình đi thong thả và tận hưởng chuyến đi theo nhịp của riêng mình.", phonetic: "/viː tɑːr deː lɵŋt ɔ ˈnjʉːtɛr ɑːv ˈreːsan ɪ voːʈ ˈeːɡɛt ˈtɛmːpʊ/" },
  { id: 1979, topic: "Thiên nhiên, đi dạo & du lịch", sv: "När jag pratar med vänner säger jag: Jag älskar när solen tittar fram mellan molnen.", vi: "Khi trò chuyện với bạn bè mình nói: Mình thích khoảnh khắc mặt trời ló dạng giữa những đám mây.", phonetic: "/jɑːɡ ˈɛlːskar nɛːr ˈsuːlɛn ˈtɪtːar fram ˈmɛlːan ˈmuːlnɛn/" },
  { id: 1980, topic: "Thiên nhiên, đi dạo & du lịch", sv: "Hemma och på fritiden säger jag: Att komma ut i naturen rensar tankarna.", vi: "Ở nhà và lúc rảnh mình nói: Ra ngoài thiên nhiên giúp đầu óc thư thái hẳn.", phonetic: "/at ˈkɔmːa ʉːt ɪ nɑtʉːˈreːn ˈrɛnːsar ˈtaŋːkarːa/" },
  { id: 1981, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag tränar svenska säger jag: På kvällen gillar jag att varva ner hemma med en bra film.", vi: "Khi luyện tiếng Thụy Điển mình nói: Buổi tối mình thích thư giãn ở nhà với một bộ phim hay.", phonetic: "/pɔː ˈkvɛlːɛn ˈjɪlːar jɑːɡ at ˈvarːva neːr ˈhɛmːa meːd ɛn brɑː fɪlm/" },
  { id: 1982, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På utflykt eller promenad säger jag: Det är skönt att krypa upp i soffan efter en aktiv dag.", vi: "Khi đi chơi hoặc đi dạo mình nói: Thật dễ chịu khi cuộn mình trên ghế sofa sau một ngày năng động.", phonetic: "/deːt ɛːr ɕøːnt at ˈkrʏːpa ɵpː ɪ ˈsɔfːan ˈɛfːtɛr ɛn ˈakːtɪv dɑːɡ/" },
  { id: 1983, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "I vardagen säger jag: Vi spelar sällskapsspel och ordlekar när vi är många.", vi: "Trong đời sống hằng ngày mình nói: Tụi mình chơi board game và trò nối chữ khi có đông người.", phonetic: "/viː ˈsɛlːskɑpsˌspeːl ɔ ˈuːɖˌleːkar nɛːr viː ɛːr ˈmɔŋːa/" },
  { id: 1984, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag pratar med vänner säger jag: Det är så kul att skratta tillsammans över en spelomgång.", vi: "Khi trò chuyện với bạn bè mình nói: Cùng cười rôm rả qua một ván chơi vui thật đấy.", phonetic: "/deːt ɛːr soː kʉːl at ˈskratːa tɪlˈsamːanːs ˈøːvɛr ɛn ˈspeːlˌɔmːɡɔŋ/" },
  { id: 1985, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Hemma och på fritiden säger jag: Jag gillar att ha det städat och mysigt omkring mig.", vi: "Ở nhà và lúc rảnh mình nói: Mình thích giữ không gian gọn gàng và ấm cúng quanh mình.", phonetic: "/jɑːɡ ˈjɪlːar at hɑː deː ˈstɛːdat ɔ ˈmʏːsɪt ɔmˈkrɪŋ mej/" },
  { id: 1986, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag tränar svenska säger jag: En varm dusch och tystnad hjälper mig att somna gott.", vi: "Khi luyện tiếng Thụy Điển mình nói: Một trận tắm nước ấm và sự yên tĩnh giúp mình ngủ ngon.", phonetic: "/ɛn varm dɵʃ ɔ ˈtʏsːtnɑd ˈjɛlːpɛr mej at ˈsɔmːna ɡɔt/" },
  { id: 1987, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "På utflykt eller promenad säger jag: Jag tar gärna en kort paus när jag behöver samla kraft.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình hay nghỉ giải lao ngắn khi cần lấy lại sức.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn kɔʈ paɵs nɛːr jɑːɡ bɛˈhøːvɛr ˈsamːla krɑft/" },
  { id: 1988, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "I vardagen säger jag: Vilken film eller serie tyckte du bäst om nyligen?", vi: "Trong đời sống hằng ngày mình nói: Gần đây bạn thích phim điện ảnh hay phim bộ nào nhất?", phonetic: "/ˈvɪlːkɛn fɪlm ˈɛlːɛr ˈseːrɪɛ ˈtʏkːtɛ dʉː bɛst ɔm ˈnʏːˌliːɡɛn/" },
  { id: 1989, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "När jag pratar med vänner säger jag: Vi gör en enkel fika med kaffe och frukt idag.", vi: "Khi trò chuyện với bạn bè mình nói: Hôm nay tụi mình làm bữa fika nhẹ nhàng với cà phê và trái cây.", phonetic: "/viː jøːr ɛn ˈɛŋːkɛl ˈfiːka meːd ˈkafːɛ ɔ frɵkt ɪˈdɑːɡ/" },
  { id: 1990, topic: "Nhà cửa, nghỉ ngơi & giải trí", sv: "Hemma och på fritiden säger jag: Det känns skönt att bara vara sig själv i lugn och ro.", vi: "Ở nhà và lúc rảnh mình nói: Thật thoải mái khi được là chính mình trong yên bình.", phonetic: "/deːt ɕɛnːs ɕøːnt at ˈbɑːra ˈvɑːra sej ɕɛlv ɪ lɵŋn ɔ rʊː/" },
  { id: 1991, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag tränar svenska säger jag: Ursäkta, vet du var närmaste busshållplats ligger?", vi: "Khi luyện tiếng Thụy Điển mình nói: Xin lỗi, bạn có biết trạm xe buýt gần nhất ở đâu không?", phonetic: "/ˈʉːˌʂɛkːta veːt dʉː vɑːr ˈnɛrmastɛ ˈbɵsˌhɔlːplats ˈlɪɡːɛr/" },
  { id: 1992, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "På utflykt eller promenad säger jag: Jag behöver köpa frukt, grönsaker och bröd idag.", vi: "Khi đi chơi hoặc đi dạo mình nói: Hôm nay mình cần mua trái cây, rau củ và bánh mì.", phonetic: "/jɑːɡ bɛˈhøːvɛr ˈɕøːpa frɵkt ˈɡrœnˌsɑːkɛr ɔ brøːd ɪˈdɑːɡ/" },
  { id: 1993, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "I vardagen säger jag: Hur mycket kostar det här totalt?", vi: "Trong đời sống hằng ngày mình nói: Món này tổng cộng giá bao nhiêu vậy?", phonetic: "/hʉːr ˈmʏkːɛt ˈkɔsːtar deːt hɛːr tʊˈtɑlt/" },
  { id: 1994, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag pratar med vänner säger jag: Jag tar gärna en påse, tack så mycket.", vi: "Khi trò chuyện với bạn bè mình nói: Cho mình xin một túi nhé, cảm ơn bạn nhiều.", phonetic: "/jɑːɡ tɑːr ˈjɛːrna ɛn ˈpoːsɛ tak soː ˈmʏkːɛt/" },
  { id: 1995, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hemma och på fritiden säger jag: Det är ganska svalt ute idag, så jag tar en tröja.", vi: "Ở nhà và lúc rảnh mình nói: Hôm nay ngoài trời khá mát nên mình mặc thêm áo len.", phonetic: "/deːt ɛːr ˈɡanːsa svɑlt ˈʉːtɛ ɪˈdɑːɡ soː jɑːɡ tɑːr ɛn ˈtrœjːa/" },
  { id: 1996, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag tränar svenska säger jag: Vi åker kollektivt eller går när det inte är så långt.", vi: "Khi luyện tiếng Thụy Điển mình nói: Tụi mình đi phương tiện công cộng hoặc đi bộ khi không quá xa.", phonetic: "/viː ˈoːkɛr kʊlːɛkˈtiːvt ˈɛlːɛr ɡoːr nɛːr deː ˈɪnːtɛ ɛːr soː lɔŋt/" },
  { id: 1997, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "På utflykt eller promenad säger jag: Jag sparar undan lite varje månad för framtida planer.", vi: "Khi đi chơi hoặc đi dạo mình nói: Mình dành dụm một chút mỗi tháng cho các kế hoạch tương lai.", phonetic: "/jɑːɡ ˈspɑːrar ˈɵnːdan ˈliːtɛ ˈvarːjɛ ˈmoːnad fœr ˈfrɑːmˌtiːda ˈplɑːnɛr/" },
  { id: 1998, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "I vardagen säger jag: Vädret växlar snabbt, så det är bra att ha paraply med.", vi: "Trong đời sống hằng ngày mình nói: Thời tiết đổi nhanh lắm nên mang theo ô là tốt nhất.", phonetic: "/ˈvɛːdrɛt ˈvɛkːslar snɑpt soː deːt ɛːr brɑː at hɑː pɑrɑˈplʏː meːd/" },
  { id: 1999, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "När jag pratar med vänner säger jag: Jag gillar tydliga och enkla rutiner i vardagen.", vi: "Khi trò chuyện với bạn bè mình nói: Mình thích những thói quen rõ ràng và đơn giản trong ngày.", phonetic: "/jɑːɡ ˈjɪlːar ˈtʏːdliɡa ɔ ˈɛŋːkla rɵˈtiːnɛr ɪ ˈvɑːrˌdɑːɡɛn/" },
  { id: 2000, topic: "Mua sắm, đi lại & cuộc sống thường nhật", sv: "Hemma och på fritiden säger jag: Varje litet steg framåt räknas.", vi: "Ở nhà và lúc rảnh mình nói: Mỗi bước tiến nhỏ về phía trước đều đáng quý.", phonetic: "/ˈvarːjɛ ˈliːtɛt steːɡ ˈfrɑːmˌɔːt ˈrɛkːnas/" }
];


